INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('deepklarity/harness-kit/dk-breadcrumb-creator', 'dk-breadcrumb-creator', 'deepklarity', 'harness-kit', 'community', 'dk-breadcrumb-creator deepklarity harness-kit community dk-breadcrumb-creator is a kit for building with AI agents, providing a compact debugging reference for devs and agents to identify workflow breaks. dk-breadcrumb-creator是一种AIエージェント开发工具，用于构建和分析工作流程，提高开发效率 dk-breadcrumb-creatorはAIエージェントのワークフロー分析と開発を支援するツールキットです dk-breadcrumb-creator는 AI 에이전트 개발을 위한 키트로 작업 흐름을 분석하고 개발 효율을 높입니다 dk-breadcrumb-creator es un kit para construir con agentes de inteligencia artificial, que proporciona patrones de ingeniería para analizar flujos de trabajo dk-breadcrumb-creator est un kit pour construire avec des agents d''intelligence artificielle, qui fournit des modèles d''ingénierie pour analyser les flux de travail dk-breadcrumb-creator ist ein Kit zum Aufbau mit KI-Agents, der Ingenieurmuster zur Analyse von Workflows bereitstellt O dk-breadcrumb-creator é uma ferramenta para análise de fluxo de trabalho que ajuda a identificar problemas no código. Ele fornece uma referência de depuração compacta para desenvolvedores e agentes. dk-breadcrumb-creator - это инструмент для анализа рабочих процессов, который помогает выявить проблемы в коде. Он предоставляет компактную справку для отладки для разработчиков и ИИ Агентов dk-breadcrumb-creator هو أداة لتحليل تدفق العمل تساعد على تحديد المشكلات في الكود. توفر مرجعًا مدمجًا للتصحيح للأشخاص المطورين وأدوات الذكاء الاصطناعي how to use dk-breadcrumb-creator dk-breadcrumb-creator setup guide dk-breadcrumb-creator alternative dk-breadcrumb-creator vs harness-kit what is dk-breadcrumb-creator dk-breadcrumb-creator install AIエージェント开发工具 工作流程分析 dk-breadcrumb-creator harness-kit monorepo AI开发效率 工作流程调试 AIエージェント开发框架 Traces workflows through the harness-kit monorepo Produces a compact debugging reference for devs and agents Supports workflow analysis via <flow_context> and $ARGUMENTS Generates output for debugging purposes, not onboarding or architecture overviews dk-breadcrumb-creator is a workflow analysis tool that traces workflows through the harness-kit monorepo, producing a compact debugging reference.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('mgreenly/ikigai/e2e-testing', 'community', 'mgreenly', 'ikigai', 'mgreenly/ikigai', 'e2e-testing', 1, 0, 45, '2026-03-02T03:51:05Z', '2026-03-06T07:17:23.903Z', 'd8f9da4f6a8ca6710317fb6f64dfbcd14ed9093a6e6ef70d8454f1fb3d4546ec', '{"id":"mgreenly/ikigai/e2e-testing","name":"e2e-testing","description":{"en":"The e2e-testing skill enables AI agents to verify ikigai behavior through control socket interactions. It benefits developers by automating end-to-end tests.","zh":"End-to-End Testing是通过控制套接字验证行为的测试，支持mock后端和headless交互","ja":"E2Eテストは、コントロールソケットを介して動作を検証するテストで、Mockバックエンドとヘッドレス相互作用をサポート","ko":"엔드 투 엔드 테스팅은 제어 소켓을 통해 동작을 검증하는 테스트로, Mock 백엔드와 헤드리스 상호작용을 지원","es":"Nuestro Agente de Codificación AI ofrece pruebas de extremo a extremo para verificar el comportamiento de ikigai a través de su socket de control","fr":"Notre Agent de codage IA propose des tests de bout en bout pour vérifier le comportement d''ikigai via son socket de contrôle","de":"Unser KI-Coding-Agent bietet End-to-End-Tests, um das Verhalten von ikigai über seine Kontrollsocke zu überprüfen","pt":"Os testes de ponta a ponta verificam o comportamento de ikigai por meio de seu soquete de controle, utilizando arquivos JSON em tests/e2e/","ru":"Тестирование от конца до конца проверяет поведение ikigai через его контрольный сокет, используя файлы JSON в tests/e2e/","ar":"الاختبارات من النهاية إلى النهاية تحقق من سلوك ikigai من خلال منفذ التحكم، باستخدام ملفات JSON في tests/e2e/"},"seo":{"title":{"en":"e2e-testing: End-to-End Test Automation Setup Guide | AI ...","zh":"End-to-End Testing Setup Guide - AIエージェント","ja":"E2Eテストベストプラクティス - AIエージェント","ko":"엔드 투 엔드 테스팅 구축 가이드 - AI 에이전트","es":"Guía de configuración de pruebas de extremo a extremo con...","fr":"Guide de configuration des tests de bout en bout avec les...","de":"Einrichtungsleitfaden für End-to-End-Tests mit KI-Agents","pt":"Guia de Configuração de Testes de Ponta a Ponta com Agent...","ru":"Настройка ИИ Агентов для Тестирования от Конца до Конца","ar":"دليل إعداد الاختبارات من النهاية إلى النهاية مع وكلاء الذ..."},"description":{"en":"Unlock efficient testing with e2e-testing! Learn how to automate end-to-end tests using ikigai-ctl and headless interaction. Get started now!","zh":"了解End-to-End Testing的技术细节，包括测试文件、执行模式和Mock后端","ja":"E2Eテストの技術的側面を学び、テストファイル、実行モード、Mockバックエンドについて","ko":"엔드 투 엔드 테스팅의 기술적 측면을 알아보세요. 테스트 파일, 실행 모드, Mock 백엔드 등","es":"Aprende a configurar pruebas de extremo a extremo con nuestro Agente de Codificación AI y mejora la calidad de tu software","fr":"Découvrez comment configurer des tests de bout en bout avec notre Agent de codage IA et améliorez la qualité de vos logiciels","de":"Erfahren Sie, wie Sie End-to-End-Tests mit unserem KI-Coding-Agent konfigurieren und die Qualität Ihrer Software verbessern","pt":"Aprenda a configurar testes de ponta a ponta com agentes de IA para verificar o comportamento de ikigai por meio de seu soquete de controle","ru":"Узнайте, как настроить тестирование от конца до конца с ИИ Агентами, чтобы проверить поведение ikigai через его контрольный сокет","ar":"تعرف على كيفية إعداد الاختبارات من النهاية إلى النهاية مع وكلاء الذكاء الاصطناعي لتحقق من سلوك ikigai من خلال منفذ التحكم"},"definition":{"en":"e2e-testing is an AI coding agent skill that automates end-to-end tests for ikigai behavior using self-contained JSON test files.","zh":"End-to-End Testing是AIエージェント中的一个测试类型，用于验证系统的整体行为","ja":"E2Eテストは、AIエージェントにおける一种テストタイプで、システムの全体的な動作を検証","ko":"엔드 투 엔드 테스팅은 AI 에이전트의 테스트 유형 중 하나로, 시스템의 전체적인 동작을 검증","es":"Las pruebas de extremo a extremo son un tipo de prueba que verifica el comportamiento de un sistema desde el inicio hasta el final","fr":"Les tests de bout en bout sont un type de test qui vérifie le comportement d''un système depuis le début jusqu''à la fin","de":"End-to-End-Tests sind eine Art von Test, die das Verhalten eines Systems von Anfang bis Ende überprüft","pt":"Testes de ponta a ponta são uma forma de verificar o comportamento de ikigai por meio de seu soquete de controle","ru":"Тестирование от конца до конца - это способ проверить поведение ikigai через его контрольный сокет","ar":"الاختبارات من النهاية إلى النهاية هي طريقة لتحقق من سلوك ikigai من خلال منفذ التحكم"},"features":{"en":["Executes tests using ikigai-ctl and headless interaction","Supports test files in JSON format stored in tests/e2e/","Defines run order using tests/e2e/index.json","Operates in mock mode using bin/mock-provider backend","Enables assertions and step execution for thorough testing"],"zh":["支持Mock后端","支持headless交互","测试文件存储在tests/e2e/目录","执行顺序定义在tests/e2e/index.json文件","支持多种执行模式"],"ja":["Mockバックエンドのサポート","ヘッドレス相互作用のサポート","テストファイルの保存先はtests/e2e/ディレクトリ","実行順序の定義はtests/e2e/index.jsonファイル","複数の実行モードのサポート"],"ko":["Mock 백엔드 지원","헤드리스 상호작용 지원","테스트 파일 저장 위치는 tests/e2e/ 디렉토리","실행 순서 정의는 tests/e2e/index.json 파일","다중 실행 모드 지원"],"es":["Verificación del comportamiento de ikigai a través de su socket de control","Uso de ikigai-ctl para interactuar con el sistema","Interacción sin cabeza mediante la carga de headless","Ejecución de pruebas en modo mock con bin/mock-provider","Definición del orden de ejecución de las pruebas mediante tests/e2e/index.json"],"fr":["Vérification du comportement d''ikigai via son socket de contrôle","Utilisation d''ikigai-ctl pour interagir avec le système","Interaction sans tête via le chargement de headless","Exécution des tests en mode mock avec bin/mock-provider","Définition de l''ordre d''exécution des tests via tests/e2e/index.json"],"de":["Überprüfung des Verhaltens von ikigai über seine Kontrollsocke","Verwendung von ikigai-ctl zur Interaktion mit dem System","Kopflose Interaktion durch das Laden von headless","Ausführung von Tests im Mock-Modus mit bin/mock-provider","Definition der Ausführungsreihenfolge der Tests über tests/e2e/index.json"],"pt":["Utiliza arquivos JSON em tests/e2e/ para definir testes","Ordem de execução definida por tests/e2e/index.json","Modos de execução: mock com bin/mock-provider","Interação sem cabeça com /load headless","Uso de ikigai-ctl para interação com o soquete de controle"],"ru":["Использует файлы JSON в tests/e2e/ для определения тестов","Порядок выполнения определяется tests/e2e/index.json","Режимы выполнения: mock с bin/mock-provider","Бесшовное взаимодействие с /load headless","Использование ikigai-ctl для взаимодействия с контрольным сокетом"],"ar":["استخدام ملفات JSON في tests/e2e/ لتحديد الاختبارات","ترتيب التنفيذ يحدد بواسطة tests/e2e/index.json","أوضاع التنفيذ: mock مع bin/mock-provider","التفاعل بدون رأس مع /load headless","استخدام ikigai-ctl للتفاعل مع منفذ التحكم"]},"keywords":{"en":["how to use e2e-testing","e2e-testing setup guide","end-to-end test automation","ikigai-ctl usage","e2e-testing vs manual testing","e2e-testing install","headless interaction testing","JSON test file format","automated testing for AI agents"],"zh":["End-to-End Testing","AIエージェント","Mock后端","headless交互","测试文件","执行模式","E2E测试","自动化测试","软件测试"],"ja":["E2Eテスト","AIエージェント","Mockバックエンド","ヘッドレス相互作用","テストファイル","実行モード","エンドツーエンドテスト","自動テスト","ソフトウェアテスト"],"ko":["엔드 투 엔드 테스팅","AI 에이전트","Mock 백엔드","헤드리스 상호작용","테스트 파일","실행 모드","E2E 테스트","자동화 테스트","소프트웨어 테스트"],"es":["pruebas de extremo a extremo","Agentes de Inteligencia Artificial","ikigai","ikigai-ctl","headless","mock-provider","tests de software","calidad de software"],"fr":["tests de bout en bout","Outils d''Intelligence Artificielle","ikigai","ikigai-ctl","headless","mock-provider","tests de logiciels","qualité de logiciels"],"de":["End-to-End-Tests","KI-Agents","ikigai","ikigai-ctl","headless","mock-provider","Software-Tests","Software-Qualität"],"pt":["testes de ponta a ponta","agentes de IA","ikigai","soquete de controle","arquivos JSON","tests/e2e/","ikigai-ctl","bin/mock-provider","integração contínua"],"ru":["тестирование от конца до конца","ИИ Агенты","ikigai","контрольный сокет","файлы JSON","tests/e2e/","ikigai-ctl","bin/mock-provider","непрерывная интеграция"],"ar":["الاختبارات من النهاية إلى النهاية","وكلاء الذكاء الاصطناعي","ikigai","منفذ التحكم","ملفات JSON","tests/e2e/","ikigai-ctl","bin/mock-provider","التكامل المستمر"]}},"owner":"mgreenly","repo":"ikigai","repoPath":"mgreenly/ikigai","stars":1,"forks":0,"updatedAt":"2026-03-02T03:51:05Z","topics":[],"category":"community","skillMd":{"name":"e2e-testing","description":"JSON-based end-to-end test format, runner, and mock provider","bodyPreview":"# End-to-End Testing\n\nEnd-to-end tests verify ikigai behavior through its control socket. For `ikigai-ctl` usage, see `/load ikigai-ctl`. For general headless interaction, see `/load headless`.\n\n## Test Files\n\nTests live in `tests/e2e/` as self-contained JSON files. Run order is defined by `tests/e2e/index.json` — a JSON array of test filenames in execution order.\n\n## Execution Modes\n\n| Mode | Backend | Steps | Assertions |\n|------|---------|-------|------------|\n| **mock** | `bin/mock-provider`","body":"# End-to-End Testing\n\nEnd-to-end tests verify ikigai behavior through its control socket. For `ikigai-ctl` usage, see `/load ikigai-ctl`. For general headless interaction, see `/load headless`.\n\n## Test Files\n\nTests live in `tests/e2e/` as self-contained JSON files. Run order is defined by `tests/e2e/index.json` — a JSON array of test filenames in execution order.\n\n## Execution Modes\n\n| Mode | Backend | Steps | Assertions |\n|------|---------|-------|------------|\n| **mock** | `bin/mock-provider` | all steps including `mock_expect` | `assert` + `assert_mock` |\n| **live** | real provider (Anthropic, OpenAI, Google) | `mock_expect` steps skipped | `assert` only |\n\nTests are written once and run in either mode. In live mode, `mock_expect` steps are skipped and `assert_mock` is not evaluated.\n\n## JSON Schema\n\n```json\n{\n  \"name\": \"human-readable test name\",\n  \"steps\": [ ... ],\n  \"assert\": [ ... ],\n  \"assert_mock\": [ ... ]\n}\n```\n\n- **`name`** — describes what the test verifies\n- **`steps`** — ordered list of actions to execute\n- **`assert`** — assertions checked in ALL modes\n- **`assert_mock`** — assertions checked only in mock mode\n\n## Step Types\n\n### `send_keys`\n\n```json\n{\"send_keys\": \"/model gpt-5-mini\\\\r\"}\n```\n\nInclude `\\\\r` to submit. See `/load ikigai-ctl` for escaping conventions.\n\n### `read_framebuffer`\n\n```json\n{\"read_framebuffer\": true}\n```\n\nAlways `read_framebuffer` before asserting. Each capture replaces the previous one.\n\n### `wait`\n\n```json\n{\"wait\": 0.5}\n```\n\n- After UI commands (`/model`, `/clear`): 0.5 seconds\n- After sending a prompt to the LLM: 3-5 seconds (prefer `wait_idle`)\n\n### `wait_idle`\n\nWait until the agent becomes idle or timeout elapses.\n\n```json\n{\"wait_idle\": 10000}\n```\n\n- Value is `timeout_ms` (integer milliseconds)\n- Exit code 0 = idle; exit code 1 = timed out (report FAIL)\n- Use instead of `wait` after sending prompts to the LLM\n\n### `mock_expect`\n\nConfigure the mock provider''s response queue. **Skipped in live mode.**\n\n```json\n{\"mock_expect\": {\"responses\": [{\"content\": \"The capital of France is Paris.\"}]}}\n```\n\nThe `responses` array is a FIFO queue — each LLM request pops the next entry. Entries contain either `content` (text) or `tool_calls` (array), never both. Must appear before the `send_keys` that triggers the LLM call.\n\n## Assertion Types\n\nAssertions run against the most recent `read_framebuffer` capture.\n\n### `contains`\n\nAt least one row contains the given substring.\n\n```json\n{\"contains\": \"gpt-5-mini\"}\n```\n\n### `not_contains`\n\nNo row contains the given substring.\n\n```json\n{\"not_contains\": \"error\"}\n```\n\n### `line_prefix`\n\nAt least one row starts with the given prefix (after trimming leading whitespace).\n\n```json\n{\"line_prefix\": \"●\"}\n```\n\n## Running Tests\n\n**Direct execution, one tool call per step.** Never use scripts or programmatic wrappers when the user asks you to run e2e tests. The scripted runner (`tests/e2e/runner`) exists for CI — when the user asks you to run tests, they want direct execution so they can observe every response.\n\n### Procedure per test file:\n\n1. Read the JSON file\n2. Determine mode — mock if ikigai is connected to `mock-provider`, live otherwise\n3. Execute each step in order, one tool call per step:\n   - `send_keys`: run `ikigai-ctl send_keys \"<value>\"`\n   - `wait`: `sleep N`\n   - `wait_idle`: run `ikigai-ctl wait_idle <value>`, fail if exit code is 1\n   - `read_framebuffer`: run `ikigai-ctl read_framebuffer`, store result\n   - `mock_expect`: in mock mode, `curl -s 127.0.0.1:<port>/_mock/expect -d ''<json>''`; in live mode, skip\n4. Evaluate assertions (`assert` always, `assert_mock` in mock mode only)\n5. Report **PASS** or **FAIL** with evidence (cite relevant framebuffer rows)\n\n### Large batches (20+ tests)\n\nDivide into chunks of 20, run sub-agents **serially** (shared instance — never parallel). Each sub-agent receives filenames and the full contents of this skill. Don''t pre-read test files yourself.\n\n## Key Rules\n\n- **Never start ikigai** — the user manages the instance\n- **Never use the runner script** — direct execution only\n- **One test file = one test** — self-contained, no dependencies\n- **Steps execute in order** — sequential, never parallel\n- **Always read_framebuffer before asserting**\n- **Never chain after wait_idle** — run `read_framebuffer` in a separate tool call\n\n## Example: UI-only test\n\n```json\n{\n  \"name\": \"no model indicator on fresh start\",\n  \"steps\": [\n    {\"read_framebuffer\": true}\n  ],\n  \"assert\": [\n    {\"contains\": \"(no model)\"}\n  ]\n}\n```\n\n## Example: mock provider test\n\n```json\n{\n  \"name\": \"basic chat completion via mock provider\",\n  \"steps\": [\n    {\"mock_expect\": {\"responses\": [{\"content\": \"The capital of France is Paris.\"}]}},\n    {\"send_keys\": \"What is the capital of France?\\\\r\"},\n    {\"wait\": 3},\n    {\"read_framebuffer\": true}\n  ],\n  \"assert\": [\n    {\"line_prefix\": \"●\"}\n  ],\n  \"assert_mock\": [\n    {\"contains\": \"The capital of France is Paris.\"}\n  ]\n}\n```\n"},"lastSynced":"2026-03-06T07:17:23.903Z","agentAnalysis":{"suitability":{"en":"Perfect for Test Automation Agents needing end-to-end testing capabilities through control socket interactions.","zh":"非常适合需要通过控制套接字交互进行端到端测试的测试自动化代理。","ja":"エンドツーエンドのテスト機能をコントロールソケットの相互作用を介して必要とするテスト自動化エージェントに最適です。","ko":"제어 소켓 상호 작용을 통해 엔드 투 엔드 테스트 기능이 필요한 테스트 자동화 에이전트에 적합합니다.","es":"Perfecto para Agentes de Automatización de Pruebas que necesitan capacidades de prueba de extremo a extremo a través de interacciones de socket de control.","fr":"Parfait pour les agents d''automatisation de tests nécessitant des capacités de test de bout en bout via des interactions de socket de contrôle.","de":"Perfekt für Testautomatisierungsagenten, die End-to-End-Testfunktionen durch Steuerungssocket-Interaktionen benötigen.","pt":"Perfeito para Agentes de Automação de Testes que precisam de capacidades de teste de ponta a ponta por meio de interações de socket de controle.","ru":"Идеально подходит для агентов автоматизации тестирования, требующих возможностей тестирования от начала до конца через взаимодействия с контрольным сокетом.","ar":"مثالي لوكلاء اختبار التلقائي الذين يحتاجون إلى قدرات اختبار من النهاية إلى النهاية من خلال تفاعلات مقبس التحكم."},"recommendation":{"en":"Empowers agents to verify ikigai behavior using JSON test files and execute tests in mock mode with bin/mock-provider, enabling automation of end-to-end tests and validation of ikigai-ctl usage.","zh":"赋予代理使用 JSON 测试文件验证 ikigai 行为的能力，并通过 bin/mock-provider 在模拟模式下执行测试，实现端到端测试的自动化和 ikigai-ctl 使用的验证。","ja":"エージェントに JSON テストファイルを使用して ikigai 行為を検証し、bin/mock-provider を使用してモックモードでテストを実行する機能を提供し、エンドツーエンドテストの自動化と ikigai-ctl の使用の検証を可能にします。","ko":"에이전트가 JSON 테스트 파일을 사용하여 ikigai 동작을 검증하고 bin/mock-provider를 사용하여 모의 모드에서 테스트를 실행하여 엔드 투 엔드 테스트의 자동화와 ikigai-ctl 사용의 검증을 가능하게 합니다.","es":"Habilita a los agentes a verificar el comportamiento ikigai utilizando archivos de prueba JSON y ejecutar pruebas en modo de simulación con bin/mock-provider, lo que permite la automatización de pruebas de extremo a extremo y la validación del uso de ikigai-ctl.","fr":"Permet aux agents de vérifier le comportement ikigai en utilisant des fichiers de test JSON et d''exécuter des tests en mode de simulation avec bin/mock-provider, ce qui permet l''automatisation des tests de bout en bout et la validation de l''utilisation de ikigai-ctl.","de":"Ermächtigt Agenten, das ikigai-Verhalten mithilfe von JSON-Testdateien zu überprüfen und Tests im Mock-Modus mit bin/mock-provider auszuführen, wodurch die Automatisierung von End-to-End-Tests und die Überprüfung der Verwendung von ikigai-ctl ermöglicht wird.","pt":"Habilita os agentes a verificar o comportamento ikigai usando arquivos de teste JSON e executar testes no modo de simulação com bin/mock-provider, permitindo a automação de testes de ponta a ponta e validação do uso de ikigai-ctl.","ru":"Наделяет агентов возможностью проверять поведение ikigai с помощью файлов тестирования JSON и выполнять тесты в режиме имитации с bin/mock-provider, что позволяет автоматизировать тестирование от начала до конца и проверять использование ikigai-ctl.","ar":"يمنح الوكلاء القدرة على التحقق من سلوك ikigai باستخدام ملفات اختبار JSON وتنفيذ الاختبارات في وضع المحاكاة مع bin/mock-provider، مما يسمح بالتخصيص الآلي للاختبارات من النهاية إلى النهاية والتحقق من استخدام ikigai-ctl."},"useCases":{"en":["Automating end-to-end tests for ikigai behavior","Validating control socket interactions through JSON test files","Debugging test failures using mock mode with bin/mock-provider"],"zh":["自动化 ikigai 行为的端到端测试","通过 JSON 测试文件验证控制套接字交互","使用模拟模式和 bin/mock-provider 调试测试失败"],"ja":["ikigai 行為のエンドツーエンドテストの自動化","JSON テストファイルを使用してコントロー