INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('mgreenly/ikigai/e2e-testing', 'e2e-testing', 'mgreenly', 'ikigai', 'community', 'e2e-testing mgreenly ikigai community The e2e-testing skill enables AI agents to verify ikigai behavior through control socket interactions. It benefits developers by automating end-to-end tests. End-to-End Testing是通过控制套接字验证行为的测试，支持mock后端和headless交互 E2Eテストは、コントロールソケットを介して動作を検証するテストで、Mockバックエンドとヘッドレス相互作用をサポート 엔드 투 엔드 테스팅은 제어 소켓을 통해 동작을 검증하는 테스트로, Mock 백엔드와 헤드리스 상호작용을 지원 Nuestro Agente de Codificación AI ofrece pruebas de extremo a extremo para verificar el comportamiento de ikigai a través de su socket de control Notre Agent de codage IA propose des tests de bout en bout pour vérifier le comportement d''ikigai via son socket de contrôle Unser KI-Coding-Agent bietet End-to-End-Tests, um das Verhalten von ikigai über seine Kontrollsocke zu überprüfen Os testes de ponta a ponta verificam o comportamento de ikigai por meio de seu soquete de controle, utilizando arquivos JSON em tests/e2e/ Тестирование от конца до конца проверяет поведение ikigai через его контрольный сокет, используя файлы JSON в tests/e2e/ الاختبارات من النهاية إلى النهاية تحقق من سلوك ikigai من خلال منفذ التحكم، باستخدام ملفات JSON في tests/e2e/ how to use e2e-testing e2e-testing setup guide end-to-end test automation ikigai-ctl usage e2e-testing vs manual testing e2e-testing install headless interaction testing JSON test file format automated testing for AI agents End-to-End Testing AIエージェント Mock后端 headless交互 测试文件 执行模式 E2E测试 自动化测试 软件测试 Executes tests using ikigai-ctl and headless interaction Supports test files in JSON format stored in tests/e2e/ Defines run order using tests/e2e/index.json Operates in mock mode using bin/mock-provider backend Enables assertions and step execution for thorough testing e2e-testing is an AI coding agent skill that automates end-to-end tests for ikigai behavior using self-contained JSON test files.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('jdconley/wodbrains/backend-templates', 'community', 'jdconley', 'wodbrains', 'jdconley/wodbrains', 'backend-templates', 1, 0, 45, '2026-02-26T22:19:05Z', '2026-03-06T07:18:28.070Z', '7dcb781e35f0f7a2bd31312ff6783975653bb7655124b7af443563e3f4dc722f', '{"id":"jdconley/wodbrains/backend-templates","name":"backend-templates","description":{"en":"The backend-templates skill enables developers to dynamically render HTML content, including database or user-provided data, using Hono html helper for secure templating.","zh":"后端模板是实现动态元标签注入和服务器端渲染的关键技术，通过Hono html Helper实现安全的模板渲染","ja":"バックエンドテンプレートはダイナミックメタタグの注入とサーバーサイドレンダリングを実現する重要な技術です。Hono html Helperを使用して安全なテンプレートレンダリングを行います","ko":"백엔드 템플릿은 동적 메타 태그 삽입과 서버 측 렌더링을 구현하는 중요한 기술입니다. Hono html Helper를 사용하여 보안 템플릿 렌더링을 수행합니다","es":"Las plantillas de backend permiten la inyección de metadatos dinámicos y el renderizado del lado del servidor de HTML con contenido de base de datos o proporcionado por el usuario.","fr":"Les modèles de backend permettent l''injection de métadonnées dynamiques et le rendu du côté serveur de HTML avec du contenu de base de données ou fourni par l''utilisateur.","de":"Backend-Vorlagen ermöglichen die Injektion dynamischer Metadaten und das Server-seitige Rendering von HTML mit Datenbank- oder benutzerdefiniertem Inhalt.","pt":"O Hono permite a renderização de HTML dinâmico e seguro, ideal para aplicações de backend que exigem flexibilidade e desempenho","ru":"Hono позволяет рендерить динамический HTML и обеспечивает безопасность шаблонов, что делает его идеальным для приложений бэкенда, требующих гибкости и производительности: ИИ Агенты","ar":"Hono يتيح تقديم HTML ديناميكي وأمان القوالب، مما يجعله مثاليًا للتطبيقات الخلفية التي تتطلب مرونة وأداء: أدوات الذكاء الاصطناعي"},"seo":{"title":{"en":"backend-templates: Server-Side Rendering Setup Gu