INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('jdconley/wodbrains/backend-templates', 'backend-templates', 'jdconley', 'wodbrains', 'community', 'backend-templates jdconley wodbrains community ai ai-powered crossfit hybrid-athlete running weightlifting workout The backend-templates skill enables developers to dynamically render HTML content, including database or user-provided data, using Hono html helper for secure templating. 后端模板是实现动态元标签注入和服务器端渲染的关键技术，通过Hono html Helper实现安全的模板渲染 バックエンドテンプレートはダイナミックメタタグの注入とサーバーサイドレンダリングを実現する重要な技術です。Hono html Helperを使用して安全なテンプレートレンダリングを行います 백엔드 템플릿은 동적 메타 태그 삽입과 서버 측 렌더링을 구현하는 중요한 기술입니다. Hono html Helper를 사용하여 보안 템플릿 렌더링을 수행합니다 Las plantillas de backend permiten la inyección de metadatos dinámicos y el renderizado del lado del servidor de HTML con contenido de base de datos o proporcionado por el usuario. Les modèles de backend permettent l''injection de métadonnées dynamiques et le rendu du côté serveur de HTML avec du contenu de base de données ou fourni par l''utilisateur. Backend-Vorlagen ermöglichen die Injektion dynamischer Metadaten und das Server-seitige Rendering von HTML mit Datenbank- oder benutzerdefiniertem Inhalt. O Hono permite a renderização de HTML dinâmico e seguro, ideal para aplicações de backend que exigem flexibilidade e desempenho Hono позволяет рендерить динамический HTML и обеспечивает безопасность шаблонов, что делает его идеальным для приложений бэкенда, требующих гибкости и производительности: ИИ Агенты Hono يتيح تقديم HTML ديناميكي وأمان القوالب، مما يجعله مثاليًا للتطبيقات الخلفية التي تتطلب مرونة وأداء: أدوات الذكاء الاصطناعي how to use backend-templates backend-templates setup guide hono html helper tutorial server-side rendering with backend-templates backend-templates alternative cloudflare worker html response secure templating with hono backend-templates install hono backend-templates example 后端模板 AI智能定时器 动态元标签 服务器端渲染 Hono html Helper Cloudflare Worker 自动转义 模板渲染 Injects dynamic meta tags for social sharing using Hono Supports server-side rendering of HTML with database or user-provided content Utilizes Hono html helper for auto-escaping interpolated values Enables HTML responses built in Cloudflare Worker Leverages `hono/html` for secure templating backend-templates is a skill that allows for server-side rendering of HTML content, utilizing technologies like Hono for secure and efficient templating.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('jomcgi/homelab/buildbuddy', 'community', 'jomcgi', 'homelab', 'jomcgi/homelab', 'buildbuddy', 1, 0, 45, '2026-03-04T00:40:57Z', '2026-03-07T01:55:34.972Z', 'd31a4ed85af09d3fd32ea2bfc960ee2bec1d9a42ac6e18c1f6bfb37580453df4', '{"id":"jomcgi/homelab/buildbuddy","name":"buildbuddy","description":{"en":"buildbuddy facilitates remote build execution and CI debugging for developers, providing tools like buildbuddy-mcp-get-invocation and buildbuddy-mcp-get-log.","zh":"BuildBuddy 是一种远程构建执行和 CI 调试工具，支持 MCP 工具和 Context Forge。它提供了构建元数据、状态和持续时间等功能。","ja":"BuildBuddy はリモートビルド実行と CI デバッグツールです。MCP ツールと Context Forge をサポートしています。ビルドメタデータ、ステータス、-duration などの機能を提供します。","ko":"BuildBuddy는 원격 빌드 실행 및 CI 디버깅 도구입니다. MCP 툴 및 Context Forge를 지원합니다. 빌드 메타데이터, 상태, duration 등의 기능을 제공합니다.","es":"BuildBuddy es una herramienta de ejecución remota de compilaciones y depuración de CI que utiliza herramientas de MCP para automatizar la autenticación y proporcionar metadatos de compilación","fr":"BuildBuddy est un outil d''exécution distante de builds et de débogage de CI qui utilise les outils de MCP pour automatiser l''authentification et fournir des métadonnées de build","de":"BuildBuddy ist ein Tool für die Remote-Ausführung von Builds und die Debugging von CI, das MCP-Tools verwendet, um die Authentifizierung zu automatisieren und Build-Metadaten bereitzustellen","pt":"O BuildBuddy é uma ferramenta de execução remota de build e depuração de CI que usa o MCP Tools para automatizar a autenticação e carregar ferramentas. Ele fornece metadados de build, status e duração","ru":"BuildBuddy - это инструмент удаленной сборки и отладки CI, который использует MCP Tools для автоматизации аутентификации и загрузки инструментов. Он предоставляет метаданные сборки, статус и продолжительность для ИИ Агентов","ar":"BuildBuddy هو أداة لتنفيذ البناء عن بُع