INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('jomcgi/homelab/buildbuddy', 'buildbuddy', 'jomcgi', 'homelab', 'community', 'buildbuddy jomcgi homelab community buildbuddy facilitates remote build execution and CI debugging for developers, providing tools like buildbuddy-mcp-get-invocation and buildbuddy-mcp-get-log. BuildBuddy 是一种远程构建执行和 CI 调试工具，支持 MCP 工具和 Context Forge。它提供了构建元数据、状态和持续时间等功能。 BuildBuddy はリモートビルド実行と CI デバッグツールです。MCP ツールと Context Forge をサポートしています。ビルドメタデータ、ステータス、-duration などの機能を提供します。 BuildBuddy는 원격 빌드 실행 및 CI 디버깅 도구입니다. MCP 툴 및 Context Forge를 지원합니다. 빌드 메타데이터, 상태, duration 등의 기능을 제공합니다. BuildBuddy es una herramienta de ejecución remota de compilaciones y depuración de CI que utiliza herramientas de MCP para automatizar la autenticación y proporcionar metadatos de compilación BuildBuddy est un outil d''exécution distante de builds et de débogage de CI qui utilise les outils de MCP pour automatiser l''authentification et fournir des métadonnées de build BuildBuddy ist ein Tool für die Remote-Ausführung von Builds und die Debugging von CI, das MCP-Tools verwendet, um die Authentifizierung zu automatisieren und Build-Metadaten bereitzustellen O BuildBuddy é uma ferramenta de execução remota de build e depuração de CI que usa o MCP Tools para automatizar a autenticação e carregar ferramentas. Ele fornece metadados de build, status e duração BuildBuddy - это инструмент удаленной сборки и отладки CI, который использует MCP Tools для автоматизации аутентификации и загрузки инструментов. Он предоставляет метаданные сборки, статус и продолжительность для ИИ Агентов BuildBuddy هو أداة لتنفيذ البناء عن بُعد وتصحيح أخطاء CI التي تستخدم MCP Tools للتحكم التلقائي في المصادقة وتحميل الأدوات. يوفر بيانات البناء، الحالة والمدة how to use buildbuddy buildbuddy setup guide buildbuddy alternative buildbuddy vs Jenkins remote build execution CI debugging tools buildbuddy install MCP tools for build management BuildBuddy 远程构建执行 CI 调试 MCP 工具 Context Forge AI 工具 构建元数据 ToolSearch Utilizes MCP tools via Context Forge for authentication Provides build metadata, status, and duration via buildbuddy-mcp-get-invocation Offers full build logs through buildbuddy-mcp-get-log Loads tools with ToolSearch query +buildbuddy Supports remote build execution for streamlined workflows buildbuddy is a remote build execution and CI debugging tool utilizing MCP tools via Context Forge for efficient build management.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('briansunter/kungfu/new-skill', 'community', 'briansunter', 'kungfu', 'briansunter/kungfu', 'new-skill', 0, 0, 45, '2026-02-16T10:46:20Z', '2026-03-07T03:42:19.267Z', '248e50558337068ba32049d45d2685f75770b1aae1dcbb77f401f9ca7f05ce83', '{"id":"briansunter/kungfu/new-skill","name":"new-skill","description":{"en":"The new-skill scaffolder creates a new skill in the kungfu repository with the correct structure and conventions, benefiting AI agent developers. It streamlines the process of setting up a new skill.","zh":"New Skill Scaffolder 是一个创建新技能的工具，帮助您设置正确的结构和约定。只需提供技能名称、描述和子目录即可创建新技能","ja":"New Skill Scaffolder は、AIエージェントの新しいスキルを作成するためのツールです。スキル名、説明、サブディレクトリを指定して、正しい構造と規約でスキルを作成できます","ko":"New Skill Scaffolder는 새로운 스킬을 생성하는 도구로, 올바른 구조와 규칙을 설정하는 데 도움을줍니다. 스킬 이름, 설명, 및 하위 디렉토리를 제공하여 새로운 스킬을 생성할 수 있습니다","es":"new-skill es una herramienta que permite crear un nuevo skill en el repositorio kungfu con la estructura y convenciones correctas. Esto incluye la creación de subdirectorios como references/, scripts/, examples/, templates/ y assets/.","fr":"new-skill est un outil qui permet de créer un nouveau skill dans le référentiel kungfu avec la structure et les conventions appropriées. Cela inclut la création de sous-répertoires tels que references/, scripts/, examples/, templates/ et assets/.","de":"new-skill ist ein Tool, das die Erstellung eines neuen Skills im kungfu-Repository mit der richtigen Struktur und Konventionen ermöglicht. Dazu gehören die Erstellung von Unterordnern wie references/, scripts/, examples/, templates/ und assets/.","pt":"O novo skill do Kungfu permite criar habilidades personalizadas com estrutura e convenções específicas.","ru":"Новое умение в Kungfu позволяет создавать пользовательские навыки с определенной структурой и соглашениями.","ar":"المهارة الجديدة في Kungfu تسمح بإنشاء مهارات 