INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('briansunter/kungfu/new-skill', 'new-skill', 'briansunter', 'kungfu', 'community', 'new-skill briansunter kungfu community The new-skill scaffolder creates a new skill in the kungfu repository with the correct structure and conventions, benefiting AI agent developers. It streamlines the process of setting up a new skill. New Skill Scaffolder 是一个创建新技能的工具，帮助您设置正确的结构和约定。只需提供技能名称、描述和子目录即可创建新技能 New Skill Scaffolder は、AIエージェントの新しいスキルを作成するためのツールです。スキル名、説明、サブディレクトリを指定して、正しい構造と規約でスキルを作成できます New Skill Scaffolder는 새로운 스킬을 생성하는 도구로, 올바른 구조와 규칙을 설정하는 데 도움을줍니다. 스킬 이름, 설명, 및 하위 디렉토리를 제공하여 새로운 스킬을 생성할 수 있습니다 new-skill es una herramienta que permite crear un nuevo skill en el repositorio kungfu con la estructura y convenciones correctas. Esto incluye la creación de subdirectorios como references/, scripts/, examples/, templates/ y assets/. new-skill est un outil qui permet de créer un nouveau skill dans le référentiel kungfu avec la structure et les conventions appropriées. Cela inclut la création de sous-répertoires tels que references/, scripts/, examples/, templates/ et assets/. new-skill ist ein Tool, das die Erstellung eines neuen Skills im kungfu-Repository mit der richtigen Struktur und Konventionen ermöglicht. Dazu gehören die Erstellung von Unterordnern wie references/, scripts/, examples/, templates/ und assets/. O novo skill do Kungfu permite criar habilidades personalizadas com estrutura e convenções específicas. Новое умение в Kungfu позволяет создавать пользовательские навыки с определенной структурой и соглашениями. المهارة الجديدة في Kungfu تسمح بإنشاء مهارات مخصصة مع هيكل واتفاقيات محددة. how to use new-skill what is new-skill new-skill alternative new-skill vs kungfu repository new-skill install new-skill setup guide kungfu repository scaffolder AI agent skill development new-skill documentation New Skill Scaffolder 创建新技能 kebab-case 名称 描述和子目录 AI工具 技能创建工具 步骤式创建过程 Gathers skill information, including name, description, and subdirectories Creates a directory and SKILL.md file with the correct structure Supports optional subdirectories like references/, scripts/, examples/, templates/, and assets/ Follows kebab-case naming convention for skill names Limits description to a single line with a maximum of 1024 characters new-skill is a scaffolder that generates a new skill in the kungfu repository with the correct structure and conventions, including optional subdirectories like references/, scripts/, and examples/.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('mcauduro0/Macro_Trading/ln-730-devops-setup', 'community', 'mcauduro0', 'Macro_Trading', 'mcauduro0/Macro_Trading', 'ln-730-devops-setup', 0, 0, 45, '2026-03-03T01:05:47Z', '2026-03-07T03:44:04.293Z', 'f7552408710441afd78a2d4e426537b618341260ec3e03948fa4d4ea5761e332', '{"id":"mcauduro0/Macro_Trading/ln-730-devops-setup","name":"ln-730-devops-setup","description":{"en":"The ln-730-devops-setup skill coordinates DevOps infrastructure setup by delegating to specialized workers, benefiting developers and project managers. It auto-detects stack and orchestrates the complete DevOps setup.","zh":"ln-730-devops-setup 是一个协调 DevOps 设置的 AI 工具，自动检测栈并委托给专门的工人","ja":"ln-730-devops-setup は DevOps 設定を調整する AI エージェントで、スタックを自動検出して専門のワーカーに委任します","ko":"ln-730-devops-setup은 DevOps 설정을 조정하는 AI 에이전트로, 스택을 자동으로 감지하고 전문 작업자에게 위임합니다","es":"ln-730-devops-setup es un coordinador de dominio de nivel 2 que configura la infraestructura DevOps para proyectos, incluyendo la detección automática de la pila.","fr":"ln-730-devops-setup est un coordinateur de domaine de niveau 2 qui met en place l''infrastructure DevOps pour les projets, y compris la détection automatique de la pile.","de":"ln-730-devops-setup ist ein Koordinator der Domäne der Ebene 2, der die DevOps-Infrastruktur für Projekte einrichtet, einschließlich der automatischen Erkennung des Stacks.","pt":"O ln-730-devops-setup é um agente de coordenação de domínio L2 que automatiza a configuração da infraestrutura DevOps, incluindo a detecção automática de pilha.","ru":"ln-730-devops-setup - это координатор домена L2, который автоматизирует настройку инфраструктуры DevOps, включая автоматическое обнаружение стека","ar":"ln-730-devops-setup هو منسق مجال L2 ي自動یکيا يعداد بنية تحتية DevOps، بما في ذلك الكشف التلقائي عن الستك"},"seo":{"title":{"en":"ln-730-devops-setup: DevOps Infrastructure Setup Guide | ...","zh":"ln-730-devops-setup 设置指南 - 自动化 DevOps 基础设施","ja":"ln-730-devops-setup Setup Guide - 自動化 DevOps インフラストラクチャ","ko":"ln-730-devops-setup 설정 가이드 - 자동화 DevOps 인프라","es":"ln-730-devops-setup: Guía de configuración de infraestruc...","fr":"ln-730-devops-setup: Guide de mise en place de l''infrastr...","de":"ln-730-devops-setup: Leitfaden für die Einrichtung von De...","pt":"ln-730-devops-setup: Guia de Configuração de Infraestrutu...","ru":"ln-730-devops-setup: Настройка инфраструктуры DevOps с по...","ar":"ln-730-devops-setup: دليل إعداد بنية تحتية DevOps باستخدا..."},"description":{"en":"Discover how to orchestrate complete DevOps setup with ln-730-devops-setup. Learn to auto-detect stack and delegate to specialized workers. Get started now!","zh":"ln-730-devops-setup 是一个协调 DevOps 设置的 AI 工具，自动检测栈并委托给专门的工人，实现项目的自动化 DevOps 基础设施设置","ja":"ln-730-devops-setup は DevOps 設定を調整する AI エージェントで、スタックを自動検出して専門のワーカーに委任し、プロジェクトの自動化 DevOps インフラストラクチャ設定を実現します","ko":"ln-730-devops-setup은 DevOps 설정을 조정하는 AI 에이전트로, 스택을 자동으로 감지하고 전문 작업자에게 위임하여 프로젝트의 자동화 DevOps 인프라 설정을 구현합니다","es":"Descubre cómo ln-730-devops-setup coordina la configuración de infraestructura DevOps para proyectos, incluyendo la detección automática de la pila","fr":"Découvrez comment ln-730-devops-setup coordonne la mise en place de l''infrastructure DevOps pour les projets, y compris la détection automatique de la pile","de":"Erfahren Sie, wie ln-730-devops-setup die Einrichtung von DevOps-Infrastruktur für Projekte koordiniert, einschließlich der automatischen Erkennung des Stacks","pt":"Aprenda a configurar a infraestrutura DevOps com o ln-730-devops-setup, um agente de coordenação de domínio L2 que automatiza a detecção de pilha","ru":"Узнайте, как настроить инфраструктуру DevOps с помощью ln-730-devops-setup, координатора домена L2, который автоматизирует обнаружение стека","ar":"تعرف على كيفية إعداد بنية تحتية DevOps باستخدام ln-730-devops-setup، منسق مجال L2 ي автомاتيكيا يكتشف الستك"},"definition":{"en":"ln-730-devops-setup is a L2 Domain Coordinator skill that coordinates DevOps infrastructure setup for projects, utilizing relative file paths and specialized workers.","zh":"ln-730-devops-setup 是一种协调 DevOps 设置的 AI 工具，用于自动化项目的 DevOps 基础设施设置","ja":"ln-730-devops-setup は DevOps 設定を調整する AI エージェントの 1 つで、プロジェクトの DevOps インフラストラクチャ設定を自動化するために使用されます","ko":"ln-730-devops-setup은 DevOps 설정을 조정하는 AI 에이전트의 하나로, 프로젝트의 DevOps 인프라 설정을 자동화하기 위해 사용됩니다","es":"ln-730-devops-setup es un agente de AI que coordina la configuración de infraestructura DevOps para proyectos","fr":"ln-730-devops-setup est un agent IA qui coordonne la mise en place de l''infrastructure DevOps pour les projets","de":"ln-730-devops-setup ist ein KI-Agent, der die Einrichtung von DevOps-Infrastruktur für Projekte koordiniert","pt":"O que é ln-730-devops-setup? É um agente de coordenação de domínio L2 para configuração de infraestrutura DevOps","ru":"Что такое ln-730-devops-setup? Это координатор домена L2 для настройки инфраструктуры DevOps","ar":"ما هو ln-730-devops-setup? هو منسق مجال L2 لعداد بنية تحتية DevOps"},"features":{"en":["Orchestrates complete DevOps setup for projects","Auto-detects stack for streamlined infrastructure setup","Utilizes relative file paths (shared/, references/, ../ln-*) for flexibility","Delegates to specialized workers for efficient task management","Coordinates with parent skill ln-700-project-bootstrap for comprehensive project setup"],"zh":["自动检测栈","委托给专门的工人","实现项目的自动化 DevOps 基础设施设置","支持多种文件路径","兼容多种项目类型"],"ja":["スタックの自動検出","専門のワーカーへの委任","プロジェクトの自動化 DevOps インフラストラクチャ設定","多種類のファイルパスのサポート","多種類のプロジェクトタイプの互換性"],"ko":["스택 자동 감지","전문 작업자에게 위임","프로젝트의 자동화 DevOps 인프라 설정","다양한 파일 경로 지원","다양한 프로젝트 유형 호환"],"es":["Coordinación de la configuración de infraestructura DevOps","Detección automática de la pila","Soporte para proyectos de nivel 7","Integración con trabajadores especializados","Configuración de rutas de archivos relativas","Compatibilidad con directorios de habilidades"],"fr":["Coordination de la mise en place de l''infrastructure DevOps","Détection automatique de la pile","Prise en charge des projets de niveau 7","Intégration avec des travailleurs spécialisés","Configuration des chemins de fichiers relatifs","Compatibilité avec les répertoires de compétences"],"de":["Koordination der Einrichtung von DevOps-Infrastruktur","Automatische Erkennung des Stacks","Unterstützung für Projekte der Ebene 7","Integration mit spezialisierten Arbeitern","Konfiguration von relativen Dateipfaden","Kompatibilität mit Fähigkeitsverzeichnissen"],"pt":["Configuração automática de infraestrutura DevOps","Detecção automática de pilha","Coordenação de trabalhadores especializados","Integração com o projeto ln-700-project-bootstrap"],"ru":["Автоматическая настройка инфраструктуры DevOps","Автоматическое обнаружение стека","Координация работы специализированных рабочих","Интеграция с проектом ln-700-project-bootstrap"],"ar":["تعداد تلقائي لبنية تحتية DevOps","اكتشاف تلقائي للستك","تنسيق عمال متخصصين","التكامل مع مشروع ln-700-project-bootstrap"]},"keywords":{"en":["how to use ln-730-devops-setup","ln-730-devops-setup setup guide","DevOps infrastructure setup","ln-730-devops-setup alternative","ln-730-devops-setup vs competitors","auto-detect stack DevOps","ln-730-devops-setup install","L2 Domain Coordinator skills"],"zh":["ln-730-devops-setup","AI 工具","DevOps 设置","自动化基础设施","项目管理","DevOps 工具","自动化设置","AI 에이전트"],"ja":["ln-730-devops-setup","AI エージェント","DevOps 設定","自動化インフラストラクチャ","プロジェクト管理","DevOps ツール","自動化設定","AI ツール"],"ko":["ln-730-devops-setup","AI 에이전트","DevOps 설정","자동화 인프라","프로젝트 관리","DevOps 도구","자동화 설정","AI 도구"],"es":["ln-730-devops-setup","configuración de infraestructura DevOps","detección automática de la pila","proyectos de nivel 7","trabajadores especializados","ruta de archivos relativa","directorio de habilidades","herramientas de AI para DevOps"],"fr":["ln-730-devops-setup","mise en place de l''infrastructure DevOps","détection automatique de la pile","projets de niveau 7","travailleurs spécialisés","chemin de fichier relatif","répertoire de compétences","outils IA pour DevOps"],"de":["ln-730-devops-setup","Einrichtung von DevOps-Infrastruktur","automatische Erkennung des Stacks","Projekte der Ebene 7","spezialisierte Arbeiter","relativer Dateipfad","Fähigkeitsverzeichnis","KI-Tools für DevOps"],"pt":["ln-730-devops-setup","configuração de infraestrutura DevOps","detecção de pilha","coordenação de trabalhadores","projeto ln-700-project-bootstrap","DevOps","infraestrutura","automatização"],"ru":["ln-730-devops-setup","настройка инфраструктуры DevOps","обнаружение стека","координация рабочих","проект ln-700-project-bootstrap","DevOps","инфраструктура","автоматизация"],"ar":["ln-730-devops-setup","عداد بنية تحتية DevOps","اكتشاف الستك","تنسيق عمال","مشروع ln-700-project-bootstrap","DevOps","بنية تحتية","تоличество"]}},"owner":"mcauduro0","repo":"Macro_Trading","repoPath":"mcauduro0/Macro_Trading","stars":0,"forks":0,"updatedAt":"2026-03-03T01:05:47Z","topics":[],"category":"community","skillMd":{"name":"ln-730-devops-setup","description":"Coordinates Docker, CI/CD, and environment configuration setup via auto-detection","bodyPreview":"> **Paths:** File paths (`shared/`, `references/`, `../ln-*`) are relative to skills repo root. If not found at CWD, locate this SKILL.md directory and go up one level for repo root.\n\n# ln-730-devops-setup\n\n**Type:** L2 Domain Coordinator\n**Category:** 7XX Project Bootstrap\n**Parent:** ln-700-project-bootstrap\n\nCoordinates DevOps infrastructure setup by delegating to specialized workers.\n\n---\n\n## Purpose & Scope\n\nOrchestrates the complete DevOps setup for a project:\n- **Does**: Auto-detect stack","body":"> **Paths:** File paths (`shared/`, `references/`, `../ln-*`) are relative to skills repo root. If not found at CWD, locate this SKILL.md directory and go up one level for repo root.\n\n# ln-730-devops-setup\n\n**Type:** L2 Domain Coordinator\n**Category:** 7XX Project Bootstrap\n**Parent:** ln-700-project-bootstrap\n\nCoordinates DevOps infrastructure setup by delegating to specialized workers.\n\n---\n\n## Purpose & Scope\n\nOrchestrates the complete DevOps setup for a project:\n- **Does**: Auto-detect stack, delegate to workers, verify configuration\n- **Does NOT**: Generate files directly (delegates to ln-731, ln-732, ln-733)\n\n---\n\n## Overview\n\n| Aspect | Details |\n|--------|---------|\n| **Input** | Project directory with source code |\n| **Output** | Docker, CI/CD, environment configuration |\n| **Workers** | ln-731 (Docker), ln-732 (CI/CD), ln-733 (Environment) |\n| **Mode** | Auto-detect (no user prompts) |\n\n---\n\n## Supported Stacks\n\n| Component | Option 1 | Option 2 |\n|-----------|----------|----------|\n| **Frontend** | React/Vite + Nginx | - |\n| **Backend** | .NET 8/9 | Python (FastAPI/Django) |\n| **Database** | PostgreSQL | - |\n| **CI/CD** | GitHub Actions | - |\n\n---\n\n## Workflow\n\n### Phase 1: Pre-flight Validation\n\nCheck required tools and project structure:\n- Verify Docker is installed (`docker --version`)\n- Verify docker-compose is available\n- Check for existing DevOps files (warn if overwriting)\n\n**Output**: Validation report or STOP with instructions\n\n### Phase 2: Project Analysis (Auto-detect)\n\nDetect project stack automatically:\n\n| Detection | Method | Files to Check |\n|-----------|--------|----------------|\n| **Frontend** | Package.json presence | `src/frontend/package.json`, `package.json` |\n| **Backend .NET** | .csproj/.sln presence | `*.sln`, `src/**/*.csproj` |\n| **Backend Python** | requirements.txt/pyproject.toml | `requirements.txt`, `pyproject.toml` |\n| **Database** | Connection strings in code | `appsettings.json`, `.env.example` |\n| **Existing CI/CD** | Workflow files | `.github/workflows/`, `azure-pipelines.yml` |\n\n**Version Detection**:\n- Node.js: Read from `package.json` engines or use `node -v`\n- .NET: Read from `*.csproj` TargetFramework\n- Python: Read from `pyproject.toml` or `runtime.txt`\n- PostgreSQL: Default to latest stable (17)\n\n**Output**: Stack configuration object with detected versions\n\n### Phase 3: Worker Delegation\n\nDelegate to workers in parallel (independent tasks):\n\n```\nln-730 (Coordinator)\n    |\n    +---> ln-731-docker-generator (via Task tool)\n    |         Input: stack config, versions\n    |         Output: Dockerfile.*, docker-compose.yml, .dockerignore\n    |\n    +---> ln-732-cicd-generator (via Task tool)\n    |         Input: stack config, detected commands\n    |         Output: .github/workflows/ci.yml\n    |\n    +---> ln-733-env-configurator (via Task tool)\n              Input: detected environment variables\n              Output: .env.example, .env.development, .gitignore updates\n```\n\n**Error Handling**:\n- If worker fails, log error and continue with others\n- Report all failures at the end\n- Suggest manual fixes for failed components\n\n### Phase 4: Configuration Verification\n\nVerify generated configuration:\n- Run `docker-compose config` to validate syntax\n- Check all referenced files exist\n- Verify no secrets in committed files\n\n**Output**: Verification report\n\n### Phase 5: Completion Report\n\nGenerate summary:\n- List all created files\n- Show detected stack configuration\n- Provide next steps for user\n\n---\n\n## Generated Files\n\n### Docker (ln-731)\n- `Dockerfile.frontend` - Multi-stage build for frontend\n- `Dockerfile.backend` - Multi-stage build for backend\n- `docker-compose.yml` - Service orchestration\n- `docker-compose.override.yml` - Development overrides (optional)\n- `.dockerignore` - Build context exclusions\n\n### CI/CD (ln-732)\n- `.github/workflows/ci.yml` - Main CI pipeline\n\n### Environment (ln-733)\n- `.env.example` - Template with all variables\n- `.env.development` - Development defaults\n- `.env.production` - Production template (placeholders)\n- `.gitignore` updates - Secrets protection\n\n---\n\n## Critical Notes\n\n1. **Auto-detect Only**: No interactive prompts. Uses detected values or sensible defaults.\n2. **Idempotent**: Check file existence before creation. Warn before overwriting.\n3. **Parallel Execution**: Workers are independent, can run in parallel.\n4. **Error Recovery**: Continue on partial failures, report all issues at end.\n5. **Version Pinning**: Use detected versions, not hardcoded values.\n\n---\n\n## Definition of Done\n\n- [ ] Pre-flight validation passed\n- [ ] Stack auto-detected successfully\n- [ ] All workers completed (or failures documented)\n- [ ] `docker-compose config` validates successfully\n- [ ] No secrets in generated files\n- [ ] Completion report displayed\n\n---\n\n## Reference Files\n\n- Worker: `../ln-731-docker-generator/SKILL.md`\n- Worker: `../ln-732-cicd-generator/SKILL.md`\n- Worker: `../ln-733-env-configurator/SKILL.md`\n\n---\n\n**Version:** 1.1.0\n**Last Updated:** 2026-01-10\n"},"lastSynced":"2026-03-07T03:44:04.293Z","agentAnalysis":{"suitability":{"en":"Perfect for Project Management Agents needing automated DevOps infrastructure setup and coordination.","zh":"非常适合需要自动化 DevOps 基础设施设置和协调的项目管理代理。","ja":"プロジェクト管理エージェントが自動化された DevOps インフラストラクチャ設定と調整を必要とする場合に最適です。","ko":"자동화된 DevOps 인프라 설정 및 조정을 필요한 프로젝트 관리 에이전트에게 적합합니다.","es":"Perfecto para Agentes de Gestión de Proyectos que necesitan una configuración de infraestructura de DevOps automatizada y coordinación.","fr":"Parfait pour les agents de gestion de projet nécessitant une configuration d''infrastructure DevOps automatisée et une coordination.","de":"Perfekt für Projektmanagement-Agenten, die eine automatisierte DevOps-Infrastruktur-Einrichtung und -Koordination benötigen.","pt":"Perfeito para Agentes de Gerenciamento de Projetos que precisam de configuração e coordenação de infraestrutura de DevOps automatizada.","ru":"Идеально подходит для агентов по управлению проектами, которым требуется автоматизированная настройка и координация инфраструктуры DevOps.","ar":"مثالي لعمليات إدارة المشاريع التي تحتاج إلى إعداد وتشغيل بنية ديف أوبس آلي."},"recommendation":{"en":"Empowers agents to orchestrate complete DevOps setups by auto-detecting stacks and delegating tasks to specialized workers, utilizing relative file paths and coordinating project bootstrap processes.","zh":"使代理能够通过自动检测堆栈并将任务委托给专用工作者，利用相对文件路径和协调项目引导过程来编排完整的 DevOps 设置。","ja":"エージェントがスタックを自動検出してタスクを専用のワーカーに委託し、相対ファイルパスを利用してプロジェクトのブートストラッププロセスを調整することで、完全な DevOps の設定をオーケストレーションできるようにします。","ko":"에이전트가 스택을 자동으로 감지하고 작업을 전문 작업자에게 위임하여 상대 파일 경로를 활용하고 프로젝트 부트스트랩 프로세스를 조정하여完整한 DevOps 설정을 오케스트레이션 할 수 있도록 합니다.","es":"Habilita a los agentes a orquestar configuraciones de DevOps completas mediante la auto-detección de pilas y la delegación de tareas a trabajadores especializados, utilizando rutas de archivo relativas y coordinando procesos de arranque de proyectos.","fr":"Permet aux agents d''orchestrer des configurations DevOps complètes en auto-détectant les piles et en déléguant des tâches à des travailleurs spécialisés, en utilisant des chemins de fichiers relatifs et en coordonnant les processus de démarrage de projet.","de":"Ermächtigt Agenten, komplette DevOps-Setups zu orchestrieren, indem sie Stacks automatisch erkennen und Aufgaben an spezialisierte Arbeiter delegieren, wobei relative Dateipfade verwendet und Projekt-Bootstrap-Prozesse koordiniert werden.","pt":"Habilita os agentes a orquestrar configurações de DevOps completas, detectando pilhas automaticamente e delegando tarefas a trabalhadores especializados, utilizando caminhos de arquivos relativos e coordenando processos de inicialização do projeto.","ru":"Позволяет агентам оркестрировать полные настройки DevOps, автоматически обнаруживая стеки и делегируя задачи специализированным работникам, используя относительные пути файлов и координируя процессы инициализации проекта.","ar":"تمكّن الوكيل من تنسيق إعدادات ديف أوبس الكاملة عن طريق الكشف التلقائي عن المكدسات و تفويض المهام إلى العمال المتخصصين، واستخدام مسارات الملفات النسبية وتنسيق عمليات بدء التشغيل للمشروع."},"useCases":{"en":["Automating DevOps infrastructure setup for new projects","Coordinating project bootstrap processes across multiple teams","Auto-detecting and configuring stacks for efficient project management"],"zh":["为新项目自动化 DevOps 基础设施设置","跨多个团队协调项目引导过程","自动检测和配置堆栈以实现高效的项目管理"],"ja":["新しいプロジェクトの DevOps インフラストラクチャ設定の自動化","複数のチーム間でプロジェクトのブートストラッププロセスを調整","スタックを自動検出して設定し、効率的なプロジェクト管理を行う"],"ko":["새로운 프로젝트를 위한 DevOps 인프라 설정 자동화","여러 팀을 걸쳐 프로젝트 부트스트랩 프로세스 조정","스택 자동 감지 및 구성으로 효율적인 프로젝트 관리"],"es":["Automatización de la configuración de la infraestructura de DevOps para nuevos proyectos","Coordinación de los procesos de arranque de proyectos en varios equipos","Auto-detección y configuración de pilas para una gestión de proyectos eficiente"],"fr":["Automatisation de la configuration de l''infrastructure DevOps pour les nouveaux projets","Coordination des processus de démarrage de projet à travers plusieurs équipes","Détection et configuration automatiques des piles pour une gestion de projet efficace"],"de":["Automatisierung der DevOps-Infrastruktur-Einrichtung für neue Projekte","Koordination von Projekt-Bootstrap-Prozessen über mehrere Teams hinweg","Automatische Erkennung und Konfiguration von Stacks für eine effiziente Projektverwaltung"],"pt":["Automatizar a configuração de infraestrutura de DevOps para novos projetos","Coordenar processos de inicialização do projeto em várias equipes","Detectar automaticamente e configurar pilhas para gerenciamento de projeto eficiente"],"ru":["Автоматизировать настройку инфраструктуры DevOps для новых проектов","Координировать процессы инициализации проекта в нескольких командах","Автоматически обнаруживать и настраивать стеки для эффективного управления проектом"],"ar":["توفير إعداد بنية ديف أوبس آلي لمشاريع جديدة","تنسيق عمليات بدء تشغيل المشروع عبر فرق متعددة","اكتشاف وتكوين المكدسات تلقائيًا من أجل إدارة مشروع فعالة"]},"limitations":{"en":["Requires access to skills repository root for relative file path resolution","Dependent on specialized workers for task delegation","Limited to projects with auto-detectable stacks"],"zh":["需要访问技能存储库根目录以解析相对文件路径","依赖于专用工作者进行任务委托","仅限于具有自动检测堆栈的项目"],"ja":["相対ファイルパスの解決のためにスキルリポジトリのルートにアクセスする必要がある","タスクの委託には専用のワーカーに依存する","自動検出可能なスタックを持つプロジェクトのみに限定される"],"ko":["상대 파일 경로를 해결하기 위해 스킬 저장소 루트에 액세스해야 함","작업 위임에는 전문 작업자에 의존함","자동 감지 가능한 스택을 갖춘 프로젝트만 해당"],"es":["Requiere acceso a la raíz del repositorio de habilidades para la resolución de rutas de archivo relativas","Dependiente de trabajadores especializados para la delegación de tareas","Limitado a proyectos con pilas auto-detectables"],"fr":["Nécessite un accès à la racine du référentiel de compétences pour la résolution des chemins de fichiers relatifs","Dépendant de travailleurs spécialisés pour la délégation de tâches","Limité aux projets avec des piles auto-détectables"],"de":["Benötigt Zugriff auf die Wurzel des Skills-Repository für die Auflösung relativer Dateipfade","Abhängig von spezialisierten Arbeitern für die Aufgabenübertragung","Begrenzt auf Projekte mit auto-erkennbaren Stacks"],"pt":["Requer acesso à raiz do repositório de habilidades para resolução de caminho de arquivo relativo","Dependente de trabalhadores especializados para delegação de tarefas","Limitado a projetos com pilhas detectáveis automaticamente"],"ru":["Требует доступа к корню хранилища навыков для разрешения относительного пути файла","Зависит от специализированных работников для делегирования задач","Ограничен проектами со стеками, обнаруживаемыми автоматически"],"ar":["يتطلب الوصول إلى 根 للمخزن المهارات لحل مسار الملف النسبي","يعتمد على العمال المتخصصين لتفويض المهام","محدود بمشاريع تحتوي على مكدسات يمكن الكشف عنها تلقائيًا"]},"version":4},"contentHash":"f7552408710441afd78a2d4e426537b618341260ec3e03948fa4d4ea5761e332","qualityScore":45}');
