INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('mcauduro0/Macro_Trading/ln-730-devops-setup', 'ln-730-devops-setup', 'mcauduro0', 'Macro_Trading', 'community', 'ln-730-devops-setup mcauduro0 Macro_Trading community The ln-730-devops-setup skill coordinates DevOps infrastructure setup by delegating to specialized workers, benefiting developers and project managers. It auto-detects stack and orchestrates the complete DevOps setup. ln-730-devops-setup 是一个协调 DevOps 设置的 AI 工具，自动检测栈并委托给专门的工人 ln-730-devops-setup は DevOps 設定を調整する AI エージェントで、スタックを自動検出して専門のワーカーに委任します ln-730-devops-setup은 DevOps 설정을 조정하는 AI 에이전트로, 스택을 자동으로 감지하고 전문 작업자에게 위임합니다 ln-730-devops-setup es un coordinador de dominio de nivel 2 que configura la infraestructura DevOps para proyectos, incluyendo la detección automática de la pila. ln-730-devops-setup est un coordinateur de domaine de niveau 2 qui met en place l''infrastructure DevOps pour les projets, y compris la détection automatique de la pile. ln-730-devops-setup ist ein Koordinator der Domäne der Ebene 2, der die DevOps-Infrastruktur für Projekte einrichtet, einschließlich der automatischen Erkennung des Stacks. O ln-730-devops-setup é um agente de coordenação de domínio L2 que automatiza a configuração da infraestrutura DevOps, incluindo a detecção automática de pilha. ln-730-devops-setup - это координатор домена L2, который автоматизирует настройку инфраструктуры DevOps, включая автоматическое обнаружение стека ln-730-devops-setup هو منسق مجال L2 ي自動یکيا يعداد بنية تحتية DevOps، بما في ذلك الكشف التلقائي عن الستك how to use ln-730-devops-setup ln-730-devops-setup setup guide DevOps infrastructure setup ln-730-devops-setup alternative ln-730-devops-setup vs competitors auto-detect stack DevOps ln-730-devops-setup install L2 Domain Coordinator skills ln-730-devops-setup AI 工具 DevOps 设置 自动化基础设施 项目管理 DevOps 工具 自动化设置 AI 에이전트 Orchestrates complete DevOps setup for projects Auto-detects stack for streamlined infrastructure setup Utilizes relative file paths (shared/, references/, ../ln-*) for flexibility Delegates to specialized workers for efficient task management Coordinates with parent skill ln-700-project-bootstrap for comprehensive project setup ln-730-devops-setup is a L2 Domain Coordinator skill that coordinates DevOps infrastructure setup for projects, utilizing relative file paths and specialized workers.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('phamhoangtuan/learn-de-opencode/specify-flow', 'community', 'phamhoangtuan', 'learn-de-opencode', 'phamhoangtuan/learn-de-opencode', 'specify-flow', 0, 0, 45, '2026-03-05T09:10:53Z', '2026-03-07T03:45:23.409Z', '0e02b137f5125f7f7c489026fe6e4d19e446f67e8691f5bb3d0d36cda56ad8d3', '{"id":"phamhoangtuan/learn-de-opencode/specify-flow","name":"specify-flow","description":{"en":"Specify-flow is an orchestration agent that drives the Speckit SDD pipeline end-to-end, guiding users through 9 commands in a linear pipeline. It benefits AI agents and developers working with data pipelines.","zh":"Specify Flow 是一个orchestration agent，用于驱动 Speckit Spec-Driven Development (SDD) 流程。它指导用户完成每个阶段的构建数据管道","ja":"Specify Flow は、Speckit Spec-Driven Development (SDD) プロセスをエンドツーエンドで駆動するオーケストレーションエージェントです","ko":"Specify Flow는 Speckit Spec-Driven Development (SDD) 프로세스를 엔드 투 엔드에서 구동하는 오케스트레이션 에이전트입니다","es":"Specify Flow es un agente de orquestación que gestiona el pipeline de desarrollo de Speckit. Aprende a configurarlo","fr":"Specify Flow est un agent d''orchestration qui gère le pipeline de développement de Speckit. Apprenez à le configurer","de":"Specify Flow ist ein Orchestrierungsagent, der den Speckit-Entwicklungspipeline verwaltet. Erfahren Sie, wie Sie ihn konfigurieren","pt":"Specify Flow é uma habilidade de orquestração que guia o usuário através de um pipeline de dados linear com 9 comandos.","ru":"Specify Flow - это способность оркестрации, которая ведет пользователя через линейный конвейер данных с 9 командами, ИИ Агенты.","ar":"Specify Flow هو قدرة على تنسيق يوجه المستخدم من خلال трубة بيانات خطية مع 9 أوامر، أدوات الذكاء الاصطناعي"},"seo":{"title":{"en":"Specify-Flow: Setup Guide for AI Agents | AI Agent Skill","zh":"Specify Flow Setup Guide: 使用 Opencode 和 Speckit 构建数据管道","ja":"Specify Flow のベストプラクティス: AIエージェントを使用したデー