INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('phamhoangtuan/learn-de-opencode/specify-flow', 'specify-flow', 'phamhoangtuan', 'learn-de-opencode', 'community', 'specify-flow phamhoangtuan learn-de-opencode community Specify-flow is an orchestration agent that drives the Speckit SDD pipeline end-to-end, guiding users through 9 commands in a linear pipeline. It benefits AI agents and developers working with data pipelines. Specify Flow 是一个orchestration agent，用于驱动 Speckit Spec-Driven Development (SDD) 流程。它指导用户完成每个阶段的构建数据管道 Specify Flow は、Speckit Spec-Driven Development (SDD) プロセスをエンドツーエンドで駆動するオーケストレーションエージェントです Specify Flow는 Speckit Spec-Driven Development (SDD) 프로세스를 엔드 투 엔드에서 구동하는 오케스트레이션 에이전트입니다 Specify Flow es un agente de orquestación que gestiona el pipeline de desarrollo de Speckit. Aprende a configurarlo Specify Flow est un agent d''orchestration qui gère le pipeline de développement de Speckit. Apprenez à le configurer Specify Flow ist ein Orchestrierungsagent, der den Speckit-Entwicklungspipeline verwaltet. Erfahren Sie, wie Sie ihn konfigurieren Specify Flow é uma habilidade de orquestração que guia o usuário através de um pipeline de dados linear com 9 comandos. Specify Flow - это способность оркестрации, которая ведет пользователя через линейный конвейер данных с 9 командами, ИИ Агенты. Specify Flow هو قدرة على تنسيق يوجه المستخدم من خلال трубة بيانات خطية مع 9 أوامر، أدوات الذكاء الاصطناعي how to use specify-flow what is specify-flow specify-flow setup guide specify-flow alternative specify-flow vs speckit specify-flow install building data pipelines with opencode speckit Spec-Driven Development AI agent skills for data pipeline management Specify Flow Opencode Speckit 数据管道 Speckit Spec-Driven Development AI 工具 orchestration agent 数据处理 Guides users through 9 commands in a linear Speckit workflow pipeline Ensures prerequisites are met before advancing to the next step Supports optional side branches in the pipeline Uses opencode for building data pipelines Utilizes speckit for Spec-Driven Development (SDD) Drives the pipeline end-to-end in strict sequential order Specify-flow is an AI agent skill that enables the building of data pipelines using opencode and speckit, following a linear pipeline with 9 commands.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('Salmanferozkhan/Cloud-and-fast-api/microsoft-agent-framework', 'community', 'Salmanferozkhan', 'Cloud-and-fast-api', 'Salmanferozkhan/Cloud-and-fast-api', 'microsoft-agent-framework', 0, 0, 45, '2026-01-17T11:39:10Z', '2026-03-07T03:47:13.632Z', 'e2026755feea920daff2a6b682e759be3d18ebca7c0a5141814d6b5fac786e42', '{"id":"Salmanferozkhan/Cloud-and-fast-api/microsoft-agent-framework","name":"microsoft-agent-framework","description":{"en":"Microsoft Agent Framework is a framework for building AI agents and multi-agent workflows, providing graph-based workflows with streaming and checkpointing capabilities. It benefits developers and organizations working with AI and machine learning.","zh":"Microsoft Agent Framework是一个用于构建、编排和部署AI代理和多代理工作流的框架","ja":"Microsoft Agent Frameworkは、AIエージェントとマルチエージェントワークフローを構築、オーケストレーション、デプロイするためのフレームワークです","ko":"Microsoft Agent Framework는 AI 에이전트와 멀티 에이전트 워크플로를 구축, 오케스트레이션, 배포하기 위한 프레임워크입니다","es":"Microsoft Agent Framework es un marco para construir y desplegar agentes de AI y flujos de trabajo de multi-agente con capacidades de streaming y checkpointing","fr":"Microsoft Agent Framework est un cadre pour construire et déployer des agents d''IA et des flux de travail de multi-agent avec des fonctionnalités de streaming et de point de contrôle","de":"Microsoft Agent Framework ist ein Rahmenwerk zum Erstellen und Bereitstellen von AI-Agents und Multi-Agent-Workflows mit Streaming- und Checkpointing-Funktionen","pt":"O Microsoft Agent Framework é uma estrutura para construir, orquestrar e implantar agentes de IA e fluxos de trabalho de vários agentes","ru":"Microsoft Agent Framework — это каркас для создания, оркестровки и развертывания ИИ Агентов и потоков работы нескольких агентов","ar":"إطار عمل Microsoft Agent هو هيكل لبناء وتحريك وتركيب وكلاء الذكاء الاصطناعي وتدفقات العمل المتعددة"},"seo":{"title":{"en":"Microsoft Agent Framework: Setup Guide for AI Agents","zh":"Microsoft Agent Framework 安装指南 - AIエージェント开发","ja":"Microsoft Agent Framework Setup Guide - AIエージェントの開発","ko":"Microsoft Agent Framework 설정 가이드 - AI 에이전트 개발","es":"Guía de configuración de Microsoft Agent Framework para d...","fr":"Guide de mise en route de Microsoft Agent Framework pour ...","de":"Einrichtungsleitfaden für Microsoft Agent Framework für E...","pt":"Guia de Configuração do Microsoft Agent Framework para De...","ru":"Настройка Microsoft Agent Framework: Руководство для разр...","ar":"دليل تركيب إطار عمل Microsoft Agent للعاملين في مجال الذك..."},"description":{"en":"Discover how to build and deploy AI agents with Microsoft Agent Framework. Learn to install and use graph-based workflows with streaming and checkpointing ca...","zh":"了解Microsoft Agent Framework的功能和特点，包括图形工作流、流式处理和人机交互等","ja":"Microsoft Agent Frameworkの機能と特徴を紹介します。グラフベースのワークフロー、ストリーミング、ヒューマンインザループなど","ko":"Microsoft Agent Framework의 기능과 특징을 알아보세요. 그래프 기반 워크플로, 스트리밍, 인간과 상호작용 등","es":"Aprende a utilizar Microsoft Agent Framework para construir flujos de trabajo de AI con capacidades de streaming y checkpointing","fr":"Découvrez comment utiliser Microsoft Agent Framework pour créer des flux de travail d''IA avec des fonctionnalités de streaming et de point de contrôle","de":"Erfahren Sie, wie Sie Microsoft Agent Framework verwenden, um AI-Workflows mit Streaming- und Checkpointing-Funktionen zu erstellen","pt":"Aprenda a configurar o Microsoft Agent Framework para construir fluxos de trabalho de agentes de IA com recursos de streaming e checkpointing","ru":"Узнайте, как настроить Microsoft Agent Framework для создания потоков работы ИИ Агентов с функциями потоковой передачи и checkpointing","ar":"تعلم كيفية تركيب إطار عمل Microsoft Agent لبناء تدفقات عمل وكلاء الذكاء الاصطناعي مع ميزات البث والتحقق"},"definition":{"en":"Microsoft Agent Framework is a framework for building, orchestrating, and deploying AI agents and multi-agent workflows with graph-based workflows and streaming capabilities.","zh":"Microsoft Agent Framework是一种用于构建和部署AI代理的框架","ja":"Microsoft Agent Frameworkは、AIエージェントを構築、デプロイするためのフレームワークです","ko":"Microsoft Agent Framework는 AI 에이전트를 구축, 배포하기 위한 프레임워크입니다","es":"Microsoft Agent Framework es un marco de trabajo para la creación de agentes de AI y flujos de trabajo de multi-agente","fr":"Microsoft Agent Framework est un cadre de travail pour la création d''agents d''IA et de flux de travail de multi-agent","de":"Microsoft Agent Framework ist ein Rahmenwerk für die Erstellung von AI-Agents und Multi-Agent-Workflows","pt":"O Microsoft Agent Framework é um conjunto de ferramentas para desenvolvedores de IA","ru":"Microsoft Agent Framework — это набор инструментов для разработчиков ИИ Агентов","ar":"إطار عمل Microsoft Agent هو مجموعة من الأدوات للعاملين في مجال الذكاء الاصطناعي"},"features":{"en":["Provides graph-based workflows with streaming capabilities","Supports checkpointing for reliable workflow execution","Includes human-in-the-loop capabilities for manual intervention","Offers time-travel capabilities for workflow debugging and analysis","Supports integration with OpenAI and Azure OpenAI via Microsoft.Agents.AI.OpenAI package","Allows installation of Google Gemini support via Microsoft.E package"],"zh":["图形工作流","流式处理","人机交互","checkpointing","时间旅行","OpenAI/Azure OpenAI支持"],"ja":["グラフベースのワークフロー","ストリーミング","ヒューマンインザループ","チェックポイント","タイムトラベル","OpenAI/Azure OpenAIサポート"],"ko":["그래프 기반 워크플로","스트리밍","인간과 상호작용","체크포인트","시간여행","OpenAI/Azure OpenAI 지원"],"es":["Soporte para flujos de trabajo de AI con capacidades de streaming","Funcionalidad de checkpointing para garantizar la integridad de los datos","Compatibilidad con OpenAI y Azure OpenAI","Soporte para Google Gemini","Capacidad de tiempo de viaje para la depuración y el análisis de flujos de trabajo"],"fr":["Prise en charge de flux de travail d''IA avec des fonctionnalités de streaming","Fonctionnalité de point de contrôle pour garantir l''intégrité des données","Compatibilité avec OpenAI et Azure OpenAI","Prise en charge de Google Gemini","Capacité de voyage dans le temps pour la débogage et l''analyse de flux de travail"],"de":["Unterstützung für AI-Workflows mit Streaming-Funktionen","Checkpointing-Funktion zur Gewährleistung der Datenintegrität","Kompatibilität mit OpenAI und Azure OpenAI","Unterstützung für Google Gemini","Zeitreise-Funktion für die Fehlersuche und Analyse von Workflows"],"pt":["Suporte a fluxos de trabalho baseados em grafos","Recursos de streaming e checkpointing","Integração com OpenAI e Azure OpenAI","Suporte a Google Gemini","Capacidades de tempo de viagem"],"ru":["Поддержка графических потоков работы","Функции потоковой передачи и checkpointing","Интеграция с OpenAI и Azure OpenAI","Поддержка Google Gemini","Возможности путешествия во времени"],"ar":["دعم تدفقات العمل القائمة على الرسوم البيانية","ميزات البث والتحقق","التكامل مع OpenAI و Azure OpenAI","دعم Google Gemini","إمكانيات السفر عبر الزمن"]},"keywords":{"en":["how to use microsoft-agent-framework","microsoft-agent-framework setup guide","what is microsoft-agent-framework","microsoft-agent-framework alternative","microsoft-agent-framework vs azure machine learning","microsoft-agent-framework install","microsoft-agent-framework for ai agents","microsoft-agent-framework graph-based workflows","microsoft-agent-framework streaming capabilities","microsoft-agent-framework checkpointing"],"zh":["Microsoft Agent Framework","AIエージェント","图形工作流","流式处理","人机交互","dotnet","AI开发"],"ja":["Microsoft Agent Framework","AIエージェント","グラフベースのワークフロー","ストリーミング","ヒューマンインザループ","dotnet","AI開発"],"ko":["Microsoft Agent Framework","AI 에이전트","그래프 기반 워크플로","스트리밍","인간과 상호작용","dotnet","AI 개발"],"es":["Microsoft Agent Framework","agentes de AI","flujos de trabajo de AI","streaming de datos","checkpointing","OpenAI","Azure OpenAI","Google Gemini","desarrollo de AI","herramientas de AI"],"fr":["Microsoft Agent Framework","agents d''IA","flux de travail d''IA","streaming de données","point de contrôle","OpenAI","Azure OpenAI","Google Gemini","développement d''IA","outils d''IA"],"de":["Microsoft Agent Framework","AI-Agents","AI-Workflows","Daten-Streaming","Checkpointing","OpenAI","Azure OpenAI","Google Gemini","AI-Entwicklung","AI-Tools"],"pt":["Microsoft Agent Framework","Desenvolvimento de IA","Fluxos de trabalho de agentes de IA","Streaming e checkpointing","OpenAI e Azure OpenAI","Google Gemini","Tempo de viagem","Desenvolvedores de IA"],"ru":["Microsoft Agent Framework","Разработка ИИ Агентов","Потоки работы ИИ Агентов","Потоковая передача и checkpointing","OpenAI и Azure OpenAI","Google Gemini","Путешествие во времени","Разработчики ИИ Агентов"],"ar":["إطار عمل Microsoft Agent","تطوير الذكاء الاصطناعي","تدفقات العمل لوكلاء الذكاء الاصطناعي","البث والتحقق","OpenAI و Azure OpenAI","Google Gemini","السفر عبر الزمن","مطورو الذكاء الاصطناعي"]}},"owner":"Salmanferozkhan","repo":"Cloud-and-fast-api","repoPath":"Salmanferozkhan/Cloud-and-fast-api","stars":0,"forks":0,"updatedAt":"2026-01-17T11:39:10Z","topics":[],"category":"community","skillMd":{"name":"microsoft-agent-framework","description":"Expert guidance for building AI agents and multi-agent workflows using Microsoft Agent Framework for .NET. Use when (1) creating AI agents with OpenAI or Azure OpenAI, (2) implementing function tools and structured outputs, (3) building multi-turn conversations, (4) designing graph-based workflows with streaming/checkpointing, (5) implementing middleware pipelines, (6) orchestrating multi-agent systems with fan-out/fan-in patterns, (7) adding human-in-the-loop interactions, (8) integrating OpenTelemetry observability, or (9) exposing agents as MCP tools.","bodyPreview":"# Microsoft Agent Framework for .NET\n\n## Overview\n\nMicrosoft Agent Framework is a framework for building, orchestrating, and deploying AI agents and multi-agent workflows. It provides graph-based workflows with streaming, checkpointing, human-in-the-loop, and time-travel capabilities.\n\n## Installation\n\n```bash\n# Core AI package\ndotnet add package Microsoft.Agents.AI\n\n# OpenAI/Azure OpenAI support\ndotnet add package Microsoft.Agents.AI.OpenAI --prerelease\n\n# Google Gemini support (via Microsoft.E","body":"# Microsoft Agent Framework for .NET\n\n## Overview\n\nMicrosoft Agent Framework is a framework for building, orchestrating, and deploying AI agents and multi-agent workflows. It provides graph-based workflows with streaming, checkpointing, human-in-the-loop, and time-travel capabilities.\n\n## Installation\n\n```bash\n# Core AI package\ndotnet add package Microsoft.Agents.AI\n\n# OpenAI/Azure OpenAI support\ndotnet add package Microsoft.Agents.AI.OpenAI --prerelease\n\n# Google Gemini support (via Microsoft.Extensions.AI)\ndotnet add package Mscc.GenerativeAI.Microsoft\n\n# Azure identity for authentication\ndotnet add package Azure.Identity\n```\n\n## Quick Start\n\n### Basic Agent with OpenAI\n\n```csharp\nusing Microsoft.Agents.AI;\nusing OpenAI;\n\nvar agent = new OpenAIClient(\"<api-key>\")\n    .GetOpenAIResponseClient(\"gpt-4o-mini\")\n    .CreateAIAgent(\n        name: \"Assistant\",\n        instructions: \"You are a helpful assistant.\"\n    );\n\nConsole.WriteLine(await agent.RunAsync(\"Hello!\"));\n```\n\n### Azure OpenAI with Azure CLI Auth\n\n```csharp\nusing Azure.AI.OpenAI;\nusing Azure.Identity;\nusing Microsoft.Agents.AI;\n\nvar agent = new AzureOpenAIClient(\n    new Uri(\"https://<resource>.openai.azure.com/\"),\n    new AzureCliCredential())\n    .GetChatClient(\"gpt-4o-mini\")\n    .CreateAIAgent(instructions: \"You are helpful.\");\n\nConsole.WriteLine(await agent.RunAsync(\"Tell me a joke.\"));\n```\n\n### Azure OpenAI with Bearer Token\n\n```csharp\nvar agent = new OpenAIClient(\n    new BearerTokenPolicy(\n        new AzureCliCredential(),\n        \"https://ai.azure.com/.default\"),\n    new OpenAIClientOptions\n    {\n        Endpoint = new Uri(\"https://<resource>.openai.azure.com/openai/v1\")\n    })\n    .GetOpenAIResponseClient(\"gpt-4o-mini\")\n    .CreateAIAgent(name: \"Bot\", instructions: \"You are helpful.\");\n```\n\n### Google Gemini\n\n```csharp\nusing Mscc.GenerativeAI;\nusing Mscc.GenerativeAI.Microsoft;\nusing Microsoft.Agents.AI;\n\nvar googleAI = new GoogleAI(\"<gemini-api-key>\");\nvar geminiModel = googleAI.GenerativeModel(\"gemini-2.0-flash\");\nIChatClient chatClient = geminiModel.AsIChatClient();\n\nvar agent = chatClient.CreateAIAgent(\n    name: \"Assistant\",\n    instructions: \"You are a helpful assistant.\"\n);\n\nConsole.WriteLine(await agent.RunAsync(\"Hello!\"));\n```\n\n## Function Tools\n\nDefine tools using attributes:\n\n```csharp\npublic class WeatherTools\n{\n    [Description(\"Gets current weather for a location\")]\n    public static string GetWeather(\n        [Description(\"City name\")] string city)\n    {\n        return $\"Weather in {city}: Sunny, 72F\";\n    }\n}\n\n// Register tools with agent\nvar agent = client.GetChatClient(\"gpt-4o-mini\")\n    .CreateAIAgent(\n        instructions: \"Help users check weather.\",\n        tools: [typeof(WeatherTools)]);\n\nawait agent.RunAsync(\"What''s the weather in Seattle?\");\n```\n\n### Function Tools with Approval\n\nFor human-in-the-loop approval:\n\n```csharp\nagent.OnToolCall += (sender, args) =>\n{\n    Console.WriteLine($\"Tool: {args.ToolName}\");\n    Console.Write(\"Approve? (y/n): \");\n    args.Approved = Console.ReadLine()?.ToLower() == \"y\";\n};\n```\n\n## Structured Output\n\nReturn strongly-typed responses:\n\n```csharp\npublic class MovieRecommendation\n{\n    public string Title { get; set; }\n    public string Genre { get; set; }\n    public int Year { get; set; }\n    public string Reason { get; set; }\n}\n\nvar result = await agent.RunAsync<MovieRecommendation>(\n    \"Recommend a sci-fi movie from the 2020s\");\n\nConsole.WriteLine($\"{result.Title} ({result.Year}) - {result.Reason}\");\n```\n\n## Multi-Turn Conversations\n\n```csharp\nvar agent = client.GetChatClient(\"gpt-4o-mini\")\n    .CreateAIAgent(instructions: \"You are a helpful assistant.\");\n\n// First turn\nvar response1 = await agent.RunAsync(\"My name is Alice.\");\n\n// Continues context\nvar response2 = await agent.RunAsync(\"What''s my name?\");\n```\n\n## Persisted Conversations\n\nSave and restore conversation state:\n\n```csharp\n// Save state\nvar state = agent.GetConversationState();\nawait File.WriteAllTextAsync(\"state.json\", state.ToJson());\n\n// Restore later\nvar savedState = ConversationState.FromJson(\n    await File.ReadAllTextAsync(\"state.json\"));\nagent.LoadConversationState(savedState);\n```\n\n## Middleware\n\nAdd custom processing pipelines:\n\n```csharp\nagent.UseMiddleware(async (context, next) =>\n{\n    Console.WriteLine($\"Request: {context.Input}\");\n    var start = DateTime.UtcNow;\n\n    await next();\n\n    var duration = DateTime.UtcNow - start;\n    Console.WriteLine($\"Response time: {duration.TotalMilliseconds}ms\");\n});\n```\n\n## Multi-Modal (Images)\n\n```csharp\nvar result = await agent.RunAsync(\n    \"Describe this image\",\n    images: [File.ReadAllBytes(\"photo.jpg\")]);\n```\n\n## Observability with OpenTelemetry\n\n```csharp\nusing var tracerProvider = Sdk.CreateTracerProviderBuilder()\n    .AddSource(\"Microsoft.Agents\")\n    .AddConsoleExporter()\n    .Build();\n\n// Agent calls are now traced\nawait agent.RunAsync(\"Hello!\");\n```\n\n## Dependency Injection\n\n```csharp\nservices.AddSingleton<AIAgent>(sp =>\n{\n    var client = sp.GetRequiredService<OpenAIClient>();\n    return client.GetChatClient(\"gpt-4o-mini\")\n        .CreateAIAgent(instructions: \"You are helpful.\");\n});\n```\n\n## Agent as MCP Tool\n\nExpose agent as Model Context Protocol tool:\n\n```csharp\nvar mcpTool = agent.AsMcpTool(\n    name: \"research_assistant\",\n    description: \"Researches topics and provides summaries\");\n```\n\n## Agent as Function Tool\n\nCompose agents by exposing one as a tool for another:\n\n```csharp\nvar researchAgent = client.GetChatClient(\"gpt-4o\")\n    .CreateAIAgent(instructions: \"You do deep research.\");\n\nvar mainAgent = client.GetChatClient(\"gpt-4o-mini\")\n    .CreateAIAgent(\n        instructions: \"Answer questions, use research tool for complex topics.\",\n        tools: [researchAgent.AsFunctionTool(\"research\", \"Deep research\")]);\n```\n\n## Workflows\n\nFor complex multi-agent orchestration, see [references/workflows.md](references/workflows.md).\n\nKey workflow patterns:\n- **Executors and Edges**: Basic workflow building blocks\n- **Streaming**: Real-time event streaming\n- **Fan-Out/Fan-In**: Parallel processing\n- **Checkpointing**: Save and resume workflow state\n- **Human-in-the-Loop**: Pause for user input\n- **Writer-Critic**: Iterative refinement loops\n\n## Best Practices\n\n1. **Use Azure CLI credentials** for local development\n2. **Add OpenTelemetry** for production observability\n3. **Implement middleware** for logging, error handling, rate limiting\n4. **Use structured outputs** when you need typed responses\n5. **Persist conversation state** for stateless services\n6. **Use checkpointing** in workflows for reliability\n7. **Implement human-in-the-loop** for sensitive operations\n\n## Resources\n\n- [GitHub Repository](https://github.com/microsoft/agent-framework)\n- [MS Learn Documentation](https://learn.microsoft.com/en-us/agent-framework/)\n- [Quick Start Guide](https://learn.microsoft.com/agent-framework/tutorials/quick-start)\n- [Samples](https://github.com/microsoft/agent-framework/tree/main/dotnet/samples)\n"},"lastSynced":"2026-03-07T03:47:13.632Z","agentAnalysis":{"suitability":{"en":"Perfect for AI Agents needing advanced multi-agent workflow orchestration and graph-based workflows with streaming and checkpointing capabilities.","zh":"适合需要高级多代理工作流编排和基于图的工作流的AI代理，具有流媒体和检查点功能。","ja":"高度なマルチエージェントワークフローオーケストレーションとグラフベースのワークフロー、ストリーミングおよびチェックポイント機能を必要とするAIエージェントに最適。","ko":"고급 多代理 워크플로 오케스트레이션 및 그래프 기반 워크플로를 필요로 하는 AI 에이전트에게 적합하며, 스트리밍 및 체크포인트 기능을 제공합니다.","es":"Perfecto para agentes de IA que necesitan una orquestación de flujo de trabajo de agente múltiple avanzada y flujos de trabajo basados en gráficos con capacidades de transmisión y punto de control.","fr":"Parfait pour les agents IA ayant besoin d''une orchestration de workflow d''agent multiple avancée et de flux de travail basés sur des graphiques avec des capacités de diffusion et de point de contrôle.","de":"Perfekt für KI-Agents, die eine erweiterte Multi-Agent-Workflow-Orchestrierung und graphbasierte Workflows mit Streaming- und Checkpointing-Funktionen benötigen.","pt":"Perfeito para Agentes de IA que necessitam de orquestração de fluxo de trabalho avançada multi-agente e fluxos de trabalho baseados em grafos com capacidades de streaming e checkpointing.","ru":"Идеально подходит для агентов ИИ, которым требуется продвинутая оркестрация рабочих процессов с несколькими агентами и рабочими процессами на основе графов с возможностями потоковой передачи и checkpointing.","ar":"مثالي لعمليات وكيل الذكاء الاصطناعي التي تحتاج إلى تحrickة متقدمة لتدفق العمل متعددة الوكلاء وعمليات العمل القائمة على الرسوم البيانية مع إمكانيات البث وتحديد النقاط"},"recommendation":{"en":"Empowers agents to build, orchestrate, and deploy AI workflows with human-in-the-loop and time-travel capabilities using Microsoft Agent Framework''s .NET packages, including Microsoft.Agents.AI and Microsoft.Agents.AI.OpenAI for OpenAI/Azure OpenAI support.","zh":"赋予代理构建、编排和部署AI工作流的能力，使用Microsoft Agent Framework的.NET包，包括Microsoft.Agents.AI和Microsoft.Agents.AI.OpenAI，支持OpenAI/Azure OpenAI，并具有人机交互和时间旅行功能。","ja":"Microsoft Agent Frameworkの.NETパッケージ、Microsoft.Agents.AIおよびMicrosoft.Agents.AI.OpenAIを使用して、エージェントがAIワークフローを構築、オーケストレーション、デプロイできるようにし、OpenAI/Azure OpenAIをサポートし、ヒューマン・イン・ザ・ループおよびタイムトラベル機能を使用します。","ko":"에이전트가 AI 워크플로를 빌드하고 오케스트레이션하고 배포할 수 있는 능력을 부여합니다. Microsoft 에이전트 프레임워크의 .NET 패키지를 사용합니다. Microsoft.Agents.AI 및 Microsoft.Agents.AI.OpenAI를 포함하여 OpenAI/Azure OpenAI를 지원하며, 사람과 루프 및 시간 여행 기능을 사용합니다.","es":"Habilita a los agentes a construir, orquestar y implementar flujos de trabajo de IA con capacidades de tiempo de viaje y humano en el ciclo utilizando los paquetes .NET de Microsoft Agent Framework, incluidos Microsoft.Agents.AI y Microsoft.Agents.AI.OpenAI para soporte de OpenAI/Azure OpenAI.","fr":"Permet aux agents de construire, d''orchestrer et de déployer des flux de travail IA avec des capacités de voyage dans le temps et d''homme dans la boucle en utilisant les packages .NET de Microsoft Agent Framework, notamment Microsoft.Agents.AI et Microsoft.Agents.AI.OpenAI pour la prise en charge d''OpenAI/Azure OpenAI.","de":"Ermöglicht es Agents, KI-Workflows mit Zeitreise- und Human-in-the-Loop-Funktionen zu erstellen, zu orchestrieren und zu bereitstellen, indem sie die .NET-Pakete von Microsoft Agent Framework verwenden, einschließlich Microsoft.Agents.AI und Microsoft.Agents.AI.OpenAI für OpenAI/Azure OpenAI-Unterstützung.","pt":"Habilita os agentes a construir, orquestrar e implantar fluxos de trabalho de IA com capacidades de loop humano e viagem no tempo, usando pacotes .NET do Microsoft Agent Framework, incluindo Microsoft.Agents.AI e Microsoft.Agents.AI.OpenAI para suporte ao OpenAI/Azure OpenAI.","ru":"Позволяет агентам создавать, оркестрировать и развертывать рабочие процессы ИИ с возможностями человеческого участия и путешествия во времени, используя пакеты .NET фреймворка Microsoft Agent, включая Microsoft.Agents.AI и Microsoft.Agents.AI.OpenAI для поддержки OpenAI/Azure OpenAI.","ar":"تمكّن الوكلاء من بناء وتحريك وتنفيذ تدفقات عمل الذكاء الاصطناعي مع إمكانيات الحوسبة البشرية والتنقل عبر الزمن باستخدام حزمة .NET من إطار عامل مايكروسوفت، بما في ذلك Microsoft.Agents.AI و Microsoft.Agents.AI.OpenAI لدعم OpenAI/Azure OpenAI"},"useCases":{"en":["Orchestrating complex AI workflows with graph-based streaming","Deploying multi-agent systems with checkpointing and time-travel capabilities","Integrating human-in-the-loop feedback into AI decision-making processes"],"zh":["编排具有图形流媒体的复杂AI工作流","部署具有检查点和时间旅行功能的多代理系统","将人机交互反馈集成到AI决策过程中"],"ja":["グラフベースのストリーミングを備えた複雑なAIワークフローのオーケストレーション","チェックポイントおよびタイムトラベル機能を備えたマルチエージェントシステムのデプロイ","AIの意思決定プロセスへのヒューマン・イン・ザ・ループのフィードバックの統合"],"ko":["그래프 기반 스트리밍을備한 복잡한 AI 워크플로 오케스트레이션","체크포인트 및 시간 여행 기능을 갖춘 멀티 에이전트 시스템 배포","AI 의사결정 프로세스에 사람과 루프 피드백 통합"],"es":["Orquestación de flujos de trabajo de IA complejos con transmisión basada en gráficos","Implementación de sistemas de agente múltiple con capacidades de punto de control y viaje en el tiempo","Integración de comentarios de humano en el ciclo en procesos de toma de decisiones de IA"],"fr":["Orchestration de flux de travail IA complexes avec diffusion basée sur des graphiques","Déploiement de systèmes d''agent multiple avec des capacités de point de contrôle et de voyage dans le temps","Intégration de commentaires humains dans les processus de prise de décision IA"],"de":["Orchestrierung komplexer KI-Workflows mit graphbasierter Streaming","Bereitstellung von Multi-Agent-Systemen mit Checkpointing- und Zeitreise-Funktionen","Integration von Human-in-the-Loop-Feedback in KI-Entscheidungsprozesse"],"pt":["Orquestração de fluxos de trabalho de IA complexos com streaming baseado em grafos","Implantação de sistemas multi-agente com capacidades de checkpointing e viagem no tempo","Integração de feedback humano no processo de tomada de decisão de IA"],"ru":["Оркестрация сложных рабочих процессов ИИ с потоковой передачей на основе графов","Развертывание систем с несколькими агентами с возможностями checkpointing и путешествия во времени","Интеграция обратной связи человека в процесс принятия решений ИИ"],"ar":["توجيه تدفقات عمل الذكاء الاصطناعي المعقدة مع بث قائم على الرسوم البيانية","نشر أنظمة متعددة الوكلاء مع إمكانيات تحديد النقاط والتنقل عبر الزمن","دمج ملاحظات الإنسان في عمليات اتخاذ القرارات الذكية"]},"limitations":{"en":["Requires .NET environment","OpenAI/Azure OpenAI support requires separate package installation","Google Gemini support requires Microsoft.E package"],"zh":[".NET环境是必需的","OpenAI/Azure OpenAI支持需要单独的包安装","Google Gemini支持需要Microsoft.E包"],"ja":[".NET環境が必要","OpenAI/Azure OpenAIのサポートには個別のパッケージのインストールが必要","Google GeminiのサポートにはMicrosoft.Eパッケージが必要"],"ko":[".NET 환경이 필요합니다","OpenAI/Azure OpenAI 지원을 위해서는 별도의 패키지 설치가 필요합니다","Google Gemini 지원을 위해서는 Microsoft.E 패키지가 필요합니다"],"es":["Requiere entorno .NET","El soporte de OpenAI/Azure OpenAI requiere una instalación de paquetes separada","El soporte de Google Gemini requiere el paquete Microsoft.E"],"fr":["Nécessite un environnement .NET","La prise en charge d''OpenAI/Azure OpenAI nécessite une installation de package séparée","La prise en charge de Google Gemini nécessite le package Microsoft.E"],"de":["Benötigt .NET-Umgebung","OpenAI/Azure OpenAI-Unterstützung erfordert separate Paketinstallation","Google Gemini-Unterstützung erfordert Microsoft.E-Paket"],"pt":["Requer ambiente .NET","Suporte ao OpenAI/Azure OpenAI requer instalação de pacote separado","Suporte ao Google Gemini requer pacote Microsoft.E"],"ru":["Требуется среда .NET","Поддержка OpenAI/Azure OpenAI требует отдельной установки пакета","Поддержка Google Gemini требует пакета Microsoft.E"],"ar":["يتطلب بيئة .NET","دعم OpenAI/Azure OpenAI يتطلب تثبيت حزمة منفصلة","دعم Google Gemini يتطلب حزمة Microsoft.E"]},"version":4},"contentHash":"e2026755feea920daff2a6b682e759be3d18ebca7c0a5141814d6b5fac786e42","qualityScore":45}');
