INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('Salmanferozkhan/Cloud-and-fast-api/microsoft-agent-framework', 'microsoft-agent-framework', 'Salmanferozkhan', 'Cloud-and-fast-api', 'community', 'microsoft-agent-framework Salmanferozkhan Cloud-and-fast-api community Microsoft Agent Framework is a framework for building AI agents and multi-agent workflows, providing graph-based workflows with streaming and checkpointing capabilities. It benefits developers and organizations working with AI and machine learning. Microsoft Agent Framework是一个用于构建、编排和部署AI代理和多代理工作流的框架 Microsoft Agent Frameworkは、AIエージェントとマルチエージェントワークフローを構築、オーケストレーション、デプロイするためのフレームワークです Microsoft Agent Framework는 AI 에이전트와 멀티 에이전트 워크플로를 구축, 오케스트레이션, 배포하기 위한 프레임워크입니다 Microsoft Agent Framework es un marco para construir y desplegar agentes de AI y flujos de trabajo de multi-agente con capacidades de streaming y checkpointing Microsoft Agent Framework est un cadre pour construire et déployer des agents d''IA et des flux de travail de multi-agent avec des fonctionnalités de streaming et de point de contrôle Microsoft Agent Framework ist ein Rahmenwerk zum Erstellen und Bereitstellen von AI-Agents und Multi-Agent-Workflows mit Streaming- und Checkpointing-Funktionen O Microsoft Agent Framework é uma estrutura para construir, orquestrar e implantar agentes de IA e fluxos de trabalho de vários agentes Microsoft Agent Framework — это каркас для создания, оркестровки и развертывания ИИ Агентов и потоков работы нескольких агентов إطار عمل Microsoft Agent هو هيكل لبناء وتحريك وتركيب وكلاء الذكاء الاصطناعي وتدفقات العمل المتعددة how to use microsoft-agent-framework microsoft-agent-framework setup guide what is microsoft-agent-framework microsoft-agent-framework alternative microsoft-agent-framework vs azure machine learning microsoft-agent-framework install microsoft-agent-framework for ai agents microsoft-agent-framework graph-based workflows microsoft-agent-framework streaming capabilities microsoft-agent-framework checkpointing Microsoft Agent Framework AIエージェント 图形工作流 流式处理 人机交互 dotnet AI开发 Provides graph-based workflows with streaming capabilities Supports checkpointing for reliable workflow execution Includes human-in-the-loop capabilities for manual intervention Offers time-travel capabilities for workflow debugging and analysis Supports integration with OpenAI and Azure OpenAI via Microsoft.Agents.AI.OpenAI package Allows installation of Google Gemini support via Microsoft.E package Microsoft Agent Framework is a framework for building, orchestrating, and deploying AI agents and multi-agent workflows with graph-based workflows and streaming capabilities.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('HakureiHikaze/Hikaze-Model-Manager-2/root', 'community', 'HakureiHikaze', 'Hikaze-Model-Manager-2', 'HakureiHikaze/Hikaze-Model-Manager-2', 'root', 0, 0, 45, '2026-03-06T12:59:22.224Z', '2026-03-06T14:09:56.326Z', '6339a1951aecb74eb07e2949aebc9a9c300bdb13f67e63515419d1461d6f62a3', '{"id":"HakureiHikaze/Hikaze-Model-Manager-2/root","name":"root","description":{"en":"The root skill governs Codex project work using the .codex directory structure, keeping sources of truth stable. It benefits developers working with Hikaze-Model-Manager-2.","zh":"Root 技术是用于管理 Codex 项目工作流的技术，通过 .codex 目录结构实现项目原则、技术栈和代码标准的管理","ja":"Root は、.codex ディレクトリ構造を使用して Codex プロジェクトワークフローを管理する技術です","ko":"Root 기술은 .codex 디렉토리 구조를 사용하여 Codex 프로젝트 작업을 관리하는 기술입니다","es":"El skill root permite gobernar proyectos Codex con Hikaze-Model-Manager-2, manteniendo fuentes de verdad inmutables y rastreando trabajos y detalles de diseño","fr":"Le skill root permet de gérer les projets Codex avec Hikaze-Model-Manager-2, en maintenant des sources de vérité immuables et en traçant les travaux et les détails de conception","de":"Das root-Skill ermöglicht die Verwaltung von Codex-Projekten mit Hikaze-Model-Manager-2, wobei unveränderliche Wahrheitsquellen aufrechterhalten und Jobs und Designdetails nachverfolgt werden","pt":"O Root é uma habilidade para governar projetos Codex com Hikaze-Model-Manager-2, mantendo fontes de verdade imutáveis e rastreando trabalhos e detalhes de design","ru":"Root - это навык для управления проектами Codex с Hikaze-Model-Manager-2, поддержания неизменных источников правды и отслеживания работ и деталей дизайна","ar":"الجذر هو مهارة لإدارة مشاريع Codex باستخدام Hikaze-Model-Manager-2، والحفاظ على مصادر الحقيقة غير القابلة للتغيير ورصد الأعمال و تفاصيل التصميم"},"seo":{"title":{"en":"root: Codex Project Governance Setup Guide | AI Agent Skill","zh":"Root 技术指南：Codex 项目工作流管理","ja":"Root AIエージェント：Codex プロジェクトワークフローの設定ガイド","ko":"Root 기술 문서: Codex 프로젝트 작업 관리","es":"Guía de configuración de root para Hikaze-Model-Manager-2","fr":"Guide de configuration de root pour Hikaze-Model-Manager-2","de":"Einrichtungsleitfaden für root in Hikaze-Model-Manager-2","pt":"Guia de Configuração do Root para Ferramentas de IA","ru":"Настройка Root для ИИ Агентов: Лучшие Практики","ar":"دليل إعداد الجذر لآلات الذكاء الاصطناعي"},"description":{"en":"Discover how to govern Codex projects with root, ensuring stable sources of truth and efficient job tracking. Learn more and get started today!","zh":"了解 Root 技术，实现 Codex 项目工作流的自动化管理，提高开发效率","ja":"Root AIエージェントを使用して、Codex プロジェクトワークフローを最適化し、開発効率を向上させます","ko":"Root 기술을 사용하여 Codex 프로젝트 작업을 자동화하고 개발 효율성을 높입니다","es":"Aprende a configurar root para gestionar proyectos Codex con Hikaze-Model-Manager-2 y mantén fuentes de verdad inmutables","fr":"Découvrez comment configurer root pour gérer les projets Codex avec Hikaze-Model-Manager-2 et maintenir des sources de vérité immuables","de":"Erfahren Sie, wie Sie root für die Verwaltung von Codex-Projekten mit Hikaze-Model-Manager-2 einrichten und unveränderliche Wahrheitsquellen aufrechterhalten","pt":"Aprenda a configurar o Root para governar projetos Codex com Hikaze-Model-Manager-2 e mantenha fontes de verdade imutáveis","ru":"Узнайте, как настроить Root для управления проектами Codex с Hikaze-Model-Manager-2 и поддержания неизменных источников правды","ar":"تعلم كيفية تكوين الجذر لإدارة مشاريع Codex باستخدام Hikaze-Model-Manager-2 والحفاظ على مصادر الحقيقة غير القابلة للتغيير"},"definition":{"en":"root is a skill that governs Codex project work for Hikaze-Model-Manager-2, maintaining stable sources of truth and tracking jobs and design details.","zh":"Root 是一种用于管理 Codex 项目工作流的技术，确保项目原则和代码标准的一致性","ja":"Root は、Codex プロジェクトワークフローを管理する技術で、プロジェクト原則とコード標準の一貫性を保証します","ko":"Root는 Codex 프로젝트 작업을 관리하는 기술로 프로젝트 원칙과 코드 표준의 일관성을 보장합니다","es":"Root es un skill que gobierna proyectos Codex con Hikaze-Model-Manager-2","fr":"Root est un skill qui gère les projets Codex avec Hikaze-Model-Manager-2","de":"Root ist ein Skill, der Codex-Projekte mit Hikaze-Model-Manager-2 verwaltet","pt":"O que é Root? Uma habilidade para governar projetos Codex com Hikaze-Model-Manager-2","ru":"Что такое Root? Навык для управления проектами Codex с Hikaze-Model-Manager-2","ar":"ما هو الجذر؟ مهارة لإدارة مشاريع Codex باستخدام Hikaze-Model-Manager-2"},"features":{"en":["Reads .codex/constitution/ for project principles and tech stack","Utilizes .codex/workflows/ for static workflow framework","References .codex/guidelines/ for implementation details and decisions","Tracks jobs and design details via .codex/jobs/activated","Maintains immutable sources of truth for project stability","Supports Hikaze-Model-Manager-2 for efficient project management"],"zh":["基于 .codex 目录结构的项目管理","实现项目原则、技术栈和代码标准的管理","支持静态工作流框架","实现实施细节和决策的跟踪","支持作业跟踪和设计细节管理"],"ja":[".codex ディレクトリ構造を使用したプロジェクト管理","プロジェクト原則、テックスタック、コード標準の管理","静的ワークフロー フレームワークのサポート","実装の詳細と決定の追跡","ジョブ追跡と設計の詳細管理"],"ko":[".codex 디렉토리 구조를 사용한 프로젝트 관리","프로젝트 원칙, 기술 스택, 코드 표준 관리","정적 작업 흐름 프레임워크 지원","구현 세부 정보와 결정 추적","작업 추적 및 디자인 세부 정보 관리"],"es":["Lectura de la constitución del proyecto en `.codex/constitution/`","Carga de flujos de trabajo estáticos desde `.codex/workflows/`","Implementación de detalles y decisiones desde `.codex/guidelines/`","Seguimiento de trabajos activados en `.codex/jobs/activated`"],"fr":["Lecture de la constitution du projet dans `.codex/constitution/`","Chargement de flux de travail statiques depuis `.codex/workflows/`","Implémentation de détails et de décisions depuis `.codex/guidelines/`","Suivi de travaux activés dans `.codex/jobs/activated`"],"de":["Lese die Projektverfassung in `.codex/constitution/`","Lade statische Workflows von `.codex/workflows/`","Implementiere Details und Entscheidungen von `.codex/guidelines/`","Verfolge aktivierte Jobs in `.codex/jobs/activated`"],"pt":["Leitura da estrutura de diretório .codex","Governo de projetos Codex com Hikaze-Model-Manager-2","Manutenção de fontes de verdade imutáveis","Rastreamento de trabalhos e detalhes de design","Integração com .codex/constitution, .codex/workflows e .codex/guidelines"],"ru":["Чтение структуры директории .codex","Управление проектами Codex с Hikaze-Model-Manager-2","Поддержание неизменных источников правды","Отслеживание работ и деталей дизайна","Интеграция с .codex/constitution, .codex/workflows и .codex/guidelines"],"ar":["قراءة هيكل الدليل .codex","إدارة مشاريع Codex باستخدام Hikaze-Model-Manager-2","الحفاظ على مصادر الحقيقة غير القابلة للتغيير","رصد الأعمال و تفاصيل التصميم","التكامل مع .codex/constitution, .codex/workflows و .codex/guidelines"]},"keywords":{"en":["how to use root","root setup guide","what is root","root alternative","root vs Hikaze-Model-Manager-1","root install","Codex project governance","Hikaze-Model-Manager-2 integration","root skill for AI agents","governing Codex projects with root"],"zh":["Root 技术","Codex 项目管理","AI 工具",".codex 目录结构","项目工作流管理","代码标准管理","静态工作流框架"],"ja":["Root AIエージェント","Codex プロジェクト管理","AI ツール",".codex ディレクトリ構造","プロジェクトワークフロー管理","コード標準管理","静的ワークフロー フレームワーク"],"ko":["Root 기술","Codex 프로젝트 관리","AI 도구",".codex 디렉토리 구조","프로젝트 작업 관리","코드 표준 관리","정적 작업 흐름 프레임워크"],"es":["root skill","Hikaze-Model-Manager-2","proyectos Codex","fuentes de verdad inmutables","seguimiento de trabajos","diseño de proyectos","gestión de proyectos","Herramientas de IA","Agentes de IA"],"fr":["skill root","Hikaze-Model-Manager-2","projets Codex","sources de vérité immuables","suivi de travaux","conception de projets","gestion de projets","Outils d''IA","Agents d''IA"],"de":["root-Skill","Hikaze-Model-Manager-2","Codex-Projekte","unveränderliche Wahrheitsquellen","Nachverfolgung von Jobs","Projektgestaltung","Projektverwaltung","KI-Tools","KI-Agents"],"pt":["Root","Ferramentas de IA","Hikaze-Model-Manager-2","Projetos Codex","Fontes de verdade imutáveis","Rastreamento de trabalhos","Detalhes de design","Estrutura de diretório .codex"],"ru":["Root","ИИ Агенты","Hikaze-Model-Manager-2","Проекты Codex","Неизменные источники правды","Отслеживание работ","Детали дизайна","Структура директории .codex"],"ar":["الجذر","آلات الذكاء الاصطناعي","Hikaze-Model-Manager-2","مشاريع Codex","مصادر الحقيقة غير القابلة للتغيير","رصد الأعمال","تفاصيل التصميم","هيكل الدليل .codex"]}},"owner":"HakureiHikaze","repo":"Hikaze-Model-Manager-2","repoPath":"HakureiHikaze/Hikaze-Model-Manager-2","stars":0,"forks":0,"updatedAt":"2026-03-06T12:59:22.224Z","topics":[],"category":"community","skillMd":{"name":"root","description":"Manage and guide Hikaze-Model-Manager-2 Codex project work via the .codex governance system. Use when the user says root skill or asks to start development based on the root skill, or when asked to set up or operate .codex constitution/workflows/guidelines/jobs, manage jobs/phases/tasks with Markdown checklists, or migrate project prompts from conductor/ into .codex/.","bodyPreview":"# Root\n\n## Overview\n\nUse this skill to govern Codex project work for Hikaze-Model-Manager-2 using the .codex directory structure, keeping immutable sources of truth stable while tracking jobs and design details.\n\n## Sources of truth and load order\n\n1. Read `.codex/constitution/` for project principles, tech stack, and code standards.\n2. Read `.codex/workflows/` for the static workflow framework.\n3. Read `.codex/guidelines/` for implementation details and decisions.\n4. Read `.codex/jobs/activated","body":"# Root\n\n## Overview\n\nUse this skill to govern Codex project work for Hikaze-Model-Manager-2 using the .codex directory structure, keeping immutable sources of truth stable while tracking jobs and design details.\n\n## Sources of truth and load order\n\n1. Read `.codex/constitution/` for project principles, tech stack, and code standards.\n2. Read `.codex/workflows/` for the static workflow framework.\n3. Read `.codex/guidelines/` for implementation details and decisions.\n4. Read `.codex/jobs/activated.md` and the active job file to understand current work.\n\n## Hard rules\n\n- Do not edit `.codex/constitution/` or `.codex/workflows/` unless the user explicitly requests changes.\n- Propose suggestions for constitution/workflows only; do not modify without explicit user instruction.\n- Record new or changed design details in `.codex/guidelines/` during design discussions.\n- Record designed but not implemented items in `.codex/guidelines/not_implemented.md`.\n- Keep all .codex content in Markdown.\n- When stating code or behavior facts, cite evidence (file path + line or command output); avoid assumptions.\n- Use a single file per job to carry phases and tasks.\n- The last task of every phase must be user manual verification.\n- Track branches as indented checklist items; complete same-indent branch items before returning to the parent flow.\n- Update `.codex/jobs/activated.md` whenever the active job changes.\n- If required .codex paths are missing, ask before creating them.\n\n## Job file format\n\nUse `jobs/<job>/<job>.md` with Markdown checklists:\n\n```markdown\n# Job: <job-name>\n\n## Phase 1: <phase-name>\n- [ ] Task: <task>\n  - [ ] Branch: <subtask>\n  - [ ] Branch: <subtask>\n- [ ] Quality Gates\n  - [ ] Build passes (if applicable)\n  - [ ] Evidence recorded (file refs / command output)\n  - [ ] Docs updated (if needed)\n- [ ] User manual verification\n\n## Phase 2: <phase-name>\n- [ ] Task: <task>\n- [ ] Quality Gates\n  - [ ] Build passes (if applicable)\n  - [ ] Evidence recorded (file refs / command output)\n  - [ ] Docs updated (if needed)\n- [ ] User manual verification\n```\n\n## Workflow usage\n\n- Treat workflows as the static guidance framework that governs each job and phase.\n- Record workflow branches in the job file as indented checklists.\n- Return to the parent flow after all items at the branch indent are complete.\n\n## Sub-skills\n\nUse specialized skills to reduce context and improve precision when scope is narrow:\n\n- `hikaze-frontend`: Vue/TypeScript/CSS UI work in `web/model_manager_frontend` or `web/custom_node_frontend`.\n- `hikaze-backend`: Python nodes and server work in `nodes/` or `backend/`.\n- `hikaze-api`: API contracts, request/response changes, and frontend-backend integration.\n\n## Conductor migration (only if requested)\n\nMigrate prompts from `custom_nodes/Hikaze-Model-Manager-2/conductor/` to `.codex/` only when the user asks:\n\n- `conductor/product.md` -> `.codex/constitution/product.md`\n- `conductor/tech-stack.md` -> `.codex/constitution/tech-stack.md`\n- `conductor/code_styleguides/*` -> `.codex/constitution/code_styleguides/*`\n- `conductor/workflow.md` -> `.codex/workflows/default.md`\n- `conductor/product-guidelines.md` -> `.codex/guidelines/product-guidelines.md`\n- `conductor/archive/*` -> `.codex/jobs/archive/*`\n- Do not migrate `conductor/discrepancies/*` unless the user explicitly requests it.\n\n## Language policy\n\nAccept any input language. Choose output language by accuracy first, then token efficiency.\n"},"lastSynced":"2026-03-06T14:09:56.326Z","agentAnalysis":{"suitability":{"en":"Ideal for Codex-based AI Agents needing structured project workflow management using the .codex directory structure","zh":"适用于需要使用 .codex 目录结构进行结构化项目工作流管理的 Codex 基础 AI 代理","ja":"Codex ベースの AI エージェントが構造化されたプロジェクトワークフローマネジメントを .codex ディレクトリ構造を使用して実現する場合に最適","ko":"Codex 기반 AI 에이전트가 .codex 디렉토리 구조를 사용하여 구조화된 프로젝트 워크플ロー 관리를 필요로 할 때 적합","es":"Ideal para agentes de IA basados en Codex que necesitan una gestión de flujo de trabajo de proyecto estructurado utilizando la estructura de directorio .codex","fr":"Idéal pour les agents d''IA basés sur Codex nécessitant une gestion de workflow de projet structurée en utilisant la structure de répertoire .codex","de":"Ideal für Codex-basierte KI-Agents, die eine strukturierte Projekt-Workflow-Verwaltung unter Verwendung der .codex-Verzeichnisstruktur benö