INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('HakureiHikaze/Hikaze-Model-Manager-2/root', 'root', 'HakureiHikaze', 'Hikaze-Model-Manager-2', 'community', 'root HakureiHikaze Hikaze-Model-Manager-2 community The root skill governs Codex project work using the .codex directory structure, keeping sources of truth stable. It benefits developers working with Hikaze-Model-Manager-2. Root 技术是用于管理 Codex 项目工作流的技术，通过 .codex 目录结构实现项目原则、技术栈和代码标准的管理 Root は、.codex ディレクトリ構造を使用して Codex プロジェクトワークフローを管理する技術です Root 기술은 .codex 디렉토리 구조를 사용하여 Codex 프로젝트 작업을 관리하는 기술입니다 El skill root permite gobernar proyectos Codex con Hikaze-Model-Manager-2, manteniendo fuentes de verdad inmutables y rastreando trabajos y detalles de diseño Le skill root permet de gérer les projets Codex avec Hikaze-Model-Manager-2, en maintenant des sources de vérité immuables et en traçant les travaux et les détails de conception Das root-Skill ermöglicht die Verwaltung von Codex-Projekten mit Hikaze-Model-Manager-2, wobei unveränderliche Wahrheitsquellen aufrechterhalten und Jobs und Designdetails nachverfolgt werden O Root é uma habilidade para governar projetos Codex com Hikaze-Model-Manager-2, mantendo fontes de verdade imutáveis e rastreando trabalhos e detalhes de design Root - это навык для управления проектами Codex с Hikaze-Model-Manager-2, поддержания неизменных источников правды и отслеживания работ и деталей дизайна الجذر هو مهارة لإدارة مشاريع Codex باستخدام Hikaze-Model-Manager-2، والحفاظ على مصادر الحقيقة غير القابلة للتغيير ورصد الأعمال و تفاصيل التصميم how to use root root setup guide what is root root alternative root vs Hikaze-Model-Manager-1 root install Codex project governance Hikaze-Model-Manager-2 integration root skill for AI agents governing Codex projects with root Root 技术 Codex 项目管理 AI 工具 .codex 目录结构 项目工作流管理 代码标准管理 静态工作流框架 Reads .codex/constitution/ for project principles and tech stack Utilizes .codex/workflows/ for static workflow framework References .codex/guidelines/ for implementation details and decisions Tracks jobs and design details via .codex/jobs/activated Maintains immutable sources of truth for project stability Supports Hikaze-Model-Manager-2 for efficient project management root is a skill that governs Codex project work for Hikaze-Model-Manager-2, maintaining stable sources of truth and tracking jobs and design details.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('Surya-Sunkari/continuous-algorithms-solver/convert', 'community', 'Surya-Sunkari', 'continuous-algorithms-solver', 'Surya-Sunkari/continuous-algorithms-solver', 'convert', 0, 0, 45, '2026-03-07T12:46:33.452Z', '2026-03-07T12:54:32.126Z', 'b8f6cccab99de40468fec6c5a715fc93d2d7a57e994f5549f7cba5e2b0da0108', '{"id":"Surya-Sunkari/continuous-algorithms-solver/convert","name":"convert","description":{"en":"The Convert skill transcribes homework problems into exact LaTeX representations, ensuring accuracy for mathematical content. It benefits developers and educators seeking precise conversions.","zh":"本工具将 Homework 问题转换为 LaTeX 格式，确保数学内容的准确转录","ja":"このツールは、Homework 問題を LaTeX 形式に変換し、数学的内容の正確な転記を実現します","ko":"이 도구는 Homework 문제를 LaTeX 형식으로 변환하여数学적 내용의 정확한 전사를 달성합니다","es":"El convertidor de homework a LaTeX convierte problemas de homework en representaciones exactas de LaTeX, garantizando la precisión en la transcripción matemática","fr":"Le convertisseur de devoirs en LaTeX convertit des devoirs en représentations LaTeX exactes, assurant la précision de la transcription mathématique","de":"Der Konverter von Hausaufgaben in LaTeX wandelt Hausaufgaben in exakte LaTeX-Darstellungen um, wobei die Genauigkeit der mathematischen Transkription gewährleistet ist","pt":"O conversor de LaTeX é uma ferramenta de precisão para transcrições matemáticas. Ele converte problemas de matemática em representações LaTeX exatas.","ru":"Преобразователь в LaTeX - это инструмент высокой точности для математических транскрипций. Он преобразует математические задачи в точные представления LaTeX.","ar":"محول LaTeX هو أداة دقيقة لنسخ النصوص الرياضية. يقوم بتحويل المسائل الرياضية إلى تمثيلات LaTeX دقيقة."},"seo":{"title":{"en":"Convert: LaTeX Representation Setup Guide | AI Agent Skill","zh":"LaTeX 转换器设置指南 - Homework 到 LaTeX 的精确转换","ja":"LaTeX 変換ツールのベストプラクティス - Homework から LaTeX への正確な変換","ko":"LaTeX 변환기 설정 가이드 - Homework에서 LaTeX로의 정확한 변환","es":"Guía de configuración para convertir homework a LaTeX","fr":"Configurer le convertisseur de devoirs en LaTeX","de":"Einrichtungsleitfaden für die Konvertierung von Hausaufga...","pt":"Guia de Configuração do Conversor de LaTeX","ru":"Настройка ИИ Агента для Преобразования в LaTeX","ar":"دليل إعداد محول LaTeX بالذكاء الاصطناعي"},"description":{"en":"Unlock precise mathematical content conversion with the Convert skill. Learn how to achieve character-perfect transcriptions and discover its applications.","zh":"使用 AIエージェント 将 Homework 问题转换为 LaTeX 格式，实现准确的数学内容转录","ja":"AIエージェントを使用して、Homework 問題を LaTeX 形式に変換し、数学的内容の正確な転記を実現","ko":"AI 툴을 사용하여 Homework 문제를 LaTeX 형식으로 변환하여数学적 내용의 정확한 전사를 달성","es":"Aprende a convertir problemas de homework en representaciones exactas de LaTeX con nuestra guía paso a paso","fr":"Découvrez comment convertir des devoirs en représentations LaTeX exactes avec notre guide étape par étape","de":"Erfahren Sie, wie Sie Hausaufgaben in exakte LaTeX-Darstellungen umwandeln, mit unserer Schritt-für-Schritt-Anleitung","pt":"Aprenda a configurar o conversor de LaTeX para transcrições matemáticas precisas. Descubra como otimizar o desempenho do agente de conversão.","ru":"Узнайте, как настроить ИИ Агент для преобразования в LaTeX для точных математических транскрипций. Оптимизируйте производительность агента.","ar":"تعلم كيفية تعيين محول LaTeX للنصوص الرياضية الدقيقة. اكتشف كيفية تحسين أداء العامل المحول."},"definition":{"en":"Convert is a skill that transcribes mathematical content into LaTeX format, prioritizing accuracy for precise representations.","zh":"LaTeX 转换器是一种将 Homework 问题转换为 LaTeX 格式的工具，用于准确转录数学内容","ja":"LaTeX 変換ツールは、Homework 問題を LaTeX 形式に変換するツールであり、数学的内容の正確な転記に使用されます","ko":"LaTeX 변환기는 Homework 문제를 LaTeX 형식으로 변환하여数学적 내용의 정확한 전사를 달성하는 도구입니다","es":"Un convertidor de homework a LaTeX es una herramienta que convierte problemas de homework en representaciones exactas de LaTeX","fr":"Un convertisseur de devoirs en LaTeX est un outil qui convertit des devoirs en représentations LaTeX exactes","de":"Ein Konverter von Hausaufgaben in LaTeX ist ein Tool, das Hausaufgaben in exakte LaTeX-Darstellungen umwandelt","pt":"O que é um conversor de LaTeX? É uma ferramenta que converte problemas de matemática em representações LaTeX exatas.","ru":"Что такое преобразователь в LaTeX? Это инструмент, который преобразует математические задачи в точные представления LaTeX.","ar":"ما هو محول LaTeX؟ هو أداة تقوم بتحويل المسائل الرياضية إلى تمثيلات LaTeX دقيقة."},"features":{"en":["Writes output to files using the Write tool for reliable subagent results","Supports conversion of homework problems into LaTeX representations","Ensures character-perfect transcriptions of mathematical content","Targets assignment folders specified by the $ARGUMENTS variable","Utilizes a subagent output strategy for efficient conversions"],"zh":["支持 Homework 问题到 LaTeX 格式的转换","确保数学内容的准确转录","使用 Write 工具将输出写入文件","支持子代理输出策略"],"ja":["Homework 問題を LaTeX 形式に変換する機能","数学的内容の正確な転記を実現","Write ツールを使用して出力をファイルに書き込む","子代理の出力戦略をサポート"],"ko":["Homework 문제를 LaTeX 형식으로 변환하는 기능","数学적 내용의 정확한 전사를 달성","Write 툴을 사용하여 출력을 파일에 작성","하위 에이전트 출력 전략 지원"],"es":["Conversión exacta de problemas de homework en LaTeX","Uso de la herramienta Write para escribir la salida en archivos","Compatibilidad con carpetas de asignación de destino","Garantía de precisión en la transcripción matemática","Soporte para subagentes que escriben resultados en archivos"],"fr":["Conversion exacte de devoirs en LaTeX","Utilisation de l''outil Write pour écrire la sortie dans des fichiers","Compatibilité avec les dossiers de destination d''affectation","Garantie de précision dans la transcription mathématique","Prise en charge des sous-agents qui écrivent les résultats dans des fichiers"],"de":["Exakte Konvertierung von Hausaufgaben in LaTeX","Verwendung des Write-Tools, um die Ausgabe in Dateien zu schreiben","Kompatibilität mit Zielordnern für die Zuweisung","Garantie der Genauigkeit bei der mathematischen Transkription","Unterstützung für Subagenten, die Ergebnisse in Dateien schreiben"],"pt":["Conversão de problemas de matemática em LaTeX","Saída de arquivos utilizando a ferramenta Write","Compatibilidade com pastas de atribuições","Suporte à transcrição de conteúdo matemático exato","Integração com subagentes para processamento de saída","Utilização do argumento $ARGUMENTS para especificar a pasta de atribuições"],"ru":["Преобразование математических задач в LaTeX","Выходные файлы с помощью инструмента Write","Возможность работы с папками заданий","Поддержка точной транскрипции математического содержания","Интеграция с субагентами для обработки вывода","Использование аргумента $ARGUMENTS для указания папки заданий"],"ar":["تحويل المسائل الرياضية إلى LaTeX","إخراج الملفات باستخدام أداة الكتابة","متوافق مع مجلدات الواجبات","دعم النسخ الدقيق للمحتوى الرياضي","التكامل مع العوامل الفرعية لمعالجة الإخراج","استخدام الحجة $ARGUMENTS لتحديد مجلد الواجب"]},"keywords":{"en":["how to use convert skill","convert skill alternative","convert setup guide","what is convert skill","convert vs latex converters","install convert skill","convert skill for ai agents","latex representation convert","convert skill tutorial"],"zh":["LaTeX 转换器","Homework 到 LaTeX","数学内容转录","AIエージェント","Write 工具","子代理输出策略"],"ja":["LaTeX 変換ツール","Homework から LaTeX","数学的内容の転記","AIエージェント","Write ツール","子代理の出力戦略"],"ko":["LaTeX 변환기","Homework에서 LaTeX로","数学적 내용의 전사","AI 툴","Write 툴","하위 에이전트 출력 전략"],"es":["convertidor de homework a LaTeX","herramientas de conversión de LaTeX","conversión exacta de problemas de homework","transcripción matemática precisa","subagentes que escriben resultados en archivos","herramienta Write para escritura de archivos","carpetas de asignación de destino","Guía de configuración para convertir homework a LaTeX"],"fr":["convertisseur de devoirs en LaTeX","outils de conversion LaTeX","conversion exacte de devoirs","transcription mathématique précise","sous-agents qui écrivent les résultats dans des fichiers","outil Write pour écriture de fichiers","dossiers de destination d''affectation","Configurer le convertisseur de devoirs en LaTeX"],"de":["Konverter von Hausaufgaben in LaTeX","LaTeX-Konvertierungstools","exakte Konvertierung von Hausaufgaben","genaue mathematische Transkription","Subagenten, die Ergebnisse in Dateien schreiben","Write-Tool für die Ausgabe in Dateien","Zielordner für die Zuweisung","Einrichtungsleitfaden für die Konvertierung von Hausaufgaben in LaTeX"],"pt":["conversor de LaTeX","transcrição matemática","ferramenta de precisão","representações LaTeX","subagentes","Write tool","pastas de atribuições","desenvolvimento de agente de conversão"],"ru":["преобразователь в LaTeX","математическая транскрипция","инструмент высокой точности","представления LaTeX","субагенты","Write tool","папки заданий","разработка агента преобразования"],"ar":["محول LaTeX","نسخ رياضي","أداة دقة","تمثيلات LaTeX","عوامل فرعية","أداة الكتابة","مجلدات الواجبات","تطوير عامل التحويل"]}},"owner":"Surya-Sunkari","repo":"continuous-algorithms-solver","repoPath":"Surya-Sunkari/continuous-algorithms-solver","stars":0,"forks":0,"updatedAt":"2026-03-07T12:46:33.452Z","topics":[],"category":"community","skillMd":{"name":"convert","description":"Convert homework PDF or problem screenshots to exact LaTeX representations","bodyPreview":"# Homework to LaTeX Converter\n\nYou are converting homework problems into their **exact** LaTeX representations. Accuracy is paramount — the output must be a character-perfect transcription of the mathematical content.\n\nThe target assignment folder is: `$ARGUMENTS`\n\n---\n\n## IMPORTANT: Subagent Output Strategy\n\nAll subagents in this skill MUST write their output to files using the Write tool, NOT return text in their response. This ensures the main agent can reliably read subagent results.\n\n- Tran","body":"# Homework to LaTeX Converter\n\nYou are converting homework problems into their **exact** LaTeX representations. Accuracy is paramount — the output must be a character-perfect transcription of the mathematical content.\n\nThe target assignment folder is: `$ARGUMENTS`\n\n---\n\n## IMPORTANT: Subagent Output Strategy\n\nAll subagents in this skill MUST write their output to files using the Write tool, NOT return text in their response. This ensures the main agent can reliably read subagent results.\n\n- Transcription subagents write to: `$ARGUMENTS/problems/pN.tex`\n- Verification subagents write to: `$ARGUMENTS/problems/pN_verification.txt`\n\nAfter all subagents finish, the main agent reads these files to check results and clean up verification files.\n\n---\n\n## PHASE 1: Input Detection & Validation\n\nAuto-detect the input mode by checking in this order:\n\n1. **PDF mode**: Use Glob to check for any `.pdf` file in `$ARGUMENTS/` (NOT in `$ARGUMENTS/notes/`). If found, use PDF mode.\n2. **Screenshot mode**: Check if `$ARGUMENTS/screenshots/` exists with `problem*` subdirectories containing image files. If found, use screenshot mode.\n3. **Neither found**: Stop and tell the user to either place a homework PDF in `$ARGUMENTS/` or create screenshot folders in `$ARGUMENTS/screenshots/problem1/`, etc.\n\nCreate `$ARGUMENTS/problems/` if it does not exist.\n\nTell the user which mode was detected before proceeding.\n\n---\n\n## PDF MODE\n\n### Phase 2P: Read & Split PDF\n\n#### Step A: Read the Full PDF\n\n1. Identify the PDF file in `$ARGUMENTS/` (if multiple PDFs exist, exclude any in `notes/` and pick the one that looks like a homework — or ask the user).\n2. Read the PDF using the Read tool. For PDFs longer than 10 pages, read in chunks of 10-20 pages using the `pages` parameter.\n3. As you read, identify:\n   - **Problem boundaries**: Look for headings like \"Problem 1\", \"Problem 2\", \"Question 1\", etc.\n   - **Footnotes**: Note which footnotes belong to which problem. Footnotes are typically numbered (e.g., superscript 1, 2, 3) and appear at the bottom of the page or end of the document.\n   - **Shared preamble text**: Any setup text that applies to multiple problems (e.g., \"For problems 1-3, assume X...\"). This should be included at the top of each relevant problem file.\n\n#### Step B: Transcribe Each Problem\n\nFor each identified problem, launch a Task subagent (subagent_type: \"general-purpose\", model: \"opus\"). You may launch multiple subagents in parallel since they write to separate files.\n\nSubagent prompt:\n\n```\nYou are an expert LaTeX transcriber. Your job is to produce an EXACT transcription of a math problem from a PDF into LaTeX.\n\nRead the following PDF file and extract ONLY the specified problem:\n[PDF file path and page range]\n\nPROBLEM TO EXTRACT: Problem N\nPROBLEM BOUNDARIES: Starts at [description] and ends at [description]\n\nFOOTNOTES BELONGING TO THIS PROBLEM:\n[list any footnotes that are referenced within this problem''s text]\n\nSHARED PREAMBLE (include at the top if present):\n[any shared setup text that applies to this problem]\n\nRULES — follow these precisely:\n1. EXACT TRANSCRIPTION: Reproduce every symbol, subscript, superscript, fraction, summation, integral, matrix, and piece of text exactly as it appears. Do not paraphrase, rephrase, simplify, or add anything.\n2. MATH NOTATION: Use standard LaTeX math commands. Use \\mathbb for blackboard bold, \\mathbf for bold vectors, \\text{} for text within math mode, \\operatorname{} for named operators, \\mathcal for calligraphic letters, \\ell for script l.\n3. FORMATTING: Preserve the visual structure — numbered parts like (i), (ii), (iii) or (a), (b), (c) should be kept as-is. Preserve paragraph breaks and line breaks where they appear meaningful.\n4. NO PREAMBLE: Output only the problem content — no \\documentclass, no \\begin{document}, no packages. Just the raw LaTeX content that would go inside a document body.\n5. NO SOLUTIONS: Only transcribe the problem statement. If a solution or hint appears, do not include it.\n6. DISPLAY MATH: Use \\[...\\] for displayed equations (never $$...$$). Use align* if the original shows aligned/numbered equations.\n7. INLINE MATH: Use $...$ for inline math.\n8. FOOTNOTES: Include footnotes using \\footnote{} inline where the superscript reference appears in the problem text. Transcribe the footnote content exactly.\n9. DOUBLE-CHECK: After transcribing, re-read the PDF and verify every symbol matches. Pay special attention to:\n   - Subscripts vs superscripts\n   - Similar-looking symbols (ε vs ∈, ≤ vs <, ⊂ vs ⊆)\n   - Parentheses vs brackets vs braces\n   - Bold vs regular vs calligraphic letters\n   - Summation/product bounds (above vs below)\n   - Fraction numerators and denominators\n   - Footnote numbering and content\n\nIMPORTANT: Use the Write tool to save your transcription to: [output file path for pN.tex]\nDo NOT just output the text — you MUST write it to the file.\n```\n\n#### Step C: Verification\n\nAfter transcription subagents complete, launch SEPARATE verification subagents (subagent_type: \"general-purpose\", model: \"opus\") — one per problem, can run in parallel.\n\nSubagent prompt:\n\n```\nYou are a LaTeX transcription verifier. You will be given a PDF of a math homework and a proposed LaTeX transcription of one problem. Your job is to find ANY discrepancies.\n\nRead the PDF:\n[PDF file path and page range]\n\nPROBLEM BEING VERIFIED: Problem N\n\nRead the proposed transcription from: [path to pN.tex]\n\nCompare the PDF to the LaTeX character by character for this problem. Check:\n1. Every mathematical symbol matches exactly\n2. Every subscript and superscript is correct\n3. All fractions, sums, products, integrals have correct bounds\n4. Text content matches word-for-word\n5. Numbering of parts/subparts matches\n6. No content is missing or added\n7. Parentheses, brackets, and delimiters match\n8. All footnotes referenced in this problem are included with exact content\n9. Any shared preamble text is correctly included\n\nIMPORTANT: Use the Write tool to save your verdict to: [path to pN_verification.txt]\nWrite either \"VERIFIED\" if the transcription is exact, or list discrepancies as:\nDISCREPANCY: [what''s wrong and what it should be]\n```\n\n#### Step D: Check Results & Retry\n\n1. Read each `pN_verification.txt` file.\n2. If VERIFIED, the problem is done.\n3. If discrepancies were found:\n   - Launch a new transcription subagent with the original PDF PLUS the discrepancy feedback. Instruct it to read the current pN.tex, fix the listed errors, and overwrite pN.tex.\n   - Launch a fresh verifier to re-check and overwrite pN_verification.txt.\n   - Repeat up to 3 times. If still failing, prepend a LaTeX comment to pN.tex: `% NOTE: Transcription could not be fully verified — check against original PDF`\n4. Delete all `pN_verification.txt` files when done.\n\n---\n\n## SCREENSHOT MODE\n\n### Phase 2S: Convert Screenshots\n\nFor each `$ARGUMENTS/screenshots/problemN/` folder:\n\n#### Step A: Read Screenshots\n\n1. Use Glob to find all image files in the folder (*.png, *.jpg, *.jpeg, *.bmp, *.webp).\n2. Sort them by filename (they may be ordered as page1.png, page2.png, etc. or similar).\n3. Read each image using the Read tool. If a problem spans multiple screenshots, read them all in order to get the complete problem.\n\n#### Step B: Transcribe to LaTeX\n\nLaunch a Task subagent (subagent_type: \"general-purpose\", model: \"opus\"). You may launch multiple subagents in parallel since they write to separate files.\n\nSubagent prompt:\n\n```\nYou are an expert LaTeX transcriber. Your job is to produce an EXACT transcription of a math problem from screenshots into LaTeX.\n\nRead the following image files using the Read tool:\n[list all image file paths for this problem]\n\nRULES — follow these precisely:\n1. EXACT TRANSCRIPTION: Reproduce every symbol, subscript, superscript, fraction, summation, integral, matrix, and piece of text exactly as it appears in the screenshot. Do not paraphrase, rephrase, simplify, or add anything.\n2. MATH NOTATION: Use standard LaTeX math commands. Use \\mathbb for blackboard bold, \\mathbf for bold vectors, \\text{} for text within math mode, \\operatorname{} for named operators, \\mathcal for calligraphic letters, \\ell for script l.\n3. FORMATTING: Preserve the visual structure — numbered parts like (i), (ii), (iii) or (a), (b), (c) should be kept as-is. Preserve paragraph breaks and line breaks where they appear meaningful.\n4. NO PREAMBLE: Output only the problem content — no \\documentclass, no \\begin{document}, no packages. Just the raw LaTeX content that would go inside a document body.\n5. NO SOLUTIONS: Only transcribe the problem statement. If a solution or hint appears, do not include it.\n6. DISPLAY MATH: Use \\[...\\] for displayed equations (never $$...$$). Use align* if the original shows aligned/numbered equations.\n7. INLINE MATH: Use $...$ for inline math.\n8. FOOTNOTES: If footnotes are visible in the screenshots, include them using \\footnote{} inline where the superscript reference appears.\n9. DOUBLE-CHECK: After transcribing, re-read the screenshot and verify every symbol matches. Pay special attention to:\n   - Subscripts vs superscripts\n   - Similar-looking symbols (ε vs ∈, ≤ vs <, ⊂ vs ⊆)\n   - Parentheses vs brackets vs braces\n   - Bold vs regular vs calligraphic letters\n   - Summation/product bounds (above vs below)\n   - Fraction numerators and denominators\n\nIMPORTANT: Use the Write tool to save your transcription to: [output file path for pN.tex]\nDo NOT just output the text — you MUST write it to the file.\n```\n\n#### Step C: Verification\n\nAfter transcription subagents complete, launch SEPARATE verification subagents (subagent_type: \"general-purpose\", model: \"opus\") — one per problem, can run in parallel.\n\nSubagent prompt:\n\n```\nYou are a LaTeX transcription verifier. You will be given screenshots of a math problem and a proposed LaTeX transcription. Your job is to find ANY discrepancies.\n\nRead the following image files using the Read tool:\n[list all image file paths for this problem]\n\nThen read the proposed transcription from: [path to pN.tex]\n\nCompare the screenshot to the LaTeX character by character. Check:\n1. Every mathematical symbol matches exactly\n2. Every subscript and superscript is correct\n3. All fractions, sums, products, integrals have correct bounds\n4. Text content matches word-for-word\n5. Numbering of parts/subparts matches\n6. No content is missing or added\n7. Parentheses, brackets, and delimiters match\n8. All visible footnotes are included with exact content\n\nIMPORTANT: Use the Write tool to save your verdict to: [path to pN_verification.txt]\nWrite either \"VERIFIED\" if the transcription is exact, or list discrepancies as:\nDISCREPANCY: [what''s wrong and what it should be]\n```\n\n#### Step D: Check Results & Retry\n\n1. Read each `pN_verification.txt` file.\n2. If VERIFIED, the problem is done.\n3. If discrepancies were found:\n   - Launch a new transcription subagent with the original screenshots PLUS the discrepancy feedback. Instruct it to read the current pN.tex, fix the listed errors, and overwrite pN.tex.\n   - Launch a fresh verifier to re-check and overwrite pN_verification.txt.\n   - Repeat up to 3 times. If still failing, prepend a LaTeX comment to pN.tex: `% NOTE: Transcription could not be fully verified — check against original screenshot`\n4. Delete all `pN_verification.txt` files when done.\n\n---\n\n## PHASE 3: Report\n\nTell the user:\n- Which input mode was used (PDF or screenshots)\n- How many problems were converted\n- Which problems passed verification on the first attempt vs. required retries\n- Any problems that could not be fully verified\n- Where the output files are saved\n- Remind the user they can now run `/solve $ARGUMENTS` to generate solutions\n"},"lastSynced":"2026-03-07T12:54:32.126Z","agentAnalysis":{"suitability":{"en":"Ideal for Math-Oriented AI Agents requiring precise LaTeX conversions for homework problems and mathematical content.","zh":"非常适合需要为作业问题和数学内容进行精确LaTeX转换的数学导向型AI Agent。","ja":"数学指向のAIエージェントが、宿題の問題や数学コンテンツのために正確なLaTeX変換を必要とする場合に理想的です。","ko":"숙제 문제와 수학 콘텐츠를 위한 정확한 LaTeX 변환이 필요한 수학 중심 AI 에이전트에 이상적입니다.","es":"Ideal para agentes de IA con orientación matemática que requieren conversiones de LaTeX precisas para problemas de tareas y contenido matemático.","fr":"Idéal pour les agents d''IA à orientation mathématique nécessitant des conversions LaTeX précises pour les problèmes de devoirs et le contenu mathématique.","de":"Ideal für mathematisch orientierte KI-Agents, die präzise LaTeX-Konvertierungen für Hausaufgabenprobleme und mathematischen Inhalt benötigen.","pt":"Ideal para Agentes de IA com orientação matemática que exigem conversões precisas de LaTeX para problemas de lição de casa e conteúdo matemático.","ru":"Идеально для математически-ориентированных агентов ИИ, требующих точных преобразований LaTeX для домашних заданий и математического контента.","ar":"مثالي لعميل الذكاء الاصطناعي ذي التوجه الرياضي الذي يتطلب تحويلات دقيقة من LaTeX لأسئلة الواجب المدرسي والمحتوى الرياضي."},"recommendation":{"en":"Empowers agents to transcribe homework problems into exact LaTeX representations, ensuring accuracy for mathematical content using character-perfect transcriptions, and leveraging the Write tool for reliable output management in formats like LaTeX.","zh":"使Agent能够将作业问题转录为精确的LaTeX表示，通过字符级完美转录确保数学内容的准确性，并利用Write工具以LaTeX等格式进行可靠的输出管理。","ja":"エージェントが宿題の問題を正確なLaTeX表現に転写することを可能にし、文字単位の完璧な転写によって数学コンテンツの正確性を確保し、Writeツールを活用してLaTeXなどのフォーマットで信頼性の高い出力管理を実現します。","ko":"에이전트가 숙제 문제를 정확한 LaTeX 표현으로 전사할 수 있도록 하여, 문자 단위 완벽 전사를 통해 수학 콘텐츠의 정확성을 보장하고, Write 도구를 활용하여 LaTeX과 같은 형식으로 신뢰할 수 있는 출력 관리를 제공합니다.","es":"Permite a los agentes transcribir problemas de tareas en representaciones LaTeX exactas, garantizando la precisión para el contenido matemático mediante transcripciones perfectas de personajes y aprovechando la herramienta Write para una gestión de salida fiable en formatos como LaTeX.","fr":"Permet aux agents de transcrire des problèmes de devoirs en représentations LaTeX exactes, en garantissant l''exactitude pour le contenu mathématique à l''aide de transcriptions de caractères parfaites et en exploitant l''outil Write pour une gestion de sortie fiable dans des formats tels que LaTeX.","de":"Ermöglicht es Agents, Hausaufgabenprobleme in exakte LaTeX-Darstellungen zu transkribieren, die Genauigkeit für mathematischen Inhalt sicherzustellen, indem character-perfecte Transkriptionen verwendet werden und das Write-Tool für eine zuverlässige Ausgabesteuerung in Formaten wie LaTeX nutzt.","pt":"Habilita os agentes a transcrever problemas de lição de casa em representações LaTeX exatas, garantindo precisão para o conteúdo matemático usando transcrições perfeitas de personagens, e aproveitando a ferramenta Write para gerenciamento de saída confiável em formatos como LaTeX.","ru":"Наделяет агентов возможностью транскрибировать домашние задания в точные представления LaTeX, обеспечивая точность для математического контента с помощью транскрипций, идеальных по символам, и использует инструмент Write для надежного управления выводом в форматах, таких как LaTeX.","ar":"يمنح الوكلاء khảية نسخ أسئلة الواجب المدرسي إلى تمثيلات دقيقة من LaTeX، مما يضمن الدقة للمحتوى الرياضي باستخدام نسخ دقيقة للأحرف، ويتوفر على أداة الكتابة لإدارة الإخراج الموثوق في صيغ مثل LaTeX."},"useCases":{"en":["Transcribing complex mathematical equations into LaTeX","Converting homework problems into precise LaTeX formats for educational materials","Generating accurate LaTeX representations for mathematical research papers"],"zh":["将复杂的数学方程式转录为LaTeX","将作业问题转换为精确的LaTeX格式以用于教育材料","为数学研究论文生成准确的LaTeX表示"],"ja":["複雑な数式をLaTeXに転写する","教材向けに宿題の問題を正確なLaTeXフォーマットに変換する","数学研究論文のための正確なLaTeX表現を生成する"],"ko":["복잡한 수학 방정식을 LaTeX으로 전사하기","교육 자료를 위해 숙제 문제를 정확한 LaTeX 형식으로 변환하기","수학 연구 논문을 위한 정확한 LaTeX 표현 생성하기"],"es":["Transcribir ecuaciones matemáticas complejas en LaTeX","Convertir problemas de tareas en formatos LaTeX precisos para materiales educativos","Generar representaciones LaTeX precisas para artículos de investigación matemática"],"fr":["Transcrire des équations mathématiques complexes en LaTeX","Convertir des problèmes de devoirs en formats LaTeX précis pour des matériels éducatifs","Générer des représentations LaTeX précises pour des articles de recherche mathématique"],"de":["Komplexe mathematische Gleichungen in LaTeX transkribieren","Hausaufgabenprobleme in präzise LaTeX-Formate für Lehrmaterialien konvertieren","Erzeugen genauer LaTeX-Darstellungen für mathematische Forschungsarbeiten"],"pt":["Transcrever equações matemáticas complexas em LaTeX","Converter problemas de lição de casa em formatos LaTeX precisos para materiais educacionais","Gerar representações LaTeX precisas para artigos de pesquisa matemática"],"ru":["Транскрибировать сложные математические уравнения в LaTeX","Преобразовывать домашние задания в точные форматы LaTeX для образовательных материалов","Генерировать точные представления LaTeX для математических исследований"],"ar":["نسخ معادلات رياضية معقدة إلى LaTeX","تحويل أسئلة الواجب المدرسي إلى صيغ LaTeX دقيقة لمواد تعليمية","توليد تمثيلات دقيقة من LaTeX لأوراق بحثية رياضية"]},"limitations":{"en":["Requires target assignment folder specified in $ARGUMENTS","Output must be written to files using the Write tool","Character-perfect transcription is mandatory"],"zh":["需要在$ARGUMENTS中指定目标分配文件夹","必须使用Write工具将输出写入文件","字符级完美转录是强制性的"],"ja":["$ARGUMENTSでターゲット割り当てフォルダを指定する必要がある","Writeツールを使用して出力をファイルに書き込む必要がある","文字単位の完璧な転写が必須である"],"ko":["$ARGUMENTS에서 대상 할당 폴더를 지정해야 함","Write 도구를 사용하여 출력을 파일에 작성해야 함","문자 단위 완벽 전사가 필수적임"],"es":["Requiere una carpeta de asignación de destino especificada en $ARGUMENTS","La salida debe escribirse en archivos utilizando la herramienta Write","La transcripción perfecta de caracteres es obligatoria"],"fr":["Nécessite un dossier de destination cible spécifié dans $ARGUMENTS","La sortie doit être écrite dans des fichiers à l''aide de l''outil Write","La transcription parfaite de caractères est obligatoire"],"de":["Benötigt ein Zielverzeichnis, das in $ARGUMENTS angegeben ist","Die Ausgabe muss in Dateien mithilfe des Write-Tools geschrieben werden","Eine character-perfecte Transkription ist obligatorisch"],"pt":["Exige pasta de atribuição de destino especificada em $ARGUMENTS","A saída deve ser escrita em arquivos usando a ferramenta Write","A transcrição perfeita de caracteres é obrigatória"],"ru":["Требует указания целевой папки назначения в $ARGUMENTS","Вывод должен быть записан в файлы с помощью инструмента Write","Транскрипция, идеальная по символам, является обязательной"],"ar":["يتطلب تحديد مجلد الإسناد الهدف في $ARGUMENTS","يجب كتابة الإخراج في الملفات باستخدام أداة الكتابة","نسخ الأحرف المثالية هو إلزامي"]},"version":4},"contentHash":"b8f6cccab99de40468fec6c5a715fc93d2d7a57e994f5549f7cba5e2b0da0108","qualityScore":45}');
