INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('Surya-Sunkari/continuous-algorithms-solver/convert', 'convert', 'Surya-Sunkari', 'continuous-algorithms-solver', 'community', 'convert Surya-Sunkari continuous-algorithms-solver community The Convert skill transcribes homework problems into exact LaTeX representations, ensuring accuracy for mathematical content. It benefits developers and educators seeking precise conversions. 本工具将 Homework 问题转换为 LaTeX 格式，确保数学内容的准确转录 このツールは、Homework 問題を LaTeX 形式に変換し、数学的内容の正確な転記を実現します 이 도구는 Homework 문제를 LaTeX 형식으로 변환하여数学적 내용의 정확한 전사를 달성합니다 El convertidor de homework a LaTeX convierte problemas de homework en representaciones exactas de LaTeX, garantizando la precisión en la transcripción matemática Le convertisseur de devoirs en LaTeX convertit des devoirs en représentations LaTeX exactes, assurant la précision de la transcription mathématique Der Konverter von Hausaufgaben in LaTeX wandelt Hausaufgaben in exakte LaTeX-Darstellungen um, wobei die Genauigkeit der mathematischen Transkription gewährleistet ist O conversor de LaTeX é uma ferramenta de precisão para transcrições matemáticas. Ele converte problemas de matemática em representações LaTeX exatas. Преобразователь в LaTeX - это инструмент высокой точности для математических транскрипций. Он преобразует математические задачи в точные представления LaTeX. محول LaTeX هو أداة دقيقة لنسخ النصوص الرياضية. يقوم بتحويل المسائل الرياضية إلى تمثيلات LaTeX دقيقة. how to use convert skill convert skill alternative convert setup guide what is convert skill convert vs latex converters install convert skill convert skill for ai agents latex representation convert convert skill tutorial LaTeX 转换器 Homework 到 LaTeX 数学内容转录 AIエージェント Write 工具 子代理输出策略 Writes output to files using the Write tool for reliable subagent results Supports conversion of homework problems into LaTeX representations Ensures character-perfect transcriptions of mathematical content Targets assignment folders specified by the $ARGUMENTS variable Utilizes a subagent output strategy for efficient conversions Convert is a skill that transcribes mathematical content into LaTeX format, prioritizing accuracy for precise representations.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('SocketDev/socket-btm/syncing-upstream', 'community', 'SocketDev', 'socket-btm', 'SocketDev/socket-btm', 'syncing-upstream', 0, 0, 45, '2026-03-06T23:26:09Z', '2026-03-07T03:52:41.953Z', '30b53ed8b455763fcdc3470b8d7930e876e5d5b80ce119bba14ab25f467816f3', '{"id":"SocketDev/socket-btm/syncing-upstream","name":"syncing-upstream","description":{"en":"The syncing-upstream skill synchronizes socket-btm with upstream Node.js by updating the submodule and regenerating patches. This benefits developers working with custom Node.js binaries and Socket Security patches.","zh":"Syncing-Upstream 是一种用于同步 Node.js 版本的技术，通过更新子模块和重新生成补丁来实现","ja":"Syncing-Upstream は Node.js バージョンを同期する技術で、サブモジュールの更新とパッチの再生成を実行する","ko":"Syncing-Upstream은 Node.js 버전을 동기화하는 기술로, 하위 모듈을 업데이트하고 패치를 재생성하는 기능을 제공","es":"Syncing-upstream es una habilidad que actualiza la versión de Node.js con patches de seguridad de Socket y mantiene el submodule actualizado","fr":"Syncing-upstream est une compétence qui met à jour la version de Node.js avec des patchs de sécurité de Socket et maintient le submodule à jour","de":"Syncing-upstream ist eine Fähigkeit, die die Node.js-Version mit Socket-Sicherheitspatches aktualisiert und das Submodule auf dem neuesten Stand hält","pt":"O syncing-upstream é uma habilidade que sincroniza o socket-btm com o Node.js upstream, atualizando o submodule e gerando patches de segurança","ru":"Syncing-upstream - это навык, который синхронизирует socket-btm с Node.js upstream, обновляя submodule и генерируя патчи безопасности","ar":"syncing-upstream هو مهارة تزامن socket-btm مع Node.js upstream، وتحديث submodule و توليد باتشات أمان"},"seo":{"title":{"en":"syncing-upstream: Node.js Synchronization Setup Guide | A...","zh":"Syncing-Upstream 设置指南：Node.js 同步最佳实践","ja":"Syncing-Upstream 導入ガイド：Node.js 同期のベストプラクティス","ko":"Syncing-Upstream 설정 가이드: Node.js 동기화 최적화","es":"Guía de configuración de syncing-upstream para agentes de IA","fr":"Mise en place de syncing-upstream pour les outils d''IA","de":"Einrichtungsleitfaden für syncing-upstream mit KI-Agenten","pt":"Guia de Configuração do syncing-upstream para Node.js","ru":"Настройка ИИ Агентов syncing-upstream для Node.js","ar":"دليل إعداد syncing-upstream لأجهزة الإيضاح الذكية Node.js"},"description":{"en":"Discover how syncing-upstream updates submodule to latest stable tag, regenerates patches, and validates build/tests. Learn to synchronize socket-btm with up...","zh":"了解 Syncing-Upstream 技术，实现 Node.js 版本更新、子模块更新、补丁重新生成等功能","ja":"Syncing-Upstream 技術を使用して Node.js バージョンを更新し、サブモジュールを更新し、パッチを再生成する","ko":"Syncing-Upstream 기술을 사용하여 Node.js 버전을 업데이트하고, 하위 모듈을 업데이트하고, 패치를 재생성하는 방법","es":"Aprende a configurar syncing-upstream para mantener actualizada la versión de Node.js con patches de seguridad de Socket","fr":"Découvrez comment configurer syncing-upstream pour maintenir à jour la version de Node.js avec des patchs de sécurité de Socket","de":"Erfahren Sie, wie Sie syncing-upstream einrichten, um die Node.js-Version mit Socket-Sicherheitspatches auf dem neuesten Stand zu halten","pt":"Aprenda a configurar o syncing-upstream para manter o Node.js atualizado e seguro com patches de segurança de socket","ru":"Узнайте, как настроить syncing-upstream для поддержания актуальности и безопасности Node.js с помощью патчей безопасности socket","ar":"تعرف على كيفية إعداد syncing-upstream لتحديث Node.js وتأمينها باستخدام باتشات أمان сокيت"},"definition":{"en":"syncing-upstream is a skill that updates the baseline Node.js version by synchronizing socket-btm with upstream Node.js, ensuring the latest stable tag and patches are applied.","zh":"Syncing-Upstream 是一种自动化工具，用于将 socket-btm 与上游 Node.js 同步","ja":"Syncing-Upstream は socket-btm を上流の Node.js と同期する自動化ツール","ko":"Syncing-Upstream은 socket-btm을 상류 Node.js와 동기화하는 자동화 도구","es":"Syncing-upstream es una habilidad de agentes de IA que sincroniza la versión de Node.js con patches de seguridad de Socket","fr":"Syncing-upstream est une compétence d''outils d''IA qui synchronise la version de Node.js avec des patchs de sécurité de Socket","de":"Syncing-upstream ist eine Fähigkeit von KI-Agenten, die die Node.js-Version mit Socket-Sicherheitspatches synchronisiert","pt":"O que é syncing-upstream? É uma habilidade que mantém o Node.js atualizado com patches de segurança de socket","ru":"Что такое syncing-upstream? Это навык, который поддерживает Node.js в актуальном состоянии с помощью патчей безопасности socket","ar":"ما هو syncing-upstream؟ إنه مهارة لت维护 Node.js محدثًا مع باتشات أمان сокيت"},"features":{"en":["Updates submodule to the latest stable tag","Regenerates patches for custom Node.js binaries","Validates build and tests pass with detailed metrics","Commits changes with updated .node-version","Ensures socket-btm is synchronized with upstream Node.js"],"zh":["自动更新 Node.js 版本","更新子模块到最新稳定标签","重新生成补丁","验证构建和测试通过","提交更改并包含详细指标"],"ja":["Node.js バージョンの自動更新","サブモジュールを最新の安定タグに更新","パッチの再生成","ビルドとテストの検証","変更のコミットと詳細なメトリクスの含み"],"ko":["Node.js 버전 자동 업데이트","하위 모듈을 최신 안정적인 태그로 업데이트","패치 재생성","빌드 및 테스트 검증","변경 사항 커밋 및详细한 메트릭 포함"],"es":["Actualización de la versión de Node.js con patches de seguridad de Socket","Mantenimiento del submodule actualizado","Regeneración de patches","Validación de la construcción y pruebas","Confirmación de cambios con métricas detalladas"],"fr":["Mise à jour de la version de Node.js avec des patchs de sécurité de Socket","Maintenance du submodule à jour","Régénération de patchs","Validation de la construction et des tests","Confirmation des modifications avec des métriques détaillées"],"de":["Aktualisierung der Node.js-Version mit Socket-Sicherheitspatches","Aufrechterhaltung des aktuellem Submodules","Neuerzeugung von Patches","Validierung der Konstruktion und Tests","Bestätigung von Änderungen mit detaillierten Metriken"],"pt":["Atualização do submodule para a última versão estável","Geração de patches de segurança de socket","Validação de build e testes","Atualização do arquivo .node-version","Commit de alterações com métricas detalhadas"],"ru":["Обновление submodule до последней стабильной версии","Генерация патчей безопасности socket","Валидация сборки и тестов","Обновление файла .node-version","Коммит изменений с подробными метриками"],"ar":["تحديث submodule إلى الإصدار المستقر الأخير","توليد باتشات أمان сокيت","التحقق من بناء وتجارب","تحديث ملف .node-version","التعهد بالتغييرات مع معايير مفصلة"]},"keywords":{"en":["how to use syncing-upstream","what is syncing-upstream","syncing-upstream alternative","syncing-upstream vs socket-btm","syncing-upstream install","syncing-upstream setup guide","Node.js synchronization","socket-btm updates","upstream Node.js integration"],"zh":["Syncing-Upstream","Node.js 同步","socket-btm","自动化工具","子模块更新","补丁重新生成","AIエージェント"],"ja":["Syncing-Upstream","Node.js 同期","socket-btm","自動化ツール","サブモジュールの更新","パッチの再生成","AIエージェント"],"ko":["Syncing-Upstream","Node.js 동기화","socket-btm","자동화 도구","하위 모듈 업데이트","패치 재생성","AI 에이전트"],"es":["agentes de IA","herramientas de IA","syncing-upstream","Node.js","patches de seguridad de Socket","submodule","regeneración de patches","validación de construcción y pruebas"],"fr":["outils d''IA","agents d''IA","syncing-upstream","Node.js","patchs de sécurité de Socket","submodule","régénération de patchs","validation de la construction et des tests"],"de":["KI-Agenten","KI-Tools","syncing-upstream","Node.js","Socket-Sicherheitspatches","Submodule","Neuerzeugung von Patches","Validierung der Konstruktion und Tests"],"pt":["syncing-upstream","Node.js","segurança de socket","patches de segurança","submodule","build e testes","desenvolvimento de software","segurança de aplicativos"],"ru":["syncing-upstream","Node.js","патчи безопасности socket","ИИ Агенты","submodule","сборка и тесты","разработка программного обеспечения","безопасность приложений"],"ar":["syncing-upstream","Node.js","باتشات أمان сокيت","أجهزة الإيضاح الذكية","submodule","بناء وتجارب","تطوير البرمجيات","أمان التطبيقات"]}},"owner":"SocketDev","repo":"socket-btm","repoPath":"SocketDev/socket-btm","stars":0,"forks":0,"updatedAt":"2026-03-06T23:26:09Z","topics":[],"category":"community","skillMd":{"name":"syncing-upstream","description":"Synchronizes socket-btm with upstream Node.js by updating the submodule to latest tag, updating `.node-version`, regenerating patches, validating build and tests. Use when updating to new Node.js releases, applying security patches, or maintaining upstream synchronization.","bodyPreview":"# syncing-upstream\n\n<task>\nYour task is to spawn an autonomous agent that synchronizes socket-btm with upstream Node.js by updating the submodule to the latest stable tag, updating `.node-version`, regenerating patches, validating build and tests pass, and committing changes with detailed metrics.\n</task>\n\n<context>\n**What is Node.js Synchronization?**\nsocket-btm builds custom Node.js binaries with Socket Security patches. This skill keeps the baseline Node.js version up-to-date by:\n- Updating u","body":"# syncing-upstream\n\n<task>\nYour task is to spawn an autonomous agent that synchronizes socket-btm with upstream Node.js by updating the submodule to the latest stable tag, updating `.node-version`, regenerating patches, validating build and tests pass, and committing changes with detailed metrics.\n</task>\n\n<context>\n**What is Node.js Synchronization?**\nsocket-btm builds custom Node.js binaries with Socket Security patches. This skill keeps the baseline Node.js version up-to-date by:\n- Updating upstream Node.js submodule to latest stable tag\n- Synchronizing `.node-version` to match submodule\n- Regenerating Socket Security patches for new Node.js version\n- Validating patches apply cleanly to new version\n- Ensuring build and tests pass with updated Node.js\n\n**socket-btm Architecture:**\nThis is Socket Security''s binary tooling manager (BTM) that:\n- Builds custom Node.js binaries with Socket Security patches\n- Tracks upstream Node.js via submodule: `packages/node-smol-builder/upstream/node`\n- Maintains `.node-version` for tooling and CI consistency\n- Applies 15 patches to Node.js source during build\n- Produces production-ready patched Node.js binaries\n\n**When to Sync:**\n- New Node.js stable release (security patches, features)\n- Security advisories requiring Node.js upgrade\n- Feature development requiring newer Node.js APIs\n- Regular maintenance (monthly or quarterly cadence)\n\n**Critical Files:**\n- `.node-version` - Node.js version for tooling (nvm, volta, etc.)\n- `packages/node-smol-builder/upstream/node` - Git submodule tracking nodejs/node\n- `packages/node-smol-builder/patches/source-patched/*.patch` - Socket Security patches\n\n**Success Metrics:**\n- Build: Must complete without errors\n- Tests: 100% pass rate\n- Patches: All 15 must apply cleanly\n- Version consistency: `.node-version` matches submodule tag\n</context>\n\n<constraints>\n**CRITICAL Requirements:**\n- Working directory MUST be clean before starting (no uncommitted changes)\n- Submodule MUST update to stable tag only (no release candidates)\n- All patches MUST apply cleanly to new Node.js version\n- Build MUST succeed without errors\n- Tests MUST pass (100% success rate)\n- Two commits MUST be created (version update + patch regeneration)\n\n**Do NOT:**\n- Update to release candidate or nightly tags (unstable)\n- Skip patch regeneration after Node.js update (will break build)\n- Skip build validation (untested changes risky for production)\n- Skip test validation (functional regressions undetected)\n- Commit without validating patches apply cleanly\n\n**Do ONLY:**\n- Update to latest stable tag (format: v*.*.*, no -rc suffix)\n- Regenerate patches after submodule update\n- Validate build and tests before final commit\n- Create two atomic commits (version + patches)\n- Use conventional commit format with detailed changelog\n- Report version change and commit metrics\n</constraints>\n\n<instructions>\n\n## Process\n\nThis skill spawns an autonomous agent to handle the complete Node.js synchronization workflow, including version update, patch regeneration, validation, and commits.\n\n### Phase 1: Validate Environment\n\n<prerequisites>\nBefore spawning the agent, verify the environment is ready:\n</prerequisites>\n\n<action>\nCheck working directory and submodule state:\n</action>\n\n```bash\n# Check working directory is clean\ngit status\n\n# Verify upstream submodule exists\nls -la packages/node-smol-builder/upstream/node\n\n# Check current Node.js version\ncat .node-version\n```\n\n<validation>\n**Expected State:**\n- ✓ Working directory clean (no uncommitted changes)\n- ✓ Submodule directory exists: `packages/node-smol-builder/upstream/node/`\n- ✓ `.node-version` file exists with valid version\n\n**If working directory NOT clean:**\n- Commit or stash changes before proceeding\n- Node.js sync should start from clean state\n\n**If submodule missing:**\n- Initialize: `git submodule update --init --recursive`\n- Report error and ask user to fix\n\nDo NOT proceed if environment checks fail.\n</validation>\n\n---\n\n### Phase 2: Spawn Autonomous Agent\n\n<action>\nLoad the agent prompt template from reference.md and spawn the autonomous agent:\n</action>\n\n**Agent Prompt Source:** The complete agent prompt template is documented in `reference.md` under the \"Agent Prompt Template\" section. This prompt contains detailed instructions for the 8-step Node.js synchronization workflow.\n\n**Spawn Agent:**\n\n```javascript\nTask({\n  subagent_type: \"general-purpose\",\n  description: \"Sync Node.js to latest version\",\n  prompt: `${NODE_SYNC_AGENT_PROMPT_FROM_REFERENCE_MD}`\n})\n```\n\n**Instructions for Skill Executor:**\n\n1. **Read the agent prompt template** from `reference.md` starting at the \"Agent Prompt Template\" heading\n2. **Extract the full prompt** (from \"Synchronize socket-btm...\" through the final rollback bash block)\n3. **Pass the prompt to Task tool** using the code block above (replace placeholder with actual prompt content)\n4. **Monitor agent execution** and capture the output\n5. **Verify completion signal**: Agent must output `<promise>NODE_SYNC_COMPLETE</promise>`\n\n**Why Extracted to reference.md:**\n- Keeps SKILL.md concise and focused on skill logic\n- Agent prompt template is 484 lines - too large to embed inline\n- reference.md provides single source of truth for the prompt\n- Easier to maintain, update, and review prompt independently\n- Follows same pattern as quality-scan skill\n\n<validation>\n**Structured Output Validation:**\n\nAfter agent returns, validate output structure before parsing:\n\n```bash\n# 1. Verify completion signal\nif ! echo \"$AGENT_OUTPUT\" | grep -q ''<promise>NODE_SYNC_COMPLETE</promise>''; then\n  echo \"ERROR: Agent did not complete successfully\"\n  echo \"Agent may have failed or encountered an error\"\n  echo \"Review agent output for error messages\"\n  exit 1\nfi\n\n# 2. Verify expected content sections exist\nVALIDATION_FAILED=0\n\nif ! echo \"$AGENT_OUTPUT\" | grep -q ''Node.js Synchronization Complete''; then\n  echo \"WARNING: Missing summary report section\"\n  VALIDATION_FAILED=1\nfi\n\nif ! echo \"$AGENT_OUTPUT\" | grep -q ''Updated from:.*→''; then\n  echo \"WARNING: Missing version change information\"\n  VALIDATION_FAILED=1\nfi\n\nif ! echo \"$AGENT_OUTPUT\" | grep -q ''Commits Created:''; then\n  echo \"WARNING: Missing commit information\"\n  VALIDATION_FAILED=1\nfi\n\nif [ $VALIDATION_FAILED -eq 1 ]; then\n  echo \"WARNING: Agent output structure incomplete\"\n  echo \"Proceeding with manual verification...\"\nfi\n```\n\n**Manual Verification Checklist:**\n- [ ] Agent output shows `<promise>NODE_SYNC_COMPLETE</promise>`\n- [ ] Two commits created (check: `git log -2 --oneline`)\n- [ ] .node-version matches submodule tag\n- [ ] Build and tests passed (check agent output for \"✓ Build and tests passed\")\n- [ ] No error messages in agent output\n\n**If validation fails:**\n- Review full agent output for specific errors\n- Check git status and commits created\n- Rollback if needed: `git reset --hard HEAD~2`\n\n**Report to user:**\n- Node.js updated: vOLD → vNEW\n- Commits: 2\n- Build: SUCCESS\n- Tests: PASS\n- Ready for push\n</validation>\n\n---\n\n### Phase 3: Complete\n\n<completion_signal>\n```xml\n<promise>SKILL_COMPLETE</promise>\n```\n</completion_signal>\n\n<summary>\nReport final results to the user:\n\n**Node.js Synchronization Skill Complete**\n=========================================\n✓ Autonomous agent spawned\n✓ Agent completed Node.js synchronization workflow\n✓ Node.js updated to latest stable version\n✓ .node-version synchronized with submodule\n✓ All patches regenerated and validated\n✓ Build and tests passed\n✓ Two commits created\n\n**Version Change:**\nOLD_VERSION → NEW_VERSION\n\n**Commits:**\n1. chore(node): update Node.js version\n2. chore(node-smol-builder): rebuild with patches\n\n**Next Steps:**\n1. Review changes: \\`git log -2 --stat\\`\n2. Test manually if desired\n3. Push to remote: \\`git push origin main\\`\n4. Monitor CI/CD for integration tests\n\nNode.js is now synchronized to the latest stable release.\n</summary>\n\n</instructions>\n\n## Success Criteria\n\n- ✅ \\`<promise>SKILL_COMPLETE</promise>\\` output\n- ✅ Autonomous agent spawned with detailed instructions\n- ✅ Agent completed Node.js synchronization workflow\n- ✅ .node-version updated to latest stable\n- ✅ Submodule updated to latest stable tag\n- ✅ All patches regenerated and applied cleanly\n- ✅ Build and tests passed (100%)\n- ✅ Two commits created with detailed messages\n- ✅ Ready for push to remote\n\n## Commands\n\nThis skill spawns an autonomous agent. No direct commands needed.\n\n## Context\n\nThis skill is useful for:\n- Updating to new Node.js stable releases\n- Applying security patches from upstream\n- Accessing new Node.js APIs and features\n- Maintaining compatibility with ecosystem tools\n- Regular maintenance (monthly or quarterly)\n\n**Safety:** Working directory must be clean. Validation ensures patches apply and tests pass before committing. Rollback available with \\`git reset --hard HEAD~2\\`.\n\n**Trade-offs:**\n- ✓ Automated workflow (minimal manual steps)\n- ✓ Validation ensures patches work with new version\n- ✓ Atomic commits (version + patches separate)\n- ✓ Retry logic for flaky operations\n- ✗ Requires clean working directory\n- ✗ May fail if patches incompatible with new Node.js\n- ✗ Manual intervention needed if validation fails\n"},"lastSynced":"2026-03-07T03:52:41.953Z","agentAnalysis":{"suitability":{"en":"Ideal for Autonomous Agents requiring seamless Node.js synchronization and Socket Security patch management.","zh":"适合需要无缝 Node.js 同步和 Socket Security 补丁管理的自主代理。","ja":"Node.js のシームレスな同期と Socket Security パッチの管理が必要な自律エージェントに適しています。","ko":"무결점 Node.js 동기화 및 Socket Security 패치 관리가 필요한 자율 에이전트에 적합합니다.","es":"Ideal para Agentes Autónomos que requieren una sincronización sin problemas de Node.js y una gestión de parches de seguridad de Socket.","fr":"Idéal pour les Agents Autonomes nécessitant une synchronisation transparente de Node.js et une gestion de correctifs de sécurité de Socket.","de":"Ideal für autonome Agenten, die eine reibungslose Node.js-Synchronisierung und eine Verwaltung von Socket-Sicherheitspatches erfordern.","pt":"Ideal para Agentes Autônomos que requerem sincronização sem problemas do Node.js e gestão de patches de segurança de Socket.","ru":"Идеально для автономных агентов, требующих бесшовной синхронизации Node.js и управления патчами безопасности Socket.","ar":"مثالي للوكلاء المستقلين الذين يتطلبون تنسيق Node.js بدون مشاكل وإدارة تصحيحات أمان Socket."},"recommendation":{"en":"Empowers agents to update submodules to the latest stable Node.js tags, regenerate patches, and validate builds, ensuring custom Node.js binaries stay up-to-date with the latest security patches and features, leveraging submodule updates and .node-version synchronization.","zh":"赋予代理更新到最新稳定 Node.js 标签的子模块、重新生成补丁和验证构建的能力，确保自定义 Node.js 二进制文件在最新的安全补丁和功能方面保持最新状态，利用子模块更新和 .node-version 同步。","ja":"エージェントが最新の安定した Node.js タグを使用してサブモジュールを更新し、パッチを再生成し、ビルドを検証する能力を付与し、カスタム Node.js バイナリが最新のセキュリティ パッチと機能を使用して最新の状態に保たれることを保証し、サブモジュールの更新と .node-version の同期を利用します。","ko":"에이전트가 최신 안정적인 Node.js 태그를 사용하여 서브모듈을 업데이트하고 패치를 재생성하며 빌드를 검증할 수 있는 기능을 부여하여 사용자 지정 Node.js 바이너리가 최신 보안 패치 및 기능과 함께 최신 상태를 유지하도록 보장하며 서브모듈 업데이트와 .node-version 동기화를 활용합니다.","es":"Habilita a los agentes a actualizar submódulos a las etiquetas estables más recientes de Node.js, regenerar parches y validar compilaciones, garantizando que los binarios personalizados de Node.js permanezcan actualizados con los últimos parches de seguridad y características, aprovechando las actualizaciones de submódulos y la sincronización de .node-version.","fr":"Permet aux agents de mettre à jour les sous-modules vers les balises stables les plus récentes de Node.js, de régénérer les correctifs et de valider les builds, en garantissant que les binaires Node.js personnalisés restent à jour avec les derniers correctifs de sécurité et fonctionnalités, en exploitant les mises à jour de sous-modules et la synchronisation de .node-version.","de":"Ermächtigt die Agenten, Untermodules auf die neuesten stabilen Node.js-Tags zu aktualisieren, Patches neu zu generieren und Builds zu validieren, um sicherzustellen, dass benutzerdefinierte Node.js-Binaries mit den neuesten Sicherheitspatches und Funktionen aktualisiert bleiben, indem die Aktualisierung von Untermodulen und die Synchronisierung von .node-version genutzt werden.","pt":"Habilita os agentes a atualizar submódulos para as tags estáveis mais recentes do Node.js, regenerar patches e validar compilações, garantindo que os binários personalizados do Node.js fiquem atualizados com os patches de segurança e recursos mais recentes, aproveitando as atualizações de submódulos e a sincronização da versão do node.","ru":"Наделяет агентов возможностью обновлять подмодули до последних стабильных тегов Node.js, регенерировать патчи и проверять сборки, обеспечивая актуальность собственных бинарных файлов Node.js с последними патчами безопасности и функциями, используя обновления подмодулей и синхронизацию версии node.","ar":"يتمكن الوكلاء من تحديث الوحدات الفرعية إلى آخر العلامات المستقرة من Node.js، وإعادة توليد التصحيحات، والتحقق من المجمعات، مما يضمن أن تبقى الثنائيات المخصصة ل Node.js محدثة مع أحدث تصحيحات الأمان والميزات، مستفيدة من تحديثات الوحدات الفرعية وتنسيق إصدار Node."},"useCases":{"en":["Updating custom Node.js binaries with Socket Security patches","Regenerating patches for enhanced security","Validating builds and tests for custom Node.js environments"],"zh":["使用 Socket Security 补丁更新自定义 Node.js 二进制文件","重新生成补丁以增强安全性","验证自定义 Node.js 环境的构建和测试"],"ja":["Socket Security パッチを使用してカスタム Node.js バイナリを更新する","セキュリティを強化するためにパッチを再生成する","カスタム Node.js 環境のビルドとテストを検証する"],"ko":["Socket Security 패치를 사용하여 사용자 지정 Node.js 바이너리를 업데이트하는 것","보안을 강화하기 위해 패치를 재생성하는 것","사용자 지정 Node.js 환경의 빌드 및 테스트를 검증하는 것"],"es":["Actualización de binarios personalizados de Node.js con parches de seguridad de Socket","Regeneración de parches para una mayor seguridad","Validación de compilaciones y pruebas para entornos personalizados de Node.js"],"fr":["Mise à jour des binaires Node.js personnalisés avec des correctifs de sécurité de Socket","Régénération de correctifs pour une sécurité améliorée","Validation des builds et des tests pour les environnements Node.js personnalisés"],"de":["Aktualisierung von benutzerdefinierten Node.js-Binaries mit Socket-Sicherheitspatches","Neugenerierung von Patches für eine verbesserte Sicherheit","Validierung von Builds und Tests für benutzerdefinierte Node.js-Umgebungen"],"pt":["Atualizar binários personalizados do Node.js com patches de segurança de Socket","Regenerar patches para segurança aprimorada","Validar compilações e testes para ambientes personalizados do Node.js"],"ru":["Обновление собственных бинарных файлов Node.js патчами безопасности Socket","Регенерация патчей для повышения безопасности","Проверка сборок и тестов для собственных сред Node.js"],"ar":["تحديث الثنائيات المخصصة ل Node.js بالتصحيحات الأمنية ل Socket","إعادة توليد التصحيحات لتحسين الأمان","التحقق من المجمعات والاختبارات للبيئات المخصصة ل Node.js"]},"limitations":{"en":["Requires Node.js environment","Needs submodule update access","Dependent on stable Node.js tags"],"zh":["需要 Node.js 环境","需要子模块更新访问权限","依赖于稳定 Node.js 标签"],"ja":["Node.js 環境が必要","サブモジュールの更新アクセスが必要","安定した Node.js タグに依存している"],"ko":["Node.js 환경이 필요함","서브모듈 업데이트 액세스가 필요함","안정적인 Node.js 태그에 의존함"],"es":["Requiere un entorno de Node.js","Necesita acceso a la actualización de submódulos","Dependiente de las etiquetas estables de Node.js"],"fr":["Nécessite un environnement Node.js","A besoin d''un accès à la mise à jour des sous-modules","Dépend des balises stables de Node.js"],"de":["Benötigt eine Node.js-Umgebung","Benötigt Zugriff auf die Untermodul-Aktualisierung","Abhängig von den stabilen Node.js-Tags"],"pt":["Requer ambiente do Node.js","Necessita acesso a atualização de submódulos","Dependente de tags estáveis do Node.js"],"ru":["Требуется среда Node.js","Необходим доступ к обновлению подмодулей","Зависит от стабильных тегов Node.js"],"ar":["يتطلب بيئة Node.js","يحتاج إلى وصول لتحديث الوحدات الفرعية","يعتمد على علامات مستقر ل Node.js"]},"version":4},"contentHash":"30b53ed8b455763fcdc3470b8d7930e876e5d5b80ce119bba14ab25f467816f3","qualityScore":45}');
