INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('SocketDev/socket-btm/syncing-upstream', 'syncing-upstream', 'SocketDev', 'socket-btm', 'community', 'syncing-upstream SocketDev socket-btm community The syncing-upstream skill synchronizes socket-btm with upstream Node.js by updating the submodule and regenerating patches. This benefits developers working with custom Node.js binaries and Socket Security patches. Syncing-Upstream 是一种用于同步 Node.js 版本的技术，通过更新子模块和重新生成补丁来实现 Syncing-Upstream は Node.js バージョンを同期する技術で、サブモジュールの更新とパッチの再生成を実行する Syncing-Upstream은 Node.js 버전을 동기화하는 기술로, 하위 모듈을 업데이트하고 패치를 재생성하는 기능을 제공 Syncing-upstream es una habilidad que actualiza la versión de Node.js con patches de seguridad de Socket y mantiene el submodule actualizado Syncing-upstream est une compétence qui met à jour la version de Node.js avec des patchs de sécurité de Socket et maintient le submodule à jour Syncing-upstream ist eine Fähigkeit, die die Node.js-Version mit Socket-Sicherheitspatches aktualisiert und das Submodule auf dem neuesten Stand hält O syncing-upstream é uma habilidade que sincroniza o socket-btm com o Node.js upstream, atualizando o submodule e gerando patches de segurança Syncing-upstream - это навык, который синхронизирует socket-btm с Node.js upstream, обновляя submodule и генерируя патчи безопасности syncing-upstream هو مهارة تزامن socket-btm مع Node.js upstream، وتحديث submodule و توليد باتشات أمان how to use syncing-upstream what is syncing-upstream syncing-upstream alternative syncing-upstream vs socket-btm syncing-upstream install syncing-upstream setup guide Node.js synchronization socket-btm updates upstream Node.js integration Syncing-Upstream Node.js 同步 socket-btm 自动化工具 子模块更新 补丁重新生成 AIエージェント Updates submodule to the latest stable tag Regenerates patches for custom Node.js binaries Validates build and tests pass with detailed metrics Commits changes with updated .node-version Ensures socket-btm is synchronized with upstream Node.js syncing-upstream is a skill that updates the baseline Node.js version by synchronizing socket-btm with upstream Node.js, ensuring the latest stable tag and patches are applied.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('wiggitywhitney/telemetry-agent-research/prd-phase', 'community', 'wiggitywhitney', 'telemetry-agent-research', 'wiggitywhitney/telemetry-agent-research', 'prd-phase', 0, 0, 45, '2026-03-03T01:53:42Z', '2026-03-07T03:54:02.960Z', '032f497723ef40b1792a383ea4790772cb6235922c83ac60ce9685b9f6ce816e', '{"id":"wiggitywhitney/telemetry-agent-research/prd-phase","name":"prd-phase","description":{"en":"The prd-phase skill creates implementation phase PRDs for telemetry agents by assembling content from existing research documents, benefiting AI agent developers.","zh":"prd-phase是一种研究和评估框架，用于AI驱动的遥测仪表代理的实现阶段PRD文档创建","ja":"prd-phaseは、AI駆動のテレメトリーエージェントの実装段階のPRD文書を作成するための研究および評価フレームワークです","ko":"prd-phase는 AI 구동 텔레메트리 에이전트의 구현 단계 PRD 문서 생성을 위한 연구 및 평가 프레임워크입니다","es":"prd-phase es un marco de evaluación de investigación para agentes de telemetría AI. Crea PRDs de implementación de fase reutilizando contenido de documentos de investigación existentes.","fr":"prd-phase est un cadre d''évaluation de la recherche pour les agents de télémétrie AI. Créez des PRDs de phase d''implémentation en réutilisant du contenu de documents de recherche existants.","de":"prd-phase ist ein Forschungs- und Bewertungsrahmen für AI-Telemetrie-Agenten. Erstellen Sie Implementierungsphasen-PRDs durch Wiederverwendung von Inhalten aus bestehenden Forschungsdokumenten.","pt":"O prd-phase é um framework de pesquisa e avaliação para agentes de instrumentação de telemetria com tecnologias de inteligência artificial. Ele ajuda a criar implementações de fase PRD","ru":"prd-phase - это исследовательский и оценочный фреймворк для агентов телелеметрии с технологиями ИИ. Он помогает создавать реализации фазы PRD","ar":"prd-phase هو إطار بحث وتقييم لأدوات एजنتات التелеметري بأدوات الذكاء الاصطناعي. يساعد على إنشاء مراحل تنفيذ موثقة"},"seo":{"title":{"en":"prd-phase: Implementation Phase PRD Creation for AI Agent...","zh":"AI工具prd-phase设置指南","ja":"AIエージェントprd-phaseのベストプラクティス","ko":"AI 에이전트 prd-phase 구축 가이드","es":"Guía de Configuración de prd-phase para Agentes de Teleme...","fr":"Guide de Mise en Place de prd-phase pour les Agents de Té...","de":"Einrichtungsleitfaden für prd-phase bei AI-Telemetrie-Age...","pt":"Guia de Configuração do prd-phase para Ferramentas de Int...","ru":"Настройка ИИ Агентов с помощью prd-phase: Лучшие Практики","ar":"إعداد أداة إدارة المراحل prd-phase لأدوات الذكاء الاصطناعي"},"description":{"en":"Discover how prd-phase streamlines AI-powered telemetry instrumentation agent development. Learn to create focused PRDs by extracting key details from resear...","zh":"了解prd-phase的技术细节，创建实现阶段的PRD文档，实现AI工具的智能化","ja":"prd-phaseの仕組みを理解し、実装段階のPRD文書を作成してAIエージェントの機能を高める","ko":"prd-phase의 기술 세부 정보를 파악하고 구현 단계의 PRD 문서를 생성하여 AI 에이전트의 기능을 향상시키는 방법","es":"Aprende a crear PRDs de implementación de fase para agentes de telemetría AI con prd-phase. Extrae detalles de documentos de investigación existentes.","fr":"Découvrez comment créer des PRDs de phase d''implémentation pour les agents de télémétrie AI avec prd-phase. Extraiez des détails de documents de recherche ex...","de":"Erfahren Sie, wie Sie Implementierungsphasen-PRDs für AI-Telemetrie-Agenten mit prd-phase erstellen. Extrahieren Sie Details aus bestehenden Forschungsdokume...","pt":"Aprenda a configurar o prd-phase para criar implementações de fase PRD para agentes de instrumentação de telemetria com tecnologias de inteligência artificial","ru":"Узнайте, как настроить prd-phase для создания реализаций фазы PRD для агентов телелеметрии с технологиями ИИ","ar":"تعرف على كيفية إعداد أداة إدارة المراحل prd-phase لإنشاء مراحل تنفيذ موثقة لعميل एजنتات التелеметري بأدوات الذكاء الاصطناعي"},"definition":{"en":"prd-phase is a research and evaluation framework for creating implementation phase PRDs for AI-powered telemetry instrumentation agents.","zh":"prd-phase是指创建实现阶段PRD文档的研究和评估框架，用于AI工具的遥测仪表代理","ja":"prd-phaseとは、AIエージェントのテレメトリーエージェントの実装段階のPRD文書を作成するための研究および評価フレームワークです","ko":"prd-phase는 AI 에이전트의 텔레메트리 에이전트의 구현 단계 PRD 문서 생성을 위한 연구 및 평가 프레임워크를 말합니다","es":"prd-phase es un marco de evaluación de investigación para agentes de telemetría AI que crea PRDs de implementación de fase","fr":"prd-phase est un cadre d''évaluation de la recherche pour les agents de télémétrie AI qui crée des PRDs de phase d''implémentation","de":"prd-phase ist ein Forschungs- und Bewertungsrahmen für AI-Telemetrie-Agenten, der Implementierungsphasen-PRDs erstellt","pt":"O prd-phase é um framework de pesquisa que ajuda a criar implementações de fase PRD para agentes de instrumentação de telemetria","ru":"prd-phase - это исследовательский фреймворк, помогающий создавать реализации фазы PRD для агентов телелеметрии","ar":"prd-phase هو إطار بحث يساعد على إنشاء مراحل تنفيذ موثقة لأدوات एजنتات التелемتري"},"features":{"en":["Assembles content from existing research documents to create focused PRDs","Extracts specific details from routing tables to ensure bounded context","Prevents detail loss by adhering to critical principles","Utilizes versioning to maintain accuracy","Creates implementation phase PRDs for telemetry agents"],"zh":["创建实现阶段PRD文档","遥测仪表代理的研究和评估","bounded context的应用","无细节丢失的文档生成","特定技术栈文档的引用"],"ja":["実装段階のPRD文書の作成","テレメトリーエージェントの研究と評価","bounded contextの適用","詳細の欠落がない文書の生成","特定のテクノロジースタック文書の参照"],"ko":["구현 단계 PRD 문서 생성","텔레메트리 에이전트의 연구 및 평가","bounded context의 적용","세부 정보의 손실이 없는 문서 생성","특정 기술 스택 문서의 참조"],"es":["Asamblea de contenido de documentos de investigación existentes","Creación de PRDs de implementación de fase para agentes de telemetría AI","Enfoque en contexto limitado para evitar pérdida de detalles","Extracción de detalles específicos de documentos de investigación","Uso de tablas de enrutamiento para guiar el proceso"],"fr":["Assemblage de contenu de documents de recherche existants","Création de PRDs de phase d''implémentation pour les agents de télémétrie AI","Focus sur le contexte limité pour éviter la perte de détails","Extraction de détails spécifiques de documents de recherche","Utilisation de tableaux de routage pour guider le processus"],"de":["Zusammenstellung von Inhalten aus bestehenden Forschungsdokumenten","Erstellung von Implementierungsphasen-PRDs für AI-Telemetrie-Agenten","Fokus auf begrenzten Kontext, um Detailverlust zu vermeiden","Extraktion spezifischer Details aus Forschungsdokumenten","Verwendung von Routierungstabellen, um den Prozess zu leiten"],"pt":["Criação de implementações de fase PRD para agentes de instrumentação de telemetria","Utilização de tecnologias de inteligência artificial para melhorar a eficiência","Análise de documentos de pesquisa existentes para extrair detalhes relevantes","Utilização de tabelas de roteamento para direcionar para os documentos certos","Manutenção de contexto limitado para evitar perda de detalhes"],"ru":["Создание реализаций фазы PRD для агентов телелеметрии","Использование технологий ИИ для повышения эффективности","Анализ существующих исследовательских документов для извлечения релевантных деталей","Использование таблиц маршрутизации для направления к правильным документам","Сохранение ограниченного контекста для предотвращения потери деталей"],"ar":["إنشاء مراحل تنفيذ موثقة لأدوات एजنتات التелемتري","استخدام أدوات الذكاء الاصطناعي لتحسين الكفاءة","تحليل الوثائق البحثية الحالية لاستخراج التفاصيل ذات الصلة","استخدام جداول التوجيه لنقل إلى الوثائق الصحيحة","الحفاظ على السياق المحدود لتجنب فقدان التفاصيل"]},"keywords":{"en":["how to use prd-phase","prd-phase alternative","prd-phase setup guide","what is prd-phase","prd-phase vs telemetry instrumentation agents","implementing prd-phase for AI agents"],"zh":["AI工具","prd-phase","遥测仪表代理","实现阶段PRD文档","bounded context","无细节丢失","AI驱动","研究和评估"],"ja":["AIエージェント","prd-phase","テレメトリーエージェント","実装段階のPRD文書","bounded context","詳細の欠落がない","AI駆動","研究と評価"],"ko":["AI 에이전트","prd-phase","텔레메트리 에이전트","구현 단계 PRD 문서","bounded context","세부 정보의 손실이 없는","AI 구동","연구 및 평가"],"es":["agentes de telemetría AI","prd-phase","creación de PRDs","evaluación de investigación","contexto limitado","extracción de detalles","tablas de enrutamiento","implementación de fase"],"fr":["agents de télémétrie AI","prd-phase","création de PRDs","évaluation de la recherche","contexte limité","extraction de détails","tableaux de routage","implémentation de phase"],"de":["AI-Telemetrie-Agenten","prd-phase","Erstellung von PRDs","Forschungsbewertung","begrenzter Kontext","Extraktion von Details","Routierungstabellen","Implementierungsphase"],"pt":["prd-phase","ferramentas de inteligência artificial","agentes de instrumentação de telemetria","criação de implementações de fase PRD","análise de documentos de pesquisa","tabelas de roteamento"],"ru":["prd-phase","ИИ агенты","агенты телелеметрии","создание реализаций фазы PRD","анализ исследовательских документов","таблицы маршрутизации"],"ar":["prd-phase","أدوات الذكاء الاصطناعي","أدوات एजنتات التелемتري","إنشاء مراحل تنفيذ موثقة","تحليل الوثائق البحثية","جداول التوجيه"]}},"owner":"wiggitywhitney","repo":"telemetry-agent-research","repoPath":"wiggitywhitney/telemetry-agent-research","stars":0,"forks":0,"updatedAt":"2026-03-03T01:53:42Z","topics":[],"category":"community","skillMd":{"name":"prd-phase","description":"Create implementation phase PRDs from pre-existing research for the telemetry agent. Translates already-complete research into focused, bounded PRDs. Use when the user says prd-phase N or wants to create a PRD for a specific build phase (1-7). Do NOT use for new feature discovery — use prd-create for that.","bodyPreview":"# Phase PRD Creation\n\n## Purpose\n\nCreate implementation phase PRDs for the telemetry agent by assembling content from existing research documents. All research is complete. The job is to route to the right documents, extract the right details, and produce a focused PRD.\n\n## Critical Principles\n\n1. **Bounded context**: Read ONLY what this phase needs. Do not read the full spec or full tech stack document. Read the specific sections listed in the routing tables below.\n2. **No detail loss**: Versio","body":"# Phase PRD Creation\n\n## Purpose\n\nCreate implementation phase PRDs for the telemetry agent by assembling content from existing research documents. All research is complete. The job is to route to the right documents, extract the right details, and produce a focused PRD.\n\n## Critical Principles\n\n1. **Bounded context**: Read ONLY what this phase needs. Do not read the full spec or full tech stack document. Read the specific sections listed in the routing tables below.\n2. **No detail loss**: Version numbers, API patterns, config field names, and code snippets must be copied verbatim from source documents into the PRD. Do not summarize technical details.\n3. **Excerpt, don''t just reference**: Critical details (acceptance gates, API patterns, rubric rules) must be IN the PRD, not just referenced by section name.\n4. **One phase at a time**: Never create multiple phase PRDs in one session. Each phase gets a fresh context.\n5. **TypeScript and ESM**: The agent is TypeScript (`\"type\": \"module\"` in package.json, native Node.js type stripping via `erasableSyntaxOnly`). All code samples use ESM `import` syntax and TypeScript interface notation. ts-morph is used for AST analysis (it handles JavaScript target files via `allowJs: true`).\n\n## Process\n\n### Step 1: Identify the Phase\n\nParse the phase number (1-7) from the user''s command.\n\n### Step 2: Read the Phase Definition\n\nRead the specific phase section from `docs/specs/research/implementation-phasing.md`. Each phase contains:\n- What Gets Built\n- Acceptance Gate\n- Rubric Rules That Apply\n- Why This Boundary\n- Spec Sections (table mapping to spec sections and subsections)\n\n**Also read these cross-cutting sections** (they apply to every phase):\n- \"Two-Tier Validation Architecture\" section\n- \"Cross-Cutting: The DX Principle\" section\n\n### Step 2b: Read Previous Phase PRD (Phase 2+ only)\n\n**Skip this step for Phase 1** — it has no predecessor.\n\nFor Phase 2+, read the previous phase''s PRD file (`prds/[id]-phase-[N-1]-*.md`). Focus on:\n\n1. **Decision Log**: Extract any decisions that changed interfaces, types, or contracts from what the design document planned\n2. **Interface changes**: Compare the previous phase''s delivered interface with what `docs/architecture/design-document.md` defines for the Phase N-1 → Phase N boundary\n\nInclude deviations in the new PRD''s Dependencies section as:\n> Phase N-1 delivered [interface/type] (with these modifications from plan: [list changes]).\n\nIf the previous phase''s decision log and design document agree (no deviations), note: \"Phase N-1 delivered interfaces as planned in the design document.\"\n\n### Step 3: Read Source Documents (Routing)\n\nRead ONLY the sections relevant to this phase.\n\n#### 3a. Spec Sections\n\nThe phase definition contains a \"Spec Sections\" table. For each row:\n- **Full** -> read the entire section from `docs/specs/telemetry-agent-spec-v3.9.md`\n- **Subsection only** -> read only the named subsection\n- **Fields only** -> extract just the named configuration fields\n- **Row only** -> extract just the named row from the Technology Stack table\n\n**Note**: The spec was renamed from v3.5.md → v3.6.md → v3.7.md → v3.8.md → v3.9.md as content versions evolved.\n\n**Spec section landmarks** (line numbers for the 1,791-line spec):\n\n| Section | Line | Key Subsections |\n|---------|------|-----------------|\n| Architecture | 55 | Coordinator+Agents 57, Coordinator API 130, Error Handling 160, Interfaces 193, Tech Stack 220, Weaver Integration 253 |\n| Init Phase (Required) | 290 | What Init Does 294, Prerequisites 324 |\n| Complete Workflow | 334 | (diagram through ~397) |\n| How It Works | 397 | Input 399, Processing (per file) 404, Output 420, Agent Output Format 424, System Prompt Structure 438, Known Failure Modes 468, Elision Detection 484 |\n| File/Directory Processing | 494 | File Revert Protocol 506, Periodic Schema Checkpoints 512 |\n| What Gets Instrumented | 528 | Priority Hierarchy 530, Review Sensitivity 543, Patterns Not Covered 560 |\n| What the Agent Actually Does to Code | 573 | Path 1: Auto-Instrumentation 577, Path 2: Manual Span 647, Decision: Which Path? 711 |\n| Attribute Priority Chain | 721 | Schema Extension Guardrails 731 |\n| Auto-Instrumentation Libraries | 745 | Why Libraries First 749, Detection Flow 755, Library Discovery 774 |\n| Validation Chain | 874 | Per-File Validation (with fix loop) 878, End-of-Run Validation 983 |\n| Agent Self-Instrumentation | 1020 | |\n| Handling Existing Instrumentation | 1079 | |\n| Schema as Source of Truth | 1097 | |\n| Result Data | 1106 | Result Structure 1116, Run-Level Result 1211, PR Summary 1241, Schema Hash Tracking 1255 |\n| Configuration | 1261 | What Goes Where 1312, Dependency Strategy 1352, Cost Visibility 1367 |\n| Minimum Viable Schema Example | 1381 | |\n| PoC Scope | 1577 | In Scope 1579, Out of Scope 1626 |\n| Evaluation & Acceptance Criteria | 1642 | Two-Tier Validation Architecture 1676, Required Verification Levels 1710 |\n\n#### 3b. Tech Stack Sections\n\nRead `references/tech-stack-by-phase.md` (bundled with this skill) to find which sections of `docs/architecture/tech-stack-evaluation.md` to read for this phase. Extract:\n- Version numbers (exact)\n- API patterns (code snippets, verbatim)\n- Caveats and limitations\n- Recommendation summaries\n\n#### 3c. Rubric Rules\n\nThe phase definition lists rubric rule IDs (e.g., NDS-001, CDQ-003). Look up each rule''s full definition in `research/evaluation-rubric.md`. The code-level rules are in **Part 2: Code-Level Evaluation** (line 136), organized as:\n\n| Dimension | Location | Rules |\n|-----------|----------|-------|\n| Gate Checks | ~line 140 | NDS-001, NDS-002, NDS-003, API-001 |\n| Non-Destructiveness | ~line 189 | NDS-004, NDS-005 |\n| Coverage | ~line 218 | COV-001 through COV-006 |\n| Restraint | ~line 282 | RST-001 through RST-005 |\n| API-Only Dependency | ~line 337 | API-002, API-003, API-004 |\n| Schema Fidelity | ~line 374 | SCH-001 through SCH-004 |\n| Code Quality | ~line 422 | CDQ-001 through CDQ-008 |\n\nFor each rule, extract: Rule ID, name, impact level, evaluation scope, full description including evaluation method, and automation classification (summary at ~line 514).\n\nFor Phase 2+, classify rules as Tier 1 (structural/blocking) vs Tier 2 (semantic/blocking or advisory) using the \"Two-Tier Validation Architecture\" section of implementation-phasing.md.\n\n#### 3d. Architectural Context (if needed)\n\nRead relevant sections of `docs/architecture/recommendations.md`:\n- Phases 1-3: \"Fix Loop Feedback Quality\" subsection\n- Phase 2: \"Two-Tier Validation (New Architecture)\" section\n- Phases 4-7: \"DX and Error Handling Architecture\" section\n- All phases: Summary table at end for quick reference\n\n#### 3e. Design Document\n\nRead relevant sections of `docs/architecture/design-document.md`. This document defines cross-phase interface contracts, module organization, and a consolidated decision register.\n\n**All phases — read these sections:**\n- Module Organization (line 312): Directory Structure (314), Module Dependency Rules (337)\n- Phase-to-Module Mapping (line 360): which modules get built in which phase\n- Consolidated Decision Register (line 376): design decisions that may affect implementation\n\n**Phase-specific interface contracts:**\n\n| Phase | Section | Line | Key Types/Contracts |\n|-------|---------|------|---------------------|\n| 1 | Phase 1 → Phase 2: Instrumentation Output | 29 | `instrumentFile` interface, `InstrumentationOutput` type |\n| 2 | Phase 2 → Phase 3: Validation Results | 84 | `validateFile` interface, `ValidationResult`/`CheckResult` types, `ValidateFileInput` |\n| 3 | Phase 3 → Phase 4: File-Level Result | 151 | `instrumentWithRetry` interface, `FileResult` evolution, schema re-resolution |\n| 4 | Phase 4 → Phase 5/6: Run-Level Result | 211 | `coordinate` interface, `RunResult` type, `CoordinatorCallbacks` |\n| 5 | Phase 5: Schema Integration Extensions | 254 | Schema integration extensions to `RunResult` |\n| 6 | Phase 6: Interface Layer | 262 | `CostCeiling`, `CoordinatorCallbacks` (wiring focus) |\n| 7 | Phase 7: Deliverables | 290 | `RunResult` consumption for git/PR, `advisoryAnnotations` flow |\n\nAlso read the Interface Contract Summary table (line 294) for a quick reference of all contracts.\n\nExtract from the design document into the PRD:\n- The interface contract relevant to this phase (input types, output types, function signature)\n- Any decision register entries that affect this phase''s implementation\n- The module directory paths this phase creates (from the Phase-to-Module Mapping)\n\n### Step 4: Assemble the PRD\n\nRead `references/phase-prd-template.md` (bundled with this skill) for the output template.\n\nFill in each section using content gathered in Steps 2-3. Key rules:\n\n**Tech Stack section:**\n- Copy version numbers exactly (e.g., \"Vitest 4.0.18\", not \"latest\")\n- Copy API code snippets verbatim — all TypeScript, ESM imports\n- Include caveats that affect THIS phase\n- Include only entries relevant to this phase\n\n**Rubric Rules section:**\n- Include the full rule definition, not just the ID\n- Group by Gate vs Dimension\n- Note which are Tier 1 vs Tier 2 (for Phase 2+)\n- Include impact level and automation classification\n\n**Acceptance Gate section:**\n- Copy the gate verbatim from the phasing document\n- Add specific, testable verification steps\n- Map each gate criterion to the rubric rules that verify it\n\n**Milestones:**\n- Define 5-8 milestones that build toward the acceptance gate incrementally\n- Each milestone should be independently testable\n- Final milestone: \"Acceptance gate passes end-to-end\"\n- Include a milestone for the DX cross-cutting requirement specific to this phase\n- Use the Phase-to-Module Mapping from the design document (Step 3e) to identify which module directories this phase creates — milestones should align with the module structure\n- Where a milestone directly satisfies a rubric rule, note the rule ID (e.g., \"Tier 1 syntax check works → NDS-001\"). Not every milestone maps to a rubric rule — Phase 1 milestones about prompt engineering and file I/O have no clean rubric connection, and stretching for one adds noise. Phase 2 (validation chain) maps naturally. Include the mapping where it''s real; omit it where it isn''t.\n\n**Spec Reference section:**\n- Reproduce the spec section map table from the phasing document\n- Add line number ranges from the landmarks table above\n\n### Step 5: Create GitHub Issue and PRD File\n\nFollow the same workflow as `/prd-create`:\n\n1. **Create GitHub Issue** with label \"PRD\":\n   ```markdown\n   ## PRD: Phase N — [Phase Name]\n\n   **Problem**: Implementation phase N of the telemetry agent — [what gets built]\n\n   **Solution**: [1-2 sentence summary from phasing document]\n\n   **Detailed PRD**: Will be added after PRD file creation\n\n   **Priority**: High\n   ```\n\n2. **Create PRD file** at `prds/[issue-id]-phase-N-[phase-name].md`\n\n3. **Update GitHub Issue** with PRD link\n\n4. **Commit** with `[skip ci]` flag:\n   ```text\n   docs(prd-[issue-id]): create Phase N PRD — [phase-name] [skip ci]\n   ```\n\n### Step 6: Post-Creation Verification\n\nBefore presenting the PRD to the user, verify:\n\n- [ ] Every rubric rule ID listed in the phasing document appears with its full definition\n- [ ] Every spec section from the phase''s spec section map is referenced with line numbers\n- [ ] Tech stack version numbers are exact (not \"latest\" or \"current\")\n- [ ] API code snippets are present and use TypeScript ESM syntax\n- [ ] The acceptance gate is copied verbatim from the phasing document\n- [ ] The DX cross-cutting requirement for this phase is included\n- [ ] No content from other phases leaked in\n- [ ] Milestones build incrementally toward the acceptance gate\n- [ ] All agent code samples are TypeScript; target file examples remain JavaScript\n\n## Source Documents\n\n| Document | Path | Purpose |\n|----------|------|---------|\n| Implementation Phasing | `docs/specs/research/implementation-phasing.md` | Phase definitions, spec section maps, cross-cutting architecture |\n| Telemetry Agent Spec | `docs/specs/telemetry-agent-spec-v3.9.md` | Source of truth for what to build |\n| Tech Stack Evaluation | `docs/architecture/tech-stack-evaluation.md` | Version numbers, API patterns, library choices |\n| Evaluation Rubric | `research/evaluation-rubric.md` | Full rule definitions for acceptance criteria |\n| Architectural Recommendations | `docs/architecture/recommendations.md` | Preserve/change verdicts, evidence base |\n| Design Document | `docs/architecture/design-document.md` | Interface contracts, module organization, decision register |\n| Tech Stack by Phase | `references/tech-stack-by-phase.md` (skill-bundled) | Routing table: which tech stack sections per phase |\n| Phase PRD Template | `references/phase-prd-template.md` (skill-bundled) | Output template |\n\n## Important Notes\n\n- **One phase per session.** Multiple phase PRDs in one context risks detail loss.\n- **The spec is the source of truth.** If the phasing document and spec disagree, the spec wins. Flag the discrepancy for the user.\n- **Don''t include evaluation findings.** The implementing AI needs what to build, not why the last attempt failed.\n- **Don''t include rejected alternatives.** No LangGraph comparisons, no Babel evaluations.\n- **Trust the routing tables.** Don''t add \"extra context that might be helpful.\"\n- **TypeScript for agent code, JavaScript for target files.** The agent code is TypeScript with ESM modules (native type stripping, `erasableSyntaxOnly`). ts-morph handles JavaScript target files via `allowJs: true`. Agent code samples use TypeScript; target file examples remain JavaScript.\n\n**Note**: If any `gh` command fails with \"command not found\", inform the user that GitHub CLI is required: https://cli.github.com/\n"},"lastSynced":"2026-03-07T03:54:02.960Z","agentAnalysis":{"suitability":{"en":"Ideal for Technical Writing Agents needing to create implementation phase PRDs for telemetry agents by assembling content from existing research documents.","zh":"适合需要为遥测代理创建实施阶段PRD的技术写作代理，通过从现有研究文档中组装内容。","ja":"テレメトリエージェントの実装段階のPRDを作成するために、既存の研究文書からコンテンツを組み立てる必要がある技術文書エージェントに最適です。","ko":"텔레메트리 에이전트를 위한 구현 단계 PRD를 만들기 위해 기존 연구 문서에서 콘텐츠를 조립하여 기술 문서 에이전트가 필요한 경우 적합합니다.","es":"Ideal para Agentes de Escritura Técnica que necesitan crear PRDs de fase de implementación para agentes de telemetría mediante la compilación de contenido de documentos de investigación existentes.","fr":"Idéal pour les agents de rédaction technique ayant besoin de créer des PRD de phase de mise en œuvre pour les agents de télémétrie en rassemblant du contenu à partir de documents de recherche existants.","de":"Ideal für technische Schreibagenten, die PRDs für die Implementierungsphase für Telemetrieagenten durch die Zusammenstellung von Inhalten aus bestehenden Forschungsdokumenten erstellen müssen.","pt":"Ideal para Agentes de Escrita Técnica que necessitam criar PRDs de fase de implementação para agentes de telemetria, montando conteúdo a partir de documentos de pesquisa existentes.","ru":"Идеально подходит для агентов технического писания, которым необходимо создавать документы PRD фазы реализации для агентов телеметрии, собирая контент из существующих исследовательских документов.","ar":"مثالية لعميل الكتابة الفنية الذين يحتاجون إلى إنشاء وثائق مواصفات الإنتاج في مرحلة التنفيذ لعميل تелеметري من خلال تجميع المحتوى من وثائق البحث الموجودة."},"recommendation":{"en":"Empowers agents to generate focused PRDs by routing to the right documents, extracting key details, and maintaining bounded context, all while preventing detail loss and adhering to critical principles.","zh":"赋予代理生成聚焦的PRD的能力，通过路由到正确的文档，提取关键细节，维持有界上下文，同时防止细节丢失并遵守关键原则。","ja":"正しいドキュメントにルーティングし、重要な詳細を抽出し、境界付きコンテキストを維持することで、詳細の損失を防ぎながら、重要な原則に従って、集中したPRDを生成するエージェントの能力を付与します。","ko":"정확한 문서로 라우팅하고 중요한 세부 정보를 추출하며 경계 포함 컨텍스트를 유지함으로써 세부 사항 손실을 방지하면서 중요한 원칙을 준수하여 집중된 PRD를 생성할 수 있는 에이전트의 능력을 부여합니다.","es":"Habilita a los agentes a generar PRDs enfocados al enrutrar a los documentos adecuados, extraer detalles clave y mantener un contexto acotado, todo esto mientras se evita la pérdida de detalles y se adhieren a los principios críticos.","fr":"Permet aux agents de générer des PRD ciblés en routant vers les bons documents, en extrayant les détails clés et en maintenant un contexte borné, le tout en évitant la perte de détails et en respectant les principes critiques.","de":"Ermächtigt Agenten, fokussierte PRDs zu generieren, indem sie zu den richtigen Dokumenten routen, wichtige Details extrahieren und einen begrenzten Kontext aufrechterhalten, all dies, während sie Detailverlust vermeiden und kritischen Prinzipien folgen.","pt":"Habilita os agentes a gerar PRDs focados, encaminhando para os documentos certos, extraíndo detalhes-chave e mantendo o contexto limitado, tudo isso enquanto evita a perda de detalhes e adere aos princípios críticos.","ru":"Наделяет агентов возможностью генерировать сфокусированные документы PRD, направляя их к правильным документам, извлекая ключевые детали и сохраняя ограниченный контекст, все это при предотвращении потери деталей и соблюдении критических принципов.","ar":"تمكّن الوكلاء من توليد مواصفات الإنتاج الموضعية من خلال توجيههم إلى الوثائق المناسبة، واستخراج التفاصيل الرئيسية، والحفاظ على السياق المحدود، كل ذلك مع منع فقدان التفاصيل والالتزام بالمبادئ الحرجة."},"useCases":{"en":["Assembling content from research documents for PRD creation","Extracting relevant details for implementation phase PRDs","Producing focused PRDs for telemetry agents"],"zh":["为PRD创建从研究文档组装内容","为实施阶段PRD提取相关细节","为遥测代理生成聚焦的PRD"],"ja":["PRD作成のために研究文書からコンテンツを組み立てる","実装段階のPRDのために関連する詳細を抽出する","テレメトリエージェントのために集中したPRDを生成する"],"ko":["PRD 생성을 위해 연구 문서에서 콘텐츠를 조립하여","구현 단계 PRD를 위한 관련 세부 사항을 추출하여","텔레메트리 에이전트를 위한 집중된 PRD를 생성하여"],"es":["Compilación de contenido de documentos de investigación para la creación de PRD","Extracción de detalles relevantes para PRD de fase de implementación","Producción de PRD enfocados para agentes de telemetría"],"fr":["Rassemblement de contenu de documents de recherche pour la création de PRD","Extraction de détails pertinents pour les PRD de phase de mise en œuvre","Production de PRD ciblés pour les agents de télémétrie"],"de":["Zusammenstellung von Inhalten aus Forschungsdokumenten für die Erstellung von PRD","Extraktion von relevanten Details für PRD der Implementierungsphase","Erstellung von fokussierten PRD für Telemetrieagenten"],"pt":["Montar conteúdo a partir de documentos de pesquisa para criação de PRD","Extraíndo detalhes relevantes para PRDs de fase de implementação","Produzindo PRDs focados para agentes de telemetria"],"ru":["Сбор контента из исследовательских документов для создания документов PRD","Извлечение релевантных деталей для документов PRD фазы реализации","Производство сфокусированных документов PRD для агентов телеметрии"],"ar":["تجميع المحتوى من وثائق البحث لإنشاء مواصفات الإنتاج","استخراج التفاصيل ذات الصلة لمواصفات الإنتاج في مرحلة التنفيذ","إنتاج مواصفات الإنتاج الموضعية لعميل تелеметري"]},"limitations":{"en":["Requires access to existing research documents","Limited to implementation phase PRD creation","Must adhere to bounded context principle"],"zh":["需要访问现有研究文档","仅限于实施阶段PRD创建","必须遵守有界上下文原则"],"ja":["既存の研究文書へのアクセスが必要","実装段階のPRD作成に限定される","境界付きコンテキストの原則に従う必要がある"],"ko":["기존 연구 문서에 대한 액세스가 필요함","구현 단계 PRD 생성에만 محدود됨","경계 포함 컨텍스트 원칙을 따라야 함"],"es":["Requiere acceso a documentos de investigación existentes","Limitado a la creación de PRD de fase de implementación","Debe adherirse al principio de contexto acotado"],"fr":["Nécessite l''accès à des documents de recherche existants","Limité à la création de PRD de phase de mise en œuvre","Doit respecter le principe de contexte borné"],"de":["Erfordert den Zugriff auf bestehende Forschungsdokumente","Begrenzt auf die Erstellung von PRD der Implementierungsphase","Muss dem Prinzip des begrenzten Kontexts folgen"],"pt":["Requer acesso a documentos de pesquisa existentes","Limitado à criação de PRD de fase de implementação","Deve aderir ao princípio do contexto limitado"],"ru":["Требует доступа к существующим исследовательским документам","Ограничен созданием документов PRD фазы реализации","Должно соблюдать принцип ограниченного контекста"],"ar":["يتطلب الوصول إلى وثائق البحث الموجودة","محدود بإنشاء مواصفات الإنتاج في مرحلة التنفيذ","يجب الالتزام بمبدأ السياق المحدود"]},"version":4},"contentHash":"032f497723ef40b1792a383ea4790772cb6235922c83ac60ce9685b9f6ce816e","qualityScore":45}');
