INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('wiggitywhitney/telemetry-agent-research/prd-phase', 'prd-phase', 'wiggitywhitney', 'telemetry-agent-research', 'community', 'prd-phase wiggitywhitney telemetry-agent-research community The prd-phase skill creates implementation phase PRDs for telemetry agents by assembling content from existing research documents, benefiting AI agent developers. prd-phase是一种研究和评估框架，用于AI驱动的遥测仪表代理的实现阶段PRD文档创建 prd-phaseは、AI駆動のテレメトリーエージェントの実装段階のPRD文書を作成するための研究および評価フレームワークです prd-phase는 AI 구동 텔레메트리 에이전트의 구현 단계 PRD 문서 생성을 위한 연구 및 평가 프레임워크입니다 prd-phase es un marco de evaluación de investigación para agentes de telemetría AI. Crea PRDs de implementación de fase reutilizando contenido de documentos de investigación existentes. prd-phase est un cadre d''évaluation de la recherche pour les agents de télémétrie AI. Créez des PRDs de phase d''implémentation en réutilisant du contenu de documents de recherche existants. prd-phase ist ein Forschungs- und Bewertungsrahmen für AI-Telemetrie-Agenten. Erstellen Sie Implementierungsphasen-PRDs durch Wiederverwendung von Inhalten aus bestehenden Forschungsdokumenten. O prd-phase é um framework de pesquisa e avaliação para agentes de instrumentação de telemetria com tecnologias de inteligência artificial. Ele ajuda a criar implementações de fase PRD prd-phase - это исследовательский и оценочный фреймворк для агентов телелеметрии с технологиями ИИ. Он помогает создавать реализации фазы PRD prd-phase هو إطار بحث وتقييم لأدوات एजنتات التелеметري بأدوات الذكاء الاصطناعي. يساعد على إنشاء مراحل تنفيذ موثقة how to use prd-phase prd-phase alternative prd-phase setup guide what is prd-phase prd-phase vs telemetry instrumentation agents implementing prd-phase for AI agents AI工具 prd-phase 遥测仪表代理 实现阶段PRD文档 bounded context 无细节丢失 AI驱动 研究和评估 Assembles content from existing research documents to create focused PRDs Extracts specific details from routing tables to ensure bounded context Prevents detail loss by adhering to critical principles Utilizes versioning to maintain accuracy Creates implementation phase PRDs for telemetry agents prd-phase is a research and evaluation framework for creating implementation phase PRDs for AI-powered telemetry instrumentation agents.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('rudironsoni/dotnet-harness-plugin/dotnet-cli-release-pipeline', 'community', 'rudironsoni', 'dotnet-harness-plugin', 'rudironsoni/dotnet-harness-plugin', 'dotnet-cli-release-pipeline', 0, 0, 45, '2026-02-27T21:33:22Z', '2026-03-07T03:54:48.208Z', 'ef54379ae95e58520328630fab5da8bab4ef958521905b2596a4dc73f36d3906', '{"id":"rudironsoni/dotnet-harness-plugin/dotnet-cli-release-pipeline","name":"dotnet-cli-release-pipeline","description":{"en":"The dotnet-cli-release-pipeline skill provides a unified release CI/CD pipeline for .NET CLI tools, enabling developers to automate workflows and generate distribution packages. It benefits .NET developers working with GitHub Actions and .NET 8.0+.","zh":"dotnet-cli-release-pipeline是一种用于自动化.NET发布流水线的工具，支持多平台和版本管理","ja":"dotnet-cli-release-pipelineは、.NETのリリースパイプラインを自動化するためのツールで、GitHub ActionsワークフローとSemVerバージョニングをサポート","ko":"dotnet-cli-release-pipeline는 자동화된 .NET 배포 파이프라인을 구축하는 데 사용되는 도구로, GitHub Actions 워크플로와 SemVer 버ージョ닝을 지원","es":"El pipeline de lanzamiento de dotnet-cli proporciona una guía integral para el desarrollo de .NET con GitHub Actions y versionamiento SemVer.","fr":"Le pipeline de publication dotnet-cli offre une guidance complète pour le développement .NET avec GitHub Actions et la stratégie de versionning SemVer.","de":"Die Release-Pipeline von dotnet-cli bietet eine umfassende Anleitung für die .NET-Entwicklung mit GitHub Actions und SemVer-Versionierung.","pt":"O dotnet-cli-release-pipeline é uma ferramenta de automação de pipeline de desenvolvimento .NET que utiliza GitHub Actions e SemVer para melhorar a eficiência do processo de desenvolvimento.","ru":"Конвейер выпуска dotnet-cli-release-pipeline — это инструмент автоматизации процесса разработки .NET, использующий GitHub Actions и SemVer для повышения эффективности.","ar":"dotnet-cli-release-pipeline 