INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('AlexandrSurkov/ForgentFramework/copilot-vscode', 'copilot-vscode', 'AlexandrSurkov', 'ForgentFramework', 'community', 'copilot-vscode AlexandrSurkov ForgentFramework community The copilot-vscode skill enables developers to leverage a multi-agent development framework for faster, higher-quality delivery across any IT project, utilizing features like custom agent files and MCP servers in VS Code. VS Code Copilot 平台是一个多代理开发框架，用于提高开发效率和质量 VS Code Copilot プラットフォームは、開発効率と品質を向上させるためのマルチエージェント開発フレームワークです VS Code Copilot 플랫폼은 개발 효율과 품질을 높이는 멀티 에이전트 개발 프레임워크입니다 El marco de desarrollo multiagente copilot-vscode permite una entrega más rápida y de mayor calidad en cualquier proyecto IT Le framework de développement multiagent copilot-vscode permet une livraison plus rapide et de meilleure qualité pour tout projet IT Das Multiagent-Entwicklungsframework copilot-vscode ermöglicht eine schnellere und hochwertigere Lieferung von IT-Projekten O Copilot VSCode é uma plataforma de desenvolvimento que melhora a entrega de projetos de TI. Oferece recursos como subagentes, handoffs e servidores MCP. Copilot VSCode — это многоагентная платформа разработки, которая повышает качество и скорость доставки ИТ-проектов. Включает в себя функции như субагенты, хэндофы и серверы MCP. Copilot VSCode هو إطار عمل متعدد الوكلاء لتحسين تسليم المشاريع التكنولوجية. يوفر ميزات مثل الوكلاء الفرعيين، وتسليم المهام، وخادم MCP how to use copilot-vscode copilot-vscode setup guide what is copilot-vscode copilot-vscode vs kite copilot-vscode install copilot-vscode alternative copilot-vscode tutorial copilot-vscode documentation copilot-vscode github copilot-vscode vs tabnine VS Code Copilot AI开发工具 代码完成 代码审查 自定义代理文件 工具选择 MCP服务器 VS Code 扩展 Loads custom agent files (.agent.md) for tailored development experiences Utilizes MCP servers in VS Code for seamless integration Supports #fetch command for reading external pages Configures SKILL.md for customized framework settings Integrates with GitHub source for version control and collaboration Follows official documentation from https://code.visualstudio.com/docs/copilot for reliable guidance copilot-vscode is a multi-agent development framework that integrates with VS Code to enhance development workflows, utilizing .agent.md files and context strategy for efficient project delivery.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('journey247/whistle-inn/docx', 'community', 'journey247', 'whistle-inn', 'journey247/whistle-inn', 'docx', 0, 0, 45, '2026-03-07T01:49:01.808Z', '2026-03-07T03:30:25.020Z', '0bd90681fcab2e282025ee14acf508b60bbd6c41ac6c3bf83c0dc14d52c37933', '{"id":"journey247/whistle-inn/docx","name":"docx","description":{"en":"The docx skill enables AI agents to create, edit, and analyze DOCX files, a ZIP archive containing XML files and resources. This skill benefits developers working with Microsoft Word documents.","zh":"DOCX 文档创建、编辑和分析技术，包括文本提取和 XML 访问","ja":"DOCX ファイルの作成、編集、分析方法。Text extraction と Raw XML access を使用する","ko":"DOCX 문서 생성, 편집, 분석 기술. Text extraction 및 Raw XML access 기능을 제공합니다","es":"El formato docx es un archivo ZIP que contiene archivos XML y otros recursos. Puedes crear, editar o analizar su contenido con herramientas avanzadas.","fr":"Le format docx est un fichier ZIP contenant des fichiers XML et d''autres ressources. Vous pouvez créer, éditer ou analyser son contenu avec des outils avancés.","de":"Das docx-Format ist eine ZIP-Datei, die XML-Dateien und andere Ressourcen enthält. Sie können den Inhalt mit fortschrittlichen Tools erstellen, bearbeiten oder analysieren.","pt":"O DOCX é um formato de arquivo ZIP que contém arquivos XML e outros recursos. Aprenda a criar, editar e analisar arquivos DOCX com ferramentas específicas.","ru":"DOCX - это формат файла ZIP, содержащий XML-файлы и другие ресурсы. Узнайте, как создавать, редактировать и анализировать файлы DOCX с помощью специальных инструментов и ИИ Агентов","ar":"DOCX هو تنسيق ملف ZIP يحتوي على ملفات XML وموارد أخرى. تعلم كيفية إنشاء وتحرير وتحليل ملفات DOCX باستخدام أدوات محددة وأدوات الذكاء الاصطناعي"},"seo":{"title":{"en":"docx: Mastering DOCX Creation and Analysis for AI Agents ...","zh":"DOCX 文档创建和编辑指南","ja":"DOCX ファイル作成と編集のベストプラクティス","ko":