INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('journey247/whistle-inn/docx', 'docx', 'journey247', 'whistle-inn', 'community', 'docx journey247 whistle-inn community The docx skill enables AI agents to create, edit, and analyze DOCX files, a ZIP archive containing XML files and resources. This skill benefits developers working with Microsoft Word documents. DOCX 文档创建、编辑和分析技术，包括文本提取和 XML 访问 DOCX ファイルの作成、編集、分析方法。Text extraction と Raw XML access を使用する DOCX 문서 생성, 편집, 분석 기술. Text extraction 및 Raw XML access 기능을 제공합니다 El formato docx es un archivo ZIP que contiene archivos XML y otros recursos. Puedes crear, editar o analizar su contenido con herramientas avanzadas. Le format docx est un fichier ZIP contenant des fichiers XML et d''autres ressources. Vous pouvez créer, éditer ou analyser son contenu avec des outils avancés. Das docx-Format ist eine ZIP-Datei, die XML-Dateien und andere Ressourcen enthält. Sie können den Inhalt mit fortschrittlichen Tools erstellen, bearbeiten oder analysieren. O DOCX é um formato de arquivo ZIP que contém arquivos XML e outros recursos. Aprenda a criar, editar e analisar arquivos DOCX com ferramentas específicas. DOCX - это формат файла ZIP, содержащий XML-файлы и другие ресурсы. Узнайте, как создавать, редактировать и анализировать файлы DOCX с помощью специальных инструментов и ИИ Агентов DOCX هو تنسيق ملف ZIP يحتوي على ملفات XML وموارد أخرى. تعلم كيفية إنشاء وتحرير وتحليل ملفات DOCX باستخدام أدوات محددة وأدوات الذكاء الاصطناعي how to use docx what is docx docx alternative docx vs odt docx install guide docx setup for AI agents creating docx files editing docx files analyzing docx content DOCX 文档创建 DOCX 编辑 DOCX 分析 AI エージェント Text extraction Raw XML access ZIP 压缩 XML 文件 Word 文档 Creates new Word documents using specific workflows Edits and analyzes contents of existing DOCX files Utilizes Text extraction for reading DOCX content Employs Raw XML access for advanced DOCX manipulation Follows a decision tree for determining the optimal workflow docx is a file format representing a ZIP archive containing XML files and other resources, used for creating, editing, and analyzing Microsoft Word documents.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('sandriaas/_dotfiles/copilot-instructions-blueprint-generator', 'community', 'sandriaas', '_dotfiles', 'sandriaas/_dotfiles', 'copilot-instructions-blueprint-generator', 0, 0, 45, '2026-02-27T08:20:29Z', '2026-03-07T03:59:44.091Z', 'e53409119442128e2afbc2b48ad1b286fb23b884934de26dd088b3a375fcfb2b', '{"id":"sandriaas/_dotfiles/copilot-instructions-blueprint-generator","name":"copilot-instructions-blueprint-generator","description":{"en":"The copilot-instructions-blueprint-generator skill generates blueprints for AI agents based on configuration variables such as project type, architecture style, and code quality focus. It benefits developers working with multiple technologies like .NET, Java, JavaScript, and Python","zh":"Copilot Instructions Blueprint Generator是一种AI智能工具，支持多种项目类型和架构风格，帮助开发者优化代码质量和文档水平","ja":"Copilot Instructions Blueprint Generatorは、AIエージェントの一種で、多種多様なプロジェクトタイプとアーキテクチャスタイルをサポートし、開発者がコード品質とドキュメントレベルを最適化するのに役立ちます","ko":"Copilot Instructions Blueprint Generator는 AI 에이전트의 일종으로 다양한 프로젝트 유형과 아키텍처 스타일을 지원하여 개발자가 코드 품질과 문서 수준을 최적화하는 데 도움을 줍니다","es":"El generador de planos de copiloto es una herramienta que ayuda a los desarrolladores a crear proyectos con tecnologías como .NET, Java y Python","fr":"Le générateur de plans de copilote est un outil qui aide les développeurs à créer des projets avec des technologies telles que .NET, Java et Python","de":"Der Copilot-Anweisungs-Blueprint-Generator ist ein Tool, das Entwicklern hilft, Projekte mit Technologien wie .NET, Java und Python zu erstellen","pt":"O Copilot Instructions Blueprint Generator é uma ferramenta de código que ajuda a melhorar a qualidade do código em várias tecnologias.","ru":"ИИ Агент Copilot Instructions Blueprint Generator - это инструмент, который помогает улучшить качество кода в различных технологиях.","ar":"Copilot Instructions Blueprint Generator هو أداة تعليمات برمجية تساعد على تحسين جودة التعليمات البرمجية في تكنولوجيا متعددة."},"seo":{"title":{"en":"Copilot Instructions Blueprint Generator: Setup Guide for...","zh":"AI智能工具：Copilot Instructions Blueprint Generator 配置指南","ja":"AIエージェント：Copilot Instructions Blueprint Generator の設定方法","ko":"AI 에이전트: Copilot Instructions Blueprint Generator 설정 가이드","es":"Generador de planos de copiloto: Guía de configuración","fr":"Générateur de plans de copilote: Meilleures pratiques","de":"Copilot-Anweisungs-Blueprint-Generator: Einrichtungsleitf...","pt":"Guia de Configuração do Copilot Instructions Blueprint Ge...","ru":"Настройка Инструментов ИИ: Copilot Instructions Blueprint...","ar":"دليل إعداد Copilot Instructions Blueprint Generator"},"description":{"en":"Discover how to configure copilot-instructions-blueprint-generator for optimal results. Learn to set up project types, architecture styles, and code quality ...","zh":"了解Copilot Instructions Blueprint Generator的配置变量和技术细节，优化您的项目开发流程","ja":"Copilot Instructions Blueprint Generatorの設定変数と技術的詳細を学び、プロジェクト開発プロセスを最適化する","ko":"Copilot Instructions Blueprint Generator의 구성 변수와 기술 세부 사항을 알아보고 프로젝트 개발 프로세스를 최적화하세요","es":"Descubre cómo configurar el generador de planos de copiloto para proyectos de .NET, Java, JavaScript, TypeScript, React, Angular y Python","fr":"Découvrez comment configurer le générateur de plans de copilote pour les projets .NET, Java, JavaScript, TypeScript, React, Angular et Python","de":"Erfahren Sie, wie Sie den Copilot-Anweisungs-Blueprint-Generator für .NET-, Java-, JavaScript-, TypeScript-, React-, Angular- und Python-Projekte konfigurieren","pt":"Aprenda a configurar o Copilot Instructions Blueprint Generator para melhorar a qualidade do código em tecnologias como .NET, Java e Python","ru":"Узнайте, как настроить Copilot Instructions Blueprint Generator для улучшения качества кода в технологиях seperti .NET, Java и Python","ar":"تعلم كيفية إعداد Copilot Instructions Blueprint Generator لتحسين جودة التعليمات البرمجية في التكنولوجيا مثل .NET و Java و Python"},"definition":{"en":"copilot-instructions-blueprint-generator is a skill that generates deterministic blueprints for AI agents using configuration variables such as project type, architecture style, and code quality focus","zh":"Copilot Instructions Blueprint Generator是一种AI智能工具，用于生成项目蓝图和配置指南","ja":"Copilot Instructions Blueprint Generatorは、プロジェクトのブループリントと設定ガイドを生成するAIエージェントの一種です","ko":"Copilot Instructions Blueprint Generator는 프로젝트 블루프린트와 설정 가이드를 생성하는 AI 에이전트의 일종입니다","es":"Un generador de planos de copiloto es una herramienta de inteligencia artificial que genera instrucciones personalizadas para proyectos de software","fr":"Un générateur de plans de copilote est un outil d''intelligence artificielle qui génère des instructions personnalisées pour les projets de logiciel","de":"Ein Copilot-Anweisungs-Blueprint-Generator ist ein KI-Tool, das individuelle Anweisungen für Softwareprojekte generiert","pt":"O que é Copilot Instructions Blueprint Generator? É uma ferramenta que gera blueprints de código personalizadas.","ru":"Что такое Copilot Instructions Blueprint Generator? Это инструмент, который генерирует индивидуальные планы кода.","ar":"ما هو Copilot Instructions Blueprint Generator؟ هو أداة لتوليد مخططات التعليمات البرمجية المخصصة."},"features":{"en":["Supports multiple project types including .NET, Java, JavaScript, TypeScript, React, Angular, and Python","Allows configuration of architecture styles such as Layered, Microservices, Monolithic, Domain-Driven, Event-Driven, and Serverless","Enables setting of code quality focus areas including Maintainability, Performance, Security, Accessibility, and Testability","Generates blueprints based on documentation levels such as Minimal, Standard, and Comprehensive","Supports auto-detection of project types for simplified configuration","Provides flexibility in setting quality priorities for AI-driven development"],"zh":["支持多种项目类型，包括.NET、Java、JavaScript、TypeScript、React、Angular、Python等","提供多种架构风格，包括分层、微服务、单体、领域驱动、事件驱动、无服务器等","允许配置代码质量焦点，包括可维护性、性能、安全性、可访问性、测试性等","支持多种文档水平，包括最小、标准、综合等","支持自动检测项目类型"],"ja":["多種多様なプロジェクトタイプをサポート、.NET、Java、JavaScript、TypeScript、React、Angular、Pythonなど","多種多様なアーキテクチャスタイルを提供、分層、微服务、単体、ドメイン駆動、イベント駆動、サーバーレスなど","コード品質の焦点を設定できる、保守性、パフォーマンス、セキュリティ、可達性、テスト性など","多種多様なドキュメントレベルをサポート、最小、標準、包括的など","プロジェクトタイプの自動検出をサポート"],"ko":["다양한 프로젝트 유형을 지원, .NET, Java, JavaScript, TypeScript, React, Angular, Python 등","다양한 아키텍처 스타일을 제공, 분층, 마이크로서비스, 단일체, 도메인 주도, 이벤트 주도, 서버리스 등","코드 품질의 초점을 설정할 수 있음, 유지 보수성, 성능, 보안, 접근성, 테스트성 등","다양한 문서 수준을 지원, 최소, 표준, 포괄적 등","프로젝트 유형의 자동 감지를 지원"],"es":["Soporte para múltiples tecnologías como .NET, Java, JavaScript, TypeScript, React, Angular y Python","Configuración de la arquitectura del proyecto con estilos como Layered, Microservices, Monolithic, Domain-Driven, Event-Driven y Serverless","Enfoque en la calidad del código con prioridades como Mantenibilidad, Rendimiento, Seguridad, Accesibilidad y Testabilidad","Niveles de documentación personalizables, desde Minimal hasta Comprehensivo","Detección automática del tipo de proyecto y ajuste de la configuración correspondiente"],"fr":["Prise en charge de plusieurs technologies comme .NET, Java, JavaScript, TypeScript, React, Angular et Python","Configuration de l''architecture du projet avec des styles tels que Layered, Microservices, Monolithic, Domain-Driven, Event-Driven et Serverless","Focus sur la qualité du code avec des priorités comme Maintenabilité, Performance, Sécurité, Accessibilité et Testabilité","Niveaux de documentation personnalisables, de Minimal à Complet","Détection automatique du type de projet et ajustement de la configuration correspondante"],"de":["Unterstützung für mehrere Technologien wie .NET, Java, JavaScript, TypeScript, React, Angular und Python","Konfiguration der Architektur des Projekts mit Stilen wie Layered, Microservices, Monolithic, Domain-Driven, Event-Driven und Serverless","Fokus auf die Code-Qualität mit Prioritäten wie Wartbarkeit, Leistung, Sicherheit, Zugänglichkeit und Testbarkeit","Anpassbare Dokumentationsniveaus, von Minimal bis Umfassend","Automatische Erkennung des Projekttyps und Anpassung der entsprechenden Konfiguration"],"pt":["Suporte a tecnologias como .NET, Java, JavaScript e Python","Opções de arquitetura como Layered, Microservices e Monolithic","Foco em qualidade de código, incluindo manutenção, desempenho e segurança","Níveis de documentação personalizáveis, de Minimal a Comprehensi","Geração de blueprints de código personalizadas com base em variáveis de configuração"],"ru":["Поддержка технологий seperti .NET, Java, JavaScript и Python","Варианты архитектуры, такие как Layered, Microservices и Monolithic","Фокус на качестве кода, включая поддержку, производительность и безопасность","Настраиваемые уровни документации, от Minimal до Comprehensi","Генерация индивидуальных планов кода на основе переменных конфигурации"],"ar":["دعم التكنولوجيا مثل .NET و Java و JavaScript و Python","خيارات الهندسة المعمارية مثل Layered و Microservices و Monolithic","التركيز على جودة التعليمات البرمجية، بما في ذلك الصيانة والأداء والأمان","مستويات الوثائق المخصصة، من Minimal إلى Comprehensi","توليد مخططات التعليمات البرمجية المخصصة بناءً على متغيرات التكوين"]},"keywords":{"en":["how to use copilot-instructions-blueprint-generator","copilot-instructions-blueprint-generator setup guide","copilot-instructions-blueprint-generator alternative","copilot-instructions-blueprint-generator vs competitor","what is copilot-instructions-blueprint-generator","copilot-instructions-blueprint-generator install","copilot-instructions-blueprint-generator for AI agents","copilot-instructions-blueprint-generator for multiple technologies","copilot-instructions-blueprint-generator configuration variables","copilot-instructions-blueprint-generator best practices"],"zh":["AI智能工具","Copilot Instructions Blueprint Generator","项目蓝图","配置指南","代码质量","文档水平","自动检测项目类型"],"ja":["AIエージェント","Copilot Instructions Blueprint Generator","プロジェクトブループリント","設定ガイド","コード品質","ドキュメントレベル","プロジェクトタイプの自動検出"],"ko":["AI 에이전트","Copilot Instructions Blueprint Generator","프로젝트 블루프린트","설정 가이드","코드 품질","문서 수준","프로젝트 유형의 자동 감지"],"es":["generador de planos de copiloto","herramientas de inteligencia artificial para desarrolladores","configuración de proyectos de software","tecnologías de desarrollo de software","calidad del código","documentación de proyectos","arquitectura de software","desarrollo de software ágil"],"fr":["générateur de plans de copilote","outils d''intelligence artificielle pour les développeurs","configuration de projets de logiciel","technologies de développement de logiciel","qualité du code","documentation de projets","architecture de logiciel","développement de logiciel agile"],"de":["Copilot-Anweisungs-Blueprint-Generator","KI-Tools für Entwickler","Konfiguration von Softwareprojekten","Software-Entwicklungstechnologien","Code-Qualität","Projekt-Dokumentation","Software-Architektur","Agiles Software-Entwickeln"],"pt":["Copilot Instructions Blueprint Generator","ferramenta de código","qualidade de código","tecnologias de desenvolvimento","arquitetura de software","desenvolvimento de software","geração de código","blueprints de código"],"ru":["ИИ Агент Copilot Instructions Blueprint Generator","инструмент кода","качество кода","технологии разработки","архитектура программного обеспечения","разработка программного обеспечения","генерация кода","планы кода"],"ar":["Copilot Instructions Blueprint Generator","أداة التعليمات البرمجية","جودة التعليمات البرمجية","تكنولوجيا التطوير","هندسة البرمجيات","تطوير البرمجيات","توليد التعليمات البرمجية","مخططات التعليمات البرمجية"]}},"owner":"sandriaas","repo":"_dotfiles","repoPath":"sandriaas/_dotfiles","stars":0,"forks":0,"updatedAt":"2026-02-27T08:20:29Z","topics":[],"category":"community","skillMd":{"name":"copilot-instructions-blueprint-generator","description":"Technology-agnostic blueprint generator for creating comprehensive copilot-instructions.md files that guide GitHub Copilot to produce code consistent with project standards, architecture patterns, and exact technology versions by analyzing existing codebase patterns and avoiding assumptions.","bodyPreview":"# Copilot Instructions Blueprint Generator\n\n## Configuration Variables\n${PROJECT_TYPE=\"Auto-detect|.NET|Java|JavaScript|TypeScript|React|Angular|Python|Multiple|Other\"} <!-- Primary technology -->\n${ARCHITECTURE_STYLE=\"Layered|Microservices|Monolithic|Domain-Driven|Event-Driven|Serverless|Mixed\"} <!-- Architectural approach -->\n${CODE_QUALITY_FOCUS=\"Maintainability|Performance|Security|Accessibility|Testability|All\"} <!-- Quality priorities -->\n${DOCUMENTATION_LEVEL=\"Minimal|Standard|Comprehensi","body":"# Copilot Instructions Blueprint Generator\n\n## Configuration Variables\n${PROJECT_TYPE=\"Auto-detect|.NET|Java|JavaScript|TypeScript|React|Angular|Python|Multiple|Other\"} <!-- Primary technology -->\n${ARCHITECTURE_STYLE=\"Layered|Microservices|Monolithic|Domain-Driven|Event-Driven|Serverless|Mixed\"} <!-- Architectural approach -->\n${CODE_QUALITY_FOCUS=\"Maintainability|Performance|Security|Accessibility|Testability|All\"} <!-- Quality priorities -->\n${DOCUMENTATION_LEVEL=\"Minimal|Standard|Comprehensive\"} <!-- Documentation requirements -->\n${TESTING_REQUIREMENTS=\"Unit|Integration|E2E|TDD|BDD|All\"} <!-- Testing approach -->\n${VERSIONING=\"Semantic|CalVer|Custom\"} <!-- Versioning approach -->\n\n## Generated Prompt\n\n\"Generate a comprehensive copilot-instructions.md file that will guide GitHub Copilot to produce code consistent with our project''s standards, architecture, and technology versions. The instructions must be strictly based on actual code patterns in our codebase and avoid making any assumptions. Follow this approach:\n\n### 1. Core Instruction Structure\n\n```markdown\n# GitHub Copilot Instructions\n\n## Priority Guidelines\n\nWhen generating code for this repository:\n\n1. **Version Compatibility**: Always detect and respect the exact versions of languages, frameworks, and libraries used in this project\n2. **Context Files**: Prioritize patterns and standards defined in the .github/copilot directory\n3. **Codebase Patterns**: When context files don''t provide specific guidance, scan the codebase for established patterns\n4. **Architectural Consistency**: Maintain our ${ARCHITECTURE_STYLE} architectural style and established boundaries\n5. **Code Quality**: Prioritize ${CODE_QUALITY_FOCUS == \"All\" ? \"maintainability, performance, security, accessibility, and testability\" : CODE_QUALITY_FOCUS} in all generated code\n\n## Technology Version Detection\n\nBefore generating code, scan the codebase to identify:\n\n1. **Language Versions**: Detect the exact versions of programming languages in use\n   - Examine project files, configuration files, and package managers\n   - Look for language-specific version indicators (e.g., <LangVersion> in .NET projects)\n   - Never use language features beyond the detected version\n\n2. **Framework Versions**: Identify the exact versions of all frameworks\n   - Check package.json, .csproj, pom.xml, requirements.txt, etc.\n   - Respect version constraints when generating code\n   - Never suggest features not available in the detected framework versions\n\n3. **Library Versions**: Note the exact versions of key libraries and dependencies\n   - Generate code compatible with these specific versions\n   - Never use APIs or features not available in the detected versions\n\n## Context Files\n\nPrioritize the following files in .github/copilot directory (if they exist):\n\n- **architecture.md**: System architecture guidelines\n- **tech-stack.md**: Technology versions and framework details\n- **coding-standards.md**: Code style and formatting standards\n- **folder-structure.md**: Project organization guidelines\n- **exemplars.md**: Exemplary code patterns to follow\n\n## Codebase Scanning Instructions\n\nWhen context files don''t provide specific guidance:\n\n1. Identify similar files to the one being modified or created\n2. Analyze patterns for:\n   - Naming conventions\n   - Code organization\n   - Error handling\n   - Logging approaches\n   - Documentation style\n   - Testing patterns\n   \n3. Follow the most consistent patterns found in the codebase\n4. When conflicting patterns exist, prioritize patterns in newer files or files with higher test coverage\n5. Never introduce patterns not found in the existing codebase\n\n## Code Quality Standards\n\n${CODE_QUALITY_FOCUS.includes(\"Maintainability\") || CODE_QUALITY_FOCUS == \"All\" ? `### Maintainability\n- Write self-documenting code with clear naming\n- Follow the naming and organization conventions evident in the codebase\n- Follow established patterns for consistency\n- Keep functions focused on single responsibilities\n- Limit function complexity and length to match existing patterns` : \"\"}\n\n${CODE_QUALITY_FOCUS.includes(\"Performance\") || CODE_QUALITY_FOCUS == \"All\" ? `### Performance\n- Follow existing patterns for memory and resource management\n- Match existing patterns for handling computationally expensive operations\n- Follow established patterns for asynchronous operations\n- Apply caching consistently with existing patterns\n- Optimize according to patterns evident in the codebase` : \"\"}\n\n${CODE_QUALITY_FOCUS.includes(\"Security\") || CODE_QUALITY_FOCUS == \"All\" ? `### Security\n- Follow existing patterns for input validation\n- Apply the same sanitization techniques used in the codebase\n- Use parameterized queries matching existing patterns\n- Follow established authentication and authorization patterns\n- Handle sensitive data according to existing patterns` : \"\"}\n\n${CODE_QUALITY_FOCUS.includes(\"Accessibility\") || CODE_QUALITY_FOCUS == \"All\" ? `### Accessibility\n- Follow existing accessibility patterns in the codebase\n- Match ARIA attribute usage with existing components\n- Maintain keyboard navigation support consistent with existing code\n- Follow established patterns for color and contrast\n- Apply text alternative patterns consistent with the codebase` : \"\"}\n\n${CODE_QUALITY_FOCUS.includes(\"Testability\") || CODE_QUALITY_FOCUS == \"All\" ? `### Testability\n- Follow established patterns for testable code\n- Match dependency injection approaches used in the codebase\n- Apply the same patterns for managing dependencies\n- Follow established mocking and test double patterns\n- Match the testing style used in existing tests` : \"\"}\n\n## Documentation Requirements\n\n${DOCUMENTATION_LEVEL == \"Minimal\" ? \n`- Match the level and style of comments found in existing code\n- Document according to patterns observed in the codebase\n- Follow existing patterns for documenting non-obvious behavior\n- Use the same format for parameter descriptions as existing code` : \"\"}\n\n${DOCUMENTATION_LEVEL == \"Standard\" ? \n`- Follow the exact documentation format found in the codebase\n- Match the XML/JSDoc style and completeness of existing comments\n- Document parameters, returns, and exceptions in the same style\n- Follow existing patterns for usage examples\n- Match class-level documentation style and content` : \"\"}\n\n${DOCUMENTATION_LEVEL == \"Comprehensive\" ? \n`- Follow the most detailed documentation patterns found in the codebase\n- Match the style and completeness of the best-documented code\n- Document exactly as the most thoroughly documented files do\n- Follow existing patterns for linking documentation\n- Match the level of detail in explanations of design decisions` : \"\"}\n\n## Testing Approach\n\n${TESTING_REQUIREMENTS.includes(\"Unit\") || TESTING_REQUIREMENTS == \"All\" ? \n`### Unit Testing\n- Match the exact structure and style of existing unit tests\n- Follow the same naming conventions for test classes and methods\n- Use the same assertion patterns found in existing tests\n- Apply the same mocking approach used in the codebase\n- Follow existing patterns for test isolation` : \"\"}\n\n${TESTING_REQUIREMENTS.includes(\"Integration\") || TESTING_REQUIREMENTS == \"All\" ? \n`### Integration Testing\n- Follow the same integration test patterns found in the codebase\n- Match existing patterns for test data setup and teardown\n- Use the same approach for testing component interactions\n- Follow existing patterns for verifying system behavior` : \"\"}\n\n${TESTING_REQUIREMENTS.includes(\"E2E\") || TESTING_REQUIREMENTS == \"All\" ? \n`### End-to-End Testing\n- Match the existing E2E test structure and patterns\n- Follow established patterns for UI testing\n- Apply the same approach for verifying user journeys` : \"\"}\n\n${TESTING_REQUIREMENTS.includes(\"TDD\") || TESTING_REQUIREMENTS == \"All\" ? \n`### Test-Driven Development\n- Follow TDD patterns evident in the codebase\n- Match the progression of test cases seen in existing code\n- Apply the same refactoring patterns after tests pass` : \"\"}\n\n${TESTING_REQUIREMENTS.includes(\"BDD\") || TESTING_REQUIREMENTS == \"All\" ? \n`### Behavior-Driven Development\n- Match the existing Given-When-Then structure in tests\n- Follow the same patterns for behavior descriptions\n- Apply the same level of business focus in test cases` : \"\"}\n\n## Technology-Specific Guidelines\n\n${PROJECT_TYPE == \".NET\" || PROJECT_TYPE == \"Auto-detect\" || PROJECT_TYPE == \"Multiple\" ? `### .NET Guidelines\n- Detect and strictly adhere to the specific .NET version in use\n- Use only C# language features compatible with the detected version\n- Follow LINQ usage patterns exactly as they appear in the codebase\n- Match async/await usage patterns from existing code\n- Apply the same dependency injection approach used in the codebase\n- Use the same collection types and patterns found in existing code` : \"\"}\n\n${PROJECT_TYPE == \"Java\" || PROJECT_TYPE == \"Auto-detect\" || PROJECT_TYPE == \"Multiple\" ? `### Java Guidelines\n- Detect and adhere to the specific Java version in use\n- Follow the exact same design patterns found in the codebase\n- Match exception handling patterns from existing code\n- Use the same collection types and approaches found in the codebase\n- Apply the dependency injection patterns evident in existing code` : \"\"}\n\n${PROJECT_TYPE == \"JavaScript\" || PROJECT_TYPE == \"TypeScript\" || PROJECT_TYPE == \"Auto-detect\" || PROJECT_TYPE == \"Multiple\" ? `### JavaScript/TypeScript Guidelines\n- Detect and adhere to the specific ECMAScript/TypeScript version in use\n- Follow the same module import/export patterns found in the codebase\n- Match TypeScript type definitions with existing patterns\n- Use the same async patterns (promises, async/await) as existing code\n- Follow error handling patterns from similar files` : \"\"}\n\n${PROJECT_TYPE == \"React\" || PROJECT_TYPE == \"Auto-detect\" || PROJECT_TYPE == \"Multiple\" ? `### React Guidelines\n- Detect and adhere to the specific React version in use\n- Match component structure patterns from existing components\n- Follow the same hooks and lifecycle patterns found in the codebase\n- Apply the same state management approach used in existing components\n- Match prop typing and validation patterns from existing code` : \"\"}\n\n${PROJECT_TYPE == \"Angular\" || PROJECT_TYPE == \"Auto-detect\" || PROJECT_TYPE == \"Multiple\" ? `### Angular Guidelines\n- Detect and adhere to the specific Angular version in use\n- Follow the same component and module patterns found in the codebase\n- Match decorator usage exactly as seen in existing code\n- Apply the same RxJS patterns found in the codebase\n- Follow existing patterns for component communication` : \"\"}\n\n${PROJECT_TYPE == \"Python\" || PROJECT_TYPE == \"Auto-detect\" || PROJECT_TYPE == \"Multiple\" ? `### Python Guidelines\n- Detect and adhere to the specific Python version in use\n- Follow the same import organization found in existing modules\n- Match type hinting approaches if used in the codebase\n- Apply the same error handling patterns found in existing code\n- Follow the same module organization patterns` : \"\"}\n\n## Version Control Guidelines\n\n${VERSIONING == \"Semantic\" ? \n`- Follow Semantic Versioning patterns as applied in the codebase\n- Match existing patterns for documenting breaking changes\n- Follow the same approach for deprecation notices` : \"\"}\n\n${VERSIONING == \"CalVer\" ? \n`- Follow Calendar Versioning patterns as applied in the codebase\n- Match existing patterns for documenting changes\n- Follow the same approach for highlighting significant changes` : \"\"}\n\n${VERSIONING == \"Custom\" ? \n`- Match the exact versioning pattern observed in the codebase\n- Follow the same changelog format used in existing documentation\n- Apply the same tagging conventions used in the project` : \"\"}\n\n## General Best Practices\n\n- Follow naming conventions exactly as they appear in existing code\n- Match code organization patterns from similar files\n- Apply error handling consistent with existing patterns\n- Follow the same approach to testing as seen in the codebase\n- Match logging patterns from existing code\n- Use the same approach to configuration as seen in the codebase\n\n## Project-Specific Guidance\n\n- Scan the codebase thoroughly before generating any code\n- Respect existing architectural boundaries without exception\n- Match the style and patterns of surrounding code\n- When in doubt, prioritize consistency with existing code over external best practices\n```\n\n### 2. Codebase Analysis Instructions\n\nTo create the copilot-instructions.md file, first analyze the codebase to:\n\n1. **Identify Exact Technology Versions**:\n   - ${PROJECT_TYPE == \"Auto-detect\" ? \"Detect all programming languages, frameworks, and libraries by scanning file extensions and configuration files\" : `Focus on ${PROJECT_TYPE} technologies`}\n   - Extract precise version information from project files, package.json, .csproj, etc.\n   - Document version constraints and compatibility requirements\n\n2. **Understand Architecture**:\n   - Analyze folder structure and module organization\n   - Identify clear layer boundaries and component relationships\n   - Document communication patterns between components\n\n3. **Document Code Patterns**:\n   - Catalog naming conventions for different code elements\n   - Note documentation styles and completeness\n   - Document error handling patterns\n   - Map testing approaches and coverage\n\n4. **Note Quality Standards**:\n   - Identify performance optimization techniques actually used\n   - Document security practices implemented in the code\n   - Note accessibility features present (if applicable)\n   - Document code quality patterns evident in the codebase\n\n### 3. Implementation Notes\n\nThe final copilot-instructions.md should:\n- Be placed in the .github/copilot directory\n- Reference only patterns and standards that exist in the codebase\n- Include explicit version compatibility requirements\n- Avoid prescribing any practices not evident in the code\n- Provide concrete examples from the codebase\n- Be comprehensive yet concise enough for Copilot to effectively use\n\nImportant: Only include guidance based on patterns actually observed in the codebase. Explicitly instruct Copilot to prioritize consistency with existing code over external best practices or newer language features.\n\"\n\n## Expected Output\n\nA comprehensive copilot-instructions.md file that will guide GitHub Copilot to produce code that is perfectly compatible with your existing technology versions and follows your established patterns and architecture.\n"},"lastSynced":"2026-03-07T03:59:44.091Z","agentAnalysis":{"suitability":{"en":"Perfect for Multi-Technology Agents needing customized project blueprints for .NET, Java, JavaScript, and Python architectures.","zh":"非常适合需要为 .NET、Java、JavaScript 和 Python 体系结构自定义项目蓝图的多技术代理。","ja":".NET、Java、JavaScript、Python アーキテクチャのカスタマイズされたプロジェクト ブループリントを必要とするマル