INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('leha-creator/youth_bot/ai-factory', 'ai-factory', 'leha-creator', 'youth_bot', 'community', 'ai-factory leha-creator youth_bot community The ai-factory skill enables developers to set up and configure Claude Code for their projects, ensuring seamless integration and security. It benefits AI agent developers and users. AI 工厂是一个用于配置 Claude Code 项目的工具，包括技术栈分析、技能安装和安全扫描 AI ファクトリーは、Claude Code プロジェクトを設定するためのツールです。テクノロジー スタックの分析、スキルのインストール、セキュリティ スキャンなど AI 팩토리는 Claude Code 프로젝트를 설정하는 데 사용되는 도구입니다. 기술 스택 분석, 스킬 설치, 보안 스캔 등 ai-factory es una herramienta para desarrolladores que permite configurar proyectos con tecnologías avanzadas, incluyendo análisis de tecnología y generación de habilidades personalizadas ai-factory est un outil pour les développeurs qui permet de configurer des projets avec des technologies avancées, y compris l''analyse de la technologie et la génération de compétences personnalisées ai-factory ist ein Tool für Entwickler, das die Konfiguration von Projekten mit fortschrittlichen Technologien ermöglicht, einschließlich Technologieanalyse und Generierung von benutzerdefinierten Fähigkeiten O ai-factory é uma ferramenta para configurar projetos de IA, permitindo análise de pilha de tecnologia e geração de habilidades personalizadas. ai-factory - это инструмент для настройки проектов ИИ Агентов, позволяющий анализировать технологический стек и генерировать пользовательские навыки. ai-factory هو أداة لتهيئة مشاريع ادوات الذكاء الاصطناعي، مما يسمح بتحليل حزمة التكنولوجيا وتوليد المهارات المخصصة. how to use ai-factory ai-factory setup guide ai-factory vs claude code ai-factory install what is ai-factory ai-factory skill generator ai-factory security scanning ai-factory project setup ai-factory alternative AI 工厂 Claude Code 技术栈分析 技能安装 安全扫描 AI 项目配置 AI 工具 Analyzes the tech stack for project setup Installs skills from skills.sh Generates custom skills via /ai-factory.skill-generator Configures MCP servers for external integrations Scans for prompt injection security vulnerabilities ai-factory is a skill that facilitates the setup and configuration of Claude Code for AI agent projects, including analyzing tech stacks and generating custom skills.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('sethdavis512/iridium-tambo/build-with-tambo', 'community', 'sethdavis512', 'iridium-tambo', 'sethdavis512/iridium-tambo', 'build-with-tambo', 0, 0, 45, '2026-03-06T01:49:45Z', '2026-03-07T04:19:43.957Z', '0ccfae810d51562db99c41bf4379a78e0a7c3cb393ae41f5e24a848b71dc9765', '{"id":"sethdavis512/iridium-tambo/build-with-tambo","name":"build-with-tambo","description":{"en":"build-with-tambo detects the tech stack and integrates Tambo, preserving existing patterns. It benefits developers who need to implement Tambo components and manage threads and input.","zh":"Build with Tambo 是一个检测技术栈并集成 Tambo 的工具，保留现有模式","ja":"Build with Tambo は、Tambo を統合し、既存のパターンを保持するためのテクノロジースタック検出ツールです","ko":"Build with Tambo는 기술 스택을检测하고 Tambo를 통합하며 기존 패턴을 유지하는 도구입니다","es":"Build with Tambo es una herramienta que permite detectar el stack tecnológico y integrar Tambo preservando patrones existentes","fr":"Build with Tambo est un outil qui permet de détecter le stack technologique et d''intégrer Tambo en préservant les modèles existants","de":"Build with Tambo ist ein Tool, das die Erkennung des Technologie-Stacks und die Integration von Tambo unter Beibehaltung bestehender Muster ermöglicht","pt":"O Build with Tambo é uma habilidade que permite detectar o tech stack e integrar o Tambo de forma eficaz, preservando padrões existentes.","ru":"Build with Tambo - это навык, который позволяет обнаруживать tech stack и интегрировать Tambo, сохраняя существующие паттерны, с помощью ИИ Агентов","ar":"Build with Tambo هو مهارة تمكنك من الكشف عن حزمة التقنيات ودمج Tambo بطريقة فعالة، مع الحفاظ على الأنماط الحالية باستخدام أدوات الإي أيه"},"seo":{"title":{"en":"build-with-tambo: Integration Setup Guide | AI Agent Skill","zh":"Build with Tambo Setup Guide - AIエージェント集成","ja":"Build with Tambo ベストプラクティス - AIエージェント","ko":"Build with Tambo 시작하기 - AI 에이전트 통합","es":"Guía de configuración de Build with Tambo para desarrolla...","fr":"Guide de mise en place de Build with Tambo pour les dével...","de":"Setup-Anleitung für Build with Tambo-Entwickler","pt":"Guia de Configuração do Build with Tambo para Desenvolved...","ru":"Настройка Build with Tambo: ИИ Агенты для Разработчиков","ar":"دليل إعداد Build with Tambo للبرمجة مع أدوات الإي أيه"},"description":{"en":"Discover how to integrate Tambo into your existing tech stack while preserving patterns. Learn more about build-with-tambo and get started today!","zh":"了解 Build with Tambo 的技术细节，包括组件、渲染和线程管理，快速集成 Tambo","ja":"Build with Tambo の詳細を確認し、Tambo を効率的に統合する方法を学びましょう","ko":"Build with Tambo에 대한 기술 정보를 확인하고 Tambo 통합을 시작하세요","es":"Descubre cómo integrar Tambo en tu proyecto y aprovecha sus componentes y capacidades de renderizado","fr":"Découvrez comment intégrer Tambo dans votre projet et profitez de ses composants et capacités de rendu","de":"Erfahren Sie, wie Sie Tambo in Ihr Projekt integrieren und seine Komponenten und Renderfunktionen nutzen","pt":"Aprenda a integrar o Tambo no seu tech stack, preservando padrões existentes e melhorando a eficiência do desenvolvimento","ru":"Узнайте, как интегрировать Tambo в ваш tech stack, сохраняя существующие паттерны и повышая эффективность разработки с помощью ИИ Агентов","ar":"اكتشف كيفية دمج Tambo في حزمة تقنياتك، مع الحفاظ على الأنماط الحالية وتحسين كفاءة التطوير باستخدام أدوات الإي أيه"},"definition":{"en":"build-with-tambo is a skill that enables the integration of Tambo into existing tech stacks, allowing for the creation and registration of Tambo components.","zh":"Build with Tambo 是一种 AI 工具，用于检测和集成 Tambo","ja":"Build with Tambo は、Tambo を検出して統合する AI エージェントです","ko":"Build with Tambo는 Tambo를 감지하고 통합하는 AI 에이전트입니다","es":"Build with Tambo es una herramienta de integración de AI que detecta el stack tecnológico y permite la creación de componentes","fr":"Build with Tambo est un outil d''intégration d''IA qui détecte le stack technologique et permet la création de composants","de":"Build with Tambo ist ein AI-Integrationstool, das den Technologie-Stack erkennt und die Erstellung von Komponenten ermöglicht","pt":"O que é Build with Tambo? É uma habilidade que facilita a integração do Tambo no desenvolvimento de software","ru":"Что такое Build with Tambo? Это навык, который облегчает интеграцию Tambo в разработку программного обеспечения с помощью ИИ Агентов","ar":"ما هو Build with Tambo؟ إنه مهارة تسهل دمج Tambo في تطوير البرمجيات باستخدام أدوات الإي أيه"},"features":{"en":["Creates and registers Tambo components, including generative and interactable components","Handles streaming props, loading states, and persistent component state through component rendering","Manages threads and input using the threads and input reference guide","Provides reference guides for deeper implementation details, including components and component rendering","Supports the preservation of existing patterns in the tech stack"],"zh":["组件创建和注册","渲染处理，包括流媒体道具和加载状态","线程和输入管理","支持生成式和交互式组件","保留现有模式"],"ja":["コンポーネントの作成と登録","レンダリングの処理、包括ストリーミング プロップとロード状態","スレッドと入力の管理","生成型とインタラクティブなコンポーネントのサポート","既存のパターンの保持"],"ko":["컴포넌트 생성 및 등록","렌더링 처리, 포함 스트리밍 속성 및 로드 상태","스레드 및 입력 관리","생성 및 상호 작용 컴포넌트 지원","기존 패턴 유지"],"es":["Detección de stack tecnológico","Integración de Tambo con patrones existentes","Creación y registro de componentes generativos e interactivos","Gestión de estados de carga y renderizado de componentes","Manejo de hilos y entrada de datos"],"fr":["Détection du stack technologique","Intégration de Tambo avec des modèles existants","Création et enregistrement de composants génératifs et interactifs","Gestion des états de chargement et de rendu des composants","Gestion des threads et de l''entrée de données"],"de":["Erkennung des Technologie-Stacks","Integration von Tambo mit bestehenden Mustern","Erstellung und Registrierung von generativen und interaktiven Komponenten","Verwaltung von Ladezuständen und Renderfunktionen von Komponenten","Verwaltung von Threads und Dateneingabe"],"pt":["Detecção de tech stack","Integração do Tambo com preservação de padrões existentes","Criação e registro de componentes do Tambo","Gerenciamento de threads e entrada","Renderização de componentes com streaming de props e estados de carregamento"],"ru":["Обнаружение tech stack","Интеграция Tambo с сохранением существующих паттернов","Создание и регистрация компонентов Tambo","Управление потоками и вводом","Рендеринг компонентов со стримингом пропсов и состояний загрузки с помощью ИИ Агентов"],"ar":["كشف حزمة التقنيات","دمج Tambo مع الحفاظ على الأنماط الحالية","إنشاء وتسجيل مكونات Tambo","إدارة الخيوط والمدخلات","تجسيد المكونات مع بث الخصائص و states التحميل باستخدام أدوات الإي أيه"]},"keywords":{"en":["how to use build-with-tambo","build-with-tambo alternative","build-with-tambo setup guide","what is build-with-tambo","build-with-tambo vs other integration tools","build-with-tambo install","integrating Tambo into existing tech stacks","Tambo component creation","build-with-tambo documentation"],"zh":["Build with Tambo","AIエージェント","Tambo 集成","组件创建","渲染处理","线程管理","AI 工具"],"ja":["Build with Tambo","AIエージェント","Tambo 統合","コンポーネントの作成","レンダリングの処理","スレッドの管理","AI ツール"],"ko":["Build with Tambo","AI 에이전트","Tambo 통합","컴포넌트 생성","렌더링 처리","스레드 관리","AI 도구"],"es":["build with tambo","integración de AI","detección de stack tecnológico","componentes generativos","renderizado de componentes","hilos y entrada de datos","desarrollo de software","herramientas de desarrollo"],"fr":["build with tambo","intégration d''IA","détection du stack technologique","composants génératifs","rendu de composants","threads et entrée de données","développement de logiciels","outils de développement"],"de":["build with tambo","AI-Integration","Erkennung des Technologie-Stacks","generative Komponenten","Renderfunktionen von Komponenten","Threads und Dateneingabe","Software-Entwicklung","Entwicklungstools"],"pt":["build with tambo","integração do tambo","tech stack","desenvolvimento de software","componentes do tambo","gerenciamento de threads","renderização de componentes"],"ru":["build with tambo","интеграция tambo","tech stack","разработка программного обеспечения","компоненты tambo","управление потоками","рендеринг компонентов","ИИ Агенты"],"ar":["build with tambo","دمج tambo","حزمة التقنيات","تطوير البرمجيات","مكونات tambo","إدارة الخيوط","تجسيد المكونات","أدوات الإي أيه"]}},"owner":"sethdavis512","repo":"iridium-tambo","repoPath":"sethdavis512/iridium-tambo","stars":0,"forks":0,"updatedAt":"2026-03-06T01:49:45Z","topics":[],"category":"community","skillMd":{"name":"build-with-tambo","description":"Build with Tambo in an existing React app. Use for existing codebases (providers, env vars, components, threads, tools). For brand-new apps, use generative-ui.","bodyPreview":"# Build with Tambo\n\nDetect tech stack and integrate Tambo while preserving existing patterns.\n\n## Reference Guides\n\nUse these guides when you need deeper implementation details for a specific area:\n\n- [Components](references/components.md) - Create and register Tambo components (generative and interactable).\n- [Component Rendering](references/component-rendering.md) - Handle streaming props, loading states, and persistent component state.\n- [Threads and Input](references/threads.md) - Manage con","body":"# Build with Tambo\n\nDetect tech stack and integrate Tambo while preserving existing patterns.\n\n## Reference Guides\n\nUse these guides when you need deeper implementation details for a specific area:\n\n- [Components](references/components.md) - Create and register Tambo components (generative and interactable).\n- [Component Rendering](references/component-rendering.md) - Handle streaming props, loading states, and persistent component state.\n- [Threads and Input](references/threads.md) - Manage conversations, suggestions, voice input, image attachments, and thread switching.\n- [Tools and Context](references/tools-and-context.md) - Add custom tools, MCP servers, context helpers, and resources.\n- [CLI Reference](references/cli.md) - Use `tambo init`, `tambo add`, and `create-app` with non-interactive flags and exit codes.\n- [Add Components to Registry](references/add-components-to-registry.md) - Convert existing React components into Tambo-ready registrations with schemas and descriptions.\n\nThese references are duplicated across both skills so each skill works independently.\n\n## Workflow\n\n1. **Detect tech stack** - Analyze package.json and project structure\n2. **Confirm with user** - Present findings, ask about preferences\n3. **Install dependencies** - Add @tambo-ai/react and peer deps\n4. **Create provider setup** - Adapt to existing patterns\n5. **Register first component** - Demonstrate with existing component\n\n## Step 1: Detect Tech Stack\n\nCheck these files to understand the project:\n\n```bash\n# Key files to read\npackage.json           # Dependencies and scripts\ntsconfig.json          # TypeScript config\nnext.config.*          # Next.js\nvite.config.*          # Vite\ntailwind.config.*      # Tailwind CSS\npostcss.config.*       # PostCSS\nsrc/index.* or app/    # Entry points\n```\n\n### Detection Checklist\n\n| Technology       | Detection                                         |\n| ---------------- | ------------------------------------------------- |\n| Next.js          | `next` in dependencies, `next.config.*` exists    |\n| Vite             | `vite` in devDependencies, `vite.config.*` exists |\n| Create React App | `react-scripts` in dependencies                   |\n| TypeScript       | `typescript` in deps, `tsconfig.json` exists      |\n| Tailwind         | `tailwindcss` in deps, config file exists         |\n| Plain CSS        | No Tailwind, CSS files in src/                    |\n| Zod              | `zod` in dependencies                             |\n| Other validation | `yup`, `joi`, `superstruct` in deps               |\n\n## Step 2: Confirm with User\n\nPresent findings and ask:\n\n```\nI detected your project uses:\n- Framework: Next.js 14 (App Router)\n- Styling: Tailwind CSS\n- Validation: No Zod (will need to add)\n- TypeScript: Yes\n\nShould I:\n1. Install Tambo with these settings?\n2. Use plain CSS instead of Tailwind for Tambo components?\n3. Something else?\n```\n\n## Step 3: Install Dependencies\n\n```bash\n# Core (always required)\nnpm install @tambo-ai/react\n\n# If no Zod installed\nnpm install zod\n```\n\n## Step 4: Create Provider Setup\n\n### Next.js App Router\n\n```tsx\n// app/providers.tsx\n\"use client\";\nimport { TamboProvider } from \"@tambo-ai/react\";\nimport { components } from \"@/lib/tambo\";\n\nexport function Providers({ children }: { children: React.ReactNode }) {\n  return (\n    <TamboProvider\n      apiKey={process.env.NEXT_PUBLIC_TAMBO_API_KEY}\n      components={components}\n    >\n      {children}\n    </TamboProvider>\n  );\n}\n```\n\n```tsx\n// app/layout.tsx\nimport { Providers } from \"./providers\";\n\nexport default function RootLayout({ children }) {\n  return (\n    <html>\n      <body>\n        <Providers>{children}</Providers>\n      </body>\n    </html>\n  );\n}\n```\n\n### Next.js Pages Router\n\n```tsx\n// pages/_app.tsx\nimport { TamboProvider } from \"@tambo-ai/react\";\nimport { components } from \"@/lib/tambo\";\n\nexport default function App({ Component, pageProps }) {\n  return (\n    <TamboProvider\n      apiKey={process.env.NEXT_PUBLIC_TAMBO_API_KEY}\n      components={components}\n    >\n      <Component {...pageProps} />\n    </TamboProvider>\n  );\n}\n```\n\n### Vite / CRA\n\n```tsx\n// src/main.tsx\nimport { TamboProvider } from \"@tambo-ai/react\";\nimport { components } from \"./lib/tambo\";\nimport App from \"./App\";\n\nReactDOM.createRoot(document.getElementById(\"root\")!).render(\n  <TamboProvider\n    apiKey={import.meta.env.VITE_TAMBO_API_KEY}\n    components={components}\n  >\n    <App />\n  </TamboProvider>,\n);\n```\n\n## Step 5: Create Component Registry\n\n```tsx\n// lib/tambo.ts (or src/lib/tambo.ts)\nimport { TamboComponent } from \"@tambo-ai/react\";\n\nexport const components: TamboComponent[] = [\n  // Components will be registered here\n];\n```\n\n## Adapting to Existing Patterns\n\n### No Tailwind? Use Plain CSS\n\nIf project uses plain CSS or CSS modules, Tambo components can be styled differently:\n\n```tsx\n// Skip --yes flag to customize styling during add\nnpx tambo add message-thread-full\n# Select \"CSS Modules\" or \"Plain CSS\" when prompted\n```\n\n### Existing Validation Library?\n\nIf using Yup/Joi instead of Zod, user can either:\n\n1. Add Zod just for Tambo schemas (recommended - small addition)\n2. Convert schemas (more work, not recommended)\n\n### Monorepo?\n\nRun commands from the package that will use Tambo:\n\n```bash\ncd packages/web\nnpx tambo init --api-key=sk_...\n```\n\n## Environment Variables\n\n`npx tambo init --api-key=sk_...` automatically creates `.env.local` with the correct env var for your framework.\n\nIf manual setup is needed (monorepo, read-only filesystem), add the appropriate variable:\n\n| Framework | Variable                    |\n| --------- | --------------------------- |\n| Next.js   | `NEXT_PUBLIC_TAMBO_API_KEY` |\n| Vite      | `VITE_TAMBO_API_KEY`        |\n| CRA       | `REACT_APP_TAMBO_API_KEY`   |\n\n## Verification\n\nAfter setup, verify by creating a simple test:\n\n```tsx\nimport { useTambo } from \"@tambo-ai/react\";\n\nfunction TestComponent() {\n  const { thread, isIdle } = useTambo();\n  console.log(\"Tambo connected:\", isIdle);\n  return <div>Tambo is set up!</div>;\n}\n```\n"},"lastSynced":"2026-03-07T04:19:43.957Z","agentAnalysis":{"suitability":{"en":"Perfect for Frontend Agents needing seamless Tambo integration and thread management.","zh":"非常适合需要无缝集成Tambo和线程管理的前端代理。","ja":"Tamboのシームレスな統合とスレッド管理が必要なフロントエンドエージェントに最適です。","ko":"Tambo를無縫的に統合하고 스레드 관리가 필요한 프론트엔드 에이전트에 적합합니다.","es":"Perfecto para agentes Frontend que necesitan una integración sin problemas con Tambo y gestión de hilos.","fr":"Parfait pour les agents Frontend qui nécessitent une intégration transparente avec Tambo et une gestion de threads.","de":"Perfekt für Frontend-Agents, die eine nahtlose Tambo-Integration und Thread-Verwaltung benötigen.","pt":"Perfeito para Agentes Frontend que necessitam de integração perfeita do Tambo e gerenciamento de threads.","ru":"Идеально для агентов Frontend, которым требуется бесшовная интеграция Tambo и управление потоками.","ar":"مثالي لعميل واجهة المستخدم الذي يحتاج إلى دمج Tambo متكامل وإدارة خيوط متواصلة."},"recommendation":{"en":"Empowers agents to detect tech stacks and integrate Tambo components while preserving existing patterns, handling streaming props, loading states, and persistent component state using threads and input management.","zh":"赋予代理检测技术栈和集成Tambo组件的能力，同时保留现有的模式，处理流媒体属性、加载状态和使用线程和输入管理的持久组件状态。","ja":"エージェントにテクノロジースタックを検出してTamboコンポーネントを統合する能力を与え、既存のパターンを保持しながら、ストリーミングプロパティ、ロード状態、スレッドと入力管理を使用した持続的なコンポーネント状態を処理する。","ko":"에이전트가 기술 스택을検출하고 Tambo 컴포넌트를 통합하는 기능을 제공하며, 기존 패턴을 유지하면서, 스트리밍 속성, 로드 상태 및 스레드와 입력 관리를 사용하여 지속적인 컴포넌트 상태를 처리합니다.","es":"Habilita a los agentes a detectar pilas de tecnología e integrar componentes de Tambo mientras preserva los patrones existentes, maneja propiedades de flujo, estados de carga y estado de componente persistente utilizando hilos y administración de entrada.","fr":"Permet aux agents de détecter les piles technologiques et d''intégrer les composants Tambo tout en préservant les modèles existants, en gérant les propriétés de flux, les états de chargement et l''état de composant persistant à l''aide de threads et de gestion d''entrée.","de":"Ermöglicht es Agenten, Technologie-Stacks zu erkennen und Tambo-Komponenten zu integrieren, während bestehende Muster erhalten bleiben, Streaming-Eigenschaften, Ladezustände und persistenten Komponentenzustand mithilfe von Threads und Eingabe-Verwaltung gehandhabt werden.","pt":"Habilita os agentes a detectar pilhas de tecnologia e integrar componentes do Tambo, preservando padrões existentes, lidando com propriedades de transmissão, estados de carregamento e estado de componentes persistentes usando threads e gerenciamento de entrada.","ru":"Наделяет агентов возможностью обнаруживать технологические стеки и интегрировать компоненты Tambo, сохраняя существующие закономерности, обрабатывая потоковые свойства, состояния загрузки и постоянное состояние компонентов с помощью потоков и управления вводом.","ar":"يمكن الوكيل من اكتشاف كتل التقنية وتكامل مكونات Tambo مع الحفاظ على الأنماط الحالية، ومعالجة خصائص البث، وحالات التحميل، و状态 المكونات الثابتة باستخدام الخيوط وإدارة الإدخال."},"useCases":{"en":["Integrating Tambo components into existing projects","Managing threads and input for efficient rendering","Implementing generative and interactable components"],"zh":["将Tambo组件集成到现有项目中","管理线程和输入以实现高效渲染","实现生成和交互式组件"],"ja":["既存のプロジェクトにTamboコンポーネントを統合する","スレッドと入力を管理して効率的なレンダリングを実現する","生成可能なコンポーネントとインタラクティブなコンポーネントを実装する"],"ko":["기존 프로젝트에 Tambo 컴포넌트를 통합하는こと","스레드와 입력을 관리하여 효율적인 렌더링을實現하는こと","생성 가능한 컴포넌트와 상호 작용 가능한 컴포넌트를 구현하는こと"],"es":["Integrar componentes de Tambo en proyectos existentes","Administrar hilos y entrada para un renderizado eficiente","Implementar componentes generativos e interactuables"],"fr":["Intégrer les composants Tambo dans les projets existants","Gérer les threads et les entrées pour un rendu efficace","Mettre en œuvre des composants génératifs et interactifs"],"de":["Tambo-Komponenten in bestehenden Projekten integrieren","Threads und Eingabe für ein effizientes Rendering verwalten","Generative und interaktive Komponenten implementieren"],"pt":["Integrar componentes do Tambo em projetos existentes","Gerenciar threads e entrada para renderização eficiente","Implementar componentes generativos e interativos"],"ru":["Интегрировать компоненты Tambo в существующие проекты","Управлять потоками и входными данными для эффективного рендеринга","Реализовать генеративные и интерактивные компоненты"],"ar":["دمج مكونات Tambo في مشاريع موجودة","إدارة الخيوط والإدخال من أجل تقديم العرض الفعال","تنفيذ المكونات التوليدية والتفاعلية"]},"limitations":{"en":["Requires Tambo compatibility","Preserves existing patterns only"],"zh":["需要Tambo兼容性","仅保留现有的模式"],"ja":["Tamboの互換性が必要","既存のパターンだけを保持する"],"ko":["Tambo의 호환성이 필요","기존 패턴만을 유지"],"es":["Requiere compatibilidad con Tambo","Preserva solo los patrones existentes"],"fr":["Nécessite la compatibilité avec Tambo","Présève uniquement les modèles existants"],"de":["Benötigt Tambo-Kompatibilität","Bewahrt nur bestehende Muster"],"pt":["Exige compatibilidade com o Tambo","Preserva padrões existentes apenas"],"ru":["Требует совместимости с Tambo","Сохраняет только существующие закономерности"],"ar":["يتطلب توافقًا مع Tambo","تحافظ على الأنماط الحالية فقط"]},"version":4},"contentHash":"0ccfae810d51562db99c41bf4379a78e0a7c3cb393ae41f5e24a848b71dc9765","qualityScore":45}');
