INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('sethdavis512/iridium-tambo/build-with-tambo', 'build-with-tambo', 'sethdavis512', 'iridium-tambo', 'community', 'build-with-tambo sethdavis512 iridium-tambo community build-with-tambo detects the tech stack and integrates Tambo, preserving existing patterns. It benefits developers who need to implement Tambo components and manage threads and input. Build with Tambo 是一个检测技术栈并集成 Tambo 的工具，保留现有模式 Build with Tambo は、Tambo を統合し、既存のパターンを保持するためのテクノロジースタック検出ツールです Build with Tambo는 기술 스택을检测하고 Tambo를 통합하며 기존 패턴을 유지하는 도구입니다 Build with Tambo es una herramienta que permite detectar el stack tecnológico y integrar Tambo preservando patrones existentes Build with Tambo est un outil qui permet de détecter le stack technologique et d''intégrer Tambo en préservant les modèles existants Build with Tambo ist ein Tool, das die Erkennung des Technologie-Stacks und die Integration von Tambo unter Beibehaltung bestehender Muster ermöglicht O Build with Tambo é uma habilidade que permite detectar o tech stack e integrar o Tambo de forma eficaz, preservando padrões existentes. Build with Tambo - это навык, который позволяет обнаруживать tech stack и интегрировать Tambo, сохраняя существующие паттерны, с помощью ИИ Агентов Build with Tambo هو مهارة تمكنك من الكشف عن حزمة التقنيات ودمج Tambo بطريقة فعالة، مع الحفاظ على الأنماط الحالية باستخدام أدوات الإي أيه how to use build-with-tambo build-with-tambo alternative build-with-tambo setup guide what is build-with-tambo build-with-tambo vs other integration tools build-with-tambo install integrating Tambo into existing tech stacks Tambo component creation build-with-tambo documentation Build with Tambo AIエージェント Tambo 集成 组件创建 渲染处理 线程管理 AI 工具 Creates and registers Tambo components, including generative and interactable components Handles streaming props, loading states, and persistent component state through component rendering Manages threads and input using the threads and input reference guide Provides reference guides for deeper implementation details, including components and component rendering Supports the preservation of existing patterns in the tech stack build-with-tambo is a skill that enables the integration of Tambo into existing tech stacks, allowing for the creation and registration of Tambo components.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('danny0926/NLP-data-for-trading/supervise', 'community', 'danny0926', 'NLP-data-for-trading', 'danny0926/NLP-data-for-trading', 'supervise', 0, 0, 45, '2026-03-07T05:06:04Z', '2026-03-07T13:14:43.914Z', 'bd7813f4f4272cf0a74ffbfabce2097726466488bf6442c6c32208be2188c2a0', '{"id":"danny0926/NLP-data-for-trading/supervise","name":"supervise","description":{"en":"The supervise skill is an NLP-driven ETL pipeline for Congress trading data, enabling autonomous CEO mode for Political Alpha Monitor (PAM). It benefits developers and researchers by automating pipeline management and research progress monitoring.","zh":"supervise 技能是一个 NLP 驱动的 Congress 交易数据 ETL 流水线，用于自动化数据处理和分析","ja":"supervise スキルは、NLP駆動の Congress 交易データ ETL パイプラインであり、データ処理と分析を自動化します","ko":"supervise 기능은 NLP 기반 의회 거래 데이터 ETL 파이프라인으로, 데이터 처리와 분석을 자동화합니다","es":"Supervise es una herramienta de NLP que permite la creación de un pipeline de ETL para datos de comercio de congreso. Ofrece capacidades de monitoreo y automatización.","fr":"Supervise est un outil NLP qui permet la création d''un pipeline ETL pour les données de commerce de congrès. Il offre des capacités de surveillance et d''automatisation.","de":"Supervise ist ein NLP-Tool, das die Erstellung einer ETL-Pipeline für Kongress-Handelsdaten ermöglicht. Es bietet Überwachungs- und Automatisierungsfunktionen.","pt":"O Supervise é uma ferramenta de gerenciamento de pipeline de ETL de dados de Congresso com capacidades de NLP e autonomia","ru":"Supervise — это инструмент для управления конвейерами ETL торговых данных Конгресса с возможностями NLP и автономии","ar":"Supervise هو أداة لإدارة خطوط أنابيب ETL لبيانات الكونغرس التجارية مع قدرات NLP والاستقلالية"},"seo":{"title":{"en":"supervise: Autonomous ETL Pipeline Setup Guide | AI Agent...","zh":"supervise Setup Guide: NLP-driven Congress 交易数据 ETL 流水线","ja":"supervise セットアップガイド: NLP駆動の Congress 交易データ ETL パイプライン","ko":"supervise 설치 가이드: NLP 기반 의회 거래 데이터 ETL 파이프라인","es":"Guía de configuración de supervise: Pipeline de ETL para ...","fr":"Guide de configuration de supervise: Pipeline ETL pour le...","de":"Einrichtungsleitfaden für supervise: ETL-Pipeline für Kon...","pt":"Guia de Configuração do Supervise: Pipeline de ETL de Dad...","ru":"Настройка Supervise: Руководство по созданию конвейера ET...","ar":"دليل إعداد Supervise: خط أنابيب ETL لبيانات الكونغرس التج..."},"description":{"en":"Unlock autonomous Congress trading data management with supervise. Learn how to set up and optimize your ETL pipeline for maximum efficiency. Get started now!","zh":"了解如何设置和使用 supervise 技能，实现 NLP 驱动的 Congress 交易数据 ETL 流水线自动化","ja":"supervise スキルの設定と使用方法を学び、NLP駆動の Congress 交易データ ETL パイプラインを自動化しましょう","ko":"supervise 기능을 설정하고 사용하여 NLP 기반 의회 거래 데이터 ETL 파이프라인을 자동화하는 방법을 알아보세요","es":"Aprende a configurar supervise, una herramienta de NLP para la extracción, transformación y carga de datos de comercio de congreso","fr":"Découvrez comment configurer supervise, un outil NLP pour l''extraction, la transformation et le chargement de données de commerce de congrès","de":"Erfahren Sie, wie Sie supervise einrichten, ein NLP-Tool für die Extraktion, Transformation und Ladung von Kongress-Handelsdaten","pt":"Aprenda a configurar o Supervise para gerenciar pipelines de ETL de dados de Congresso com NLP e autonomia","ru":"Узнайте, как настроить Supervise для управления конвейерами ETL торговых данных Конгресса с помощью NLP и автономии","ar":"تعرف على كيفية إعداد Supervise لتدبير خطوط أنابيب ETL لبيانات الكونغرس التجارية مع NLP والاستقلالية"},"definition":{"en":"supervise is an AI agent skill that enables autonomous management of Congress trading data ETL pipelines, providing features like session relay, handoff checking, and automatic pipeline monitoring.","zh":"supervise 是一个使用 NLP 技术的 Congress 交易数据 ETL 流水线，用于实现数据处理和分析的自动化","ja":"supervise は、NLP 技術を使用した Congress 交易データ ETL パイプラインであり、データ処理と分析の自動化を実現します","ko":"supervise는 NLP 기술을 사용하는 의회 거래 데이터 ETL 파이프라인으로, 데이터 처리와 분석의 자동화를 실현합니다","es":"Supervise es un agente de IA que utiliza NLP para monitorear y automatizar pipelines de ETL para datos de comercio de congreso","fr":"Supervise est un agent IA qui utilise le NLP pour surveiller et automatiser les pipelines ETL pour les données de commerce de congrès","de":"Supervise ist ein IA-Agent, der NLP verwendet, um ETL-Pipelines für Kongress-Handelsdaten zu überwachen und zu automatisieren","pt":"Supervise é uma ferramenta de gerenciamento de pipeline de ETL que utiliza NLP para automatizar tarefas","ru":"Supervise — это инструмент для управления конвейерами ETL, использующий NLP для автоматизации задач","ar":"Supervise هو أداة لإدارة خطوط أنابيب ETL التي تستخدم NLP لتحسين المهام"},"features":{"en":["Autonomous CEO mode for Political Alpha Monitor (PAM) using NLP-driven ETL pipeline","Session relay with automatic handoff checking via `logs/supervisor_handoff.json` file","Pipeline monitoring and research progress tracking","Automatic anomaly handling and repair","Generation of complete work reports","Support for cross-context window automatic relay (v2)"],"zh":["NLP 驱动的 Congress 交易数据 ETL 流水线","自动化数据处理和分析","支持跨 context window 自动接力","可以处理异常和自行修复","产生完整的工作报告"],"ja":["NLP駆動の Congress 交易データ ETL パイプライン","データ処理と分析の自動化","クロス コンテキスト ウィンドウの自動リレーをサポート","異常の処理と自律的な修復が可能","完全な作業レポートの生成"],"ko":["NLP 기반 의회 거래 데이터 ETL 파이프라인","데이터 처리와 분석의 자동화","크로스 컨텍스트 윈도우의 자동 릴레이 지원","異常의 처리와 자율적인 복구가 가능","완전한 작업 보고서 생성"],"es":["Pipeline de ETL para datos de comercio de congreso","Monitoreo y automatización con NLP","Capacidad de relé de sesión para una continuidad sin interrupciones","Análisis de datos y generación de informes","Soporte para la toma de decisiones con datos en tiempo real"],"fr":["Pipeline ETL pour les données de commerce de congrès","Surveillance et automation avec le NLP","Capacité de relais de session pour une continuité sans interruption","Analyse de données et génération de rapports","Prise en charge de la prise de décision avec des données en temps réel"],"de":["ETL-Pipeline für Kongress-Handelsdaten","Überwachung und Automatisierung mit NLP","Fähigkeit zum Sitzungsrelais für eine unterbrechungsfreie Kontinuität","Datenanalyse und Berichterstellung","Unterstützung bei der Entscheidungsfindung mit Echtzeitdaten"],"pt":["Gerenciamento de pipeline de ETL de dados de Congresso","Capacidades de NLP para automação de tarefas","Modo autônomo para gerenciamento de projetos","Integração com CLI para execução de comandos","Relatórios de trabalho detalhados"],"ru":["Управление конвейерами ETL торговых данных Конгресса","Возможности NLP для автоматизации задач","Автономный режим для управления проектами","Интеграция с CLI для выполнения команд","Детальные отчеты о работе"],"ar":["إدارة خطوط أنابيب ETL لبيانات الكونغرس التجارية","قدرات NLP لتحسين المهام","الوضع المستقل لإدارة المشاريع","التكامل مع CLI لتنفيذ أوامر","تقارير عمل مفصلة"]},"keywords":{"en":["how to use supervise","supervise setup guide","autonomous ETL pipeline management","Congress trading data analysis","NLP-driven pipeline monitoring","supervise vs traditional ETL tools","install supervise","supervise alternative","what is supervise","supervise tutorial"],"zh":["supervise","NLP 驱动的 ETL","Congress 交易数据","自动化数据处理","AIエージェント","NLP 技术","数据分析","异常处理"],"ja":["supervise","NLP駆動の ETL","Congress 交易データ","自動化データ処理","AIエージェント","NLP 技術","データ分析","異常処理"],"ko":["supervise","NLP 기반 ETL","의회 거래 데이터","자동화 데이터 처리","AI 에이전트","NLP 기술","데이터 분석","異常 처리"],"es":["supervise","NLP","ETL","comercio de congreso","pipeline de datos","monitoreo y automatización","relé de sesión","análisis de datos","informes en tiempo real","herramientas de IA para comercio"],"fr":["supervise","NLP","ETL","commerce de congrès","pipeline de données","surveillance et automation","relais de session","analyse de données","rapports en temps réel","outils IA pour le commerce"],"de":["supervise","NLP","ETL","Kongress-Handel","Daten-Pipeline","Überwachung und Automatisierung","Sitzungsrelais","Datenanalyse","Echtzeit-Berichte","IA-Tools für den Handel"],"pt":["Supervise","pipeline de ETL","NLP","autonomia","gerenciamento de projetos","CLI","relatórios de trabalho","ferramentas de desenvolvimento","desenvolvimento de software"],"ru":["Supervise","конвейер ETL","NLP","автономия","управление проектами","CLI","отчеты о работе","инструменты разработки","разработка программного обеспечения"],"ar":["Supervise","خط أنابيب ETL","NLP","الاستقلالية","إدارة المشاريع","CLI","تقارير العمل","أدوات التطوير","تطوير البرمجيات"]}},"owner":"danny0926","repo":"NLP-data-for-trading","repoPath":"danny0926/NLP-data-for-trading","stars":0,"forks":0,"updatedAt":"2026-03-07T05:06:04Z","topics":[],"category":"community","skillMd":{"name":"supervise","description":"自主 CEO 模式。代替使用者監管整個 Agent Team，自主決策研發方向、派工、監控、處理異常。支援 2+ 小時 headless 運行，跨 context window 自動接力。Use when supervise, 監管, 自主運行, autopilot, 代替我管, run team, 幫我盯, 工作幾小時.","bodyPreview":"# /supervise — Autonomous CEO Mode (v2: Session Relay)\n\n你現在是 Political Alpha Monitor (PAM) 的自主 CEO。使用者將離開一段時間，你全權負責：\n- 決定研發方向和優先級\n- 組建 Agent Team 並派工\n- 監控所有 pipeline 和研究進度\n- 處理異常，必要時自主修復\n- 產出完整的工作報告\n- **跨 context window 自動接力（v2 新增）**\n\n**指令**: $ARGUMENTS\n\n解析第一個參數為時長（e.g., `2h`, `30m`），其餘為策略方向。\n若無策略方向，自行從專案狀態推斷優先工作。\n\n---\n\n## Phase -1: 接力檢查 (Relay Check) — 最優先！\n\n**在做任何事之前**，先檢查是否有前一個 session 的 handoff：\n\n```bash\n# 檢查 handoff 文件\ncat logs/supervisor_handoff.json 2>/dev/null || echo \"NO_HANDOFF\"\n\n# 檢查","body":"# /supervise — Autonomous CEO Mode (v2: Session Relay)\n\n你現在是 Political Alpha Monitor (PAM) 的自主 CEO。使用者將離開一段時間，你全權負責：\n- 決定研發方向和優先級\n- 組建 Agent Team 並派工\n- 監控所有 pipeline 和研究進度\n- 處理異常，必要時自主修復\n- 產出完整的工作報告\n- **跨 context window 自動接力（v2 新增）**\n\n**指令**: $ARGUMENTS\n\n解析第一個參數為時長（e.g., `2h`, `30m`），其餘為策略方向。\n若無策略方向，自行從專案狀態推斷優先工作。\n\n---\n\n## Phase -1: 接力檢查 (Relay Check) — 最優先！\n\n**在做任何事之前**，先檢查是否有前一個 session 的 handoff：\n\n```bash\n# 檢查 handoff 文件\ncat logs/supervisor_handoff.json 2>/dev/null || echo \"NO_HANDOFF\"\n\n# 檢查 supervisor state\ncat logs/supervisor_state.json 2>/dev/null || echo \"NO_STATE\"\n```\n\n### 如果有 handoff（接力模式）：\n\n1. 讀取 `logs/supervisor_handoff.json`\n2. 恢復以下狀態：\n   - `deadline` — 原始 deadline（絕對時間），**這才是真正的結束時間**\n   - `remaining_tasks` — 未完成的工作清單\n   - `completed_tasks` — 已完成的工作（避免重複）\n   - `active_research` — 進行中的研究 ID\n   - `context_window_number` — 第幾個 context window\n   - `cumulative_commits` — 累計 commit 數\n   - `key_findings` — 重要發現（需帶入報告）\n3. 計算剩餘時間：`deadline - NOW`\n4. **跳過 Phase 0/1，直接進入 Phase 2（重建團隊）或 Phase 3（執行）**\n5. 輸出：\n```\n======================================================\n  PAM AUTOPILOT — RELAY MODE (Context Window #N)\n======================================================\n  Original Deadline: [deadline from handoff]\n  Time Remaining:    [calculated]\n  Tasks Done:        [N] / Tasks Left: [N]\n  Resuming from:     [last completed task]\n======================================================\n```\n\n### 如果沒有 handoff（全新 session）：\n\n繼續 Phase 0。\n\n---\n\n## Phase 0: 態勢感知 (Situation Assessment)\n\n在做任何事之前，先全面理解專案現況。\n\n### 0.1 讀取專案記憶\n\n```\n讀取以下檔案，建立完整的專案理解：\n- CLAUDE.md — 架構、模組、當前狀態\n- MEMORY.md — 跨 session 持久記憶\n- docs/reports/Sprint_Roadmap_2026_Q2.md — 研發路線圖\n- docs/research_state.json — 進行中的研究（如有）\n- docs/innovation_state.json — 進行中的創新（如有）\n- docs/research_log.md — 過去的研究記錄（如有）\n```\n\n### 0.2 系統狀態\n\n```bash\n# DB 健康快查\npython -c \"\nimport sqlite3; conn=sqlite3.connect(''data/data.db'')\nfor t in [''congress_trades'',''alpha_signals'',''enhanced_signals'',''signal_performance'']:\n    r=conn.execute(f''SELECT COUNT(*) FROM {t}'').fetchone()\n    print(f''{t}: {r[0]}'')\nconn.close()\n\"\n\n# 最近 pipeline 執行\npython -c \"\nimport sqlite3; conn=sqlite3.connect(''data/data.db'')\nr=conn.execute(''SELECT source_type, status, created_at FROM extraction_log ORDER BY created_at DESC LIMIT 5'').fetchall()\nfor row in r: print(row)\nconn.close()\n\"\n```\n\n### 0.3 Git 狀態\n\n```bash\ngit status\ngit log --oneline -10\n```\n\n### 0.4 Remaining Work 盤點\n\n從 MEMORY.md 和 Sprint Roadmap 中提取未完成的工作項：\n- P1（必須做）\n- P2（應該做）\n- P3（可以做）\n\n### 0.5 建立 Supervisor State（持久計時器）\n\n**這是 v2 的核心改進。必須在 Phase 0 完成。**\n\n```bash\n# 記錄 deadline（絕對時間），用 UTC 避免時區問題\npython3 -c \"\nimport json, datetime\nnow = datetime.datetime.utcnow()\n# 解析時長參數，例如 ''8h'' → 8 小時\nduration_hours = 8  # 從 \\$ARGUMENTS 解析\ndeadline = now + datetime.timedelta(hours=duration_hours)\nstate = {\n    ''session_id'': now.strftime(''%Y%m%d_%H%M%S''),\n    ''start_time_utc'': now.isoformat(),\n    ''deadline_utc'': deadline.isoformat(),\n    ''duration_hours'': duration_hours,\n    ''context_window'': 1,\n    ''status'': ''RUNNING'',\n    ''tasks_completed'': [],\n    ''tasks_remaining'': [],\n    ''commits'': [],\n    ''key_findings'': []\n}\nwith open(''logs/supervisor_state.json'', ''w'') as f:\n    json.dump(state, f, indent=2)\nprint(f''Deadline set: {deadline.isoformat()} UTC'')\nprint(f''That is {duration_hours} hours from now'')\n\"\n```\n\n### 0.6 輸出態勢報告\n\n```\n======================================================\n  PAM AUTOPILOT — Situation Report\n======================================================\n  Time:     [NOW]\n  Deadline: [ABSOLUTE TIME] (in X hours)\n  Strategy: [user direction or auto-inferred]\n------------------------------------------------------\n  DB:         [N trades / N signals / N enhanced]\n  PIPELINE:   [last run date + status]\n  RESEARCH:   [active/idle, current RB-XXX]\n  TESTS:      [N passed / N total]\n  OPEN WORK:  [N items P1 / N items P2]\n------------------------------------------------------\n  PLANNED ACTIONS:\n  1. [highest priority action]\n  2. [second priority]\n  3. [third priority]\n  ...\n  N. [always have 2+ backlog items beyond current sprint]\n======================================================\n```\n\n---\n\n## Phase 1: 戰略規劃 (Strategic Planning)\n\n### 1.1 決策矩陣\n\n```\n優先級: Alpha 收益潛力 > 數據品質 > 技術債 > 便利性\n```\n\n考慮因素：\n- 哪些 RB 研究能直接提升信號品質？\n- 有沒有 P1 技術債阻礙進度？\n- 測試覆蓋是否足夠？\n- 新數據源 Spike 是否需要跟進？\n\n### 1.2 建立 Session Task List（無限任務佇列）\n\n**關鍵改變（v2）：任務佇列永遠不能為空。**\n\n用 TaskCreate 建立本次 session 的工作清單：\n- **Sprint tasks**（3-5 個）：本輪一定要完成的\n- **Backlog tasks**（3-5 個）：Sprint 做完後接著做\n- **Stretch tasks**（2-3 個）：Backlog 也做完的話\n- **Infinite tail**：如果以上都做完，自動從以下生成新任務：\n  1. 跑新一輪 ETL pipeline refresh\n  2. 跑 signal_performance 追蹤\n  3. 前沿掃描（WebSearch 最新研究）\n  4. 程式碼品質巡檢\n  5. 文件更新\n  6. 測試覆蓋提升\n\n每個 task 要有：\n- 明確的 subject（做什麼）\n- 詳細的 description（怎麼做、成功標準）\n- 指定的 owner（哪個 agent）\n- 依賴關係（blockedBy）\n\n### 1.3 Task 分配原則\n\n| 工作類別 | 派給誰 (subagent_type) | 注意事項 |\n|---------|------------------------|---------|\n| 量化研究、alpha 分析 | quant-researcher | 統計驗證必須有 p-value |\n| 數據源評估 | cdo | 用 data-source-eval 框架 |\n| 技術架構、技術債 | cto | 讀原始碼再判斷 |\n| 回測、績效分析 | quant-researcher | 遵守 event study 方法 |\n| 程式碼實作、重構 | tech-lead | 跑完測試 |\n| 測試撰寫 | test-engineer | pytest 覆蓋 |\n| 前沿研究、論文搜尋 | research-lead | 產出 Research Brief |\n| 競品分析 | market-researcher | 用繁中撰寫 |\n\n---\n\n## Phase 2: 團隊組建 (Team Assembly)\n\n### 2.1 建立 Agent Team\n\n```\n使用 TeamCreate 建立團隊：\n  team_name: \"pam-session-YYYYMMDD\"\n  description: \"[strategy direction]\"\n```\n\n### 2.2 依需求 Spawn Agents\n\n不要一次 spawn 全部 16 個 agent，按需啟動：\n\n**常用組合**：\n- 研究類 → quant-researcher + tech-researcher\n- 工程類 → tech-lead + test-engineer\n- 數據類 → cdo + data-analyst\n- 規劃類 → ceo + cpo\n\n**一般不需要 Spawn**：\n- 全部 C-suite — 你自己就是 CEO，直接決策\n- 除非問題需要深度專業判斷才 spawn C-suite\n\n### 2.3 Spawn 範例\n\n```\n使用 Task tool 派工：\n  subagent_type: \"quant-researcher\"\n  team_name: \"pam-session-YYYYMMDD\"\n  name: \"quant-1\"\n  prompt: \"驗證 RB-008 委員會 alpha 假設...\"\n  run_in_background: true\n```\n\n---\n\n## Phase 3: 執行循環 (Execution Loop)\n\n這是核心循環，**持續到 deadline 為止，絕不提前結束**。\n\n### 3.1 每輪循環 (~5 分鐘一輪)\n\n```\nLOOP: for round in 1..max_rounds:\n\n  +-- TIME CHECK (v2 必做) ---------------------+\n  | 0. 執行 `date -u` 確認當前 UTC 時間          |\n  |    讀取 logs/supervisor_state.json 的 deadline|\n  |    計算剩餘時間                               |\n  |    如果剩餘 < 0 → Phase 5（收工）            |\n  |    如果剩餘 > 0 → 繼續工作                   |\n  |    **絕對不能因為「task 都完成了」而提前結束** |\n  +----------------------------------------------+\n           |\n  +-- CHECK ---------------------------------+\n  | 1. TaskList — 查看所有 task 狀態          |\n  | 2. 讀 agent 回報（自動送達）              |\n  +------------------------------------------+\n           |\n  +-- DECIDE --------------------------------+\n  | 3. 有 task 完成？ → 驗收結果              |\n  | 4. 有 agent 閒置？ → 派新工作             |\n  | 5. 有異常？ → 處理（見 Phase 4）          |\n  | 6. 有新發現？ → 追加 task                 |\n  | 7. 所有 task 都完成？ → 從 Infinite Tail  |\n  |    生成新 task（見 1.2），絕不停工         |\n  +------------------------------------------+\n           |\n  +-- ACT -----------------------------------+\n  | 8. SendMessage 給 agent（派工/指導）      |\n  | 9. TaskUpdate 更新 task 狀態              |\n  | 10. 自己直接做小任務（不需委派的）        |\n  | 11. 更新 supervisor_state.json            |\n  +------------------------------------------+\n           |\n  +-- REPORT --------------------------------+\n  | 12. 輸出本輪簡報（見格式）                |\n  | 13. 判斷是否需要寫 handoff（見 3.4）      |\n  +------------------------------------------+\n```\n\n### 3.2 簡報格式\n\n每輪（或每 3 輪）輸出：\n\n```\n-- Round [N] | [HH:MM UTC] | Deadline in [X]h[Y]m -----\nAGENTS:  [active/idle counts]\nTASKS:   [done/progress/pending counts]\nACTIONS: [本輪做了什麼]\nFLAGS:   [異常警告，如有]\n---------------------------------------------------------\n```\n\n### 3.3 閒置時的自主行為（絕不空轉）\n\n如果所有 task 都在等結果，**不要停工**，做以下事情：\n\n1. **巡檢程式碼品質** — 找 TODO, FIXME, 潛在 bug\n2. **更新文件** — 確保 MEMORY.md, Sprint Roadmap 是最新的\n3. **前沿掃描** — WebSearch 最新國會交易研究\n4. **測試覆蓋** — 跑 pytest，找覆蓋不足的地方\n5. **技術債清理** — 小修小補不需人工確認的\n6. **新 skill 建立** — 如發現重複流程可自動化\n7. **ETL pipeline refresh** — 重新抓取最新數據\n8. **Signal performance tracking** — 更新信號績效\n9. **Dashboard regeneration** — 重新生成報告\n\n### 3.4 Context Survival Protocol（v2 核心）\n\n**每 5 輪必做一次 context 健康檢查。**\n\n如果感覺 context 開始變長（對話超過 ~80 輪），主動執行 handoff：\n\n```bash\n# 寫入結構化 handoff 文件\npython3 -c \"\nimport json, datetime\nhandoff = {\n    ''schema_version'': ''2.0'',\n    ''written_at_utc'': datetime.datetime.utcnow().isoformat(),\n    ''deadline_utc'': ''[從 supervisor_state.json 讀取]'',\n    ''context_window_number'': N,  # 當前是第幾個 context window\n    ''cumulative_commits'': [''commit1'', ''commit2'', ...],\n    ''tasks_completed'': [\n        {''id'': ''T1'', ''subject'': ''...'', ''result'': ''...''},\n    ],\n    ''tasks_remaining'': [\n        {''id'': ''T5'', ''subject'': ''...'', ''priority'': ''P1'', ''description'': ''...''},\n    ],\n    ''active_research'': ''RB-XXX'',\n    ''key_findings'': [\n        ''finding 1'',\n        ''finding 2'',\n    ],\n    ''agent_team_config'': {\n        ''team_name'': ''pam-session-YYYYMMDD'',\n        ''agents_needed'': [''quant-researcher'', ''tech-lead''],\n    },\n    ''resume_instructions'': ''具體說明下一個 context window 應該從哪裡開始''\n}\nwith open(''logs/supervisor_handoff.json'', ''w'') as f:\n    json.dump(handoff, f, indent=2, ensure_ascii=False)\nprint(''Handoff written successfully'')\n\"\n```\n\n然後輸出給用戶：\n```\n============================================================\n  CONTEXT WINDOW HANDOFF\n============================================================\n  Deadline 尚未到達！還有 [X] 小時 [Y] 分鐘。\n  已完成 [N] 個任務，剩餘 [M] 個。\n\n  Handoff 已寫入 logs/supervisor_handoff.json\n\n  請開新對話並輸入：\n  /supervise [剩餘時間] 接力模式\n\n  新 session 會自動讀取 handoff 繼續工作。\n============================================================\n```\n\n### 3.5 強制時間紀律（v2 核心規則）\n\n**以下規則不可違反：**\n\n1. **唯一的結束條件是 deadline 到達**。Task 全部完成不是結束條件。\n2. **每 3 輪執行 `date -u`** 確認真實時間，對比 deadline。\n3. **如果所有 planned tasks 完成，從 Infinite Tail（3.3）生成新任務**。\n4. **如果 context window 即將耗盡，寫 handoff 而不是寫收工報告**。\n5. **永遠在 supervisor_state.json 中更新進度**，這是跨 context 的持久記憶。\n\n---\n\n## Phase 4: 異常處理 (Exception Handling)\n\n### 4.1 可自主處理\n\n| 異常 | 動作 | 限制 |\n|------|------|------|\n| 測試失敗 | 分析原因，自主修復 | 只修相關 code |\n| 小 bug 修復 | 直接修 + commit + push | 跑 pytest 確認 |\n| DB 查詢異常 | 檢查 schema，修正查詢 | 不改 DB 結構 |\n| API 呼叫失敗 | 重試或 fallback | 記錄到 extraction_log |\n| Import 錯誤 | 檢查依賴，安裝缺失 | pip install only |\n\n### 4.2 需暫停升級\n\n| 異常 | 動作 |\n|------|------|\n| **Alpha > 5% CAR** | 停止分析，可能有 look-ahead bias |\n| **Pipeline crash** | 記錄 traceback，不自動重啟 |\n| **Hit rate > 75%** | 標記風險，可能過擬合 |\n| **merge 衝突** | 不自動解決，記錄等人工處理 |\n| **DB 結構改變** | 不自動遷移，等人工確認 |\n\n### 4.3 絕不做\n\n- 不刪除任何 branch 或重要檔案\n- 不 force push\n- 不修改 production pipeline 的核心信號邏輯\n- 不在無測試的情況下改動信號評分公式\n- 不刪除 DB 資料\n\n---\n\n## Phase 5: 收工報告 (Final Report)\n\n**只有在 deadline 真正到達時才執行此 Phase。**\n\n（如果 context window 耗盡但 deadline 未到，執行 3.4 Handoff 而不是收工。）\n\n```markdown\n# PAM Autopilot Report\n\n## Session Info\n- Duration: [X hours Y minutes]\n- Context Windows: [N] (relay count)\n- Strategy: [direction]\n- Date: [YYYY-MM-DD]\n- Commits: [total across all context windows]\n\n## Executive Summary\n[2-3 句概括本次成果]\n\n## Tasks Completed\n| # | Task | Owner | Result |\n|---|------|-------|--------|\n| 1 | [subject] | [agent] | [outcome] |\n\n## Tasks In Progress\n| # | Task | Owner | Status | ETA |\n|---|------|-------|--------|-----|\n\n## Key Findings\n1. [重要發現]\n2. [重要發現]\n\n## Flags & Issues\n- [任何需要人工關注的問題]\n\n## Code Changes\ngit log --oneline [session_start_commit]..HEAD\n\n## Recommendations for Next Session\n1. [建議下次做什麼]\n2. [建議下次做什麼]\n```\n\n### 5.1 存檔\n\n- 報告寫入 `logs/autopilot_YYYYMMDD_HHMM.md`\n- 更新 MEMORY.md（如有重要發現）\n- 更新 Sprint Roadmap（如有研究結果）\n- **刪除 `logs/supervisor_handoff.json`**（session 正式結束，清除 handoff）\n- 更新 `logs/supervisor_state.json` status 為 `COMPLETED`\n\n### 5.2 Team Shutdown\n\n```\n對所有 active agent 發送 shutdown_request：\n  SendMessage type: \"shutdown_request\"\n\n等待所有 agent 確認後：\n  TeamDelete\n```\n\n---\n\n## 時長換算\n\n| 輸入 | 巡檢輪數 | 預估 Context Windows |\n|------|---------|---------------------|\n| `30m` | ~6 輪 | 1 |\n| `1h` | ~12 輪 | 1 |\n| `2h` | ~24 輪 | 1-2 |\n| `4h` | ~48 輪 | 2-3 |\n| `8h` | ~96 輪 | 3-5 |\n\n---\n\n## 安全邊界\n\n### 成本控制\n- 每輪結束後估算已用成本\n- 剩餘 < 20% 時進入 report-only 模式\n\n### 品質控制\n- 所有 code 修改必須通過 pytest\n- Alpha > 5% CAR 立即觸發審查\n- 信號公式修改需要統計顯著性支撐\n\n### 時間控制（v2 新增）\n- **deadline 是硬性截止時間**，只有到達 deadline 才能結束\n- 每 3 輪用 `date -u` 校準時間\n- Context window 耗盡時寫 handoff，不寫收工報告\n- supervisor_state.json 是跨 context 的真實狀態來源\n"},"lastSynced":"2026-03-07T13:14:43.914Z","agentAnalysis":{"suitability":{"en":"Ideal for Autonomous AI Agents requiring advanced pipeline management and research progress monitoring in Congress trading data analysis.","zh":"适用于需要高级管道管理和研究进度监控的自治AI代理，特别是在国会交易数据分析中。","ja":"高度なパイプライン管理と研究進度の監視が必要な自律型AIエージェントに最適です。特に、国会取引データ分析において。","ko":"고급 파이프라인 관리와 연구 진행 상황 모니터링이 필요한 자율형 AI 에이전트에게 적합합니다. 특히 국회 거래 데이터 분석에서","es":"Ideal para Agentes de IA Autónomos que requieren una gestión de pipeline avanzada y un monitoreo del progreso de la investigación en el análisis de datos de comercio del Congreso.","fr":"Idéal pour les Agents d''IA Autonomes nécessitant une gestion de pipeline avancée et un suivi des progrès de la recherche dans l''analyse de données de commerce du Congrès.","de":"Ideal für autonome KI-Agents, die eine erweiterte Pipelineverwaltung und eine Überwachung der Forschungsfortschritte in der Datenanalyse des Kongresshandels erfordern.","pt":"Ideal para Agentes Autônomos de IA que exigem gerenciamento avançado de pipelines e monitoramento do progresso da pesquisa na análise de dados de negociação do Congresso.","ru":"Идеально для автономных агентов ИИ, требующих передового управления конвейерами и мониторинга прогресса исследований в анализе данных торговли Конгресса.","ar":"مثالي للوكلاء المستقلين للذكاء الاصطناعي الذين يحتاجون إلى إدارة متقدمة لأنابيب ومراقبة تقدم البحث في تحليل بيانات التداول في الكونجرس."},"recommendation":{"en":"Empowers agents to automate pipeline management, monitor research progress, and handle exceptions using NLP-driven ETL pipelines, enabling autonomous CEO mode for Political Alpha Monitor (PAM) with features like session relay and handoff detection.","zh":"赋予代理自动化管道管理、监控研究进度和使用NLP驱动的ETL管道处理异常的能力，从而实现Political Alpha Monitor（PAM）的自主CEO模式，具有会话中继和交接检测等功能。","ja":"エージェントがパイプライン管理を自動化し、研究進度を監視し、NLP駆動のETLパイプラインを使用して例外を処理する機能を提供し、セッションリレーとハンドオフ検出などの機能を備えたPolitical Alpha Monitor（PAM）の自律CEOモードを可能にします。","ko":"에이전트가 파이프ライン 관리를 자동화하고 연구 진행 상황을 모니터링하며 NLP驱动의 ETL 파이프라인을 사용하여 예외를 처리할 수 있는 기능을 제공하여 Political Alpha Monitor(PAM)의 자율형 CEO 모드를 가능하게 하며, 세션 중계 및 인수検출 등의 기능을 제공합니다.","es":"Habilita a los agentes a automatizar la gestión de pipeline, monitorear el progreso de la investigación y manejar excepciones utilizando pipelines ETL impulsados por NLP, lo que permite el modo CEO autónomo para Political Alpha Monitor (PAM) con características como relé de sesión y detección de entrega.","fr":"Permet aux agents d''automatiser la gestion de pipeline, de suivre les progrès de la recherche et de gérer les exceptions en utilisant des pipelines ETL pilotés par NLP, ce qui permet le mode CEO autonome pour Political Alpha Monitor (PAM) avec des fonctionnalités comme le relais de session et la détection de passage.","de":"Ermöglicht es den Agenten, die Pipelineverwaltung zu automatisieren, den Forschungsfortschritt zu überwachen und Ausnahmen mit NLP-GETT-Pipelines zu verarbeiten, wodurch der autonome CEO-Modus für Political Alpha Monitor (PAM) mit Funktionen wie Sitzungsrelais und Übergabedetektion aktiviert wird.","pt":"Habilita os agentes a automatizar o gerenciamento de pipelines, monitorar o progresso da pesquisa e lidar com exceções usando pipelines ETL impulsionados por NLP, permitindo o modo CEO autônomo para Monitor Alpha Político (PAM) com recursos como retransmissão de sessão e detecção de passagem.","ru":"Наделяет агентов возможностью автоматизировать управление конвейерами, отслеживать прогресс исследований и обрабатывать исключения с помощью конвейеров ETL, управляемых NLP, обеспечивая автономный режим CEO для Политического Альфа-Монитора (PAM) с функциями, такими как передача сеанса и обнаружение передачи.","ar":"تمكّن الوكلاء من автомат hóa إدارة الأنابيب ومراقبة تقدم البحث ومعالجة الاستثناءات باستخدام أنابيب ETL مدفوعة ب NLP، وتوفير وضع المدير التنفيذي المستقل لمراقب ألفا السياسي (PAM) مع ميزات مثل إعادة بث الجلسة وتحديد التبديل."},"useCases":{"en":["Automating pipeline management for Congress trading data","Monitoring research progress and adjusting priorities","Handling exceptions and performing autonomous repairs"],"zh":["自动化国会交易数据的管道管理","监控研究进度并调整优先级","处理异常并执行自主修复"],"ja":["国会取引データのパイプライン管理の自動化","研究進度の監視と優先順位の調整","例外の処理と自律修復の実行"],"ko":["국회 거래 데이터의 파이프라인 관리 자동화","연구 진행 상황 모니터링 및 우선 순위 조정","예외 처리 및 자율형 수리 수행"],"es":["Automatizar la gestión de pipeline para datos de comercio del Congreso","Monitorear el progreso de la investigación y ajustar las prioridades","Manejar excepciones y realizar reparaciones autónomas"],"fr":["Automatiser la gestion de pipeline pour les données de commerce du Congrès","Suivre les progrès de la recherche et ajuster les priorités","Gérer les exceptions et effectuer des réparations autonomes"],"de":["Automatisierung der Pipelineverwaltung für Kongresshandelsdaten","Überwachung der Forschungsfortschritte und Anpassung der Prioritäten","Verarbeitung von Ausnahmen und Durchführung autonomer Reparaturen"],"pt":["Automatizar o gerenciamento de pipelines para dados de negociação do Congresso","Monitorar o progresso da pesquisa e ajustar prioridades","Lidar com exceções e realizar reparos autônomos"],"ru":["Автоматизировать управление конвейерами для данных торговли Конгресса","Отслеживать прогресс исследований и корректировать приоритеты","Обрабатывать исключения и выполнять автономные ремонты"],"ar":["توفير إدارة الأنابيب الآلية لبيانات التداول في الكونجرس","مراقبة تقدم البحث وتعديل الأولويات","معالجة الاستثناءات وتنفيذ الإصلاحات المستقلة"]},"limitations":{"en":["Requires NLP capabilities for ETL pipeline management","Limited to Political Alpha Monitor (PAM) context","Needs access to logs and handoff files for session relay"],"zh":["需要NLP能力来管理ETL管道","仅限于Political Alpha Monitor（PAM）环境","需要访问日志和交接文件来实现会话中继"],"ja":["ETLパイプライン管理のためにNLP能力が必要","Political Alpha Monitor（PAM）環境のみに限定","セッションリレーを実現するためにログとハンドオフファイルへのアクセスが必要"],"ko":["ETL 파이프라인 관리를 위한 NLP 능력이 필요","Political Alpha Monitor(PAM) 환경에만 제한","세션 중계를 구현하기 위해 로그 및 인수 파일에 대한 액세스가 필요"],"es":["Requiere capacidades de NLP para la gestión de pipelines ETL","Limitado al contexto de Political Alpha Monitor (PAM)","Necesita acceso a registros y archivos de entrega para el relé de sesión"],"fr":["Nécessite des capacités de NLP pour la gestion de pipelines ETL","Limité au contexte de Political Alpha Monitor (PAM)","Nécessite un accès aux journaux et aux fichiers de passage pour le relais de session"],"de":["Benötigt NLP-Fähigkeiten für die Verwaltung von ETL-Pipelines","Begrenzt auf den Kontext von Political Alpha Monitor (PAM)","Benötigt Zugriff auf Protokolle und Übergabedateien für das Sitzungsrelais"],"pt":["Exige capacidades de NLP para gerenciamento de pipelines ETL","Limitado ao contexto do Monitor Alpha Político (PAM)","Necessita acesso a logs e arquivos de passagem para retransmissão de sessão"],"ru":["Требует возможностей NLP для управления конвейерами ETL","Ограничен контекстом Политического Альфа-Монитора (PAM)","Требует доступа к журналам и файлам передачи для передачи сеанса"],"ar":["يتطلب قدرات NLP لإدارة أنابيب ETL","محدود سياق مراقب ألفا السياسي (PAM)","يحتاج إلى الوصول إلى السجلات وملفات التبديل لإعادة بث الجلسة"]},"version":4},"contentHash":"bd7813f4f4272cf0a74ffbfabce2097726466488bf6442c6c32208be2188c2a0","qualityScore":45}');
