INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('danny0926/NLP-data-for-trading/supervise', 'supervise', 'danny0926', 'NLP-data-for-trading', 'community', 'supervise danny0926 NLP-data-for-trading community The supervise skill is an NLP-driven ETL pipeline for Congress trading data, enabling autonomous CEO mode for Political Alpha Monitor (PAM). It benefits developers and researchers by automating pipeline management and research progress monitoring. supervise 技能是一个 NLP 驱动的 Congress 交易数据 ETL 流水线，用于自动化数据处理和分析 supervise スキルは、NLP駆動の Congress 交易データ ETL パイプラインであり、データ処理と分析を自動化します supervise 기능은 NLP 기반 의회 거래 데이터 ETL 파이프라인으로, 데이터 처리와 분석을 자동화합니다 Supervise es una herramienta de NLP que permite la creación de un pipeline de ETL para datos de comercio de congreso. Ofrece capacidades de monitoreo y automatización. Supervise est un outil NLP qui permet la création d''un pipeline ETL pour les données de commerce de congrès. Il offre des capacités de surveillance et d''automatisation. Supervise ist ein NLP-Tool, das die Erstellung einer ETL-Pipeline für Kongress-Handelsdaten ermöglicht. Es bietet Überwachungs- und Automatisierungsfunktionen. O Supervise é uma ferramenta de gerenciamento de pipeline de ETL de dados de Congresso com capacidades de NLP e autonomia Supervise — это инструмент для управления конвейерами ETL торговых данных Конгресса с возможностями NLP и автономии Supervise هو أداة لإدارة خطوط أنابيب ETL لبيانات الكونغرس التجارية مع قدرات NLP والاستقلالية how to use supervise supervise setup guide autonomous ETL pipeline management Congress trading data analysis NLP-driven pipeline monitoring supervise vs traditional ETL tools install supervise supervise alternative what is supervise supervise tutorial supervise NLP 驱动的 ETL Congress 交易数据 自动化数据处理 AIエージェント NLP 技术 数据分析 异常处理 Autonomous CEO mode for Political Alpha Monitor (PAM) using NLP-driven ETL pipeline Session relay with automatic handoff checking via `logs/supervisor_handoff.json` file Pipeline monitoring and research progress tracking Automatic anomaly handling and repair Generation of complete work reports Support for cross-context window automatic relay (v2) supervise is an AI agent skill that enables autonomous management of Congress trading data ETL pipelines, providing features like session relay, handoff checking, and automatic pipeline monitoring.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('eduhub-org/eduhub/cherrypick-hotfix', 'community', 'eduhub-org', 'eduhub', 'eduhub-org/eduhub', 'cherrypick-hotfix', 12, 8, 45, '2026-02-26T20:45:02Z', '2026-03-06T06:45:18.408Z', 'b41246f411348b6cccddf2f4b905ae6da2f1ccc02a0440f2985eda672f445198', '{"id":"eduhub-org/eduhub/cherrypick-hotfix","name":"cherrypick-hotfix","description":{"en":"The cherrypick-hotfix skill helps developers sync production hotfixes with the develop branch using Git cherry-picking. It benefits development teams working with Git version control.","zh":"Cherrypick-Hotfix 是一个 Git 工作流程，用于将生产环境的热修复应用到开发分支，确保未来版本的稳定性","ja":"Cherrypick-Hotfix は、プロダクション環境のホットフィックスを開発ブランチに適用し、将来のバージョンの安定性を確保する Git ワークフローです","ko":"Cherrypick-Hotfix는 프로덕션 환경의 핫픽스를 개발 브랜치에 적용하여 미래 버전의 안정성을 보장하는 Git 워크플로우입니다","es":"El skill cherrypick-hotfix se utiliza para incluir correcciones en futuras versiones de desarrollo cuando se han realizado cambios directamente en producción.","fr":"Le skill cherrypick-hotfix est utilisé pour inclure des corrections dans les futures versions de développement lorsque des changements ont été effectués directement en production.","de":"Das Skill cherrypick-hotfix wird verwendet, um Korrekturen in zukünftigen Entwicklungsversionen einzuschließen, wenn Änderungen direkt in der Produktion vorgenommen wurden.","pt":"O Cherry-pick Hotfix é uma técnica para garantir a consistência do código em produção e desenvolvimento","ru":"Cherry-pick Hotfix - это техника, обеспечивающая согласованность кода в производстве и разработке","ar":"Cherry-pick Hotfix هو تقنية لضمان الاتساق في الإنتاج والتنمية"},"seo":{"title":{"en":"cherrypick-hotfix: Git Cherry-Picking Setup Guide | AI Ag...","zh":"Cherrypick-Hotfix 设置指南：Git Cherry-Pick 教程","ja":"Cherrypick-Hotfix セットアップガイド：Git Cherry-Pick を使ったホットフィックスの適用","ko":"Cherrypick-Hotfix 설정 가이드: Git Cherry-Pick 사용법","es":"Guía de configuración de cherrypick-hotfix para desarrollo","fr":"Guide de mise en place de cherrypick-hotfix pour le dével...","de":"Einrichtungsleitfaden für cherrypick-hotfix in der Entwic...","pt":"Guia de Configuração do Cherry-pick Hotfix para Desenvolv...","ru":"Настройка Cherry-pick Hotfix: Лучшие Практики для Разрабо...","ar":"إعداد Cherry-pick Hotfix: دليل المستخدم للطورين"},"description":{"en":"Learn how to apply cherrypick-hotfix to sync production fixes with develop branch. Follow our step-by-step guide to ensure seamless Git workflow integration.","zh":"了解如何使用 Cherrypick-Hotfix 将生产环境的热修复应用到开发分支，确保未来版本的稳定性","ja":"Cherrypick-Hotfix を使用してプロダクション環境のホットフィックスを開発ブランチに適用し、将来のバージョンの安定性を確保する方法を学びます","ko":"Cherrypick-Hotfix를 사용하여 프로덕션 환경의 핫픽스를 개발 브랜치에 적용하여 미래 버전의 안정성을 보장하는 방법을 알아보세요","es":"Aprende a aplicar cherrypick-hotfix para incluir correcciones en futuras versiones con Git","fr":"Découvrez comment appliquer cherrypick-hotfix pour inclure des corrections dans les futures versions avec Git","de":"Erfahren Sie, wie Sie cherrypick-hotfix anwenden, um Korrekturen in zukünftigen Versionen mit Git einzuschließen","pt":"Aprenda a aplicar o Cherry-pick Hotfix para garantir a consistência do código em produção e desenvolvimento","ru":"Узнайте, как применять Cherry-pick Hotfix, чтобы обеспечить согласованность кода в производстве и разработке","ar":"تعرف على كيفية تطبيق Cherry-pick Hotfix لضمان الاتساق في الإنتاج والتنمية"},"definition":{"en":"cherrypick-hotfix is a Git workflow technique used to apply production hotfixes to the develop branch, ensuring future releases include critical fixes.","zh":"Cherrypick-Hotfix 是一个 Git 命令，用于将单个提交从一个分支复制到另一个分支","ja":"Cherrypick-Hotfix は、1 つのコミットを 1 つのブランチから別のブランチにコピーする Git コマンドです","ko":"Cherrypick-Hotfix는 하나의 커밋을 하나의 브랜치에서 다른 브랜치로 복사하는 Git 명령입니다","es":"Cherrypick-hotfix es una técnica de desarrollo que permite incluir correcciones en futuras versiones","fr":"Cherrypick-hotfix est une technique de développement qui permet d''inclure des corrections dans les futures versions","de":"Cherrypick-hotfix ist eine Entwicklungstechnik, die es ermöglicht, Korrekturen in zukünftigen Versionen einzuschließen","pt":"Cherry-pick Hotfix é uma técnica de Git para aplicar commits específicos em branches diferentes","ru":"Cherry-pick Hotfix - это техника Git, позволяющая применять конкретные коммиты в разных ветках","ar":"Cherry-pick Hotfix هو تقنية Git لتطبيق التعديلات المحددة في الفروع المختلفة"},"features":{"en":["Identifies missing commits between production and develop branches using `git log --oneline develop..production`","Cherry-picks specific commits to the develop branch using `git cherry-pick <commit-hash>`","Updates the develop branch with the latest hotfixes using `git push origin develop`","Ensures future releases include production hotfixes by syncing the develop branch","Utilizes Git commands for seamless workflow integration"],"zh":["使用 Git Cherry-Pick 命令将热修复应用到开发分支","确保未来版本的稳定性","支持多个分支的热修复应用","提供快速的热修复应用步骤","支持 Git 命令行工具"],"ja":["Git Cherry-Pick コマンドを使用してホットフィックスを開発ブランチに適用","将来のバージョンの安定性を確保","複数のブランチのホットフィックス適用をサポート","迅速なホットフィックス適用手順を提供","Git コマンドラインツールをサポート"],"ko":["Git Cherry-Pick 명령을 사용하여 핫픽스를 개발 브랜치에 적용","미래 버전의 안정성을 보장","여러 브랜치의 핫픽스 적용을 지원","빠른 핫픽스 적용 단계를 제공","Git 명령행 도구를 지원"],"es":["Identificación de commits faltantes con Git","Cherrypick de correcciones a la rama de desarrollo","Uso de Git para asegurar la inclusión de correcciones en futuras versiones","Integración con el flujo de trabajo de desarrollo","Soporte para la gestión de versiones con Git"],"fr":["Identification des commits manquants avec Git","Cherrypick de corrections sur la branche de développement","Utilisation de Git pour assurer l''inclusion de corrections dans les futures versions","Intégration avec le flux de travail de développement","Prise en charge de la gestion de versions avec Git"],"de":["Identifizierung fehlender Commits mit Git","Cherrypick von Korrekturen auf den Entwicklungszweig","Verwendung von Git, um die Einbeziehung von Korrekturen in zukünftigen Versionen sicherzustellen","Integration in den Entwicklungswerkfluss","Unterstützung für die Versionsverwaltung mit Git"],"pt":["Identificação de commits faltantes com `git log --oneline develop..production`","Aplicação de commits específicos com `git cherry-pick <commit-hash>`","Garantia de consistência do código em produção e desenvolvimento","Integração com Git para gerenciamento de branches","Suporte à resolução de conflitos de código"],"ru":["Определение缺失ных коммитов с помощью `git log --oneline develop..production`","Применение конкретных коммитов с помощью `git cherry-pick <commit-hash>`","Обеспечение согласованности кода в производстве и разработке","Интеграция с Git для управления ветками","Поддержка решения конфликтов кода"],"ar":["تحديد التعديلات الناقصة باستخدام `git log --oneline develop..production`","تطبيق التعديلات المحددة باستخدام `git cherry-pick <commit-hash>`","ضمان الاتساق في الإنتاج والتنمية","التكامل مع Git لإدارة الفروع","دعم حل النزاعات في الكود"]},"keywords":{"en":["how to use cherrypick-hotfix","cherrypick-hotfix vs git rebase","cherrypick-hotfix setup guide","git cherry-picking tutorial","what is cherrypick-hotfix","cherrypick-hotfix alternative"],"zh":["Cherrypick-Hotfix","Git Cherry-Pick","热修复","开发分支","生产环境","Git 工作流程","AIエージェント","代码管理"],"ja":["Cherrypick-Hotfix","Git Cherry-Pick","ホットフィックス","開発ブランチ","プロダクション環境","Git ワークフロー","AIエージェント","コード管理"],"ko":["Cherrypick-Hotfix","Git Cherry-Pick","핫픽스","개발 브랜치","프로덕션 환경","Git 워크플로우","AI 에이전트","코드 관리"],"es":["cherrypick-hotfix","desarrollo de software","Git","correcciones de código","versiones de desarrollo","flujo de trabajo de desarrollo","gestión de versiones","herramientas de desarrollo"],"fr":["cherrypick-hotfix","développement de logiciels","Git","corrections de code","versions de développement","flux de travail de développement","gestion de versions","outils de développement"],"de":["cherrypick-hotfix","Software-Entwicklung","Git","Korrekturen von Code","Entwicklungsversionen","Entwicklungsworkflow","Versionsverwaltung","Entwicklungstools"],"pt":["cherry-pick hotfix","git cherry-pick","commits faltantes","branches git","desenvolvimento de software","gerenciamento de código","resolução de conflitos"],"ru":["cherry-pick hotfix","git cherry-pick","отсутствующие коммиты","ветки git","разработка программного обеспечения","управление кодом","решение конфликтов"],"ar":["cherry-pick hotfix","git cherry-pick","التعديلات الناقصة","فروع git","تنمية البرمجيات","إدارة الكود","حل النزاعات"]}},"owner":"eduhub-org","repo":"eduhub","repoPath":"eduhub-org/eduhub","stars":12,"forks":8,"updatedAt":"2026-02-26T20:45:02Z","topics":["certificates","courses","education","events","hacktoberfest"],"category":"community","skillMd":{"name":"cherrypick-hotfix","description":"Cherry-pick hotfix commits from production to develop. Use when a hotfix was pushed directly to production and needs to be backported to develop branch.","bodyPreview":"# Cherry-pick Hotfix to Develop\n\n## When to Use\n\n- A hotfix was pushed directly to production\n- The fix is missing from develop (and possibly staging)\n- You need to ensure the fix is included in future releases\n\n## Quick Steps\n\n### 1. Identify the missing commits\n\n```bash\n# Show commits in production that are NOT in develop\ngit log --oneline develop..production\n```\n\n### 2. Cherry-pick to develop\n\n```bash\ngit checkout develop\ngit pull origin develop\ngit cherry-pick <commit-hash>\ngit push origin d","body":"# Cherry-pick Hotfix to Develop\n\n## When to Use\n\n- A hotfix was pushed directly to production\n- The fix is missing from develop (and possibly staging)\n- You need to ensure the fix is included in future releases\n\n## Quick Steps\n\n### 1. Identify the missing commits\n\n```bash\n# Show commits in production that are NOT in develop\ngit log --oneline develop..production\n```\n\n### 2. Cherry-pick to develop\n\n```bash\ngit checkout develop\ngit pull origin develop\ngit cherry-pick <commit-hash>\ngit push origin develop\n```\n\n### 3. Verify\n\n```bash\n# Confirm the commit is now in develop\ngit branch --contains <commit-hash>\n```\n\n## Optional: Also add to staging immediately\n\n**When to cherry-pick to staging:**\n- User explicitly asks to also add to staging\n- User mentions the fix is urgent or needed in staging\n- Context suggests staging needs the fix before the next develop merge\n\n**Default behavior:** Only cherry-pick to develop unless user requests staging or context indicates it''s needed.\n\n**If uncertain:** Ask the user: \"Should I also cherry-pick this to staging, or is develop sufficient?\"\n\n**If staging is needed:**\n\n```bash\ngit checkout staging\ngit pull origin staging\ngit cherry-pick <commit-hash>\ngit push origin staging\n```\n\n## Troubleshooting\n\n### Cherry-pick conflict\nIf there are conflicts during cherry-pick:\n```bash\n# Resolve conflicts in the files\n# Then continue\ngit add .\ngit cherry-pick --continue\n```\n\n### Wrong commit cherry-picked\n```bash\n# Abort before completing\ngit cherry-pick --abort\n```\n\n### Multiple hotfix commits\nCherry-pick in chronological order (oldest first):\n```bash\ngit cherry-pick <older-commit> <newer-commit>\n```\n"},"lastSynced":"2026-03-06T06:45:18.408Z","agentAnalysis":{"suitability":{"en":"Perfect for Version Control Agents needing Git cherry-picking capabilities for production hotfixes.","zh":"非常适合需要 Git cherry-picking 功能的版本控制代理，以便为生产环境提供热修复。","ja":"バージョン管理エージェントが生产環境のホットフィックスに Git cherry-picking 機能を必要とする場合に最適です。","ko":"생산 환경의 핫픽스에 Git cherry-picking 기능이 필요한 버전 관리 에이전트에게 적합합니다.","es":"Perfecto para Agentes de Control de Versiones que necesitan capacidades de cherry-picking de Git para hotfixes de producción.","fr":"Parfait pour les Agents de Contrôle de Version ayant besoin de capacités de cherry-picking Git pour les correctifs de production.","de":"Perfekt für Version Control Agents, die Git-Cherry-Picking-Funktionen für Produktions-Hotfixes benötigen.","pt":"Perfeito para Agentes de Controle de Versão que precisam de capacidades de cherry-picking do Git para hotfixes de produção.","ru":"Идеально подходит для агентов контроля версий, которым необходимы возможности cherry-picking Git для исправления производственных ошибок.","ar":"مثالي لعميل التحكم في الإصدار الذين يحتاجون إلى قدرات cherry-picking من Git لتحديثات الإنتاج الساخنة."},"recommendation":{"en":"Empowers agents to sync production hotfixes with the develop branch using Git cherry-picking, ensuring fixes are included in future releases via git log and git cherry-pick commands.","zh":"使代理能够使用 Git cherry-picking 将生产环境的热修复与开发分支同步，确保通过 git log 和 git cherry-pick 命令将修复包含在未来的版本中。","ja":"エージェントが Git cherry-picking を使用して生产環境のホットフィックスを開発ブランチと同期できるようにし、git log と git cherry-pick コマンドを使用して将来的にリリースされるバージョンに修復が含まれることを保証します。","ko":"에이전트가 Git cherry-picking을 사용하여 생산 환경의 핫픽스를 개발 브랜치와 동기화할 수 있도록 하여 git log와 git cherry-pick 명령을 통해 향후 버전에 수정 사항이 포함되도록 보장합니다.","es":"Habilita a los agentes a sincronizar hotfixes de producción con la rama de desarrollo utilizando el cherry-picking de Git, asegurando que los arreglos se incluyan en futuras versiones a través de los comandos git log y git cherry-pick.","fr":"Permet aux agents de synchroniser les correctifs de production avec la branche de développement en utilisant le cherry-picking Git, en veillant à ce que les corrections soient incluses dans les futures versions via les commandes git log et git cherry-pick.","de":"Ermächtigt Agenten, Produktions-Hotfixes mit dem Entwicklungsbranch mithilfe von Git-Cherry-Picking zu synchronisieren, sodass die Korrekturen in zukünftigen Versionen über die Befehle git log und git cherry-pick enthalten sind.","pt":"Habilita os agentes a sincronizar hotfixes de produção com a branch de desenvolvimento usando o cherry-picking do Git, garantindo que as correções sejam incluídas em futuras versões via comandos git log e git cherry-pick.","ru":"Наделяет агентов возможностью синхронизировать исправления производственных ошибок с веткой разработки с помощью cherry-picking Git, гарантируя, что исправления будут включены в будущие релизы через команды git log и git cherry-pick.","ar":"يمنح الوكلاء القدرة على مزامنة تحديثات الإنتاج الساخنة مع فرع التطوير باستخدام cherry-picking من Git ، مما يضمن تضمين الإصلاحات في الإصدارات المستقبلية عبر أوامر git log و git cherry-pick."},"useCases":{"en":["Cherry-picking production hotfixes to develop","Identifying missing commits between production and develop branches","Syncing hotfixes with staging environments"],"zh":["将生产环境的热修复 cherry-picking 到开发分支","确定生产环境和开发分支之间缺失的提交","将热修复与预发环境同步"],"ja":["生产環境のホットフィックスを開発ブランチに cherry-picking する","生产環境と開発ブランチの間の缺失しているコミットを特定する","ホットフィックスをステージング環境と同期する"],"ko":["생산 환경의 핫픽스를 개발 브랜치로 체리픽킹","생산 환경과 개발 브랜치 사이에 누락된 커밋을 식별","핫픽스를 스테이징 환경과 동기화"],"es":["Cherry-picking de hotfixes de producción a desarrollar","Identificación de commits faltantes entre las ramas de producción y desarrollo","Sincronización de hotfixes con entornos de staging"],"fr":["Cherry-picking des correctifs de production pour le développement","Identification des commits manquants entre les branches de production et de développement","Synchronisation des correctifs avec les environnements de staging"],"de":["Cherry-Picking von Produktions-Hotfixes zum Entwicklungsbranch","Identifizierung fehlender Commits zwischen Produktions- und Entwicklungsbranch","Synchronisierung von Hotfixes mit Staging-Umgebungen"],"pt":["Cherry-picking de hotfixes de produção para desenvolvimento","Identificação de commits ausentes entre branches de produção e desenvolvimento","Sincronização de hotfixes com ambientes de staging"],"ru":["Cherry-picking исправлений производственных ошибок в разработку","Определение пропущенных коммитов между производственными и разработными ветками","Синхронизация исправлений с промежуточными окружениями"],"ar":["تخصيص تحديثات الإنتاج الساخنة إلى التطوير","تحديد الالتزامات المفقودة بين فروع الإنتاج والتطوير","مزامنة تحديثات الإنتاج الساخنة مع بيئات الإعداد"]},"limitations":{"en":["Requires Git version control","Needs access to production and develop branches"],"zh":["需要 Git 版本控制","需要访问生产环境和开发分支"],"ja":["Git バージョン管理が必要","生产環境と開発ブランチへのアクセスが必要"],"ko":["Git 버전 관리가 필요","생산 환경과 개발 브랜치에 접근이 필요"],"es":["Requiere control de versiones Git","Necesita acceso a las ramas de producción y desarrollo"],"fr":["Nécessite le contrôle de version Git","Besoin d''accès aux branches de production et de développement"],"de":["Benötigt Git-Versionierung","Benötigt Zugriff auf Produktions- und Entwicklungsbranch"],"pt":["Requer controle de versão do Git","Necessita acesso às branches de produção e desenvolvimento"],"ru":["Требуется контроль версий Git","Необходим доступ к производственной и разработческой веткам"],"ar":["يتطلب التحكم في الإصدار من Git","يحتاج إلى الوصول إلى فروع الإنتاج والتطوير"]},"version":4},"contentHash":"b41246f411348b6cccddf2f4b905ae6da2f1ccc02a0440f2985eda672f445198","qualityScore":45}');
