INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('eduhub-org/eduhub/cherrypick-hotfix', 'cherrypick-hotfix', 'eduhub-org', 'eduhub', 'community', 'cherrypick-hotfix eduhub-org eduhub community certificates courses education events hacktoberfest The cherrypick-hotfix skill helps developers sync production hotfixes with the develop branch using Git cherry-picking. It benefits development teams working with Git version control. Cherrypick-Hotfix 是一个 Git 工作流程，用于将生产环境的热修复应用到开发分支，确保未来版本的稳定性 Cherrypick-Hotfix は、プロダクション環境のホットフィックスを開発ブランチに適用し、将来のバージョンの安定性を確保する Git ワークフローです Cherrypick-Hotfix는 프로덕션 환경의 핫픽스를 개발 브랜치에 적용하여 미래 버전의 안정성을 보장하는 Git 워크플로우입니다 El skill cherrypick-hotfix se utiliza para incluir correcciones en futuras versiones de desarrollo cuando se han realizado cambios directamente en producción. Le skill cherrypick-hotfix est utilisé pour inclure des corrections dans les futures versions de développement lorsque des changements ont été effectués directement en production. Das Skill cherrypick-hotfix wird verwendet, um Korrekturen in zukünftigen Entwicklungsversionen einzuschließen, wenn Änderungen direkt in der Produktion vorgenommen wurden. O Cherry-pick Hotfix é uma técnica para garantir a consistência do código em produção e desenvolvimento Cherry-pick Hotfix - это техника, обеспечивающая согласованность кода в производстве и разработке Cherry-pick Hotfix هو تقنية لضمان الاتساق في الإنتاج والتنمية how to use cherrypick-hotfix cherrypick-hotfix vs git rebase cherrypick-hotfix setup guide git cherry-picking tutorial what is cherrypick-hotfix cherrypick-hotfix alternative Cherrypick-Hotfix Git Cherry-Pick 热修复 开发分支 生产环境 Git 工作流程 AIエージェント 代码管理 Identifies missing commits between production and develop branches using `git log --oneline develop..production` Cherry-picks specific commits to the develop branch using `git cherry-pick <commit-hash>` Updates the develop branch with the latest hotfixes using `git push origin develop` Ensures future releases include production hotfixes by syncing the develop branch Utilizes Git commands for seamless workflow integration cherrypick-hotfix is a Git workflow technique used to apply production hotfixes to the develop branch, ensuring future releases include critical fixes.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('cesaroeduardo/icon-library-visualization/skill-creator', 'community', 'cesaroeduardo', 'icon-library-visualization', 'cesaroeduardo/icon-library-visualization', 'skill-creator', 5, 1, 45, '2026-02-20T17:16:48Z', '2026-03-06T06:55:43.976Z', 'b2e3d83f60425c2d0b9d4162efb8f9aa322b45843497340f2289f42be422801c', '{"id":"cesaroeduardo/icon-library-visualization/skill-creator","name":"skill-creator","description":{"en":"The skill-creator provides guidance for creating effective skills, extending Claude''s capabilities with modular, self-contained packages. It benefits developers seeking to specialize Claude for specific domains or tasks.","zh":"Skill Creator 是一个提供创建有效技能的指南，包括专用工作流和工具","ja":"Skill Creator は、専用のワークフローとツールを提供する、効果的なスキルの作成を支援するガイドです","ko":"Skill Creator는 특정 도메인 또는 작업을 위한 전문 지식과 워크플로우를 제공하는 효과적인 스킬 생성을 위한 가이드입니다","es":"Skill Creator es una habilidad que proporciona orientación para crear habilidades efectivas para bibliotecas de iconos con flujos de trabajo especializados","fr":"Skill Creator est une compétence qui fournit des conseils pour créer des compétences efficaces pour les bibliothèques d''icônes avec des flux de travail spécialisés","de":"Skill Creator ist eine Fähigkeit, die Anleitungen zur Erstellung effektiver Fähigkeiten für Icon-Bibliotheken mit spezialisierten Workflows bietet","pt":"O Skill Creator é uma ferramenta para criar skills personalizados para catálogos de ícones, permitindo a extensão das capacidades do agente","ru":"Skill Creator - это инструмент для создания пользовательских навыков для каталогов иконок, позволяющий расширить возможности ИИ Агента","ar":"Skill Creator هو أداة لإنشاء مهارات مخصصة لكتالوج الرموز، مما يسمح بتوسيع قدرات الوكيل"},"seo":{"title":{"en":"skill-creator: Modular Skill Development Setup Guide | AI...","zh":"Skill Creator 设置指南 - AI智能代理技术","ja":"Skill Creator 導入ガイド - AIエージェント開発","ko":"Skill Creator 설정 가이드 - AI 에이전트 개발 도구","es":"Guía de configuración de Skill Creator para bibliotecas d...","fr":"Guide de mise en place de Skill Creator pour les biblioth...","de":"Einrichtungsleitfaden für Skill Creator zur Erstellung vo...","pt":"Guia de Configuração do Skill Creator para Catálogo de Íc...","ru":"Настройка ИИ Агентов с Skill Creator для Каталогов Иконок","ar":"دليل إعداد Skill Creator لكتالوج الرموز"},"description":{"en":"Unlock specialized workflows with skill-creator. Discover how to extend Claude''s capabilities and transform it into a specialized agent. Get started now!","zh":"了解 Skill Creator 的技术细节和应用场景，开发出更好的 AI 智能代理","ja":"Skill Creator の特徴と技術的な詳細を学び、より効率的な AI エージェントを開発しましょう","ko":"Skill Creator의 기술 세부 정보와 적용 사례를 알아보고 더 나은 AI 에이전트를 개발하세요","es":"Aprende a crear habilidades personalizadas con Skill Creator para mejorar tus proyectos de bibliotecas de iconos con flujos de trabajo especializados","fr":"Découvrez comment créer des compétences personnalisées avec Skill Creator pour améliorer vos projets de bibliothèques d''icônes avec des flux de travail spéci...","de":"Erfahren Sie, wie Sie benutzerdefinierte Fähigkeiten mit Skill Creator erstellen können, um Ihre Icon-Bibliotheksprojekte mit spezialisierten Workflows zu ve...","pt":"Aprenda a criar skills personalizados com o Skill Creator para catálogos de ícones e melhore a capacidade do seu agente","ru":"Получите руководство по созданию навыков с помощью Skill Creator для каталогов иконок и повысьте возможности вашего ИИ Агента","ar":"تعلم كيفية إنشاء مهارات مخصصة باستخدام Skill Creator لكتالوج الرموز وتحسين قدرات وكيلك"},"definition":{"en":"skill-creator is a personal project for an icon library catalogue, providing specialized knowledge, workflows, and tools for creating effective skills.","zh":"Skill Creator 是一种 AI 智能代理技能，提供创建和管理技能的指导","ja":"Skill Creator は、AI エージェントのスキルを作成および管理するためのガイドを提供する、モジュラーなパッケージです","ko":"Skill Creator는 AI 에이전트의 스킬을 생성하고 관리하기 위한 지침을 제