INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('cesaroeduardo/icon-library-visualization/skill-creator', 'skill-creator', 'cesaroeduardo', 'icon-library-visualization', 'community', 'skill-creator cesaroeduardo icon-library-visualization community catalogue icon-library icons library-catalogue The skill-creator provides guidance for creating effective skills, extending Claude''s capabilities with modular, self-contained packages. It benefits developers seeking to specialize Claude for specific domains or tasks. Skill Creator 是一个提供创建有效技能的指南，包括专用工作流和工具 Skill Creator は、専用のワークフローとツールを提供する、効果的なスキルの作成を支援するガイドです Skill Creator는 특정 도메인 또는 작업을 위한 전문 지식과 워크플로우를 제공하는 효과적인 스킬 생성을 위한 가이드입니다 Skill Creator es una habilidad que proporciona orientación para crear habilidades efectivas para bibliotecas de iconos con flujos de trabajo especializados Skill Creator est une compétence qui fournit des conseils pour créer des compétences efficaces pour les bibliothèques d''icônes avec des flux de travail spécialisés Skill Creator ist eine Fähigkeit, die Anleitungen zur Erstellung effektiver Fähigkeiten für Icon-Bibliotheken mit spezialisierten Workflows bietet O Skill Creator é uma ferramenta para criar skills personalizados para catálogos de ícones, permitindo a extensão das capacidades do agente Skill Creator - это инструмент для создания пользовательских навыков для каталогов иконок, позволяющий расширить возможности ИИ Агента Skill Creator هو أداة لإنشاء مهارات مخصصة لكتالوج الرموز، مما يسمح بتوسيع قدرات الوكيل how to use skill-creator what is skill-creator skill-creator alternative skill-creator vs icon library skill-creator install skill-creator setup guide modular skill development Claude specialized agent icon library catalogue AI 智能代理 Skill Creator 创建技能 管理技能 专用工作流 模块化包 Claude 能力扩展 AI 开发工具 Provides specialized workflows for specific domains or tasks Extends Claude''s capabilities with modular, self-contained packages Transforms Claude into a specialized agent equipped with procedural knowledge Supports creation of skills as onboarding guides for specific domains or tasks Enables multi-step workflows for specialized knowledge and tools skill-creator is a personal project for an icon library catalogue, providing specialized knowledge, workflows, and tools for creating effective skills.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('deadlock-api/deadlock-api/shadcn', 'community', 'deadlock-api', 'deadlock-api', 'deadlock-api/deadlock-api', 'shadcn', 7, 1, 45, '2026-03-07T22:01:38Z', '2026-03-08T01:59:26.915Z', 'cefd8f067461a5994741aef6be1e285bb62c5a0dceef79006dd3caaa4fbfec1a', '{"id":"deadlock-api/deadlock-api/shadcn","name":"shadcn","description":{"en":"shadcn is a framework for building UI components and design systems, adding components as source code to projects via the CLI. It benefits developers seeking efficient UI management.","zh":"shadcn UI框架是一种用于构建用户界面和设计系统的工具，通过CLI命令将组件添加到项目中","ja":"shadcn UIフレームワークは、ユーザーインターフェイスとデザインシステムを構築するためのツールです。CLIコマンドを使用してコンポーネントをプロジェクトに追加します","ko":"shadcn UI 프레임워크는 사용자 인터페이스와 디자인 시스템을 구축하기 위한 도구입니다. CLI 명령을 사용하여 컴포넌트를 프로젝트에 추가합니다","es":"shadcn es un framework para construir interfaces de usuario y componentes personalizados. Utiliza el CLI para agregar componentes como código fuente al proyecto","fr":"shadcn est un framework pour créer des interfaces utilisateur et des composants personnalisés. Il utilise le CLI pour ajouter des composants comme code source au projet","de":"shadcn ist ein Framework für die Erstellung benutzerdefinierter Benutzeroberflächen und Komponenten. Es verwendet die CLI, um Komponenten als Quellcode zum Projekt hinzuzufügen","pt":"O shadcn é um framework de UI que permite adicionar componentes como código-fonte ao projeto via CLI.","ru":"shadcn - это фреймворк UI, который позволяет добавлять компоненты в виде исходного кода в проект через CLI.","ar":"shadcn هو إطار عمل UI يسمح بإضافة المكونات كкод مصدر إلى المشروع من خلال CLI."},"seo":{"title":{"en":"shadcn: UI Component Setup Guide | AI Agent Skill","zh":"shadcn UI框架设置指南","ja":"shadcn UIフレームワーク設定ガイド - AIエージェント","ko":"shadcn UI 프레임워크 설정 가이드 - AI 에이전트","es":"Guía de configuración de shadcn para desarrolladores","fr":"Guide de mise en place de shadcn pour les développeurs","de":"Einrichtungsleitfaden für shadcn-Entwickler","pt":"Guia de Configuração do shadcn: Framework de UI Avançado","ru":"Руководство по настройке shadcn: ИИ Агенты для UI","ar":"دليل إعداد shadcn: إطار عمل UI متقدم"},"description":{"en":"Discover how to integrate shadcn into your project using CLI commands like `npx shadcn@latest` and unlock efficient UI component management","zh":"了解如何使用shadcn UI框架构建用户界面和设计系统，包括CLI命令和项目集成","ja":"shadcn UIフレームワークを使用してユーザーインターフェイスとデザインシステムを構築する方法について説明します - AIエージェント","ko":"shadcn UI 프레임워크를 사용하여 사용자 인터페이스와 디자인 시스템을 구축하는 방법에 대해 알아보세요 - AI 에이전트","es":"Aprende a utilizar shadcn para construir interfaces de usuario y componentes personalizados con nuestra guía paso a paso","fr":"Découvrez comment utiliser shadcn pour créer des interfaces utilisateur et des composants personnalisés avec notre guide étape par étape","de":"Erfahren Sie, wie Sie shadcn verwenden, um benutzerdefinierte Benutzeroberflächen und Komponenten zu erstellen, mit unserer Schritt-für-Schritt-Anleitung","pt":"Aprenda a usar o shadcn para construir componentes de UI e sistemas de design com o CLI","ru":"Откройте для себя, как использовать shadcn для создания компонентов UI и систем дизайна с помощью CLI","ar":"تعرف على كيفية استخدام shadcn لبناء مكونات واجهة المستخدم وأنظمة التصميم مع CLI"},"definition":{"en":"shadcn is a UI component framework that integrates into projects via CLI commands for efficient design system management","zh":"shadcn UI框架是一种用于构建用户界面和设计系统的工具","ja":"shadcn UIフレームワークは、ユーザーインターフェイスとデザインシステムを構築するためのツールです","ko":"shadcn UI 프레임워크는 사용자 인터페이스와 디자인 시스템을 구축하기 위한 도구입니다","es":"shadcn es un framework de código abierto para la creación de interfaces de usuario y componentes personalizados","fr":"shadcn est un framework open source pour la création d''interfaces utilisateur et de composants personnalisés","de":"shadcn ist ein Open-Source-Framework für die Erstellung benutzerdefinierter Benutzeroberflächen und Komponenten","pt":"O shadcn é um framework de UI para construir componentes e sistemas de design.","ru":"shadcn - это фреймворк UI для создания компонентов и систем дизайна.","ar":"shadcn هو إطار عمل UI لإنشاء مكونات وأنظمة التصميم."},"features":{"en":["Adds UI components as source code to projects via the CLI","Supports project-specific package runners like `npx`, `pnpm dlx`, and `bunx`","Provides project information via `npx shadcn@latest info --json` command","Enables design system management through component integration","Runs CLI commands based on the project''s `packageManager`"],"zh":["通过CLI命令将组件添加到项目中","支持不同包管理器（npm、pnpm、bun」","提供项目信息和设置功能","使用npx、pnpm dlx或bunx运行CLI命令"],"ja":["CLIコマンドを使用してコンポーネントをプロジェクトに追加","異なるパッケージマネージャー（npm、pnpm、bun）をサポート","プロジェクト情報と設定機能を提供","npx、pnpm dlx、またはbunxを使用してCLIコマンドを実行"],"ko":["CLI 명령을 사용하여 컴포넌트를 프로젝트에 추가","다른 패키지 관리자（npm、pnpm、bun）를 지원","프로젝트 정보와 설정 기능을 제공","npx、pnpm dlx 또는 bunx를 사용하여 CLI 명령을 실행"],"es":["Construcción de interfaces de usuario personalizadas","Agregar componentes como código fuente al proyecto via CLI","Compatibilidad con diferentes administradores de paquetes (npm, pnpm, bun)","Uso de comandos CLI personalizados (npx shadcn@latest)","Compatibilidad con proyectos que utilizan diferentes administradores de paquetes"],"fr":["Création d''interfaces utilisateur personnalisées","Ajout de composants comme code source au projet via CLI","Compatibilité avec différents gestionnaires de paquets (npm, pnpm, bun)","Utilisation de commandes CLI personnalisées (npx shadcn@latest)","Compatibilité avec des projets qui utilisent différents gestionnaires de paquets"],"de":["Erstellung benutzerdefinierter Benutzeroberflächen","Hinzufügen von Komponenten als Quellcode zum Projekt über die CLI","Unterstützung für verschiedene Paket-Manager (npm, pnpm, bun)","Verwendung von benutzerdefinierten CLI-Befehlen (npx shadcn@latest)","Unterstützung für Projekte, die unterschiedliche Paket-Manager verwenden"],"pt":["Adiciona componentes como código-fonte ao projeto via CLI","Suporta uso com diferentes gerenciadores de pacotes","Permite executar comandos com `npx shadcn@latest`, `pnpm dlx shadcn@latest` ou `bunx --bun shadcn@latest`"],"ru":["Добавляет компоненты в виде исходного кода в проект через CLI","Поддерживает использование с разными менеджерами пакетов","Позволяет выполнять команды с `npx shadcn@latest`, `pnpm dlx shadcn@latest` или `bunx --bun shadcn@latest`"],"ar":["يضيف المكونات كкод مصدر إلى المشروع من خلال CLI","يدعم استخدامها مع إدارة حزمة مختلفة","يسمح بتنفيذ أوامر مع `npx shadcn@latest`، `pnpm dlx shadcn@latest` أو `bunx --bun shadcn@latest`"]},"keywords":{"en":["how to use shadcn","shadcn ui component setup","shadcn alternative","shadcn vs other ui frameworks","shadcn install guide","what is shadcn","shadcn cli commands","shadcn design system management"],"zh":["shadcn UI框架","CLI命令","用户界面","设计系统","包管理器","npx","pnpm","bun"],"ja":["shadcn UIフレームワーク","CLIコマンド","ユーザーインターフェイス","デザインシステム","パッケージマネージャー","npx","pnpm","bun","AIエージェント"],"ko":["shadcn UI 프레임워크","CLI 명령","사용자 인터페이스","디자인 시스템","패키지 관리자","npx","pnpm","bun","AI 에이전트"],"es":["shadcn","framework de interfaces de usuario","componentes personalizados","CLI","administradores de paquetes","desarrollo de software","herramientas de desarrollo","framework de código abierto","interfaces de usuario personalizadas"],"fr":["shadcn","framework d''interfaces utilisateur","composants personnalisés","CLI","gestionnaires de paquets","développement de logiciels","outils de développement","framework open source","interfaces utilisateur personnalisées"],"de":["shadcn","Framework für Benutzeroberflächen","benutzerdefinierte Komponenten","CLI","Paket-Manager","Software-Entwicklung","Entwicklungstools","Open-Source-Framework","benutzerdefinierte Benutzeroberflächen"],"pt":["shadcn","framework de UI","componentes de UI","sistemas de design","CLI","gerenciador de pacotes","npx","pnpm","bunx"],"ru":["shadcn","фреймворк UI","компоненты UI","системы дизайна","CLI","менеджер пакетов","npx","pnpm","bunx","ИИ Агенты"],"ar":["shadcn","إطار عمل UI","مكونات واجهة المستخدم","أنظمة التصميم","CLI","مدير حزمة","npx","pnpm","bunx","أدوات الذكاء الاصطناعي"]}},"owner":"deadlock-api","repo":"deadlock-api","repoPath":"deadlock-api/deadlock-api","stars":7,"forks":1,"updatedAt":"2026-03-07T22:01:38Z","topics":[],"category":"community","skillMd":{"name":"shadcn","description":"Manages shadcn components and projects — adding, searching, fixing, debugging, styling, and composing UI. Provides project context, component docs, and usage examples. Applies when working with shadcn/ui, component registries, presets, --preset codes, or any project with a components.json file. Also triggers for shadcn init, create an app with --preset, or switch to --preset.","bodyPreview":"# shadcn/ui\n\nA framework for building ui, components and design systems. Components are added as source code to the user''s project via the CLI.\n\n> **IMPORTANT:** Run all CLI commands using the project''s package runner: `npx shadcn@latest`, `pnpm dlx shadcn@latest`, or `bunx --bun shadcn@latest` — based on the project''s `packageManager`. Examples below use `npx shadcn@latest` but substitute the correct runner for the project.\n\n## Current Project Context\n\n```json\n!`npx shadcn@latest info --json 2>","body":"# shadcn/ui\n\nA framework for building ui, components and design systems. Components are added as source code to the user''s project via the CLI.\n\n> **IMPORTANT:** Run all CLI commands using the project''s package runner: `npx shadcn@latest`, `pnpm dlx shadcn@latest`, or `bunx --bun shadcn@latest` — based on the project''s `packageManager`. Examples below use `npx shadcn@latest` but substitute the correct runner for the project.\n\n## Current Project Context\n\n```json\n!`npx shadcn@latest info --json 2>/dev/null || echo ''{\"error\": \"No shadcn project found. Run shadcn init first.\"}''`\n```\n\nThe JSON above contains the project config and installed components. Use `npx shadcn@latest docs <component>` to get documentation and example URLs for any component.\n\n## Principles\n\n1. **Use existing components first.** Use `npx shadcn@latest search` to check registries before writing custom UI. Check community registries too.\n2. **Compose, don''t reinvent.** Settings page = Tabs + Card + form controls. Dashboard = Sidebar + Card + Chart + Table.\n3. **Use built-in variants before custom styles.** `variant=\"outline\"`, `size=\"sm\"`, etc.\n4. **Use semantic colors.** `bg-primary`, `text-muted-foreground` — never raw values like `bg-blue-500`.\n\n## Critical Rules\n\nThese rules are **always enforced**. Each links to a file with Incorrect/Correct code pairs.\n\n### Styling & Tailwind → [styling.md](./rules/styling.md)\n\n- **`className` for layout, not styling.** Never override component colors or typography.\n- **No `space-x-*` or `space-y-*`.** Use `flex` with `gap-*`. For vertical stacks, `flex flex-col gap-*`.\n- **Use `size-*` when width and height are equal.** `size-10` not `w-10 h-10`.\n- **Use `truncate` shorthand.** Not `overflow-hidden text-ellipsis whitespace-nowrap`.\n- **No manual `dark:` color overrides.** Use semantic tokens (`bg-background`, `text-muted-foreground`).\n- **Use `cn()` for conditional classes.** Don''t write manual template literal ternaries.\n- **No manual `z-index` on overlay components.** Dialog, Sheet, Popover, etc. handle their own stacking.\n\n### Forms & Inputs → [forms.md](./rules/forms.md)\n\n- **Forms use `FieldGroup` + `Field`.** Never use raw `div` with `space-y-*` or `grid gap-*` for form layout.\n- **`InputGroup` uses `InputGroupInput`/`InputGroupTextarea`.** Never raw `Input`/`Textarea` inside `InputGroup`.\n- **Buttons inside inputs use `InputGroup` + `InputGroupAddon`.**\n- **Option sets (2–7 choices) use `ToggleGroup`.** Don''t loop `Button` with manual active state.\n- **`FieldSet` + `FieldLegend` for grouping related checkboxes/radios.** Don''t use a `div` with a heading.\n- **Field validation uses `data-invalid` + `aria-invalid`.** `data-invalid` on `Field`, `aria-invalid` on the control. For disabled: `data-disabled` on `Field`, `disabled` on the control.\n\n### Component Structure → [composition.md](./rules/composition.md)\n\n- **Items always inside their Group.** `SelectItem` → `SelectGroup`. `DropdownMenuItem` → `DropdownMenuGroup`. `CommandItem` → `CommandGroup`.\n- **Use `asChild` (radix) or `render` (base) for custom triggers.** Check `base` field from `npx shadcn@latest info`. → [base-vs-radix.md](./rules/base-vs-radix.md)\n- **Dialog, Sheet, and Drawer always need a Title.** `DialogTitle`, `SheetTitle`, `DrawerTitle` required for accessibility. Use `className=\"sr-only\"` if visually hidden.\n- **Use full Card composition.** `CardHeader`/`CardTitle`/`CardDescription`/`CardContent`/`CardFooter`. Don''t dump everything in `CardContent`.\n- **Button has no `isPending`/`isLoading`.** Compose with `Spinner` + `data-icon` + `disabled`.\n- **`TabsTrigger` must be inside `TabsList`.** Never render triggers directly in `Tabs`.\n- **`Avatar` always needs `AvatarFallback`.** For when the image fails to load.\n\n### Use Components, Not Custom Markup → [composition.md](./rules/composition.md)\n\n- **Use existing components before custom markup.** Check if a component exists before writing a styled `div`.\n- **Callouts use `Alert`.** Don''t build custom styled divs.\n- **Empty states use `Empty`.** Don''t build custom empty state markup.\n- **Toast via `sonner`.** Use `toast()` from `sonner`.\n- **Use `Separator`** instead of `<hr>` or `<div className=\"border-t\">`.\n- **Use `Skeleton`** for loading placeholders. No custom `animate-pulse` divs.\n- **Use `Badge`** instead of custom styled spans.\n\n### Icons → [icons.md](./rules/icons.md)\n\n- **Icons in `Button` use `data-icon`.** `data-icon=\"inline-start\"` or `data-icon=\"inline-end\"` on the icon.\n- **No sizing classes on icons inside components.** Components handle icon sizing via CSS. No `size-4` or `w-4 h-4`.\n- **Pass icons as objects, not string keys.** `icon={CheckIcon}`, not a string lookup.\n\n### CLI\n\n- **Never decode or fetch preset codes manually.** Pass them directly to `npx shadcn@latest init --preset <code>`.\n\n## Key Patterns\n\nThese are the most common patterns that differentiate correct shadcn/ui code. For edge cases, see the linked rule files above.\n\n```tsx\n// Form layout: FieldGroup + Field, not div + Label.\n<FieldGroup>\n  <Field>\n    <FieldLabel htmlFor=\"email\">Email</FieldLabel>\n    <Input id=\"email\" />\n  </Field>\n</FieldGroup>\n\n// Validation: data-invalid on Field, aria-invalid on the control.\n<Field data-invalid>\n  <FieldLabel>Email</FieldLabel>\n  <Input aria-invalid />\n  <FieldDescription>Invalid email.</FieldDescription>\n</Field>\n\n// Icons in buttons: data-icon, no sizing classes.\n<Button>\n  <SearchIcon data-icon=\"inline-start\" />\n  Search\n</Button>\n\n// Spacing: gap-*, not space-y-*.\n<div className=\"flex flex-col gap-4\">  // correct\n<div className=\"space-y-4\">           // wrong\n\n// Equal dimensions: size-*, not w-* h-*.\n<Avatar className=\"size-10\">   // correct\n<Avatar className=\"w-10 h-10\"> // wrong\n\n// Status colors: Badge variants or semantic tokens, not raw colors.\n<Badge variant=\"secondary\">+20.1%</Badge>    // correct\n<span className=\"text-emerald-600\">+20.1%</span> // wrong\n```\n\n## Component Selection\n\n| Need                       | Use                                                                                                 |\n| -------------------------- | --------------------------------------------------------------------------------------------------- |\n| Button/action              | `Button` with appropriate variant                                                                   |\n| Form inputs                | `Input`, `Select`, `Combobox`, `Switch`, `Checkbox`, `RadioGroup`, `Textarea`, `InputOTP`, `Slider` |\n| Toggle between 2–5 options | `ToggleGroup` + `ToggleGroupItem`                                                                   |\n| Data display               | `Table`, `Card`, `Badge`, `Avatar`                                                                  |\n| Navigation                 | `Sidebar`, `NavigationMenu`, `Breadcrumb`, `Tabs`, `Pagination`                                     |\n| Overlays                   | `Dialog` (modal), `Sheet` (side panel), `Drawer` (bottom sheet), `AlertDialog` (confirmation)       |\n| Feedback                   | `sonner` (toast), `Alert`, `Progress`, `Skeleton`, `Spinner`                                        |\n| Command palette            | `Command` inside `Dialog`                                                                           |\n| Charts                     | `Chart` (wraps Recharts)                                                                            |\n| Layout                     | `Card`, `Separator`, `Resizable`, `ScrollArea`, `Accordion`, `Collapsible`                          |\n| Empty states               | `Empty`                                                                                             |\n| Menus                      | `DropdownMenu`, `ContextMenu`, `Menubar`                                                            |\n| Tooltips/info              | `Tooltip`, `HoverCard`, `Popover`                                                                   |\n\n## Key Fields\n\nThe injected project context contains these key fields:\n\n- **`aliases`** → use the actual alias prefix for imports (e.g. `@/`, `~/`), never hardcode.\n- **`isRSC`** → when `true`, components using `useState`, `useEffect`, event handlers, or browser APIs need `\"use client\"` at the top of the file. Always reference this field when advising on the directive.\n- **`tailwindVersion`** → `\"v4\"` uses `@theme inline` blocks; `\"v3\"` uses `tailwind.config.js`.\n- **`tailwindCssFile`** → the global CSS file where custom CSS variables are defined. Always edit this file, never create a new one.\n- **`style`** → component visual treatment (e.g. `nova`, `vega`).\n- **`base`** → primitive library (`radix` or `base`). Affects component APIs and available props.\n- **`iconLibrary`** → determines icon imports. Use `lucide-react` for `lucide`, `@tabler/icons-react` for `tabler`, etc. Never assume `lucide-react`.\n- **`resolvedPaths`** → exact file-system destinations for components, utils, hooks, etc.\n- **`framework`** → routing and file conventions (e.g. Next.js App Router vs Vite SPA).\n- **`packageManager`** → use this for any non-shadcn dependency installs (e.g. `pnpm add date-fns` vs `npm install date-fns`).\n\nSee [cli.md — `info` command](./cli.md) for the full field reference.\n\n## Component Docs, Examples, and Usage\n\nRun `npx shadcn@latest docs <component>` to get the URLs for a component''s documentation, examples, and API reference. Fetch these URLs to get the actual content.\n\n```bash\nnpx shadcn@latest docs button dialog select\n```\n\n**When creating, fixing, debugging, or using a component, always run `npx shadcn@latest docs` and fetch the URLs first.** This ensures you''re working with the correct API and usage patterns rather than guessing.\n\n## Workflow\n\n1. **Get project context** — already injected above. Run `npx shadcn@latest info` again if you need to refresh.\n2. **Check installed components first** — before running `add`, always check the `components` list from project context or list the `resolvedPaths.ui` directory. Don''t import components that haven''t been added, and don''t re-add ones already installed.\n3. **Find components** — `npx shadcn@latest search`.\n4. **Get docs and examples** — run `npx shadcn@latest docs <component>` to get URLs, then fetch them. Use `npx shadcn@latest view` to browse registry items you haven''t installed. To preview changes to installed components, use `npx shadcn@latest add --diff`.\n5. **Install or update** — `npx shadcn@latest add`. When updating existing components, use `--dry-run` and `--diff` to preview changes first (see [Updating Components](#updating-components) below).\n6. **Fix imports in third-party components** — After adding components from community registries (e.g. `@bundui`, `@magicui`), check the added non-UI files for hardcoded import paths like `@/components/ui/...`. These won''t match the project''s actual aliases. Use `npx shadcn@latest info` to get the correct `ui` alias (e.g. `@workspace/ui/components`) and rewrite the imports accordingly. The CLI rewrites imports for its own UI files, but third-party registry components may use default paths that don''t match the project.\n7. **Review added components** — After adding a component or block from any registry, **always read the added files and verify they are correct**. Check for missing sub-components (e.g. `SelectItem` without `SelectGroup`), missing imports, incorrect composition, or violations of the [Critical Rules](#critical-rules). Also replace any icon imports with the project''s `iconLibrary` from the project context (e.g. if the registry item uses `lucide-react` but the project uses `hugeicons`, swap the imports and icon names accordingly). Fix all issues before moving on.\n8. **Registry must be explicit** — When the user asks to add a block or component, **do not guess the registry**. If no registry is specified (e.g. user says \"add a login block\" without specifying `@shadcn`, `@tailark`, etc.), ask which registry to use. Never default to a registry on behalf of the user.\n9. **Switching presets** — Ask the user first: **reinstall**, **merge**, or **skip**?\n   - **Reinstall**: `npx shadcn@latest init --preset <code> --force --reinstall`. Overwrites all components.\n   - **Merge**: `npx shadcn@latest init --preset <code> --force --no-reinstall`, then run `npx shadcn@latest info` to list installed components, then for each installed component use `--dry-run` and `--diff` to [smart merge](#updating-components) it individually.\n   - **Skip**: `npx shadcn@latest init --preset <code> --force --no-reinstall`. Only updates config and CSS, leaves components as-is.\n\n## Updating Components\n\nWhen the user asks to update a component from upstream while keeping their local changes, use `--dry-run` and `--diff` to intelligently merge. **NEVER fetch raw files from GitHub manually — always use the CLI.**\n\n1. Run `npx shadcn@latest add <component> --dry-run` to see all files that would be affected.\n2. For each file, run `npx shadcn@latest add <component> --diff <file>` to see what changed upstream vs local.\n3. Decide per file based on the diff:\n   - No local changes → safe to overwrite.\n   - Has local changes → read the local file, analyze the diff, and apply upstream updates while preserving local modifications.\n   - User says \"just update everything\" → use `--overwrite`, but confirm first.\n4. **Never use `--overwrite` without the user''s explicit approval.**\n\n## Quick Reference\n\n```bash\n# Create a new project.\nnpx shadcn@latest init --name my-app --preset base-nova\nnpx shadcn@latest init --name my-app --preset a2r6bw --template vite\n\n# Create a monorepo project.\nnpx shadcn@latest init --name my-app --preset base-nova --monorepo\nnpx shadcn@latest init --name my-app --preset base-nova --template next --monorepo\n\n# Initialize existing project.\nnpx shadcn@latest init --preset base-nova\nnpx shadcn@latest init --defaults  # shortcut: --template=next --preset=base-nova\n\n# Add components.\nnpx shadcn@latest add button card dialog\nnpx shadcn@latest add @magicui/shimmer-button\nnpx shadcn@latest add --all\n\n# Preview changes before adding/updating.\nnpx shadcn@latest add button --dry-run\nnpx shadcn@latest add button --diff button.tsx\nnpx shadcn@latest add @acme/form --view button.tsx\n\n# Search registries.\nnpx shadcn@latest search @shadcn -q \"sidebar\"\nnpx shadcn@latest search @tailark -q \"stats\"\n\n# Get component docs and example URLs.\nnpx shadcn@latest docs button dialog select\n\n# View registry item details (for items not yet installed).\nnpx shadcn@latest view @shadcn/button\n```\n\n**Named presets:** `base-nova`, `radix-nova`\n**Templates:** `next`, `vite`, `start`, `react-router`, `astro` (all support `--monorepo`) and `laravel` (not supported for monorepo)\n**Preset codes:** Base62 strings starting with `a` (e.g. `a2r6bw`), from [ui.shadcn.com](https://ui.shadcn.com).\n\n## Detailed References\n\n- [rules/forms.md](./rules/forms.md) — FieldGroup, Field, InputGroup, ToggleGroup, FieldSet, validation states\n- [rules/composition.md](./rules/composition.md) — Groups, overlays, Card, Tabs, Avatar, Alert, Empty, Toast, Separator, Skeleton, Badge, Button loading\n- [rules/icons.md](./rules/icons.md) — data-icon, icon sizing, passing icons as objects\n- [rules/styling.md](./rules/styling.md) — Semantic colors, variants, className, spacing, size, truncate, dark mode, cn(), z-index\n- [rules/base-vs-radix.md](./rules/base-vs-radix.md) — asChild vs render, Select, ToggleGroup, Slider, Accordion\n- [cli.md](./cli.md) — Commands, flags, presets, templates\n- [customization.md](./customization.md) — Theming, CSS variables, extending components\n"},"lastSynced":"2026-03-08T01:59:26.915Z","agentAnalysis":{"suitability":{"en":"Perfect for Frontend Agents needing efficient UI component management and design system integration via CLI.","zh":"非常适合需要高效 UI 组件管理和设计系统集成的前端代理，通过 CLI 实现。","ja":"フロントエンド エージェントが効率的な UI コンポーネント管理とデザイン システム統合を必要とする場合に最適です。CLI 経由で実現します。","ko":"効率적인 UI 컴포넌트 관리와 디자인 시스템 통합이 필요한 프론트엔드 에이전트에게 적합합니다. CLI를 통해 구현됩니다.","es":"Perfecto para Agentes Frontend que necesitan una gestión eficiente de componentes de interfaz de usuario y una integración del sistema de diseño a través de CLI.","fr":"Parfait pour les agents Frontend qui ont besoin d''une gestion efficace des composants d''interface utilisateur et d''une intégration du système de conception via CLI.","de":"Perfekt für Frontend-Agents, die eine effiziente Verwaltung von Benutzeroberflächenkomponenten und eine Integration des Designsystems über CLI benötigen.","pt":"Perfeito para Agentes Frontend que necessitam de gerenciamento eficiente de componentes de interface do usuário e integração de sistema de design via CLI.","ru":"Идеально для агентов Frontend, которым необходим эффективный менеджмент компонентов пользовательского интерфейса и интеграция системы дизайна через CLI.","ar":"مثالي للموكلين الأماميين الذين يحتاجون إلى إدارة فعالة لمكونات واجهة المستخدم وتكامل نظام التصميم عبر CLI."},"recommendation":{"en":"Empowers agents to manage UI components as source code, integrating seamlessly with project package runners like npm, pnpm, or bun, and utilizing design systems for consistent user interfaces.","zh":"赋予代理管理 UI 组件作为源代码的能力，通过项目包运行器（如 npm、pnpm 或 bun）无缝集成，并利用设计系统实现一致的用户界面。","ja":"エージェントが UI コンポーネントをソース コードとして管理できるようにし、プロジェクト パッケージ ランナー（npm、pnpm、または bun など）とシームレスに統合し、デザイン システムを使用して一貫したユーザー インターフェイスを提供します。","ko":"에이전트가 UI 컴포넌트를 소스 코드로서 관리할 수 있도록 하며, 프로젝트 패키지 러너(npm, pnpm, 또는 bun 등)를 통해 무缝하게 통합되고, 디자인 시스템을 사용하여 일관된 사용자 인터페이스를 제공합니다.","es":"Habilita a los agentes a gestionar los componentes de interfaz de usuario como código fuente, integrándose de forma transparente con los ejecutores de paquetes de proyectos como npm, pnpm o bun, y utilizando sistemas de diseño para interfaces de usuario coherentes.","fr":"Permet aux agents de gérer les composants d''interface utilisateur comme du code source, s''intégrant sans heurts avec les exécuteurs de paquets de projet tels que npm, pnpm ou bun, et utilisant des systèmes de conception pour des interfaces utilisateur cohérentes.","de":"Ermöglicht es den Agents, Benutzeroberflächenkomponenten als Quellcode zu verwalten, indem sie nahtlos mit Projekt-Paket-Runnern wie npm, pnpm oder bun integriert werden und Designsysteme für konsistente Benutzeroberflächen nutzen.","pt":"Habilita os agentes a gerenciar componentes de interface do usuário como código-fonte, integrando-se perfeitamente com executores de pacotes de projeto como npm, pnpm ou bun, e utilizando sistemas de design para interfaces de usuário consistentes.","ru":"Наделяет агентов возможностью управлять компонентами пользовательского интерфейса как исходным кодом, интегрируясь без проблем с запускающими пакеты проекта, такими как npm, pnpm или bun, и используя системы дизайна для последовательных интерфейсов пользователя.","ar":"تمكّن الوكلاء من إدارة مكونات واجهة المستخدم ككود مصدر، وتكاملها بشكل متجانس مع مشغلات حزم المشروع مثل npm و pnpm و bun، واستخدام أنظمة التصميم لواجهات مستخدم متسقة."},"useCases":{"en":["Automating UI component additions to projects","Generating consistent design systems across applications","Managing UI components via CLI for efficient development workflows"],"zh":["将 UI 组件自动添加到项目中","在应用程序中生成一致的设计系统","通过 CLI 高效地管理 UI 组件以实现开发工作流"],"ja":["プロジェクトに UI コンポーネントを自動的に追加する","アプリケーション全体に一貫したデザイン システムを生成する","CLI を使用して UI コンポーネントを効率的に管理し、開発ワークフローを実現する"],"ko":["프로젝트에 UI 컴포넌트를 자동으로 추가하는 것","애플리케이션 전체에 일관된 디자인 시스템을 생성하는 것","CLI를 사용하여 UI 컴포넌트를 효율적으로 관리하여 개발 워크플ロー 구현"],"es":["Automatización de la adición de componentes de interfaz de usuario a proyectos","Generación de sistemas de diseño coherentes en aplicaciones","Gestión de componentes de interfaz de usuario a través de CLI para flujos de trabajo de desarrollo eficientes"],"fr":["Automatisation de l''ajout de composants d''interface utilisateur aux projets","Génération de systèmes de conception cohérents dans les applications","Gestion de composants d''interface utilisateur via CLI pour des flux de travail de développement efficaces"],"de":["Automatisierung der Hinzufügung von Benutzeroberflächenkomponenten zu Projekten","Erzeugung konsistenter Designsysteme in Anwendungen","Verwaltung von Benutzeroberflächenkomponenten über CLI für effiziente Entwicklungswerkflüsse"],"pt":["Automatizar adições de componentes de interface do usuário a projetos","Gerar sistemas de design consistentes em todo o aplicativo","Gerenciar componentes de interface do usuário via CLI para fluxos de trabalho de desenvolvimento eficientes"],"ru":["Автоматизировать добавление компонентов пользовательского интерфейса в проекты","Генерировать последовательные системы дизайна во всех приложениях","Управлять компонентами пользовательского интерфейса через CLI для эффективных рабочих процессов разработки"],"ar":["تحسين إضافة مكونات واجهة المستخدم إلى المشاريع","_generating_ أنظمة تصميم متسقة عبر التطبيقات","إدارة مكونات واجهة المستخدم من خلال CLI من أجل سير عمل التطوير الفعّالة"]},"limitations":{"en":["Requires project package runner like npm, pnpm, or bun","Must run CLI commands using the project''s package runner"],"zh":["需要项目包运行器，如 npm、pnpm 或 bun","必须使用项目的包运行器运行 CLI 命令"],"ja":["npm、pnpm、または bun などのプロジェクト パッケージ ランナーが必要","プロジェクトのパッケージ ランナーを使用して CLI コマンドを実行する必要がある"],"ko":["npm, pnpm, 또는 bun 같은 프로젝트 패키지 러너가 필요","프로젝트의 패키지 러너를 사용하여 CLI 명령어를 실행해야 함"],"es":["Requiere un ejecutor de paquetes de proyecto como npm, pnpm o bun","Debe ejecutar comandos de CLI utilizando el ejecutor de paquetes del proyecto"],"fr":["Nécessite un exécuteur de paquet de projet tel que npm, pnpm ou bun","Doit exécuter des commandes CLI en utilisant l''exécuteur de paquet du projet"],"de":["Benötigt einen Projekt-Paket-Runner wie npm, pnpm oder bun","Muss CLI-Befehle mithilfe des Projekt-Paket-Runners ausführen"],"pt":["Exige um executor de pacote de projeto como npm, pnpm ou bun","Deve executar comandos CLI usando o executor de pacote do projeto"],"ru":["Требует запускающего пакеты проекта, такого как npm, pnpm или bun","Должен запускать команды CLI, используя запускающий пакеты проекта"],"ar":["يتطلب مشغل حزمة مشروع مثل npm و pnpm و bun","يجب تشغيل أوامر CLI باستخدام مشغل حزمة المشروع"]},"version":4},"contentHash":"cefd8f067461a5994741aef6be1e285bb62c5a0dceef79006dd3caaa4fbfec1a","qualityScore":45}');
