INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('deadlock-api/deadlock-api/shadcn', 'shadcn', 'deadlock-api', 'deadlock-api', 'community', 'shadcn deadlock-api deadlock-api community shadcn is a framework for building UI components and design systems, adding components as source code to projects via the CLI. It benefits developers seeking efficient UI management. shadcn UI框架是一种用于构建用户界面和设计系统的工具，通过CLI命令将组件添加到项目中 shadcn UIフレームワークは、ユーザーインターフェイスとデザインシステムを構築するためのツールです。CLIコマンドを使用してコンポーネントをプロジェクトに追加します shadcn UI 프레임워크는 사용자 인터페이스와 디자인 시스템을 구축하기 위한 도구입니다. CLI 명령을 사용하여 컴포넌트를 프로젝트에 추가합니다 shadcn es un framework para construir interfaces de usuario y componentes personalizados. Utiliza el CLI para agregar componentes como código fuente al proyecto shadcn est un framework pour créer des interfaces utilisateur et des composants personnalisés. Il utilise le CLI pour ajouter des composants comme code source au projet shadcn ist ein Framework für die Erstellung benutzerdefinierter Benutzeroberflächen und Komponenten. Es verwendet die CLI, um Komponenten als Quellcode zum Projekt hinzuzufügen O shadcn é um framework de UI que permite adicionar componentes como código-fonte ao projeto via CLI. shadcn - это фреймворк UI, который позволяет добавлять компоненты в виде исходного кода в проект через CLI. shadcn هو إطار عمل UI يسمح بإضافة المكونات كкод مصدر إلى المشروع من خلال CLI. how to use shadcn shadcn ui component setup shadcn alternative shadcn vs other ui frameworks shadcn install guide what is shadcn shadcn cli commands shadcn design system management shadcn UI框架 CLI命令 用户界面 设计系统 包管理器 npx pnpm bun Adds UI components as source code to projects via the CLI Supports project-specific package runners like `npx`, `pnpm dlx`, and `bunx` Provides project information via `npx shadcn@latest info --json` command Enables design system management through component integration Runs CLI commands based on the project''s `packageManager` shadcn is a UI component framework that integrates into projects via CLI commands for efficient design system management');
